INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0069', 1, NULL, 5, NULL, NULL, 'അനിസ്ലാമിക സൽക്കാരത്തിൽ ക്ഷണം നിരസിക്കാമോ ?', 'സ്ത്രീപുരുഷ സങ്കലനവും, പാട്ടുകളും,വരനും വധുവും ഒരുമിച്ചു സ്റ്റേജിൽ ഫോട്ടോ എടുക്കുകയും ചെയ്യുന്ന അടുത്ത കുടുംബക്കാരുടെ വിവാഹസൽക്കാരത്തിനു ക്ഷണിച്ചാൽ എന്ത് ചെയ്യണം? പോകാതിരുന്നാൽ കുടുംബബന്ധം മുറിച്ച ശിക്ഷ ലഭിക്കുമോ ?', 'Malayalam', 'published', '<p>ഹറാമായ കാര്യങ്ങൾ നടക്കുന്ന &nbsp;വിവാഹ സൽക്കാരങ്ങളിലും മറ്റും നമ്മൾ പങ്കെടുക്കുന്നത് മുഖേന ഹറാമുകളെ &nbsp;തടുക്കുവാനോ ഇല്ലാതാക്കുവാനോ &nbsp;സാധിക്കുമെങ്കിൽ അതിൽ പങ്കെടുക്കേണ്ടതാണ്. &nbsp;ഇനി ആ ഹറാമുകളെ തടുക്കുവാനോ, &nbsp; ഇല്ലാതാക്കാനോ നമുക്ക്&nbsp;സാധിക്കില്ലെങ്കിൽ അതിൽ പങ്കെടുക്കാൻ ഹറാമാണ്.&nbsp;</p> <p>&nbsp;ഹറാം നടക്കുന്ന കാര്യം അറിയാതെ ആ സൽക്കാരത്തിൽ പങ്കെടുത്താൽ അല്ലെങ്കിൽ നമ്മൾ ചെന്നതിനു ശേഷമാണ് ഹറാം ആരംഭിച്ചത് എങ്കിൽ അതിനെ നമ്മൾ തടയണം. &nbsp;അവർ നമ്മളെ അംഗീകരിച്ചില്ലെങ്കിൽ ആ സൽക്കാരത്തിൽ നാം പങ്കെടുക്കരുത്.&nbsp;</p> <p>&nbsp;ഇതുപോലുള്ള സൽക്കാരത്തിൽ പങ്കെടുക്കാതിരുന്നതിൻറെ&nbsp;പേരിൽ അടുത്ത കുടുംബക്കാർ &nbsp;ബന്ധം മുറിച്ചാൽ പോലും നമ്മൾ കുറ്റക്കാർ ആവുകയില്ല. അല്ലാഹുവിന് എതിര് പ്രവർത്തിക്കുന്നതിൽ ഒരു സൃഷ്ടിയെയും വഴിപ്പെടാൻ പാടില്ലെന്ന് നബി (സ) അരുളിയിരിക്കുന്നു.</p>', 4, 0, 5, '1970-01-01 01:00:00', 1, '2020-01-29 00:09:32', '2023-06-09 17:03:26') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0101', 1, NULL, 5, NULL, NULL, 'ഗർഭിണിയുടെ നോമ്പ് ഉപേക്ഷിക്കൽ', 'ഗർഭിണി ആദ്യ നാളുകളിൽ അനുഭവിക്കേണ്ടി വരുന്ന തളർച്ച, തലവേദന, ഛർദി, തലകറക്കം പോലുള്ള കാര്യങ്ങൾക്ക് വേണ്ടി നോമ്പ് വിടാൻ അനുവാദം ഉണ്ടോ ? , ഉണ്ടെങ്കിൽ അതിന്റെ പിടിച്ച് വീട്ടൽ എപ്രകാരം ആണ് ?', 'Malayalam', 'published', '<p>ഒരു ഗർഭിണിയായ സ്ത്രീക്ക് ഉണ്ടാകാവുന്ന ശാരീരിക പ്രശ്നങ്ങളുടെയും ബുദ്ധിമുട്ടിൻ്റെയും &nbsp;പേരിൽ നോമ്പ് വിടാവുന്നതാണ്.ആ &nbsp;നഷ്ടപ്പെട്ട നോമ്പുകൾ അടുത്തവർഷത്തെ നോമ്പ് ആരംഭിക്കുന്നതിനുമുമ്പ് പിടിച്ചു വീട്ടിയാൽ മതി. എന്നാൽ നോമ്പ് വെക്കുന്നതിൽ പ്രത്യേകിച്ച് ശാരീരിക ബുദ്ധിമുട്ട് ഇല്ല, പക്ഷേ ,ഡോക്ടർമാരുടെ നിർദേശപ്രകാരം ഗർഭസ്ഥശിശുവിന് വേണ്ടി മരുന്നു &nbsp;കഴിക്കാനോ മറ്റുകാര്യങ്ങൾക്കോ &nbsp;ആയി നോമ്പ് വിടുകയാണെങ്കിൽ ആ നഷ്ടപ്പെട്ട നോമ്പ് പിടിച്ചു വീടുന്നതിനോട് &nbsp;കൂടി ഫിദിയയും &nbsp;നൽകൽ നിർബന്ധമാണ്. ഇത് ഷാഫി മദ്ഹബിലെ വീക്ഷണമാണ്.&nbsp;</p> <p>ഹനഫി മദ്ഹബ് അനുസരിച്ച് ഗർഭാവസ്ഥയിൽ ഉണ്ടാകുന്ന ശാരീരിക പ്രശ്നങ്ങളുടെ പേരിൽ ഒരു സ്ത്രീ നോമ്പ് വിട്ടാലും അല്ലെങ്കിൽ ഗർഭ ശിശുവിനെ ആവശ്യാർത്ഥം നോമ്പ് വിട്ടാലും ആനഷ്ടപ്പെട്ട നോമ്പ് പിടിച്ചു വീട്ടിൽ മാത്രമേ നിർബന്ധമുള്ളൂ ഫിദിയ നൽകേണ്ടതില്ല</p>', 7, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-10 13:17:15', '2024-03-21 01:12:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0077', 1, NULL, 5, NULL, NULL, 'Fighting between husband and wife', 'Assalamu Alykum I had my nikkah in Haram Kaaba, back in December 2015 Alhamdulillah, but not ruksati till the month of September. In the start I and my wife have a beautiful conversation and mental understanding. but since past a month we are fighting on very small issues and the fight took long and it feels like our love in our heart is going down. Please suggest me what should I do. As we are getting married this month InshaAllah, as the days are near the conflicts and issues between us rises very often. Please suggest some dua and advise. Thankyou JazakAllah khair.', 'English', 'published', '<p><strong>In the Name of Allah, the Most Gracious, the Most Merciful.</strong></p> <p><strong>&nbsp;</strong></p> <p>We attach the marriage recipe of Mufti Ebrahim Desai Sahib. Follow the advises in it. Insha Allah there will be barakah in the marriage.</p> <p><strong>&nbsp;</strong></p> <p><strong>1.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Fear Allah:</strong></p> <p>It was the noble practice of Nabi&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam*</em>&nbsp;to conscientize the spouses about the fear for Allah before performing a Nikah by reciting the verses&nbsp;<em>(Nisa v14, Ahzab v69, Aali-Imraan v101)</em>&nbsp;from the&nbsp;<em>Qur&rsquo;ān</em>. All the verses are common in the message of Taqwa (fear of Allah). The spouses will be first committed to Allah before being committed to their partner. There can be no doubt in the success of a marriage governed by the fear of Allah.</p> <p><strong>2.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Never be angry at the same time:</strong></p> <p>Anger is the root cause for all marital disputes. One Sahabi came to Rasulullah&nbsp;<em>salallahu</em><em>῾</em><em>alayhi wasallam</em>&nbsp;and sought some advice. Rasulullah&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam</em>&nbsp;replied, control your anger. The same advice was rendered three times.&nbsp;<em>(Mishkaat pg.433; HM Saeed)</em></p> <p><strong>3.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>If one has to win an argument, let it be the other:</strong></p> <p>Nabi&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam</em>&nbsp;said: &ldquo;Whoever discards an argument despite being correct shall earn a palace in the centre of Jannah.&nbsp;<em>(Ibid pg.412)</em></p> <p><strong>4.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Never shout at each other unless the house is on fire:</strong></p> <p>Luqman (AS) while offering advice to his son said: &ldquo;and lower your voice for verily the most disliked voice is that of a donkey&rdquo;.&nbsp;<em>(Surah Luqman v19)</em></p> <p><strong>5.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>If you have to criticize, do it lovingly:</strong></p> <p>Rasulullah&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam</em>&nbsp;said, &lsquo;A Mu&rsquo; min is a mirror for a Mu&rsquo;min.&rsquo;&nbsp;<em>(Abu Dawud vol.2 pg.325; Imdadiyah)</em>&nbsp;Advise with dignity and silently.</p> <p><strong>6.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Never bring up mistakes of the past:</strong></p> <p>Nabi&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam</em>&nbsp;said: &ldquo;Whoever conceals the faults of others, Allah shall conceal his faults on the day of Qiyaamah.&rdquo;&nbsp;<em>(Mishkaat pg.429; HM Saeed)</em></p> <p><strong>7.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Neglect the whole world rather than your marriage partner:</strong></p> <p>Nabi&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam</em>&nbsp;confirmed the advice of Salman to Abu-Darda (May Allah be pleased with him) for neglecting his wife. &ldquo;Verily there is a right of your wife over you.&rdquo;<em>&nbsp;</em><em>(Nasai Hadith2391)</em></p> <p><strong>8.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>Never sleep with an argument unsettled:</strong></p> <p>Abu Bakr (may Allah be pleased with him) resolved his dispute with his wife over-feeding the guests before going to bed.&nbsp;<em>(Bukhari Hadith 602)</em></p> <p><strong>9.</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>At least, once everyday, express your gratitude to your partner:</strong></p> <p>Nabi&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam</em>&nbsp;said, &lsquo;Whoever does not show gratitude to the people has not shown gratitude to Allah.&rsquo;&nbsp;<em>(Abu Dawud pg.662; Karachi)</em></p> <p><strong>10.</strong>&nbsp;<strong>When you have done something wrong, be ready to admit it and ask for forgiveness:</strong></p> <p>&nbsp;Nabi&nbsp;<em>salallahu</em><em>&nbsp;</em><em>῾</em><em>alayhi wasallam</em>&nbsp;said, &lsquo;All the sons of Aadam commit error, and the best of those who err are those who seek forgiveness.&rsquo;&nbsp;<em>(Tirmidhi Hadith 2499)</em></p> <p><strong>&nbsp;</strong></p> <p><strong>And Allāh Ta῾āla Knows Best</strong></p>', 7, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-01 23:48:12', '2024-06-11 21:51:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0151', 1, NULL, 1, NULL, NULL, 'ഹനഫി മദ്ഹബ് അനുസരിച്ചു മയ്യിത്ത് നമസ്കാരം ഒന്നിൽ കൂടുതൽ നമസ്കരിക്കുവാൻ അനുവാദം ഉണ്ടോ?', 'ഹനഫി മദ്ഹബ് അനുസരിച്ചു മയ്യിത്ത് നമസ്കാരം ഒന്നിൽ കൂടുതൽ നമസ്കരിക്കുവാൻ അനുവാദം ഉണ്ടോ?', 'Malayalam', 'published', '<p>ഹനഫി മദ്ഹബ് അനുസരിച്ചു മയ്യത്ത് നമസ്&zwnj;കാരം ഒന്നിൽ കൂടുതൽ നമസ്&zwnj;കരിക്കൽ അനുവദനീയം അല്ല. അഥവാ ഒന്നിൽ കൂടുതൽ നമസ്&zwnj;കരിച്ചാൽ ആദ്യത്തെ നമസ്&zwnj;കാരം ഒഴികെ ബാക്കിയുള്ളവ പരിഗണനീയവുമല്ല. എന്നാൽ മയ്യത്തിന്റെ വലിയ്യുടെ &nbsp;അനുവാദം വ്യക്തമായോ അല്ലെങ്കിൽ സൂചനയിലൂടെയോ ലഭിക്കാതെയാണ് ആദ്യത്തെ നമസ്&zwnj;കാരം നടന്നതെങ്കിൽ വലിയ്യിന് രണ്ടാമത് നമസ്&zwnj;കരിക്കുവാൻ അനുവാദം ഉണ്ട്. &nbsp;ആദ്യത്തെ ജമാഅത്തിൽ പങ്കെടുക്കാത്തവർക്ക് വലിയ്യിനോടൊപ്പം നമസ്&zwnj;കരിക്കാവുന്നതാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-04 21:06:07', '2023-07-31 11:37:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0262', 1, NULL, 2, NULL, NULL, 'മുറിച്ച് മാറ്റപ്പെട്ട അവയവം മറമാടുന്നതിൻ്റെ വിധി എന്ത് ?', 'ശരീരത്തിലെ ഒരു അവയവം രോഗം കാരണം മുറിച്ചു മാറ്റപെട്ടാൽ ആ അവയവത്തെ മറമാടുന്നതിന്ന് മുമ്പായി കഴുകൽ നിർബന്ധമുണ്ടോ? ശാഫിഈ മദ്ഹബ് വിധി എന്താണ് ?', 'Malayalam', 'published', '<p>ശരീരത്തിലെ അവയവം രോഗം കാരണം മുറിച്ചുമാറ്റപ്പെട്ട് കഴിഞ്ഞാൽ അത് &nbsp;പൊതിഞ്ഞ് &nbsp;മറമാടിയാൽ മതിയാകുന്നതാണ് അതു കഴുകുകയോ അതിനുവേണ്ടി നമസ്കരിക്കുകയോ ചെയ്യേണ്ടതില്ല.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-11-05 20:18:41', '2020-11-05 20:18:41') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0091', 1, NULL, 5, NULL, NULL, 'ഹോട്ടലുകളിൽ മാംസാഹാരം കഴിക്കാമോ?', 'ഹോട്ടലുകളിൽ പോകുമ്പോൾ ഹോട്ടലുടമയോ വെയ്റ്ററോ ഇറച്ചി ഹലാൽ ആണെന്ന് പറഞ്ഞാൽ മാംസാഹാരം അവിടുന്ന് കഴിക്കാമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-02-08 23:06:44', '2023-11-02 16:10:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0213', 1, NULL, 1, NULL, NULL, 'qasar namaz ke bare me Hardees', 'Assalamu alikum Kya ap mujhe qasar namaz ke bare me Hardees aur quran se bata sakte h ki kitne kilometre jane par qasar padhna chahiye', 'Urdu', 'published', '<p>جب کوئی شخص درمیانی رفتار سےچل کر ٤٨میل کا سفر کا ارادہ کرلے تو وہ شخص مسافر کہلاتا ہے٤٨میل۷۷۰۲٤٨ کلو میٹر کا ہوتا ہے احناف کے نزدیک اتنی دوری کا سفر کرنے پر قصر کرنے کا حکم ہے یعنی چار رکعت والی نماز دو رکعت پڑھنا ضروری ے البتہ روزہ کے سلسلے میں اختیار ہے چاہے تو روزہ رکھ لے یا سفر سے واپسی کے بعد روزہ رکھ لے.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2020-08-19 03:19:11', '2020-08-19 03:19:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0232', 1, NULL, 5, NULL, NULL, 'മോറിസ് coin ല്&zwj; cash inwest ചെയത് കിട്ടുന്ന ലാഭം halal ആണോ', 'മോറിസ് coin ല്&zwj; cash inwest ചെയത് കിട്ടുന്ന ലാഭം halal ആണോ?', 'Malayalam', 'published', '<p>Morris &nbsp;coin ലൂടെ ലഭിക്കുന്ന ലാഭം ഹലാലല്ല കൂടുതൽ വിവരണത്തിനായി താഴെയുള്ള Link പരിശോധിക്കുക<br /> https://fatwa.kauzariyya.com/single.php?question=206</p>', 9, 0, 5, '1970-01-01 01:00:00', 1, '2020-09-19 16:41:11', '2023-11-27 06:02:41') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0258', 1, NULL, 5, NULL, NULL, 'പ്രൊഫഷണൽ എന്ന നിലയ്ക്ക് ഹിജാമ ചികിത്സകൻ വാങ്ങുന്ന ഫീസിന്റെ വിധി', 'ഞാൻ ഒരു ഹിജാമ ചികിത്സകനാണ്. ക്ലിനിക്കൽ ഉപകരണങ്ങളും മറ്റ് ചിലവുകളും ചേർത്ത് ഞാൻ ചികിത്സ ചെയ്യുമ്പോൾ അതിൽ നിശ്ചിത ഫീസ് വാങ്ങുന്നതിന്റെ ഇസ്ലാമിക വിധി എന്താണ്...?? കാരണം ഹിജാമക്കാരന് ഫീസ് വാങ്ങൽനിശിദ്ധമാണെന്ന് ചില ഹദീസുകൾ (ജാമിഉ തിർമുദി 1275, 1278, ബുഖാരി 2238, 5962, സുനൻ നസാഈ 4673, 4294, സുനൻ ഇബ്നു മാജ 2165, സഹീഹ് മുസ്ലിം 1568) വ്യക്തമായി സൂചിപ്പിക്കുന്നു. എന്നാൽ മറ്റ് ചില ഹദീസുകളാകട്ടെ ഹിജാമക്കാരന് പ്രവാചകൻ (സ) ഫീസ് നൽകിയതായും, അത് വാങ്ങുന്നതിൽ കുഴപ്പവുമില്ല എന്നും വ്യക്തമായി സൂചിപ്പിക്കുന്നു. ( ബുഖാരി 2279, 2280, 2281,2277, ഇബ്നു മാജ 2163, 2164, സുനൻ അബൂ ദാവൂദ് 3423, 3224) ഈ രണ്ട് വിഭാഗം ഹദീസുകളുടെയും അടിസ്ഥാനത്തിൽ ഹിജാമ ചികിത്സകൻ ഫീസ് വാങ്ങുന്നതിന്റെ വിധിയെന്താണ്..? അനുവദനീയമെങ്കിൽ ഫീസിന്റെ മാനദണ്ഠങ്ങൾ എന്തൊക്കെയാണ്..?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2020-10-26 03:35:39', '2020-10-26 03:35:39') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0066', 1, NULL, 5, NULL, NULL, 'നബി തങ്ങളുടെ മേലുള്ള സ്വലാത്തിന്റെ പ്രതിഫലം വീതിച്ചു നൽകുമോ ?', 'നബി തങ്ങളുടെ മേൽ സ്വലാത്ത് ചൊല്ലിയാൽ അതിന്റെ പ്രതിഫലം ആർക്കും വീതിച്ച് കൊടുക്കില്ലാ എന്ന് ചില സംസാരങ്ങളിൽ കേട്ടിട്ടുണ്ട് , ഇത് പ്രാമാണികം ആണോ ?', 'Malayalam', 'published', '<p>ഏറെ അന്വേഷണങ്ങൾക്കും പഠനങ്ങൾക്കു ശേഷവും ചോദ്യത്തിൽ പ്രതിബാധിച്ച വിഷയത്തിൽ വിശ്വാസയോഗ്യവും ആധികാരികവും ആയ തെളിവുകൾ ലഭിച്ചില്ല.</p>', 6, 0, 5, '1970-01-01 01:00:00', 1, '2020-01-15 02:15:16', '2024-08-19 07:30:34') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0019', 1, NULL, 1, NULL, NULL, 'ഗർഭിണി ആയ അവസ്ഥയിലുള്ള മരുന്നുപയോഗം', 'ഞാൻ pregnant ആണ്. അതുകൊണ്ട് doctor jelatin എന്ന content അടങ്ങിയ susten 200 എന്ന മരുന്ന് എനിക്ക് priscribe ചെയ്തു. ഈ മരുന്ന് abortion ആവാതിരിക്കാനുള്ള മരുന്നാണ്. എന്നാൽ jelatin എന്ന content കൂടുതൽ ആയി Animal fatil നിന്നോ ചിലപ്പോൾ വൃക്ഷങ്ങളിൽ നിന്നോ ആണ് ഉണ്ടാക്കുന്നത് എന്ന് അറിയാൻ കഴിഞ്ഞു . നിലവിൽ അബോർഷൻ ആവാതിരിക്കാൻ ഈ ഗുളിക കഴിക്കൽ അനുവദനീയം ആണോ ?', 'Malayalam', 'published', 'ജലാറ്റിൻ അടങ്ങിയ ഗുളിക കഴിക്കൽ അനുവദനീയം ആണ്. ഹനഫി മദ്ഹബ് അനുസരിച്ച് നജസ് ആയ വസ്തുക്കൾ ധാതു മാറ്റം സംഭവിച്ച് വേറൊരു ധാതു ആയി മാറിയാൽ ശുദ്ധി ആകുന്നതാണ്. ധാതു മാറ്റം സംഭവിക്കിന്നത് സ്വയം ആണെങ്കിലും രാസപ്രവർത്തന ഫലമായോ മറ്റോ ആണെങ്കിലും ഇതേ വിധി തന്നെ ആണ്. ആധുനിക പണ്ഡിതൻ മാരുടെ അഭിപ്രായം ജലറ്റിനിൽ മൃഗങ്ങളുടെ അവശിഷ്ടം അടങ്ങിയിട്ടുണ്ട് എങ്കിലും അവ ധാതു മാറ്റത്തിന് വിധേയം ആണ്. ഈ അടിസ്ഥാനത്തിൽ ജലാറ്റിൻ അടങ്ങിയ മരുന്നുകൾ ഉപയോഗിക്കൽ അനുവതനീയം ആണ്.', 5, 0, 5, '1970-01-01 01:00:00', 1, '2019-09-29 07:39:30', '2023-12-01 04:11:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0010', 1, NULL, 1, NULL, NULL, 'അന്യമതസ്തരുടെ പള്ളികൾ നിർമിക്കാൻ സാധനങ്ങൾ വിക്കൽ', 'അമ്പലം പണിയുന്നതിനു വേണ്ടി സിമന്റ്, കട്ട, ടൈൽസ് മുതലായ വസ്തുക്കളും, ആരാധനക്കായി പ്രസാദവും മറ്റും ഉണ്ടാക്കാൻ പലചരക്ക് സാധനങ്ങൾ വിൽക്കലും ഇസ്ലാമികമായി അനുവദനീയം ആണോ ?', 'Malayalam', 'published', 'ഇമാം അബൂഹനീഫാ (റ;അ) യുടെ അഭിപ്രായം അനുസരിച് അമ്പലം, ക്രിസ്ത്യൻ പള്ളി പോലുള്ളവ പണിയാൻ വേണ്ടി സിമന്റ്, കട്ട, ടൈൽസ് മുതലായ വസ്തുക്കളും, ആരാധനക്കായി പ്രസാദവും മറ്റും ഉണ്ടാക്കാൻ പലചരക്ക് സാധനങ്ങളും വിൽക്കുന്നതിൽ തെറ്റില്ല. According to imam Abu Haneefa (ra) there is no issue in selling bricks, tiles & other materials for building temples, churches & other religious centres and for selling cereals for non-Muslim act of worship', 78, 0, 5, '1970-01-01 01:00:00', 1, '2019-09-29 07:12:56', '2024-10-16 18:38:48') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0099', 1, NULL, 5, NULL, NULL, 'ഒരാൾ മരണപ്പെട്ടാൽ ഖബറടക്കം പിന്തിക്കാമോ? മക്കൾ ഗൾഫിൽ നിന്ന് മടങ്ങി വരുന്നത് വരെ', 'ഒരാൾ മരണപ്പെട്ടാൽ ഖബറടക്കം പിന്തിക്കാമോ? മക്കൾ ഗൾഫിൽ നിന്ന് മടങ്ങി വരുന്നത് വരെ. പിന്തിക്കാവുന്ന പരമാവധി ദിവസം എത്രയാണ്? അതിനു ദീൻ അനുവദിക്കുന്ന കാരണങ്ങൾ എന്തെല്ലാം ആണ്?', 'Malayalam', 'published', '<p><br /> രാജ്യത്തിൻറെ നിർബന്ധ നിയമമനുസരിച്ച് പിന്തിപ്പിക്കൽ അനിവാര്യമായി വരുന്ന പോസ്റ്റ് മാർട്ടം പോലുള്ള കാരണങ്ങൾ ഇല്ലാത്തപ്പോൾ എത്രയും പെട്ടെന്ന് ഖബറടക്കാൻ പരിശ്രമിക്കേണ്ടതാണ്. ഏതെങ്കിലും ബന്ധുവിന് വേണ്ടി കബറടക്കം പിന്തിരിപ്പിക്കാതിരിക്കലാണ് ഉത്തമം .ജഡം ജീർണത യിലേക്ക് എത്തുന്ന വിധം പിന്തിപ്പിക്കൽ നിഷിദ്ധമാണ്&nbsp;</p> <p>&nbsp;</p>', 16, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-09 09:15:49', '2023-09-04 09:24:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0142', 1, NULL, 5, NULL, NULL, 'ചിത്രം വരയ്ക്കൽ,ഫോട്ടോഗ്രാഫി', 'ചിത്രം വരയ്ക്കലും ഫോട്ടോ എടുക്കലും ഹറാം ആണോ?', 'Malayalam', 'published', '<p>ഡിജിറ്റൽ ക്യാമറകളോ, മൊബൈൽ ക്യാമറകളോ അല്ലാത്ത സംവിധാനങ്ങൾ കൊണ്ട് ജീവനുള്ളവയുടെ ഫോട്ടോ എടുക്കൽ അനുവദനീയമാണെന്ന് അഭിപ്രായപ്പെടുന്നവർക്ക് ബലമേകുന്ന തെളിവുകൾ കാണാൻ കഴിയുന്നില്ല,(ഡിജിറ്റൽ, മൊബൈൽ ക്യാമറകളുടെ ചർച്ച ശേഷം വിവരിക്കുന്നതാണ്)</p> <p>മാത്രമല്ല കള്ള് കൈ കൊണ്ട് നിർമ്മിച്ചാലും ഉപകരണങ്ങൾ കൊണ്ട് നിർമ്മിച്ചാലും നിയമത്തിന് വിത്യാസം വരാത്തത് പോലെ</p> <p>ശരീഅത്ത് അനുവദിക്കാത്ത ഒരു കാര്യം പ്രവർത്തിക്കാനായി നൂതനമായ ഏത് സാങ്കേതിക ശൈലി ആവിഷ്കരിച്ചാലും അതിന്റെ നിശിദ്ധത്തിന് മാറ്റം വരുത്താൻ കഴിയില്ല.</p> <p>ആയതിനാൽ ഹദീസുകളിൽ ശക്തമായി നിരോധിക്കപ്പെട്ട ജീവനുള്ളവയുടെ ചിത്രം വരയ്ക്കൽ കൈകൾ കൊണ്ടാണെങ്കിലും ഉപകരണങ്ങൾ കൊണ്ടാണെങ്കിലും ഹറാം ആണ്.&nbsp; (ഫത്ഹുൽ മുൽഹിം 142/11)</p> <p>എന്നിരുന്നാലും സർക്കാരുമായി ബന്ധപ്പെടുന്ന പാസ്പോർട്ട് , ആധാർ പോലുള്ള നിർബന്ധിത സാഹചര്യങ്ങളിൽ ഇതിന് അനുമതി നൽകപ്പെട്ടിട്ടുണ്ട്.</p> <p>لأن مواضع الضرورة مستثناة من الحرمة كما في تناول الميتة. فتح الملهم</p> <p>എന്നാൽ ആധുനിക സംവിധാനങ്ങളായ ഡിജിറ്റൽ ക്യാമറയിലും മൊബൈലിലും മറ്റും ഫോട്ടോ എടുക്കുന്നതുമായി ബന്ധപ്പെട്ട് ഉലമാക്കൾക്കിടയിൽ&nbsp; അഭിപ്രായവ്യത്യാസം</p> <p>നിലനിൽക്കുന്നുവെങ്കിലും ഇവ ഉപയോഗിച്ച് എടുക്കുന്ന ചിത്രങ്ങൾക്ക് സ്ഥായിയായ രൂപമോ ഭാവമോ ഇല്ലാത്തതിനാൽ ഇൗ ചിത്രങ്ങളെ ഹദീസിലൂടെ തടയപ്പെട്ട تصوير (രൂപം നിർമിക്കൽ) ന്റെ ഗണത്തിൽ പെടുത്താൻ കഴിയില്ല എന്ന് മനസ്സിലാകുന്നു. ഡിജിറ്റൽ ക്യാമറയുടെ പ്രവർത്തന രീതികളെ പറ്റിയുള്ള</p> <p>അറിവും ഇത് ശരി വെയ്ക്കുന്നു.(<a href=\"https://ml.m.wikipedia.org/wiki/%E0%B4%9B%E0%B4%BE%E0%B4%AF%E0%B4%BE%E0%B4%97%E0%B5%8D%E0%B4%B0%E0%B4%BE%E0%B4%B9%E0%B4%BF\">ഛായാഗ്രാഹി - വിക്കിപീഡിയ (wikipedia.org)</a>)</p> <p>&nbsp;</p> <p>ആയതിനാൽ ഇൗ തെളിവുകൾ മുൻ നിർത്തി അത് ഫിലിമുകളിലേക്കോ മറ്റു ഫ്രൈമുകളിലേക്കോ പകർത്താത്തിടത്തോളം ഡിജിറ്റൽ സംവിധാനങ്ങൾ വഴി എടുക്കുന്ന ഫോട്ടോകൾ അനുവദിക്കാവുന്നതാണ്. (فقہی مقالات -&nbsp; 4)</p> <p>എന്നാൽ അമിതമായ സെൽഫി ജ്വരത്തിലേക്കും&nbsp; നിഷിദ്ധമായ കാഴ്ച കളിലേക്കും മറ്റു പല അപകടങ്ങളിലേക്കും ഇത് കൊണ്ടെത്തിക്കുമെങ്കിൽ അനാവശ്യ രൂപത്തിലുള്ള ഇതിന്റെ ഉപയോഗം കർശനമായി ഒഴിവാക്കേണ്ടതാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-22 12:41:10', '2020-05-22 12:41:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0279', 1, NULL, 1, NULL, NULL, 'وطی کرنے والے جانوروں سے نفع اٹھانا مکروہ کی تفصیل', 'اگر کسی نے حلال جانوروں سے وطی کر لی تو اسکا ان جانوروں سے نفع اٹھانا مکروہ ہے وضاحت کر دیں کہ کونسا مکروہ ہے اگر وطی کرنے والے جانوروں سے کوئی نفع اٹھاتا رہے جیسا کہ دودھ بیچ کر پیسے حاصل کرنا اور ان پیسوں سے کپڑے خریدنا اور انہیں کپڑوں میں نماز پڑھنا تو کپڑوں کا اور نماز کا کیا حکم ہے', 'Urdu', 'published', '<p>مندرجہ بالا مسألہ میں کراہت سے مراد کراہت تحریمہ ہے اگر کوئ شحض اس سے نفع اٹھاتے تو نفع انهانے والا گنهگار ہوگا لیکن وہ کپڑا اس كى ملکیت میں آئے گا .اور اس سے نماز پڑھے تو نماز صحيح ہو&nbsp; جاےگا<br /> &nbsp;</p>', 11, 0, 5, '1970-01-01 01:00:00', 1, '2020-12-26 03:39:09', '2024-06-30 10:22:25') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0040', 1, NULL, 1, NULL, NULL, 'RCM', 'Direct Selling ലൂടെ പ്രവർത്തിക്കുന്ന ഒരു കമ്പനിയാണ് RCM. ഇതിൽ ബന്ധപ്പെടുന്നതിന്റെ വിധി എന്താണ്?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2019-11-24 05:23:32', '2024-01-06 05:40:24') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0143', 1, NULL, 2, NULL, NULL, 'Onam ,Christmas , new year ,vishu foods brought by non muslim neighbour to us . Is it acceptable to eat it .', 'എൻറെ അയൽവാസി ഓണം വിഷു ക്രിസ്മസ് ന്യൂ ഇയർ എന്നീ ആഘോഷങ്ങളുടെ ഭാഗമായി ആയി ഭക്ഷണപാനീയങ്ങൾ വീട്ടിൽ കൊണ്ടു വരാറുണ്ട്. അവർ ഹിന്ദുവാണ്. ഇത്തരം ഭക്ഷണ പാനീയങ്ങൾ കഴിക്കുന്നത്.  അതുപോലെ ഓണത്തിന് അവരുടെ വീട്ടിൽ സദ്യ കഴിക്കാൻ ക്ഷണിക്കാറുണ്ട് ഉണ്ട് . അവരുടെ വരുമാനം ഹലാലായതാണ് ,അങ്ങനെയാണെങ്കിൽ എങ്കിൽ അവ കഴിക്കുന്നത് അനുവദനീയമാണോ ?  ', 'Malayalam', 'published', 'അയൽവാസി ഏത് മതക്കാരൻ  എന്ന് നോക്കാതെ അയൽപക്ക ബന്ധം പുലർത്തണം എന്ന് പഠിപ്പിക്കുന്ന മതമാണ് ഇസ്ലാം എന്നാൽ മതപരമായ കാര്യങ്ങളിൽ  ഒരു വിട്ടുവീഴ്ചക്കും ഇസ്ലാം തയ്യാറാകുന്നില്ല لكم دينكم ولي دين   .മറ്റു മതസ്ഥർ നൽകുന്ന ഭക്ഷണപാനീയങ്ങൾ അവരുടെ മതത്തിലെ  ആരാധനയുമായി ബന്ധപ്പെട്ടതാണെങ്കിൽ അത് കഴിക്കൽ ഹറാമാണ്. അവർ നൽകുന്ന ഭക്ഷണം അവരുടെ ആരാധനകളുമായി  ബന്ധപ്പെടാത്തതും ഇസ്ലാം അനുവദിച്ചിട്ടുള്ളതും ആണെങ്കിൽ അത് കഴിക്കൽ അനുവദനീയമാണ് .ഓണം ക്രിസ്മസ് എന്നിവ നിലവിൽ ഒരു മതത്തിൻറെ ആരാധന ആണോ ആ ജനങ്ങളുടെ ആഘോഷം ആണോ എന്ന് വ്യക്തമല്ലാത്തതിനാൽ അവർ നൽകുന്ന ഭക്ഷണങ്ങൾ ഒഴിവാക്കേണ്ടതാണ് .', 21, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-22 14:55:10', '2024-09-14 13:36:46') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0096', 1, NULL, 5, NULL, NULL, 'Is it an authentic hadeeth?', 'Lucky is the woman, whose first child is a daughter Prophet Muhammad (sawa) [al-Kafi, Vol. 2, pg. 6] Is this an authentic hadeeth?', 'English', 'published', '<p>There are many hadeeth mentioned about the virtue of the daughters. But the words mentioned in the question can&#39;t be found in any of the authentic books.&nbsp;<br /> Al Kafi is a basic books of shia community. This wordings are fake apocryphal narration.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-09 09:05:26', '2020-02-09 09:05:26') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0079', 1, NULL, 5, NULL, NULL, 'Is my salary halal or mashbooh or haram?', 'I work in the C&E department of an investment research and investment management firm. My department handles data related to various types, including financial data (7.8%), futures exchanges and options (17%), and economic indicators and statistics (4.9%). The financial data includes information related to interest rates of various banks worldwide, as well as data related to futures contracts and intra-day trading. The remaining data relates to commodities such as agriculture, coal, emissions, energy, European natural gas, European power, freight, metals, natural gas, oil, petrochemical products, power, rig count, and weather. All of this data comes from over 200 commodity exchanges worldwide, and our company analyzes and arranges it for our customers. I work as a system administrator in the C&E department, responsible for maintaining the servers and software that collect this data. I do not directly work with the commodity data on these servers, and I am not even aware of the data\'s values.
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0137', 1, NULL, 1, NULL, NULL, 'ഹലാൽ ആയ ഒരു വരുമാനം എളുപ്പം അവൻ വേണ്ടി എന്തെങ്കിലും അമൽ പറഞ്ഞു തരുമോ?', 'അസ്സലാമു അലൈക്കും ഞാൻ എൻജിനീയറിങ് പടിത്തം കഴിഞ്ഞു 3 വർഷം കഴിഞ്ഞു എന്റെ വിവാഹം കഴിഞ്ഞു എനിക്ക് ഇതു വരെ job ഒന്നും ആയില്ല ഞാൻ job search ചെയ്യ്തു ഗൾഫിൽ പോയി പക്ഷേ ജോബ് കിട്ടിയിട്ടില്ല business തുടങ്ങണമെന്ന് ആഗ്രഹം ഉണ്ട് പക്ഷേ വീട്ടിൽ ആരും അതിനെ സപ്പോർട്ട് ചെയ്യുന്നില്ല, എനിക്ക് വരുമാനം ഒന്നുമില്ല അപ്പോൾ 1. എന്നിക്ക് ഹലാൽ ആയ ഒരു വരുമാനം എളുപ്പം അവൻ വേണ്ടി എന്തെങ്കിലും അമൽ പറഞ്ഞു തരുമോ? 2. ഭാര്യയുടെ ചിലവിനു ഉപയോഗിക്കാൻ എനിക്കു ഫാമിലി ഇൽ ഉള്ളവർ തരുന്ന പൈസ അനുവദനീയം ആണോ? 3. ഞാൻ വീണ്ടും ഗൾഫിൽ job searching വേണ്ടി പോകാൻ ഇരിക്കുകയാണ്, അങ്ങനെ പോകുമ്പോൾ ഭാര്യയും ആയി 4 മാസത്തിൽ കൂടുതൽ പിരിഞ്ഞു ഇരിക്കുന്നതു ശരി ആണോ? ഞാൻ ഹനഫി മദ്ഹബ് ഫോളോ ചെയ്യുന്നു.', 'Malayalam', 'published', '<p>1) أ اللَّهمَّ اكْفِني بحَلالِكَ عَن حَرَامِكَ، وَاغْنِني بِفَضلِكَ عَمَّن سِوَاكَ <br /> എന്ന ദുആ പതിവാക്കുക.  </p> <p><br /> 2) ഫാമിലിയിൽ നിന്ന് ലഭിക്കുന്നത് സദഖയുടെ തുകയാണ് എങ്കിൽ  താങ്കൾക്ക് നിരുപാധികം അത് ഉപയോഗിക്കൽ  അനുവദനീയമാണ്. സക്കാത്തിൻെറ തുകയാണ് എങ്കിൽ ആവശ്യ വസ്തുക്കൾ കഴിച്ച് 612 ഗ്രാം വെള്ളിയുടെ  തുക താങ്കളുടെ കൈവശം ഇല്ലായെങ്കിൽ; ഉണ്ടെങ്കിൽ തന്നെ അതിനെ മികക്കുന്ന കടം താങ്കൾക്കുണ്ട് എങ്കിലും അതും താങ്കൾക്ക് ഉപയോഗിക്കാവുന്നതാണ്.</p> <p><br /> 3) ഭാര്യയുടെ അനുമതിയോടുകൂടി നാലു മാസത്തിൽ കൂടുതൽ ഭാര്യയെ വിട്ടു നിൽക്കുന്നതിന് വിരോധമില്ല.</p>', 6, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-21 03:04:36', '2024-10-23 13:40:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0120', 1, NULL, 5, NULL, NULL, 'പള്ളി പരിപാലനത്തിന് എടുക്കുന്ന കമ്മിറ്റിക്കാർക്ക് വേണ്ട ഗുണങ്ങൾ എന്തെല്ലാമാണ്?', 'പള്ളി പരിപാലനത്തിന് എടുക്കുന്ന കമ്മിറ്റിക്കാർക്ക് വേണ്ട ഗുണങ്ങൾ എന്തെല്ലാമാണ്?', 'Malayalam', 'published', '<p>&nbsp;</p> <p>حامدا ومصليا أما بعد&nbsp;</p> <p>പള്ളി പരിപാലനം, നിർമ്മാണം തുടങ്ങിയ കാര്യങ്ങളുമായി ബന്ധപ്പെടുന്നവർക്ക് വേണ്ട പ്രധാനപ്പെട്ട അഞ്ച് ഗുണങ്ങൾ ഖുർആൻ ശെരീഫ് വ്യക്തമാക്കുന്നുണ്ട്. 1, അല്ലാഹുവിലുള്ള വിശ്വാസം 2, അന്ത്യദിനത്തിലുള്ള വിശ്വാസം 3, നിസ്കാരം കൃത്യനിഷഠയോടെ നിലനിർത്തൽ 4, സകാത്ത് കൊടുക്കൽ 5, നിഷ്കളങ്കത. മേൽ വിവരിച്ച ഗുണങ്ങൾ ഉള്ളവരിൽ മറ്റെല്ലാ ഗുണങ്ങളും ഉണ്ടായിരിക്കുമെന്നത് വ്യക്തമാണ്. ചുരുക്കത്തിൽ പൂർണമായും അല്ലാഹുവിനെ ഭയപ്പെട്ട് ദീനീ നിയമങ്ങളും ചിട്ടകളും മുറുകെ പിടിക്കുന്ന സജ്ജനങ്ങളായിരിക്കണം പള്ളി പരിപാലകർ .&nbsp;&nbsp;<span dir=\"RTL\">الله أعلم بالصواب</span></p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-03-04 05:11:48', '2020-03-04 05:11:48') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0174', 1, NULL, 1, NULL, NULL, 'Why tattoos are haram when male circumcision is halal?', 'Why tattoos are haram while male circumcision is halal and also a sunnah?', 'English', 'published', '<p>&nbsp;Allah has created the human body in the most beautiful way. &nbsp;Allah has forbidden it to be distorted. Therefore, Islam forbids tattooing on body parts. This is because tattooing distorts the human body and unnecessarily causes harm. &nbsp;There are various hadiths also telling us that it causes the wrath of Allah.</p> <p>&nbsp;ابن عباس قال والمستوصلة والمتنمصة والمستوشمة من<br /> &nbsp;(ابو داود -4170)<br /> &nbsp;عبد الله الله لعن الله الواشمة والمستوشمات للحسن للحسن خلق</p> <p>Allah, Who has created the human body in the most beautiful way, is also fully aware of it&#39;s nature. Allah has made circumcision compulsory.<br /> Circumcision is an act practiced by the Prophets and commanded by our beloved Prophet (peace and blessings of Allah be upon him) to follow them.</p> <p>&nbsp;ابو رضي عن عن الله الله عليه الفطره الختان: الخ (الخ)<br /> &nbsp;هريره الله عنه قال قال رسول الله الله عليه وسلم اختتن النبي صلى عليه وسلم ثمانين سنه (رواه البخاري ومسلم)<br /> &nbsp;تعالى: ان</p> <p>Modern science also encourages circumcision. If not circumcised, the genitals are more prone to accumulate impurities under the skin and cause many diseases.</p> <p>Circumcision is therefore obligatory for every Muslim. &nbsp;But a tattoo is a disfigurement of the human body unnecessarily and causing harm.<br /> Hence, it is impermissible.</p>', 113, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-26 02:59:09', '2023-08-28 19:43:50') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0239', 1, NULL, 2, NULL, NULL, 'സിയാറത്', 'ഖബർ സിയാറത് ചെയ്യുമ്പോൾ ഫാത്തിഹ ഓതുന്നത് സുന്നത്തിൽ പെട്ടതാണോ', 'Malayalam', 'published', '<p>ഖബർ സിയാറത്ത് നടത്തുമ്പോൾ ഫാത്തിഹ ഓതൽ പ്രത്യേകം സുന്നത്തില്ല.</p> <p>എന്നാലും സൂറത്തുൽ ഫാത്തിഹ, യാസീൻ, ഇഹ്&zwnj;ലാസ്, തകാസുർ, ആയത്തുൽകുർസി, ആമനറസൂൽ, തുടങ്ങിയ ധാരാളം മഹത്വങ്ങളും പ്രതിഫലങ്ങളും അടങ്ങിയ ആയത്തുകളും സൂറത്തുകളും ഓതി ഹദിയ ചെയ്യൽ മഹത്വമുള്ള കാര്യമാണെന്ന് പണ്ഡിതന്മാർ അഭിപ്രായപ്പെട്ടിട്ടുണ്ട്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-09-24 11:25:25', '2020-09-24 11:25:25') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0202', 1, NULL, 1, NULL, NULL, 'Highrich ഓൺലൈൻ കച്ചവട സ്ഥാപനം', 'Highrich പോലത്തെ ഓൺലൈൻ കച്ചവട സംരംഭങ്ങൾ വഴി വരുമാനവും ലാഭവുമൊക്കെ കരസ്ഥമാക്കുന്നക്കുന്നതിന്റെ ശരീഅത്തിലെ വിധി എന്താണ്?  തെളിവ് സഹിതം മറുപടി പ്രതീക്ഷിക്കുന്നു. ', 'Malayalam', 'published', '<p>ഈ കച്ചവട ങ്ങളുടെ പ്രവർത്തനരീതി വിശദമായി ചോദ്യത്തിൽ ഉൾക്കൊള്ളിക്കുക.</p>', 5, 0, 5, '1970-01-01 01:00:00', 1, '2020-07-20 14:16:11', '2023-08-07 12:34:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0047', 1, NULL, 2, NULL, NULL, 'ഇദ്ദ കാലഘട്ടത്തിൽ പുറത്തു പോകാൻ അനുവാദമുണ്ടോ?', 'വിവാഹ മോചിതരുടെ ഇദ്ദ കാലഘട്ടത്തിൽ ഏതെങ്കിലും മക്കളുടെ വിവാഹ ആവശ്യങ്ങൾക്കോ മറ്റോ പുറത്തു പോകാൻ അനുവാദമുണ്ടോ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2019-11-26 11:26:10', '2019-11-26 11:26:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0068', 1, NULL, 5, NULL, NULL, 'വധുവിന്റെ പിതാവ് നടത്തുന്ന വിവാഹസൽകാരത്തിൽ പങ്കെടുക്കാമോ ?', 'വിവാഹവുമായി ബന്ധപ്പെട്ടു സാധാരണ വധുവിന്റെ പിതാവ് നടത്തുന്ന വിവാഹസൽകാരത്തിൽ പങ്കെടുക്കാമോ ? വിവാഹസമയത്തു മകൾക്കു ലക്ഷക്കണക്കിന് രൂപയുടെ സ്വർണ്ണം നൽകിയതിനാൽ അനന്തരസ്വത്തു ആൺമക്കൾക്ക് മാത്രം നൽകാമോ ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-01-15 05:04:45', '2023-04-16 20:08:50') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0123', 1, NULL, 5, NULL, NULL, 'ലുഡോ അനുവദനീയം ആണോ ?', 'Ludo പോലെ കട്ടകൾ ഉപയോഗിച്ചുള്ള കളികൾ അനുവദനീയം ആണോ?', 'Malayalam', 'published', '<p>ദുൻയാവിലോ ആഖിറത്തിലോ &nbsp;എന്തെങ്കിലും തരത്തിലുള്ള പ്രയോജനങ്ങൾ നൽകാത്തതും ഇസ്ലാമിൽ അനുവദിക്കപ്പെടാത്ത ഏതെങ്കിലും &nbsp;കാര്യം(ഔറത്ത് മറക്കുക, ഇബാദത്തുകൾക്ക് മുടക്കം വരാതിരിക്കുക, ഇബാദത്തുകൾക്കുള്ള സമയം പാഴാക്കുക, തുക പന്തയം വയ്ക്കുക, പോലുള്ളവ) ഉൾക്കൊള്ളുന്നതുമായ എല്ലാ കളികളും അനുവദനീയമല്ലാത്തതാണ്.<br /> ഈ അടിസ്ഥാനത്തിൽ ലൂഡോ പോലുള്ള കളികൾ കളിക്കൽ അനുവദനീയമല്ല. കാരണം അതിൽ പൊതുവേ &nbsp;ഇബാദത്തുകൾക്ക് മുടക്കം വരലും ഇബാദത്തിന് വേണ്ടിയുള്ള സമയങ്ങൾ നഷ്ടപ്പെടുത്തലും ഉണ്ട്.<br /> ഇനി മേൽപ്പറഞ്ഞ കുഴപ്പങ്ങൾ ഇല്ലാത്ത രൂപത്തിലും &nbsp;ദുൻയവിയും ഉഖ്റവിയുമായ യാതൊരു പ്രയോജനവും നൽകാത്ത കളി ആയതുകൊണ്ട് &nbsp;അത്തരം കളികളിൽനിന്ന് നിന്ന് ഒഴിഞ്ഞു നിൽക്കേണ്ടതാണ്.&nbsp;</p> <p>NB : മാനസിക, ശാരീരിക ഉന്മേഷത്തിന് വേണ്ടി, സമയങ്ങൾ ഒരുപാട് പാഴാകാതെ വളരെ കുറഞ്ഞ സമയം&nbsp;കളിക്കുന്നതിന് കുഴപ്പമില്ല.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2020-03-31 00:08:09', '2024-01-26 20:15:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0163', 1, NULL, 5, NULL, NULL, 'പലിശയെ സംബന്ധിച്ച്', '1.ഗൂഗിൾ പേ പോലുള്ളവയിൽ നിന്ന് പണം അയക്കുമ്പോൾ ലഭിക്കുന്ന റിവാർഡുകൾ അനുവദനീയമാണോ? 2.ബങ്കിൽ നിന്ന് ലഭിക്കുന്ന പലിശ ആർക്കൊക്കെ കൊടുക്കാം? പുണ്യം പ്രതീക്ഷിക്കാതെ അത് പ്രായമായവർക്ക്ൽ നകാമോ?', 'Malayalam', 'published', '<p>1) &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ഗൂഗിൾ&nbsp; പേ&nbsp; പോലുള്ളവയിൽ നിന്നും ലഭിക്കുന്ന അവാർഡുകൾ അവരുടെ ഭാഗത്തുനിന്നുമുള്ള സമ്മാനങ്ങളാണ്. സമ്മാനം സ്വീകരിക്കുവാൻ ശരീഅത്തിൽ അനുവാദം ഉള്ളതിനാൽ ഈ റിവാർഡുകൾ സ്വീകരിക്കാവുന്നതാണ് .</p> <p><span dir=\"RTL\">عَن عائِشَةَ رَضِي الله تَعَالَى عَنْهَا قالتْ كانَ رسولُ الله صلى الله عَلَيْهِ وَسلم يقْبَلُ الهدِيَّةَ ويُثيبُ علَيْها. (صحيح البخاري 2585</span>)</p> <p>&nbsp;</p> <p>2) &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;പലിശ പുണ്യം പ്രതീക്ഷിക്കാതെ സകാത്ത് വാങ്ങാൻ അർഹതയുള്ള പാവങ്ങൾക്ക് നൽകേണ്ടതാണ്.<br /> <span dir=\"RTL\">&nbsp;</span></p>', 9, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-21 22:25:09', '2024-09-19 09:53:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0227', 1, NULL, 1, NULL, NULL, 'നിബന്ധന വെച്ച് ത്വലാഖ് പറഞ്ഞാൽ ഭാര്യ ത്വലാഖ് ആകുമോ ?', 'ബഹുമാന്യ പണ്ഡിതരെ, എൻ്റെ ഭാര്യയുമായി കഴിഞ്ഞ രാത്രിയിൽ ഉണ്ടായ ഒരു വഴക്കിൻ്റെ പേരിൽ ഇപ്രകാരം അവളോട് ഞാൻ പറഞ്ഞു<br /> &quot; നിൻ്റെ അവിഷ്യങ്ങൾ എന്നോട് നീ ചോതിച്ചില്ലെങ്കിൽ അന്ന് നീ തലാഖ് ചൊല്ലപ്പെട്ടവൾ ആണെന്ന് നീ മനസ്സിലാക്കി കൊള്ളുക &quot;. ആവിഷ്യങ്ങൾ എന്നത് കൊണ്ടുള്ള ഉദ്ദേശം സാമ്പത്തിക ആവിശ്യം ആണെന്ന് എനിക്കും അവൾക്കും മനസ്സ് കൊണ്ട് അറിയാം, കാരണം ഈ പിണക്കത്തിന് കാരണമായ പ്രശ്നം ഇതുപോലെ ഒന്ന് ആയിരുന്നു, എൻ്റെ ചോദ്യം ഇതാണ് , എൻ്റെയും അവളുടെയും വിവാഹബന്ധം ഇപ്പൊൾ ഏത് അവസ്ഥയിൽ ആണ് ?', 'Malayalam', 'published', '<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; താങ്കളുടെ&nbsp; ഭാര്യ മറ്റൊരാളോട് സാമ്പത്തികമായ സഹായം ചോദിക്കുമ്പോൾ തന്നെ ഒരു ത്വലാഖ് സംഭവിക്കും.ഇദ്ദയുടെ കാലാവധിയിൽ തന്നെ ഭാര്യയെ തിരിച്ചെടുക്കാവുന്നതാണ്.താങ്കളുടെ ഭാര്യക്ക് സാമ്പത്തികമായ&nbsp; ആവശ്യങ്ങൾ വന്നിട്ട് മറ്റാരോടും ചോദിച്ചില്ലെങ്കിൽ ത്വലാഖ് സംഭവിക്കുകയില്ല</p>', 4, 0, 5, '1970-01-01 01:00:00', 1, '2020-08-24 23:24:34', '2024-10-18 08:42:59') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0138', 1, NULL, 5, NULL, NULL, 'പെരുന്നാൾ ദിനങ്ങളിൽ പടക്കം പൊട്ടിക്കുന്നത് അനുവദനീയം ആണോ?', 'പെരുന്നാൾ ദിനങ്ങളിൽ പടക്കം, കമ്പിത്തിരി ഇവ കത്തികുത്തിനെ കുറിച്ച് പണ്ഡിതന്മാരുടെ അഭിപ്രായം എന്താണ്?', 'Malayalam', 'published', '<p>പെരുന്നാൾ ആഘോഷം എങ്ങനെയായിരിക്കണമെന്ന് ഇസ്ലാം വ്യക്തമായി പറയുന്നുണ്ട്. പടക്കം പൊട്ടിക്കൽ പോലുള്ള കാര്യങ്ങൾ ഇസ്ലാം അനുവദിക്കുന്നില്ല, അത് ദുർവ്യയവും ഇതര സമുദായങ്ങളുടെ ആചാരങ്ങളിൽ പെട്ടതും ആണ്. ആയതിനാൽ പടക്കം പൊട്ടിക്കൽ പോലുള്ള ധൂർത്തുകൾ ഹറാമാണ്. ധൂർത്തടിക്കുന്ന വരെ ശൈത്താൻറെ&nbsp;സഹോദരങ്ങൾ എന്നാണ് ഇസ്ലാം വിശേഷിപ്പിക്കുന്നത്. ആരെങ്കിലും മറ്റുള്ള സമുദ്ധയങ്ങളോട് സാദൃശ്യം കാണിച്ചാൽ അവരിൽ പെട്ടവൻ ആകുമെന്ന് നബി തങ്ങൾ സല്ലല്ലാഹു അലൈഹിവസല്ലം അരുളിയിരിക്കുന്നു .</p>', 62, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-21 04:36:23', '2024-09-11 06:31:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0090', 1, NULL, 5, NULL, NULL, 'ചിട്ടിയിൽ കൂടൽ അനുവദനീയം ആണോ ?', 'ഒരു അടവ് നടത്തുന്നവർ എടുക്കുന്ന ചിട്ടിയിൽ കൂടൽ അനുവദനീയം ആണോ ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2020-02-08 23:04:12', '2023-04-16 20:04:38') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0181', 1, NULL, 1, NULL, NULL, 'عيسائي لڑکی سے نکاح جائز ہے یا نہیں', 'السلام عليكم میرا نام عثمان ہے میں پاکستان کراچی شہر سے ہو محترم میں ایک کریسٹن لڑکی سے نکاح کرنا چاہتا ہو جو کے مسلمان نہیں ہونا چاہتی اور وہ پہلے ایک مسلمان کے نکاح میں تھی جس کے ساتھ اس لڑکی کے 18 سال رہ چوکھی تی پر وہ ١٠ ماہ سے الگ ہوگئے تھےالگ الگ ملک میں پر انکا طلاق ابھی ہوا ہے 10 ماہ کے بعد تو اسلام میں اس عورت سے نکاح کرناجائز ہے یا نہیں اور یہ عورت عددت میں بیٹے گی یا نہیں اور اگر بھیٹنا بھی ہوگا تو کتنے وقت کے لئے کیو کے وہ کرسٹن ہے اور 10 ماہ تک وہ اپنے شوہر سے ملی تک نہیں اور انکی آدھی فیملی مسلمان ہے آدھی عیسا ئ کھا نا پینا حلال ہے انکا پر لڑکی حضرت عیسا علیہ سلام کو خدا کا بیٹا مانتی ہے کیا اس سے نکاح جائز ہے یا نہیں اسلام اور قرآن کے روشنی میں اگر جائز ہے تو انکے لئے عدد ت کا کیا طریقہ ہوگا جب کے لڑکی نے خود طلاق لیا ہے ؟', 'Urdu', 'published', '<p>حامدا ومصليا</p> <p>مسیحی عورت سے مسلمانوں کا شادی کرنا بنیادی طور پر جائز ہے تاہم ایسی شادیوں کو رواج دینایاحوصلہ افزائی کرنا غیر مناسب ہے کیونکہ اسکااثر بچوں کےعقائداوران کی  پرورش پرپڑیگاعلماءکرام نے واضح طورپرذکرفرمایاہے کہ یہ شادی مذکورہ وجوہات کی بناء پر مكروه ہے۔<br />  جہاں تک عیسائی عورت کی عدت کامسئلہ ہے تواس کو مسلمان عورت کی طرح ہی عدت مکمل کرنا ہے</p>', 11, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-28 01:56:18', '2023-10-22 08:27:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0187', 1, NULL, 2, NULL, NULL, 'പ്രൊവിഡൻ്റ് ഫണ്ട്', 'ഞാൻ ഒരു പ്രൈവറ്റ് കമ്പനിയിൽ ജോലി ചെയ്യുന്നു. പ്രൊവിഡൻ്റ് ഫണ്ട് വാങ്ങൽ അനുവദനീയമാണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-07-04 22:25:12', '2023-04-16 20:13:45') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0056', 1, NULL, 1, NULL, NULL, 'മരുന്ന് കമ്പനികളുടെ റെപ്രെസെന്ററ്റീവ്സ് തരുന്ന മരുന്ന് ഉപയോഗിക്കുന്നതിന്റെ വിധി എന്താണ്?', 'ഞാൻ ഒരു ഡോക്ടർ ആണ്. മരുന്ന് കമ്പനികളുടെ representatives അവരുടെ മരുന്നിന്റെ പ്രൊമോഷൻ വേണ്ടി എന്നെ കാണാറുണ്ട്. അവർ സാമ്പിൾ മരുന്നുകൾ തരാറുണ്ട്. ആ മരുന്നുകൾ സ്വന്തമായിട്ടോ എനിക്ക് വേണ്ടപ്പെട്ടവർക്കു വേണ്ടിയോ ഉപയോഗിക്കുന്നതിന്റെ വിധി എന്താണ്? മറ്റൊരു ചോദ്യം കൂടി ഉണ്ട്. സ്കാൻ സെന്റർസ് അവരുടെ സ്ഥാപനത്തിലേക്ക് സ്കാൻ എടുക്കാൻ എഴുതിയാൽ ഒരു ചെറിയ ശതമാനം ഡോക്ടറിന് കൊടുക്കാറുണ്ട്. ഇത് വാങ്ങുന്നതിന്റെ വിധി എന്താണ്? ഒഴിവാക്കാൻ പറ്റാത്ത സാഹചര്യത്തിലേ സ്കാനിംഗ് ആണ്. ആ പണം ഡോക്ടർ വാങ്ങിയില്ലെങ്കിൽ സ്കാൻ സെന്റർ തന്നെ എടുക്കും.', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2019-12-05 04:30:18', '2023-04-16 08:47:48') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0022', 1, NULL, 1, NULL, NULL, 'Investment in Share Business', 'What is the ruling of investing in share business?', 'English', 'published', 'The investment scheme and terms and conditions of this company is against the ruling of Sharia. So that, these kinds of dealings are not permissible & the earning through this profit is also haram.', 22, 0, 5, '1970-01-01 01:00:00', 1, '2019-09-29 07:43:07', '2024-05-30 10:50:04') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0024', 1, NULL, 1, NULL, NULL, 'ആർത്തവ രക്തം എങ്ങിനെ കണക്ക് കൂട്ടാം', 'പ്രസവ ശേഷം എത്ര ദിവസം ആണ് ആർത്തവം പുറപ്പെടാൻ ആവിശ്യം, നിയമം വിശതമാക്കുക ?', 'Malayalam', 'published', '<p>ഹനഫി മദ്ഹബിൽ, പ്രസവാനന്തര രക്തസ്രാവത്തിന്റെ (നിഫാസിന്റെ) കാലഘട്ടം പ്രസവശേഷം 40 ദിവസമായി കണക്കാക്കപ്പെടുന്നു. ഈ കാലയളവിനപ്പുറം രക്തസ്രാവം തുടരുകയാണെങ്കിൽ രോഗരക്തമായി പരിഗണിക്കും, ഇനി പ്രസവരക്തം നിന്നതിനു ശേഷം 15 ദിവസം കഴിഞ്ഞ് രക്തം വീണ്ടും കണ്ടാൽ അത് ആർത്തവ രക്തമായി പരിഗണിക്കും, ഇനി പുറപ്പെടുന്നത് 3 ദിവസങ്ങളിൽ കുറവാണെങ്കിൽ രോഗരക്തമായി പരിഗണിക്കും.</p>', 7, 0, 5, '2022-05-09 13:28:27', 1, '2019-10-10 23:31:27', '2023-08-14 10:07:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0208', 1, NULL, 5, NULL, NULL, 'Online ലൂടെയുള്ള വിവാഹം ശരിയാകുമോ ?', 'Online ലൂടെയുള്ള വിവാഹം ശരിയാകുമോ ?', 'Malayalam', 'published', '<p><br /> വരനും വധുവിന്റെ രക്ഷിതാവും, അല്ലെങ്കിൽ അവരുടെ ഭാഗത്തുനിന്ന് ഉത്തരവാദിത്വം ഏൽപ്പിക്കപ്പെട്ട ആളുകൾ(വക്കീൽ), നികാഹിന്റെ സമയത്ത്  ഒരു സ്ഥലത്തുതന്നെ ഉണ്ടായിരിക്കൽ<br />  നിക്കാഹ് ശരിയാകുന്നതിനുള്ള നിബന്ധനകളിൽ പെട്ടതാണ്.  ഓൺലൈനിലൂടെ രണ്ട് പേരും രണ്ട് സ്ഥലങ്ങളിൽ ഇരുന്ന് നിക്കാഹ് ചെയ്യുമ്പോൾ, ചില പണ്ഡിതന്മാരുടെ അടുക്കൽ \"ഓൺലൈൻ\"  ഒരു മജ്‌ലിസ്(സ്ഥലം) ആയി പരിഗണിക്കപ്പെടുന്നതിനാൽ അവരുടെ അടുക്കൽ നിക്കാഹ് ശരിയാകുമെ ങ്കിലും കൂടുതൽ പണ്ഡിതന്മാരും വിവാഹം പോലുള്ള മഹത്തായ ഒരു ഉടമ്പടി കൂടുതൽ സൂക്ഷ്മത പാലിക്കേണ്ട ഒന്നായതിനാൽ നിക്കാഹിൽ \"ഓൺലൈൻ\" ഒരു മജ്ലിസ്(സ്ഥലം)ആയി പരിഗണിക്കാത്തവരാണ് . പ്രസ്തുത നിബന്ധന പാലിക്കാത്തതിനാൽ അവരുടെ അടുക്കൽ \"ഓൺലൈൻ\" നിക്കാഹ് ശരിയാകുന്നതല്ല .</p> <p> ആയതിനാൽ  വരനും വധുവും രണ്ടു സ്ഥലങ്ങളിലായിപ്പോകുന്ന പ്രത്യേക സാഹചര്യങ്ങളിൽ സൂക്ഷ്മത താഴെപ്പറയുന്ന (വക്കാലത്ത് ഏൽപ്പിക്കുന്ന) രണ്ട് രീതികളാണ്. <br />   വധുവിന്റെ രക്ഷിതാവ് (വലിയ്യ്) വരനുള്ള നാട്ടിലെ ഏതെങ്കിലും ഒരു വ്യക്തിയെ തൻറെ മകളുടെ നിക്കാഹ് ചെയ്തു കൊടുക്കുന്നതിന് ഏൽപ്പിക്കുകയും  അതനുസരിച്ച് അദ്ദേഹം സാക്ഷികളുടെ സാന്നിധ്യത്തിൽ  വരന് ആ പെൺകുട്ടിയെ നിക്കാഹ് ചെയ്തു കൊടുക്കുകയും ചെയ്യുക എന്നതാണ് ഒന്നാമത്തെ രീതി.  രണ്ടാമത്തെ രീതി,വരൻ വധുവിന്റെ നാട്ടിലെ ഏതെങ്കിലും ഒരു വ്യക്തിയെ തൻറെ നിക്കാഹ് സ്വീകരിക്കുന്നതിന് വേണ്ടി ഉത്തരവാദിത്വം ഏൽപ്പിക്കുകയും അദ്ദേഹം അതനുസരിച്ച് സാക്ഷികളുടെ സാന്നിധ്യത്തിൽ നിക്കാഹ് സ്വീകരിക്കുകയും ചെയ്യുക എന്നതാണ്', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-08-04 05:34:57', '2023-09-04 05:36:52') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0102', 1, NULL, 1, NULL, NULL, 'രോഗിയുടെ ഹജ്ജ് നിർവഹണം', 'എന്റെ ഭർത്യ മാതാവിന് ഇൗ വർഷം ഹജ്ജ് നിർവഹിക്കുന്നതിന് അവസരം ലഭിച്ചു, വർഷങ്ങളായി അവർക്ക് ഉള്ള ചെവിയിലെ പഴുപ്പ് കാരണം ശുദ്ധി സൂക്ഷിക്കാൻ പടാണ്, ചെവിയിൽ നിന്നും ഒലിച്ച ഇറങ്ങുന്ന പഴുപ്പിൽ ഏത് രീതിയിലുള്ള നടപടിയാണ് കയ്ക്കൊല്ലെണ്ടത്', 'Malayalam', 'pending', NULL, 2, 0, 5, NULL, NULL, '2020-02-10 13:26:38', '2023-04-16 08:49:40') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0248', 1, NULL, 2, NULL, NULL, 'സിയാറത്', 'നബി കാണിച്ചു തന്നെ സിയാറത് എങ്ങനെ ആണ്. ഇന്ന് കാണുന്ന പോലേ സൂറ ഓതി ദുആ ആണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-10-17 10:55:25', '2023-11-02 04:58:34') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0020', 1, NULL, 5, NULL, NULL, 'നബി തങ്ങളുടെ മേൽ സലാത്ത്', 'നബി തങ്ങളുടെ മേൽ സലാത്ത് ചൊല്ലിയാൽ അതിന്റെ പ്രതിഫലം ആർക്കും വീതിച്ച് കൊടുക്കില്ലാ എന്ന് ചില സംസാരങ്ങളിൽ കേട്ടിട്ടുണ്ട് , ഇത് പ്രാമാണികം ആണോ ?', 'Malayalam', 'published', 'ഏറെ അന്യോഷണങ്ങൾക്കും പഠനങ്ങൾക്ക് ശേഷവും ചോദ്യത്തിൽ പ്രതിബാധിച്ച വിഷയത്തിൽ വിശ്വാസയോഗ്യം ആതികരികവും ആയ തെളിവുകൾ ലഭിച്ചില്ല.', 17, 0, 5, '1970-01-01 01:00:00', 1, '2019-09-29 07:40:46', '2024-07-27 04:41:51') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0058', 1, NULL, 1, NULL, NULL, 'ഭാര്യ ഇദ്ദയിരിക്കൽ നിർബന്ധമാണോ ?', 'ഭർത്താവ് മരണപ്പെട്ടാൽ ഭാര്യ ഇദ്ദയിരിക്കൽ നിർബന്ധമാണോ ? അങ്ങനെയിരിക്കണമെങ്കിൽ അതിന്റെ നിയമം എന്താണ് ?', 'Malayalam', 'assigned', 'ഭർത്താവ് മരണപ്പെട്ടാൽ ഭാര്യ ഇദ്ദയിൽ കഴിഞ്ഞുകൂടാൻ നിർബന്ധമാണ്. ഗർഭിണിയല്ലെങ്കിൽ 4 മാസവും 10 ദിവസവും ഗർഭിണിയാണെങ്കിൽ പ്രസവിക്കുന്നത് വരെയും ആണ് മറയിരിക്കേണ്ടത്. ഇദ്ദയിരിക്കുമ്പോൾ ആഭരണങ്ങളും മറ്റു അലങ്കാര വസ്‌തുക്കളും ഉപേക്ഷിക്കേണ്ടതാണ്. ഇദ്ദ എന്നത് കൊണ്ട് വിവക്ഷിക്കപ്പെടുന്നത് വീട് വിട്ട് പുറത്തു പോകാതിരിക്കുക എന്നതാണ്. വീട്ടിന്റെ ഉള്ളിൽ എവിടെ പോകുന്നതിനും മുറ്റത്ത്‌ ഇറങ്ങുന്നതിനുമൊന്നും തടസ്സമില്ല.', 0, 0, 5, NULL, NULL, '2019-12-07 23:19:45', '2019-12-07 23:19:45') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0095', 1, NULL, 1, NULL, NULL, 'ഷാഫി മദ്ഹബ് തഖ്‌ലീദ് ചെയ്‌തു നമസ്‌കരിക്കേണ്ടി വന്നാൽ കുളിയും വുളുവും കൂടി ഷാഫി മദ്ഹബിൽ എടുക്കേണ്ടതുണ്ടോ?', 'ഒരു ഹനഫി മദ്ഹബുകാരന് നിർബന്ധിത ഘട്ടത്തിൽ (ജമ്മും കസറും) ഷാഫി മദ്ഹബ് തഖ്ലീദ് ചെയ്തു നമസ്കരിക്കേണ്ടി വന്നാൽ കുളിയും വുളുവും കൂടി ഷാഫി മദ്ഹബിൽ എടുക്കേണ്ടതുണ്ടോ? (ഹനഫി മദ്ഹബിലെ വുളുവും കുളിയും ഷാഫി മദ്ഹബിൽ ഫർദുകളുടെ നിബന്ധന പൂർത്തിയാക്കാത്തതിൻറെ പേരിൽ)<br /> അതോ ഹനഫി മദ്ഹബിൽ കുളിയും വുളുവും എടുത്തു ഷാഫി മദ്ഹബിൽ നമസ്കരിക്കാമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-02-08 23:50:48', '2023-04-16 20:10:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0203', 1, NULL, 5, NULL, NULL, 'Reading surah yaseen', 'Assalamualikum varahmathullahi vabarakathuhu. After juma prayer of friday,its been said to read 41 times surah yaseen keeping niyyah and to finish it before the coming friday before fajr. It is said; this is doneto fulfill all the wishes. Is it authentic ? Would appreciate an early reply Jazakallahu khair', 'English', 'published', '<p>No such procedure is validated in sharia. Hence it is bid&#39;a(innovation) to do such action pretending to be sunnah.&nbsp;</p> <p>But a person can keep intention of a result &nbsp;experienced action done by scholars in spiritual treatment regarding ruqya.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-07-20 16:16:49', '2024-09-23 09:03:55') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0217', 1, NULL, 1, NULL, NULL, 'Birthday wishing of among muslims', 'Birthday wishing of among muslims', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2020-08-19 03:27:08', '2020-08-19 03:27:08') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0034', 1, NULL, 5, NULL, NULL, 'Transgender വിഭാഗത്തിൽ പെട്ടവർക്ക് ഇസ്ലാം നൽകുന്ന അവകാശങ്ങൾ', 'Transgender വിഭാഗത്തിൽ പെട്ടവർക്ക് ഇസ്ലാം നൽകുന്ന അവകാശങ്ങൾ എന്തെല്ലാം ആണ് ? ട്രാൻസ്‍ജിൻഡർ ഏതെല്ലാം ടൈപ് ഉണ്ട് ? അവരുടെ വിവാഹത്തിന്റെ നിയമം എന്താണ് ? വിശദമായ ഉത്തരം പ്രാക്ടീക്ഷിക്കുന്നു ആനുകാലിക പ്രസക്തി ഉള്ളത് കൊണ്ട്', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2019-11-21 02:53:11', '2019-11-21 02:53:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0054', 1, NULL, 2, NULL, NULL, 'Permissibility of distributing \"Uluhiyah\" raw meat to Non Muslim Neighbours during Eid Al Adha', 'Could you please clarify if its permissible to distribute the \"Uluhiyah\" raw meat to Non mulsim neighbours? If No, then please provide the clear Islamic justification based on Quran & Sunnah and If Yes, then too please provide the clear Islamic justification based on Quran & Sunnah Thank you for your guidance and May Allah (SWT) grant you abundance reward for clarifying this question. Ameen!', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2019-12-03 01:22:16', '2019-12-03 01:22:16') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0060', 1, NULL, 1, NULL, NULL, 'Moulana Saad', 'What is your ruling about Moulana Saad of Banglawali Masjid who has made highly obnoxious comments regarding prophets and is warned by Darul Uloom Deoband.', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2019-12-13 06:15:09', '2019-12-13 06:15:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0043', 1, NULL, 5, NULL, NULL, 'ഹെൽത് ഇൻഷൂർ ചെയ്യാമോ?', 'ഹാർട്ട്, കിഡ്നി, കരൾ, തലച്ചോറ്, ആക്സിഡൻ്റ് മുതലായവയുമായി ബന്ധപ്പെട്ട ചികിത്സകൾ, കാൻസർ പോലുള്ള മാരക രോഗങ്ങളുടെ ചികിത്സകൾ തുടങ്ങിയവ നമ്മുടെ നാട്ടിൽ സാധാരണക്കാർക്ക് താങ്ങാവുന്നതിലും കൂടുതലാണ്, അത്തരം സാഹചര്യങ്ങളിൽ മാത്രം ഉപയോഗിക്കുക എന്ന ലക്ഷ്യത്തോടെ ഹെൽത് ഇൻഷൂർ ചെയ്യാമോ? ഇക്കാര്യത്തിൽ സർക്കാർ / സ്വകാര്യ ഇൻഷൂർ കമ്പനികളുടെ വിധി ഒന്നു തന്നെയാണോ? ഹനഫി / ഷാഫി വിധികൾ പ്രതീക്ഷിക്കുന്നു', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2019-11-26 02:05:29', '2023-04-16 20:03:04') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0223', 1, NULL, 2, NULL, NULL, 'ما حكم استعمال بطاقة الضمان الصحي', '<span dir=\"RTL\">ما حكم استعمال بطاقة الضمان الصحي</span>', 'Arabic', 'published', '<p>جميع أنواع التأمين الصحي المتداولة حاليا مع أقساط التأمين غير ممسوح بها ، لما فى ذلك من الربا والقمار المحظورين المحرمين</p>', 12, 0, 5, '1970-01-01 01:00:00', 1, '2020-08-19 03:43:59', '2023-08-21 18:04:38') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0235', 1, NULL, 1, NULL, NULL, 'സ്ത്രീകളുടെ മയ്യത്ത് നമസ്കാരo', 'സ്ത്രീകളുടെ മയ്യത്ത് നമസ്കാരത്തിന്റെ വിധി എന്താണ് ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-09-21 06:32:56', '2023-11-02 04:57:45') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0251', 1, NULL, 2, NULL, NULL, 'മുഹ്യുദീൻ ഷെയ്ഖ്', 'സഹാബാളേക്കാൾ വളരെ കുറഞ്ഞ പദവി ഉള്ള മുഹ്യുദീൻ ശൈഖിന് പണ്ഡിതന്മാർ വല്ലാത്ത സ്ഥാനം കൊടുക്കുന്നത് കടുത്ത തെറ്റല്ലേ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-10-17 11:10:27', '2023-11-02 05:00:03') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0014', 1, NULL, 1, NULL, NULL, 'ആമ ഇറച്ചി കഴിക്കുന്നതിന്റെ വിധി', 'ഹനഫി മദ്ഹബ് പ്രകാരം ആമ ഇറച്ചി കഴിക്കുന്നതിന്റെ വിധി', 'Malayalam', 'published', 'ഹനഫി മദ്ഹബ് പ്രകാരം ആമ ഇറച്ചി കഴിക്കാൻ പാടില്ല, ഹറാം ആണ്.', 18, 0, 5, '1970-01-01 01:00:00', 1, '2019-09-29 07:27:32', '2024-08-29 18:32:20') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0104', 1, NULL, 5, NULL, NULL, 'അനന്തരസ്വത്ത് ആൺമക്കൾക്ക് മാത്രം നൽകാമോ?', 'വിവാഹസമയത്തു മകൾക്കു ലക്ഷക്കണക്കിന് രൂപയുടെ സ്വർണ്ണം നൽകിയതിനാൽ അനന്തരസ്വത്ത്ആൺമക്കൾക്ക് മാത്രം നൽകാമോ?', 'Malayalam', 'published', '<p>പിതാവിൻറെ ജീവിതകാലത്ത് തൻറെ മക്കളിൽ ഒരാൾക്ക് പിതാവ് സംഭാവന നൽകിയത് കാരണമായി പിതാവിൻറെ മരണശേഷം അർഹമാകുന്ന അനന്തരസ്വത്തവകാശം സംഭാവന ലഭിച്ചയാൾക്ക് നഷ്ടപ്പെടുന്നില്ല. അതിനാൽ വിവാഹസമയത്ത് സ്വർണം ലഭിച്ച സഹോദരിയും പിതാവിൻറെ സമ്പത്തിൻറെ അവകാശിയാണ്. അവരുടെ അവകാശം നിഷേധിക്കൽ കടുത്ത കുറ്റമാണ്, നരകശിക്ഷയ്ക്കു കാരണമാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-11 01:37:32', '2023-12-19 10:53:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0093', 1, NULL, 5, NULL, NULL, 'പാത്രം വടിച്ചു കഴിക്കുന്നതിൻറെ ഫസായിൽ എന്താണ്?', 'ഭക്ഷണം കഴിക്കുമ്പോൾ പാത്രം വടിച്ചു കഴിച്ചാൽ ആ പത്രം അയാൾക്ക് വേണ്ടി ദുആ ചെയ്യും എന്ന് കേട്ടിട്ടുണ്ട്.<br /> ഈ ഫസായിൽ ആധികാരികമാണോ?<br /> പാത്രം വടിച്ചു കഴിക്കുന്നതിൻറെസ്ഥിരപ്പെട്ട ഫസായിൽ എന്താണ്?', 'Malayalam', 'published', '<p><br /> &quot;ഭക്ഷണം കഴിച്ചു കഴിഞ്ഞാൽ പാത്രം വടിച്ചു കഴിക്കുകയാണെങ്കിൽ ആ പാത്രം ആ വ്യക്തിക്കു വേണ്ടി പാപമോചനത്തിനായി ദുആ ചെയ്യും&quot; എന്ന ഹദീസ് തിർമിദി റിപ്പോർട്ട് ചെയ്യുന്ന സ്വഹീഹായ ഹദീസാണ്. ആയതിനാൽ പാത്രം &nbsp;വടിച്ച്കഴിക്കുന്നതുമായി ബന്ധപ്പെട്ട ഈ മഹത്വം ആധികാരികം ആണ്. ഇത് തന്നെയാണ് ഈ വിഷയത്തിൽ സ്ഥിരപ്പെട്ടിട്ടുള്ള മഹത്വവും.</p>', 12, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-08 23:14:01', '2024-08-19 07:31:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0013', 1, NULL, 1, NULL, NULL, 'Is it allowed to eat tortoise?', 'کچھوا کھانا کیسا ہے؟', 'Urdu', 'published', 'کچھوا کھانا حرام ہے واللہ اعلم بالصواب', 25, 0, 5, '1970-01-01 01:00:00', 1, '2019-09-29 07:26:15', '2023-07-13 12:06:37') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0072', 1, NULL, 5, NULL, NULL, 'Erectile dysfunction and Nikah', 'Assalamualaikum Mufti sb situation is like this : suppose &#39;A&#39;(man) is to marry &#39;R&#39;(woman), &#39;A&#39; suddenly suffers from erectic dysfunction after tie up, and for this very reason he delayed nikah ,and is of the opinion till he is not physically fit he won&#39;t go for nikah, except if he is allowed in shariat, &#39;R&#39; is not ready to marry anyone else except &#39;A&#39; and she is well aware about the problem. Now my question is 1. Could they go for nikah? 2. Please mention each and every condition if any', 'English', 'published', '<p><strong>In the Name of Allah, the Most Gracious, the Most Merciful.</strong></p> <p><strong>Assalāmu ῾alaykum wa Rahmatullāhi Wabarakātuh</strong></p> <p>&nbsp;</p> <p>If &lsquo;R&rsquo; agrees to marry &lsquo;A&rsquo; as he is, she may do so. However she cannot come out of &lsquo;A&rsquo; &#39;s marriage due to his erectile dysfunction.</p> <p><strong>And Allāh Ta῾āla Knows Best</strong></p>', 18, 0, 5, '1970-01-01 01:00:00', 1, '2020-01-30 02:43:09', '2024-09-13 06:12:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0171', 1, NULL, 2, NULL, NULL, 'പലിശയെ സംബന്ധിച്ച് ഉള്ള സംശയം?', '1.ഗൂഗിൾ പേ പോലുള്ളവയിൽ നിന്ന് പണം അയക്കുമ്പോൾ ലഭിക്കുന്ന റിവാർഡുകൾ അനുവദനീയമാണോ? 2.ബങ്കിൽ നിന്ന് ലഭിക്കുന്ന പലിശ ആർക്കൊക്കെ കൊടുക്കാം? പുണ്യം പ്രതീക്ഷിക്കാതെ അത് പ്രായമായവർക്ക്നൽകാമോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2020-06-21 22:31:50', '2020-06-21 22:31:50') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0197', 1, NULL, 1, NULL, NULL, 'About the problems of the hearing impaired', 'Assalam O Alaikum Dear Respected Mufti Question No. 1: Is it correct to make the Qur&#39;an in sign language or not? Question No. 2: Do the words of the Qur&#39;an, such as Bismillah-ur-Rehman-ur-Rehman, be recited verbally, or are these words recited with the gestures of the Qur&#39;an with equal hands? Question No. 3: Dumb people are unable to offer words during prayers, so they can remember the gestures of glorification of Surah Al-Fatihah and other bowing and prostration. Will the prayer be performed in this way? Question No. 4: Can a dumb person repeat in his mind the suggestive translations of Qur&#39;anic Surahs in order to humble himself in prayer and to avoid getting lost in thoughts? Question No. 5: What are the rules and regulations that must be followed while teaching and learning the indications of Quranic words? Is it permissible to teach DEF at the same time? Question No. 6: What should be the qualifications of those who make the Qur&#39;an or Surahs in sign language? For example, is it Mufti or Deaf or is it the interpreter of sign language? Regards. Shakeel Qazi, Translator', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-07-19 05:29:37', '2023-11-02 04:56:41') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0230', 1, NULL, 5, NULL, NULL, 'ട്രാൻസ്ജൻഡർ (Transgender) വിഭാഗത്തിൽ പെട്ടവർക്ക് ഇസ്ലാം നൽകുന്ന അവകാശങ്ങൾ എന്തെല്ലാം ആണ് ?', 'ട്രാൻസ്ജെൻഡർ വിഭാഗത്തിൽ പെട്ടവർക്ക് ഇസ്ലാം നൽകുന്ന അവകാശങ്ങൾ എന്തെല്ലാം ആണ് ? ട്രാൻസ്ജൻഡർ (Transgender)  ഏതെല്ലാം ടൈപ് ഉണ്ട് ? എന്താണ് അവരുടെ വിവാഹ നിയമം? വിശദമായ ഉത്തരം പ്രതീക്ഷിക്കുന്നു', 'Malayalam', 'published', '<p>ട്രാൻസ്ജെൻഡേഴ്സ് അവരുടെ ശാരീരിക പ്രകൃതി അനുസരിച്ച് പല വിഭാഗക്കാരാണ്.<br> ഒന്ന് ഏതെങ്കിലും ഒരു ലിംഗം മാത്രമുള്ളവരാണ്, പക്ഷേ ശരീരത്തിലെ ഹോർമോണുകൾ എതിർ വിഭാഗക്കാരുടേതായിരിക്കും.&nbsp;</p> <p>ഇവർക്ക് തന്റെ ലിംഗത്തിനനുസരിച്ച് സ്ത്രീയോ പുരുഷനോ ആയി കഴിയുകയും തന്റെ ലിംഗത്തിന് അനുയോജ്യമായ ഹോർമോൺ ചികിത്സകൾ തേടുകയും ചെയ്യാം.&nbsp;</p> <p>ഇന്നത്തെ സാഹചര്യത്തിൽ ഇവർ തന്റെ ഹോർമോണിനനുസരിച്ച് അവയവമാറ്റ ശസ്ത്രക്രിയ &nbsp;നടത്താറുണ്ട്.ഇത് അനുവദനീയമല്ല.&nbsp;<br> ഹോർമോണുകളെ മാത്രം പരിഗണിച്ച് സ്ത്രീയോ പുരുഷനോ എന്ന് വിലയിരുത്തുന്നതിൽ ദൂരവ്യാപകമായ പ്രശ്നങ്ങൾ സമൂഹത്തിനുണ്ട്.<br> &nbsp;അതുകൊണ്ട് ഇസ്ലാം ഇതിനെ തടയുന്നു.&nbsp;</p> <p>മറ്റൊരു വിഭാഗം രണ്ട് ലിംഗവും ഇല്ലാതെ ഗുഹ്യഭാഗത്ത് ഒരു ദ്വാരം മാത്രം ഉള്ളവരോ അല്ലെങ്കിൽ ഇരു ലിംഗവും ഉള്ളവരോ ആണ് . ഇവർക്ക് മെഡിക്കൽ സംവിധാനങ്ങൾ ഉപയോഗപ്പെടുത്തി ആണോ പെണ്ണോ എന്ന് വ്യക്തമാകുന്ന പക്ഷം എതിർലിംഗം ഒഴിവാക്കാവുന്നതാണ്.&nbsp;</p> <p>ഇവരെ മൂന്നാം വിഭാഗക്കാരായി മാറ്റി നിർത്താതെ പുരുഷനാണൊ സ്ത്രീയാണൊ എന്ന് വിലയിരുത്തി ശരീഅത്തിലെ വിധിവിലക്കുകളായ നോമ്പ്, നമസ്കാരം, വിവാഹം, അനന്തരാവകാശം തുടങ്ങിയ മുഴുവൻ കാര്യങ്ങളിലും ഇസ്ലാം പരിഗണിക്കുകയും, അതു മുഖേന അവരെ സംരക്ഷിക്കുകയും ചെയ്തിരിക്കുന്നു.&nbsp;</p> <p>ഇനി ഒരു നിലയ്ക്കും സ്ത്രീയൊ പുരുഷനോ എന്ന് വ്യക്തമാകുന്നില്ലായെങ്കിൽ അവർക്കുമുള്ള എല്ലാ അവകാശങ്ങളും നൽകി കൊണ്ട് പരിശുദ്ധ ദീൻ പ്രത്യേക വിധിവിലക്കുകൾ നൽകിയിട്ടുണ്ട്. &nbsp;അതനുസരിച്ച് മൂന്നാം വിഭാഗക്കാരായി അവർ കഴിയണം.&nbsp;</p> <p>ട്രാൻസ്ജെൻഡേഴ്സ് പുരുഷനോ സ്ത്രീയോ എന്ന് വ്യക്തമായാൽ വിവാഹം കഴിക്കുന്നതിന് യാതൊരു തടസ്സവും ഇല്ല എന്നാൽ ജെൻഡർ ഒരുവിധത്തിലും തിരിച്ചറിയാൻ സാധിക്കാത്തവർക്ക് വിവാഹം കഴിക്കാൻ പാടില്ല.&nbsp;&nbsp;<br></p> <p><br></p>', 14, 0, 5, '2023-04-06 09:35:51', 1, '2020-09-15 13:42:27', '2024-10-08 20:01:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0231', 1, NULL, 1, NULL, NULL, 'കസേരയിൽ ഇരുന്നുള്ള നമസ്കാരം അനുവദനീയമാണോ?', 'നമസ്കാരം കസേരയിൽ അനുവദനീയമാണോ?  അനുവദനീയമാണോങ്കിൽ ഏത് നിലയിൽ നിർവഹിക്കണം, കസേര എവിടെയാണ് ഇടേണ്ടത്?', 'Malayalam', 'published', '<p>നിന്ന് നമസ്കരിക്കുന്നതിന് കഴിവില്ലാത്ത ഒരു വ്യക്തിക്ക് ഇരുന്ന് നമസ്കരിക്കുന്നതിന് ഇസ്‌ലാമിൽ അനുവാദമുണ്ട്. എന്നാൽ ഈ സാഹചര്യത്തിൽ അദ്ദേഹത്തിന് നിലത്ത് നെറ്റി മുട്ടിച്ച് കൊണ്ട് സാധാരണ ഗതിയിൽ സുജൂദ് നിർവഹിക്കുന്നത് പോലെ സുജൂദ് നിർവഹണം സാധ്യമാണെങ്കിൽ അദ്ദേഹം നിലത്ത്  (സാധ്യമെങ്കിൽ)അത്തഹിയാത്തിന്റെ ഇരുത്തം ഇരുന്ന് കൊണ്ട് അപ്രകാരം നെറ്റി നിലത്ത് മുട്ടിച്ച് സുജൂദ് ചെയ്ത് നമസ്ക്കരിക്കൽ നിർബന്ധമാണ്.  ഇനി നിലത്ത് നെറ്റി മുട്ടിച്ചു കൊണ്ട് സുജൂദ് ചെയ്യുന്നതിന് അദ്ദേഹത്തിന് ഒരു തരത്തിലും കഴിയുന്നില്ലെങ്കിൽ അത്തരം സാഹചര്യങ്ങളിൽ എങ്ങനെ ഇരിക്കലാണോ സാധ്യമാകുന്നത് അങ്ങനെയുള്ള  ഏത് രൂപത്തിലും ഇരുന്ന് ആഗ്യം കാണിച്ച്  നമസ്കരിക്കാവുന്നതാണ്.                                  ഈ  രൂപത്തിൽ കസേരയിൽ ഇരുന്നും അദ്ദേഹത്തിന് നമസ്ക്കാരം നിർവഹിക്കാവുന്നതാണ്.  ഇവിടെ, നിന്ന് ആംഗ്യം കാണിച്ച് നമസ്കരിക്കുന്നതിനേക്കാൾ ഇരുന്ന് ആംഗ്യംകാണിച്ചു നമസ്കരിക്കുന്നതാണ് ഉത്തമം.</p> <p> സ്വഫ്ഫിൽ  ആളുകൾ നിൽക്കുന്നതിന്റെ അതേ നിരയിൽ  തന്നെ കസേര ഇടേണ്ടതാണ് . പുറകിലേക്ക്  ഇറക്കി ഇടുന്നതിലൂടെ സ്വഫ്ഫുകളിൽ വിടവുണ്ടാകും.അത് നബി സല്ലല്ലാഹു അലൈഹിവസല്ലം വളരെ ശക്തമായി തടഞ്ഞതും ഉണർത്തിയതും ആയ കാര്യമാണ്.</p> <p><br /> NB: കസേരയിൽ ഇരുന്നു നമസ്കരിക്കുമ്പോൾ റുകൂളം സുജൂദും ആംഗ്യം കാണിച്ചാണ് നിർവഹിക്കേണ്ടത് .കസേരയിൽ സുജൂദിന് വേണ്ടി പ്രത്യേകം പലക ഘടിപ്പിച്ച് അതിൽ സുജൂദ് ചെയ്താലും ആംഗ്യം കാണിച്ച് നിർവഹിക്കുന്ന സ്ഥാനത്ത് തന്നെയാണ്. നിലത്ത്  നെറ്റി മുട്ടിച്ചു ഉള്ള യഥാർത്ഥ സുജൂദിന്റെ സ്ഥാനത്ത് ആവുകയില്ല.</p>', 26, 0, 5, '1970-01-01 01:00:00', 1, '2020-09-17 03:35:28', '2023-07-31 13:33:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0082', 1, NULL, 2, NULL, NULL, 'ആർത്തവ സമയത്തു സ്ത്രീകൾക്ക് ഖുർആൻ പഠിക്കാമോ?', 'ആർത്തവ സമയത്തു സ്ത്രീകൾക്ക് ഖുർആൻ പഠിക്കാമോ?', 'Malayalam', 'published', '<p>ശാഫി മദ്ഹബിലെ പ്രബലമായ അഭിപ്രായമനുസരിച്ച് ആർത്തവകാരിയായ സ്ത്രീ ഖുർആൻ സ്പർശിക്കലും, പാരായണം ചെയ്യലും ഹറാമാണ്.&nbsp;</p> <p>قال رسول الله صلى الله عليه وسلم لا تقرإ الحائض ولا الجنب شيئا من القران&nbsp; : رواه الترمذي</p> <p>നബി തങ്ങൾ (സ) അരുളി : &nbsp;ആർത്തവകാരിയും വലിയ അശുദ്ധിയുള്ളവരും ഖുർആനിൽ നിന്നും അല്പം പോലും പാരായണം ചെയ്യരുത്.</p> <p>قال رسول اللّٰه&nbsp; صلى الله عليه وسلم لا يمس القرآن الا طاهر</p> <p>റസൂലുല്ലാഹി (സ) അരുളി : ശുദ്ധി ഇല്ലാത്തവർ ഖുർആൻ സ്പർശിക്കരുത്. </p> <p>ആർത്തവകാരി ശബ്ദം വെളിയിൽ വരുന്ന രീതിയിൽ ഖുർആൻ പാരായണം ചെയ്യലാണ് നിഷിദ്ധമായിട്ടുള്ളത്. &nbsp;എന്നാൽ അവൾ ഖുർആനിലേക്ക് നോക്കിയിരിക്കുന്നതിനോ, മനസ്സിൽ ഓർമ്മിക്കുന്നതിനോ, &nbsp;ശബ്ദം വെളിയിൽ വരാത്ത രീതിയിൽ ചുണ്ടുകൾ അനക്കുന്നതിനോ, ഖുർആനിലെ ദുആ ദിക്&zwnj;റുകൾ&nbsp;ദുആയുടെയും ദിക്&zwnj;റിൻറെയും&nbsp;നിയ്യത്തിൽ &nbsp;ഖുർആനെന്ന ഉദ്ദേശ്യം ഇല്ലാതെ &nbsp;ഉച്ചരിക്കന്നതിനോ &nbsp;വിരോധമില്ല.&nbsp;</p> <p>لمن به حدث اكبر اجراء القرآن علي قلبه ونظر في المصحف وقراءة ما نسخت تلاوته وتحريك لسانه وهمسه بحيث لا يسمع نفسه لانها ليست بقراءة القرآن<br /> (مخني المحتاج 1/241) &nbsp;النجم الوهاج 1/384) (الفقه المنهجي 1/384) (حاشية الشرواني)</p>', 7, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-02 01:30:05', '2024-01-05 15:00:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0004', 1, NULL, 1, NULL, NULL, 'ഭാര്യയ്ക്ക് മറ ഇരിക്കൽ നിർബന്ധമാണോ', 'ഭർത്താവ് മരിച്ചു കഴിഞ്ഞാൽ ഭാര്യയ്ക്ക് ഇദ്ദ ഇരിക്കൽ നിർബന്ധമാണോ? അതിന്റെ ആവശ്യം എന്താണ്?', 'Malayalam', 'published', '<p>ഭർത്താവ് മരിച്ച സ്ത്രീ ഇദ്ദ ഇരിക്കൽ നിർബന്ധമാണ്. അതിന്റെ കാരണം അള്ളാഹു തആല കൽപ്പിച്ചു എന്നത് തന്നെയാണ്. ഇനി അതിലെ യുക്തിയാണ് ചോദ്യത്തിന്റെ ഉദ്ദേശമെങ്കിൽ അവയിൽ ചിലത് പരാമർശിക്കുന്നു : 1) മരിച്ചു പോയ ആളുടെ സന്താനം ഭാര്യയുടെ ഉദരത്തിൽ ഉണ്ടെങ്കിൽ അതിന് കളങ്കം വരാതെ മറ്റൊരു വിവാഹം ഉടൻ കഴിക്കാതിരിക്കൽ. 2) തന്റെ സംരക്ഷണം ഇത്രകാലം നിർവഹിച്ചുപോന്ന ഭർത്താവിനോടുള്ള ആദരവും സ്നേഹവും നന്ദിയും അറിയിക്കുവാൻ.</p>', 21, 0, 5, '2023-04-02 09:06:23', 1, '2019-09-29 06:49:15', '2024-10-18 08:40:25') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0106', 1, NULL, 5, NULL, NULL, 'ബിസിനസിൽ പങ്കാളിക്ക് സാലറി എടുക്കാമോ?', 'ബിസിനസിൽ പങ്കാളികളിൽ ഒരാൾ ബിസിനസ് നോക്കി നടത്തുന്നതിൻറെ പേരിൽ അയാൾക്ക് ലാഭവിഹിതം കൂടാതെ സാലറി എടുക്കാമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-03-04 04:11:31', '2023-04-16 08:50:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0185', 1, NULL, 5, NULL, NULL, 'വീഡിയോകൾ നിർമിക്കൽ അനുവദനീയമാണോ?', 'السلام عليكم സ്വർഗം ,നരകം, ഖബർശിക്ഷ തുടങ്ങിയ ഇസ്ലാമിലെ വിശ്വാസ കാര്യങ്ങൾ, ഇസ്ലാമിക ചരിത്രങ്ങൾ എന്നിവ അടിസ്ഥാനമാക്കി സാങ്കൽപ്പികമായ വീഡിയോകൾ നിർമിക്കൽ അനുവദനീയമാണോ?', 'Malayalam', 'published', '<p>ചോദ്യത്തിൽ പരാമർശിക്കപ്പെട്ട രീതിയിലുള്ള വീഡിയോകൾ നിർമിക്കലും അത് ജനങ്ങളിലേക്ക് എത്തിക്കലും അനുവദനീയമല്ല. കാരണം സ്വർഗ്ഗം, നരകം, കബർ ശിക്ഷ, പോലുള്ളവ നമ്മുടെ സങ്കൽപങ്ങൾക്കും അപ്പുറമായതിനാൽ ഇവകളെയെല്ലാം ഒരു വീഡിയോ രൂപത്തിലാക്കി സംപ്രേക്ഷണം ചെയ്യുമ്പോൾ നമ്മുടെ പരിമിതമായ ബുദ്ധിയിലുള്ള സങ്കല്പങ്ങൾക്ക് അനുസൃതമായി മാത്രമേ ജനങ്ങൾക്കു മുമ്പിൽ കാണിക്കുവാൻ സാധിക്കുകയുള്ളൂ. അതുകൊണ്ട് &nbsp;അവകളെ അതിന്റെ പരിപൂർണ്ണമായ രൂപത്തിൽ നിർമ്മിക്കാൻ സാധിക്കാത്തതിനാൽ ഒന്നുങ്കിൽ അവയിൽ ഇല്ലാത്ത പല കാര്യങ്ങളും അതിലേക്ക് ചേർക്കപ്പെടാനും അല്ലെങ്കിൽ &nbsp;വേണ്ട കാര്യങ്ങൾ അതിൽ നിന്ന് നഷ്ടപ്പെടാനും കാരണമാകുന്നു . ആയതിനാൽ ഇത് ഇസ്ലാമിൽ ഇല്ലാത്ത കാര്യങ്ങൾ കെട്ടിച്ചമക്കലാണ്.ദീനിൽ ഇല്ലാത്ത ഒരു കാര്യം ദീനിന്റെ പേരിൽ &nbsp;കെട്ടിച്ചമയ്ക്കൽ ഹറാമായ കാര്യമാണ്. &nbsp;</p> <p>അതുപോലെ തന്നെയാണ് ഇസ്ലാമിക ചരിത്രങ്ങളെ അടിസ്ഥാനമാക്കി വീഡിയോകൾ നിർമ്മിക്കുമ്പോഴും സംഭവിക്കുന്നത് . അതായത് ഇസ്ലാമിലെ ചരിത്രങ്ങൾ ഒരു വീഡിയോ ആയി നിർമ്മിക്കുമ്പോൾ &nbsp;അതിൽ മുഴുവൻ സംഭവങ്ങളും വ്യക്തമായ രീതിയിൽ അതിന്റെ യാഥാർത്ഥ്യത്തോടുകൂടി കാണിക്കൽ അസാധ്യമായതിനാൽ &nbsp;ഇല്ലാത്ത പല സംഭവങ്ങളും ദൃശ്യങ്ങളും കാഥാപാത്രങ്ങളും അതിലേക്ക് കൂട്ടിചേർക്കപ്പെടാനും വേണ്ട കാര്യങ്ങൾ അതിൽ നിന്ന് നഷടപ്പെടാനും കാരണമാവുന്നു.</p> <p>&nbsp;ചുരുക്കത്തിൽ ഒരു മനുഷ്യന്റെ സങ്കല്പങ്ങൾക്കും അപ്പുറത്തുള്ള വിശ്വാസ പരമായ കാര്യങ്ങളെ പരിമിതമായ ബുദ്ധികൊണ്ട് സങ്കൽപ്പിച്ച് അതിൽ യാഥാർത്ഥ്യമായ കാര്യങ്ങളെ പൂർണ്ണമായി ഉൾക്കൊള്ളിക്കാതെ ഇല്ലാത്തവ കൂട്ടിച്ചേർത്ത് &nbsp;വീഡിയോകൾ &nbsp;നിർമ്മിക്കലും അത് ജനങ്ങളിലേക്ക് എത്തിച്ചു കൊടുക്കലും പാപകരമായ കാര്യമാണ്. അത് അനുവദനീയമല്ല.<br /> &nbsp;</p>', 5, 0, 5, '1970-01-01 01:00:00', 1, '2020-07-03 00:49:42', '2024-07-21 02:57:43') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0113', 1, NULL, 1, NULL, NULL, 'ഇഞ്ചക്ഷൻ എടുത്താൽ നോമ്പ് മുറിയുമോ? ', 'ഇഞ്ചക്ഷൻ എടുത്താൽ നോമ്പ് മുറിയുമോ? ', 'Malayalam', 'published', '<p>മനുഷ്യശരീരത്തിലെ സ്വാഭാവിക ദ്വാരങ്ങൾ മുഖേന തലച്ചോറിലേക്കോ വയറിലേക്കോ എന്തെങ്കിലും പ്രവേശിക്കുകയോ അല്ലെങ്കിൽ താൽക്കാലികമായി ഉണ്ടാക്കപ്പെട്ട ദ്വാരങ്ങൾ മുഖേന നേരിട്ട് വയറിലേക്ക് എന്തെങ്കിലും പ്രവേശിക്കുകയോ ചെയ്യുമ്പോഴാണ് നോമ്പ് മുറിയുന്നത്.&nbsp; ഇഞ്ചക്ഷൻ മുഖേന മരുന്ന് ഉള്ളിൽ കടക്കുന്നത്&nbsp; ഞരമ്പുകളിലൂടെയായതിനാൽ&nbsp; നോമ്പ് മുറിയുകയില്ല.</p>', 34, 0, 5, '1970-01-01 01:00:00', 1, '2020-03-04 04:46:14', '2024-04-03 08:41:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0044', 1, NULL, 1, NULL, NULL, 'اپنی زوجہ کو طلاق دینا', 'کیا فرماتے ہیں علماء کرام مندرجہ ذیل مسئلہ کے بارے میں ایک مسئلہ میں اپنی زوجہ کو طلاق دینا چاہا اور مقامی اسٹامپ فروش کے پاس جاکر طلاق لکھنے کو کہا، اسٹامپ فروش نے کچھ یوں لکھا کہ میں اپنی زوجہ کو اپنے بندھن سے آزد کرتے ہوئے طلاق طلاق طلاق دیتا ہوں جبکہ میں نے یہ الفاظ زبانی نہیں کہے اور نہ ہی میں سہ بارے کے بارے میں واقف تھا. میں نے کہیں سنا تھا کی تین دینے سے ایک طلاق واقع ہو تی ہے ، ميرا کا ارادہ صرف ایک طلاق دینا تھا، میں نے سمجھا ایک طلاق واقع کرنے کیلئے تین دفعہ لفظ طلاق لکھنا پڑتا ہے، چنانچہ میں نے دستخط کر دیا اور بذریعہ ڈاک بھیج دیا، یہ جو کچھ مین نے لکھا ہے اللہ کو حاظر وناظر جان کر حلفیہ لکھا ہے. لہٰذا بتلایا جائے کہ کیا میرے لئے زوجہ مذکورہ کو لوٹانے کی گنجائش ہے-', 'English', 'assigned', NULL, 2, 0, 5, NULL, NULL, '2019-11-26 02:11:50', '2019-11-26 02:11:50') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0186', 1, NULL, 5, NULL, NULL, 'Can the interest money be used to pay income tax.Can we use it fir paying electricity and other bills which we feel is not right as per our estimate.', 'The same as short question', 'English', 'published', '<p>If one has accumulated money through interest, that amount must be disposed off to the poor and needy, or it should be used for public needs without the intention of attaining reward. However, it will not be permissible to use interest money to pay income tax, any fines or unjustified bills.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2020-07-03 12:52:19', '2023-06-30 08:03:43') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0234', 1, NULL, 1, NULL, NULL, 'നഗ്നമായി കുളിക്കുന്നതിന്റെ വിധി', 'നഗ്നമായി കുളിക്കുന്നതിന്റെ വിധി എന്താണ് ?', 'Malayalam', 'published', '<p>ജനമധ്യത്തിൽ ആയിരിക്കെ ഔറത്ത് മറക്കൽ നിർബന്ധമായത് പോലെ ഒരാൾ തനിച്ചായിരിക്കുമ്പോഴും ഔറത്ത് മറയ്ക്കൽ നിർബന്ധമാണ്. കാരണം അത് ഇസ്ലാമിക മര്യാദകളിൽ പെട്ടതാണ്. എന്നാൽ കുളി പോലുള്ള ആവശ്യഘട്ടങ്ങളിൽ മറ്റുള്ളവർ തൻറെ ഔറത്ത് കാണാത്ത നിലയിൽ മറയിൽ കുളിക്കുന്ന ആൾക്ക് ഔറത്ത് വെളിവാക്കാമെങ്കിലും മറച്ചുകൊണ്ട് കുളിക്കലാണ് ഏറ്റവും നല്ലത്. തനിച്ചാകുന്ന അവസ്ഥയിൽ പോലും ആവശ്യമില്ലാതെ ഔറത്ത് വെളിവാക്കൽ ഹറാമാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-09-21 06:30:33', '2020-09-21 06:30:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0249', 1, NULL, 2, NULL, NULL, 'ഖബർ കെട്ടി പൊക്കൽ', 'സജ്ജനങ്ങളുടെ ഖബർ കെട്ടിപ്പൊക്കൽ അനുവദനീയം ആണോ. ഇപ്പോൾ അങ്ങനെ ഉള്ള സ്ഥലങ്ങളിൽ നടക്കുന്ന ആചാരങ്ങൾ ശിർക്കിലേക് നയിക്കില്ലേ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-10-17 11:01:11', '2023-11-02 04:58:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0008', 1, NULL, 1, NULL, NULL, 'Multi-Level Marketing അനുവദനീയമാണോ?', 'ഞാൻ Dr. xxx xxx എൻറെ ചോദ്യം MULTI LEVEL MARKETING COMPANY യെ കുറിച്ചാണ്. ഈ കമ്പനി കോസ്മെറ്റിക്സും, മരുന്നുകളും മെഡിക്കൽ പ്രിസ്ക്രിപ്ഷൻ ഇല്ലാതെ മാർക്കറ്റ് ചെയ്യുന്നതിനായി കമ്മീഷൻ ഇനത്തിൽ മെമ്പർമാരെ ആഡ് ചെയ്യുന്നു. ഇതിൽ മെമ്പർഷിപ്പും കമ്മീഷനും ഒരു വർഷത്തേക്ക് ലഭിക്കുന്നതിനായി ഇരുപതിനായിരം രൂപ വിലവരുന്ന കോസ്മെറ്റിക് ഐറ്റംസും മരുന്നുകളും വാങ്ങേണ്ടി വരുന്നു. ഞാൻ ഈ പ്രൊഡക്ട്സ് DIRECT MARKETING ചെയ്യുകയാണെങ്കിൽ അവർ വാങ്ങുന്നതിന്റെ ബിസിനസ് വോളിയമായ 14000 രൂപയുടെ 10% എനിക്ക് ലഭിക്കുന്നതാണ്. അതുകൂടാതെ ഏന്റെ കീഴിലുള്ളവർ മാർക്കറ്റ് ചെയ്ത് ആഡ് ചെയ്യിപ്പിക്കുന്നവരുടെ 9% കമ്പനി ബോണസായും തരുന്നു. ഇതുകൂടാതെ കമ്പനി അനേകം ഓഫറുകളും എനിക്ക് തരുന്നു. എൻറെ (പെർഫോമൻസ് ബോണസ്) കീഴിൽ നിൽക്കുന്നവർ പണിയെടുക്കുന്നത് മൂലമായി ടാർജറ്റ് തുക അച്ചീവ് ചെയ്യുകയാണെങ്കിൽ എനിക്ക് വിദേശ രാജ്യങ്ങളിലേക്കുള്ള യാത്രയും അല്ലെങ്കിൽ യാത്രയുടെ തുക പണമായും കൈപറ്റാവുന്നതാണ്. 
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0041', 1, NULL, 2, NULL, NULL, 'If a person is doing a work of makng wooden elephants', 'If a person is doing a work of makng wooden elephants and selling and his sole income is only through those elephant makng...can we accept the food items or fr us and bakery items they bring as gift for us to our house. Incase we dont use can we give to othe muslim relatives or beighbours or friends?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2019-11-25 23:32:51', '2023-04-16 20:08:04') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0048', 1, NULL, 2, NULL, NULL, 'സയ്യിദിനാ എന്ന പദം സ്വലാത്തിൽ ഉരുപയോഗിക്കാമോ?', 'ഇബ്രാഹിമി സ്വലാത്ത് ചെല്ലുമ്പോൾ അതിൽ സയ്യിദിനാ എന്ന് പറയാമോ അല്ലാഹുമ്മ സല്ലി അലാ സയ്യിദിനാ മുഹമ്മദ്‌ എന്ന്?', 'Malayalam', 'published', '<p>ഹദീസുകളിൽ ഇബ്രാഹീമീ സ്വലാത്തിൽ സയ്യിദിനാ എന്ന പദം സ്ഥിരപ്പെട്ട് വന്നിട്ടില്ലാത്തതിനാൽ സയ്യിദിനാ എന്ന പദം ഒഴിവാക്കി ഹദീസുകളിൽ വന്ന പോലെ ചൊല്ലലാണ് ഏറ്റവും നല്ലതെങ്കിലും നബിതങ്ങളോടുള്ള മാര്യാദയുടെ പേരിൽ സയ്യിദിനാ എന്ന പദം ചേർത്ത് പറയുന്നതിനെ കർമശാസ്ത്ര പണ്ഡിതന്മാർ അനുവദിച്ചിട്ടുണ്ട്.</p>', 14, 0, 5, '1970-01-01 01:00:00', 1, '2019-11-26 11:35:36', '2023-10-28 04:01:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0108', 1, NULL, 5, NULL, NULL, 'ളുഹ്ർ ഖളാ ആക്കുന്നത് ചെറുപാപം ആണോ വൻപാപമാണോ?', 'ജോലിത്തിരക്കിൻറെ പേരിൽ ളുഹ്ർ ഖളാ ആക്കുന്നത് ചെറുപാപം ആണോ വൻപാപമാണോ?', 'Malayalam', 'published', '<p>&nbsp;الجواب، بحمد ربنا و الصلاة على نبينا<br /> ളുഹ്ർ നമസ്കാരം ഒരു വ്യക്തിയുടെ മേൽ ഫർളാക്കപ്പെട്ട അഞ്ചു &nbsp;നമസ്കാരങ്ങളിൽ പെട്ടെ ഒന്നാണ്. &quot;ഫർള്&quot; എന്നത് ഇസ്ലാമിൽ ഒരു ഇബാദത്തിന് &nbsp;നൽകുന്ന ഏറ്റവും ഉയർന്ന വിധിയാണ്, അതിനുമുകളിൽ പ്രാധാന്യമുള്ള മറ്റൊരു വിധിയില്ല. അങ്ങനെ വരുമ്പോൾ ജോലിത്തിരക്ക്, ഇത്രത്തോളം പ്രാധാന്യമർഹിക്കുന്ന ഒരു ഇബാദത്ത് മുടക്കുന്നതിന് മതിയാകുന്ന തരത്തിലുള്ള കാരണമല്ല. ഇത്തരത്തിൽ ജോലിത്തിരക്കിന്റെ പേരിൽ നമസ്കാരം ഖളാ ആക്കൽ ഹറാമാണ് വൻപാപവുമാണ്. അങ്ങനെ സംഭവിച്ചു പോയിട്ടുണ്ടെങ്കിൽ നമസ്കാരം ഖളാ വീട്ടുന്നതിനോടൊപ്പം തൗബ ചെയ്യുകയും ചെയ്യേണ്ടതാണ്.</p> <p>و الله أعلم بالصواب</p>', 4, 0, 5, '1970-01-01 01:00:00', 1, '2020-03-04 04:20:58', '2023-09-04 05:12:06') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0031', 1, NULL, 1, NULL, NULL, 'വുളൂ ചെയ്യുമ്പോൾ കയറ്റി കഴുകൽ', 'വുളു എടുക്കുമ്പോൾ അവയവങ്ങൾ കയറ്റി കഴുകണം എന്ന് കേട്ടു, ശരിയാണോ ?', 'Malayalam', 'published', '<p>വുളൂ ചെയ്യുമ്പോൾ മുഖം, രണ്ട്‌&nbsp;കൈകൾ, രണ്ട്‌&nbsp;കാലുകൾ എന്നിവയുടെ മുഴുവൻ ഭാഗവും കഴുകിയെന്ന് ഉറപ്പ് വരുത്താനായി അൽപം കയറ്റികഴുകൽ വുളൂഇന്റെ മര്യാദയിൽ പെട്ടതാണ്.</p>', 5, 0, 5, '2022-05-09 13:28:27', 1, '2019-11-19 23:03:32', '2024-04-04 20:06:27') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0046', 1, NULL, 1, NULL, NULL, 'അമ്പലം പണിയാൻ വേണ്ടി സിമന്റ്, കട്ട വിക്കൽ അനുവതനീയം ആണോ ?', 'അമ്പലം പണിയാൻ വേണ്ടി സിമന്റ്, കട്ട, ടൈൽസ് മുതലായ വസ്തുക്കൾ വിൽകുന്നതിന്റെയും, ആരാധനക്ക് ഉപയോഗിക്കാനായി ( പ്രസാദം മറ്റും ഉണ്ടാക്കാൻ ) പലചരക്ക് സാധനങ്ങൾ വിക്കലും അനുവതനീയം ആണോ ?', 'English', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2019-11-26 02:23:34', '2019-11-26 02:23:34') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0059', 1, NULL, 5, NULL, NULL, 'ഭാര്യയെ തൊട്ടാൽ wuzhu മുറിയുമോ?', 'ഭാര്യയെ തൊട്ടാൽ wuzhu മുറിയുമോ?..മുറിയുമെന്നാണെങ്കിൽ അപകടമോ മറ്റോ മൂലം സ്വയം wuzhu എടുക്കാൻ പറ്റാത്ത അവസ്ഥയിൽ ഭാര്യായല്ലേ അടുത്ത് സഹായിയായി എപ്പോഴും ഉണ്ടാവുക.അന്നേരം wuzhu എടുപ്പിക്കുവാൻ മറ്റൊരാളെ തെടേണ്ടി വരില്ലേ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2019-12-09 12:36:42', '2019-12-09 12:36:42') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0166', 1, NULL, 5, NULL, NULL, 'പലിശയെ സംബന്ധിച്ച്', '1.ഗൂഗിൾ പേ പോലുള്ളവയിൽ നിന്ന് പണം അയക്കുമ്പോൾ ലഭിക്കുന്ന റിവാർഡുകൾ അനുവദനീയമാണോ? 2.ബങ്കിൽ നിന്ന് ലഭിക്കുന്ന പലിശ ആർക്കൊക്കെ കൊടുക്കാം? പുണ്യം പ്രതീക്ഷിക്കാതെ അത് പ്രായമായവർക്ക്ൽ നകാമോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2020-06-21 22:26:18', '2020-06-21 22:26:18') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0130', 1, NULL, 1, NULL, NULL, 'ലോക്ക് ഡൗണിൽ പെരുന്നാൾ നിസ്കാരം വീട്ടിൽ നിർവഹിക്കാമോ?', 'ലോക്ക് ഡൗണിൽ പെരുന്നാൾ നിസ്കാരം വീട്ടിൽ നിർവഹിക്കാമോ?<br />', 'Malayalam', 'published', '<p>ഇന്ന് ലോകം കടന്നു പോയിക്കൊണ്ടിരിക്കുന്നത് മുമ്പൊരിക്കലും കണ്ടിട്ടില്ലാത്ത പ്രതിസന്ധികളിലൂടെ യാണ്. ഈ സന്ദർഭത്തിൽ പെരുന്നാൾ നമസ്കാരം പ്രാധാന്യമർഹിക്കുന്ന ഒരു വിഷയമാണ്.ജുമുഅയുടെ നിബന്ധനകൾ തന്നെയാണ് പെരുന്നാൾ നമസ്കാരത്തിൻറെ നിബന്ധനയായി വരുന്നതെങ്കിലും ജുമുഅ നഷ്ടപ്പെട്ടാൽ പകരം ളുഹർ ഉണ്ട് പെരുന്നാൾ നമസ്കാരം നഷ്ടപ്പെട്ടാൽ അതിന് പകരം നമസ്കാരം ഇല്ല എന്നത് അത് ഈ വിഷയത്തിന് ഗൗരവം കൂട്ടുന്നുണ്ട്.</p> <p>നിലവിലെ സാഹചര്യത്തിൽ പള്ളികളും ആരാധനാലയങ്ങളും ഒന്നും സുരക്ഷാക്രമീകരണങ്ങളും മുൻകരുതലുകളും പാലിച്ചുകൊണ്ട് പോലും ആളുകൾ &nbsp;ഒരുമിച്ചു കൂടുന്ന തരത്തിൽ തുറന്നു കിട്ടുക ഒരുനിലക്കും സാധ്യമല്ലെങ്കിൽ ഹനഫീ മദ്ഹബ് അനുസരിച്ച് ജുമുഅ നമസ്കാരം നിർബന്ധമായ, &nbsp;പുരുഷന്മാർ പെരുന്നാൾ നമസ്കാരം<br /> വീടുകളിലും മറ്റും നമസ്കരിക്കുകയാണ് വേണ്ടത്. &nbsp;ചെറു ചെറു സംഘങ്ങളായി തിരിഞ്ഞ് സൗകര്യമുള്ള പല പലസ്ഥലങ്ങളിലായി( വീട് മറ്റ് സൗകര്യ &nbsp;സ്ഥലങ്ങൾ) &nbsp;ഒരുമിച്ചുകൂടി &nbsp; പെരുന്നാളിന്റെ &nbsp;രണ്ട് റക്അത്ത് നമസ്കാരംപൂർത്തീകരിക്കുക (ഹനഫി മദ്ഹബ് അനുസരിച്ച് സ്ത്രീകൾക്ക് പെരുന്നാൾ നമസ്കാരം നിർബന്ധമില്ല എങ്കിലും വീടുകളിൽ പുരുഷന്മാരുടെ നമസ്കാരത്തിൽ അവർക്ക് പങ്കെടുക്കാവുന്നതാണ്).<br /> (و شرط لافتراضها) تسعة تختص بها................ (و ذكورة) محققة<br /> قوله:(محققة) ذكره فى النهر بحثا لإخراج الخنثى المشكل ، ونقله الشيخ إسماعيل البرجندى : قبل معاملتهبالأضر تقتضى وجوبها عليه. أقول فيه نظر ، بل تقتضى عدم خروجه إلى مجامع الرجال ولذا لا تجب على المرأة ، فافهم.<br /> (الدر المختارمع رد المحتار------3/27)<br /> (البحر الرائق----3/262)</p> <p>പെരുന്നാൾ നമസ്കാരത്തിന് ഖുതുബ നിർവ്വഹിക്കൽ സുന്നത്ത് മാത്രമേ ഉള്ളൂ അതുകൊണ്ട് പ്രത്യേക സാഹചര്യം കണക്കിലെടുത്ത്, അധികസമയം ഒരുമിച്ച് ഇരിക്കൽ തടസ്സം ഉണ്ടെങ്കിൽ ഖുത്ബ ഉപേക്ഷിക്കാവുന്നതാണ്.<br /> ഓതാൻ സൗകര്യമുണ്ടെങ്കിൽ &nbsp;അധികം ദീർഘിപ്പിക്കാതെ ചെറിയ രൂപത്തിൽ ഓതാവുന്നതാണ്. ഓതിയാൽ സുന്നത്തിന്റെ പ്രതിഫലം കിട്ടും.<br /> (تجب صلاتها) فى الأصح(على من تجب عليه الجمعة بشرائطها ) المتقدمة (سوى الخطبة)فإنها سنة بعدها.<br /> قوله(بشرائطها) متعلقة بتجب الأول و الضمير راجع الجمعة شمل شرائط الوجوب وشرائط الصحة،<br /> (رد المحتار-------3/45,46)<br /> (البحر الرائق--2/276</p> <p>അതുപോലെ &nbsp;പെരുന്നാൾ നമസ്കാരത്തിന് നിശ്ചിത എണ്ണം ആളുകൾ ജമാഅത്തിന് ഉണ്ടായിരിക്കണമെന്നും നിബന്ധനയില്ല. ഇമാമിനോടൊപ്പം ഒരാൾ മാത്രം ആയിരുന്നാലും മതിയാകുന്നതാണ്. എത്രപേർക്കാണോ സാഹചര്യമനുസരിച്ച് ഒരു സ്ഥലത്ത് ഒരുമിച്ചു കൂടാൻ &nbsp;പറ്റുന്നത് അത്രയും ആളുകൾ ഒരുമിച്ചുകൂടി നമസ്കരിക്കാവുന്നതാണ്.<br /> قلت: وفي امامة البحرأن الجماعة فى العيد تسن على القول بسنيتها و تجب على القول بوجوبها اه&zwj;. و ظاهره أنها غير شرط على القول بالسنية، لكن صرح بعده بأنها شرط لصحتها على كل من القولين :أي فتكون شرطا لصحة الاتيان بها على وجه السنة &nbsp;و إلا كانت نفلا مطلقا .تأمل . لكن اعترض ط ما ذكره المصنف &nbsp;بأن الجمعة من شرائطها الجماعة التى هي جمع ، والواحد هنا مع الإمام جماعة كما فى النهر&nbsp;<br /> (رد المحتار مع الدر المختار -----------3/46)<br /> (الفقه الميسر----<br /> (و تؤدى بمصر ) واحد (بمواضع) كثيرة (اتفاقا)<br /> (رد المحتار مع الدر المختار----3/59</p> <p>എവിടെയാണോ പെരുന്നാൾ &nbsp;നമസ്കാരം നിർവഹിക്കുന്നത് അവിടെ &nbsp; നമസ്കരിക്കാൻ വരുന്നതിൽ നിന്നും ആരെയും തടയാത്ത രൂപത്തിൽ അവിടേക്കുള്ള വാതിലുകൾ തുറന്നിടുക. ഇത് പൊതു അനുവാദമുണ്ട് എന്ന് കാണിക്കുവാൻ വേണ്ടിയാണ്, എന്നാൽ നിശ്ചിത സ്ഥലത്ത് &nbsp;ആരെയൊക്കെ കൂട്ടിയാണോ നമസ്കരിക്കാൻ ഉദ്ദേശിക്കുന്നത് അവരെ അല്ലാതെ മറ്റാരെയും പരസ്യമായി അറിയിക്കാതിരിക്കുക.&nbsp;<br /> (فقهى مقالات مع حوالة الكتب الفقهية المعتبرة---31--38 ,ഭാഗം4)</p> <p>മേൽ പറയപ്പെട്ട പ്രകാരം പെരുന്നാൾ നമസ്കാരത്തിന് സാധിക്കാത്തവർ പ്രതിഫലത്തെ ആഗ്രഹിച്ചുകൊണ്ട്صلاة الضحى പോലെ നാല് റക്അത്ത്(രണ്ട് രണ്ട് റക്അത്തുകൾ വീതം) നമസ്കരിക്കുക.<br /> فإن عجز صلى أربعا كالضحى<br /> قوله: (صلى أربعا كالضحى)أي استحبابا كما فى القهستانى وليس هذا قضاء لأنه ليس على كيفيتها ط.<br /> (الدر المختار مع رد المحتار---3/59)<br /> قلت: وهي صلاة الضحى كما فى الحالية عن الخانية ، فقوله تبعا للبدائع &quot; كالضحى&quot; معناه أنه لا يكبر فيها للزوائد مثل العيد. تأمل&nbsp;<br /> (الدر المختار مع رد المحتار---3/59)<br /> (البحر الرائق--2/284)</p> <p>&nbsp;ان فسدت بخروج الوقت أو فاتت عن وقتها مع الامام سقطت ، و لایقضیہا عندنا و قال الشافعی یصلیها وحدها کما یصلی الامام یکبر فیها تکبیرات العید و الصحیح قولنا لأن الصلاة بہذہ الصفة ما عرفت قربة الا بفعل رسول للہ ﷺ کالجمعة ورسول للہ ﷺ ما فعلها الا بالجماعة کالجمعة ، فلایجوز ادائها الا بتلک الصفة و لانها مختصة بشرائط یتعذر تحصلیها فی القضاء فلا تقضی کالجمعة و یصلی اربعا مثل صلاة الضحی ان شاء لانها اذا فاتت لا یمکن تدارکها بالقضاء لفقد الشرائط فلو صلی الضحی لینال الثواب کان حسنا لکن لا یجب لعدم دلیل الوجوب ( بدائع الصنائع ۱/۲۷۹)</p> <p>البحر الرائق__</p> <p><br /> പെരുന്നാൾ നിസ്കാരത്തിൻറെ രൂപം&nbsp;<br /> &nbsp;<br /> വാജിബായ രണ്ട് റക്അത്ത് പെരുന്നാൾ നമസ്കാരം അല്ലാഹുവിനു വേണ്ടി നമസ്കരിക്കുന്നു എന്ന് നീയത്ത് ചെയ്ത്<br /> തക്ബീറതുൽ ഇഹ്റാം പറഞ്ഞ് &nbsp;കൈ കെട്ടി സനാഅ് ഓതിയതിന് ശേഷം രണ്ടു പ്രാവശ്യം തക്ബീർ പറഞ്ഞു കൈകൾ ഉയർത്തി താഴ്ത്തി ഇടുക. മൂന്നാമത്തെ തക്ബീർ പറഞ്ഞു കൈ കെട്ടി ഫാത്തിഹയും സൂറത്തും ഓതുക. റുകൂഉം &nbsp;സുജൂദും കഴിഞ്ഞ് രണ്ടാമത്തെ റക്അത്തിലെ ഫാതിഹയും സൂറത്തും ഓതിയതിനുശേഷം മൂന്നു പ്രാവശ്യം തക്ബീർ പറഞ്ഞ് കൈകളുയർത്തി താഴ്ത്തിയിടുക. നാലാമത്തെ തക്ബീർ പറഞ്ഞ് റുകൂഇലേക്ക്&zwnj; പോകുക. ശേഷം സാധാരണ പോലെ നമസ്കാരം പൂർത്തീകരിക്കുക.<br /> &nbsp;<br /> &nbsp;പെരുന്നാൾ നമസ്കാരത്തിൻറെ ഖുതുബ&nbsp;</p> <p>ഒന്നാമത്തെ ഖുതുബ<br /> اللّہُ اَکْبَرُ،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر․اَلْحَمْدُلِلّہِ رَبِّ العَالَمِینَ وَ الصَّلاةُ وَ السَّلامُ عَلی سَیِّدِنَامُحَمَّدٍخَاتَمِ النَبِیینَ و عَلیَ آلِہِ وَاَصْحَابِہِ أجْمَعِینَ۔أمّا بَعْدُ!فَقَدْ قَالَ اللّہُ تَعَالَی: قَدْ أَفْلَحَ مَن تَزَکَّی ․ وَذَکَرَ اسْمَ رَبِّہِ فَصَلّی․ بَلْ تُؤْثِرُونَ الْحَیَاةَ الدُّنْیَا ․وَالْآخِرَةُ خَیْْرٌ وَأَبْقَی ․ إِنَّ ہَذَا لَفِیْ الصُّحُفِ الْأُولَی․ صُحُفِ إِبْرَاہِیْمَ وَمُوسَی․وَقَالَ رَسُوْلُ اللّہُﷺ:اِنَّ لِکُلِّ قَوْمٍ عِیْداً وَہَذَا عِیْدُنَا۔بَارَکَ اللّہُ لَنَا وَلَکُمْ فِی القُرْآنِ العَظِیْمِ وَ نَفَعَنَا وَ اِیّاکُمْ بِہَدْیِ سِیِّدِ المُرْسَلِینَ</p> <p>രണ്ടാമത്തെ ഖുതുബ</p> <p>اللّہُ اَکْبَرُ،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اللّہُ اَکْبَر،اَلْحَمْدُ لِلّہِ نَحْمَدُہُ وَ نَسْتَعِینُہُ وَ نَسْتَغْفِرُہُ وَ نُوٴْمِنُ بِہِ وَ نَتَوَکَّلُ عَلَیْہِ وَنَعُوذُبِاللَہِ مِنْ شُرُورِأنْفُسِنَا وَ مِنْ سَیِّأتِ أعْمَاْلِنَا،وَ نَشْہَدُأنْ لَا اِلہَ اِلاّ اللّہُ وَ نَشْہَدُأنَّ مُحَمّداًرَسُوْلَ اللَہِﷺوَعَلَی آلِہِ وَصَحْبِہِ وَ بَارَکَ وَ سَلَّمَ۔أمَّا بَعْدُ!قَالَ رَسُوْلُ اللّہِﷺزَکَاةُالفِطْرِطُہْرَةٌلِلصَائِمِ مِنَ اللَغْوِوَالرَّفَثِ وَطُعْمَةٌ لِلمَسَاکِینِ أو کَمَا قَالَ عَلَیْہِ السَّلَا مُ وَقَالَ &nbsp;تَعَالی:َإِنَّ اللّہَ یَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ وَإِیْتَاء ذِیْ الْقُرْبَی وَیَنْہَی عَنِ الْفَحْشَاء وَالْمُنکَرِ وَالْبَغْیِ یَعِظُکُمْ لَعَلَّکُمْ تَذَکَّرُون۔وَلَذِکْرُاللّہِ اَکْبَرُ۔<br /> <br /> &nbsp;സാഹചര്യങ്ങൾക്ക് അനുസൃതമായി മാസ്ക് പോലുള്ള ഉള്ള സുരക്ഷാ ക്രമീകരണങ്ങളും മുൻകരുതലുകളും കൃത്യമായി പാലിക്കുക.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-16 11:25:38', '2023-03-31 06:58:59') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0196', 1, NULL, 1, NULL, NULL, 'ബിസ്ക്കറ്റുകൾ', 'കേരളത്തിൽ ലഭ്യമാകുന്ന കേക്കുകൾ ബിസ്ക്കറ്റുകൾ കൾ ഇവയുടെ ഇൻഗ്രേഡിയൻസുകൾ വായിച്ചു നോക്കുമ്പോൾ അതിൽ പ്രത്യേകിച്ച് എമൾ സിഫയർ എന്ന കാറ്റഗറിയിലുള്ള കുറച്ച് കോഡുകൾ (E- code E471, E472, E473 etc) കാണാൻ സാധിക്കും, ഈ കോഡുകൾ നമ്മൾ നെറ്റിൽ സെർച്ച് ചെയ്യുമ്പോൾ ചിലത് ഉണ്ടാക്കുന്നത് വെജിറ്റബിളിൽ നിന്നാണെന്നും ചിലത് ഉണ്ടാക്കുന്നത് അനിമൽ ഓർ വെജിറ്റബിൾ ഫറ്റിൽ നിന്നാണെന്ന് കാണാൻ സാധിക്കുo. അതുപോലെതന്നെ ആ പാക്കറ്റിന് പുറത്ത് വെജിറ്റേറിയൻ എന്ന് കാണിക്കാൻ വേണ്ടി ഒരു പച്ച ഡോട്ട് നമുക്ക് കാണാൻ സാധിക്കും ഇത്തരം ബേക്കറി പലഹാരങ്ങൾ ചോക്ലേറ്റുകൾ കഴിക്കാൻ നമുക്ക് അനുവാദമുണ്ടോ ?', 'Malayalam', 'published', '<p>അനുവദനീയമാണ്. കൂടുതൽ വിശദീകരണത്തിനായി ചുവടെ ചേർക്കുന്ന ലിങ്കിലെ മറുപടി കാണുക</p> <p><a href=\"https://fatwa.kauzariyya.com/single.php?question=180\">https://fatwa.kauzariyya.com/single.php?question=180</a></p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-07-16 03:03:18', '2020-07-16 03:03:18') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0001', 1, NULL, 5, NULL, NULL, 'MULTI LEVEL MARKETING COMPANY യെ കുറിച്ച്, നിയമം എന്താണ് ?', 'MULTI LEVEL MARKETING COMPANY യെ കുറിച്ച്, നിയമം എന്താണ് ? ഇസ്ലാമിൽ ഒരു കാര്യം അനുവദിനീയമാകുന്നതിന്റെ അടിസ്ഥാനമായി കാര്യങ്ങൾ സഹിതം വിശദമാക്കുക.', 'Malayalam', 'published', '<p><a href=\"https://daruliftakauzariyya.com/answer-details/8\">മറുപടിക്കായി താഴെയുള്ള ലിങ്ക് പരിശോധിക്കുക QID : 8 - Category : Business - Madhab : Hanafi Madhab (daruliftakauzariyya.com)</a></p>', 63, 0, 5, '2022-05-09 13:28:27', 1, '2019-09-18 11:09:40', '2024-08-19 18:22:16') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0036', 1, NULL, 5, NULL, NULL, 'Hadith', 'Hadith حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَمُحَمَّدُ بْنُ الصَّبَّاحِ، قَالاَ حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنِ الزُّهْرِيِّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ عُمَرُ بْنُ الْخَطَّابِ لَقَدْ خَشِيتُ أَنْ يَطُولَ، بِالنَّاسِ زَمَانٌ حَتَّى يَقُولَ قَائِلٌ مَا أَجِدُ الرَّجْمَ فِي كِتَابِ اللَّهِ فَيَضِلُّوا بِتَرْكِ فَرِيضَةٍ مِنْ فَرَائِضِ اللَّهِ أَلاَ وَإِنَّ الرَّجْمَ حَقٌّ إِذَا أُحْصِنَ الرَّجُلُ وَقَامَتِ الْبَيِّنَةُ أَوْ كَانَ حَمْلٌ أَوِ اعْتِرَافٌ وَقَدْ قَرَأْتُهَا الشَّيْخُ وَالشَّيْخَةُ إِذَا زَنَيَا فَارْجُمُوهُمَا الْبَتَّةَ ‏.‏ رَجَمَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَرَجَمْنَا بَعْدَهُ ‏.‏ It was narrated from Ibn`Abbas that `Umar bin Khattab said: \"I fear that after a long time has passed, some will say: \'I do not find (the sentence of) stoning in the Book of Allah (ﷺ),\' and they will go astray by abandoning one of the obligations enjoined by Allah (SWT). Rather stoning is a must if a man is married (or previously married) and proof is established, or if pregnancy results or if he admits it. I have read it (in the Quran). \"And if an old man and an old woman commit adultery, stone them both.\" The Messenger of Allah (ﷺ) stoned (adulterers) and we stoned (them) after him.\' \" English : Vol. 3, Book 20, Hadith 2553 Arabic : Book 20, Hadith 2650 Sunan Ibn Majah It had write in this hadeeth that Umar ra seen in Quran that stoning to death for a married person who commit adultery. But nowhere in the Quran we can see stoning. Is it a contradiction? Does any verses where removed from the Quran? Then why? What is the logic behind that?', 'Malayalam', 'answered', NULL, 3, 0, 5, NULL, NULL, '2019-11-21 02:55:46', '2019-11-21 02:55:46') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0039', 1, NULL, 1, NULL, NULL, 'kiss and suck with younger brother', 'I have a younger brother. He kiss and suck my breast. I kiss his belly and suck his nipple as sign of caress. Is it permissible?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2019-11-24 05:19:27', '2023-11-02 16:16:34') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0033', 1, NULL, 5, NULL, NULL, '40, മരണാനന്തരം പ്രത്യേക മൗലൂദ് ആഘോഷം എന്ന വിശ്വാസത്തെക്കുറിച്ചുള്ള ഇസ്ലാമിക വീക്ഷണം', 'ഒരാൾ മരിച്ചാൽ ആത്മാവ് 40 ദിവസം വീട്ടിൽ ഇരിക്കുമെന്നും 40-ാം ദിവസം സലാം ചൊല്ലി ആത്മാവ് പോകുമെന്നും പറയപ്പെടുന്നു. 40-ാം ദിവസം ആത്മാവിനെ യാത്രയാക്കാൻ പ്രത്യേക മൗലൂദ് സദസും നടക്കും. ഇതിന് എന്തെങ്കിലും അടിസ്ഥാനമുണ്ടോ? ഈ പ്രവൃത്തി മരണപ്പെട്ട ആൾക്കോ 40 ചെയ്തവർക്കോ പ്രതിഫലം നൽകുമോ? ഇതുപോലെ, 3, 40, 365 (ഓരോ വർഷങ്ങൾ തികയുമ്പോൾ) പ്രത്യേക മൗലൂദ് അനുഷ്ഠിക്കുന്നതിന്റെ വിധി എന്താണ് ?', 'Malayalam', 'answered', '<p>മരണശേഷം 40 ദിവസം ആത്മാവ് തങ്ങുകയും പ്രത്യേക മൗലൂദ് ആഘോഷങ്ങൾ നടത്തുകയും ചെയ്യുന്നത് ആധികാരിക ഇസ്ലാമിക സ്രോതസ്സുകളെ അടിസ്ഥാനമാക്കിയുള്ളതല്ല. <br>ഈ വിശ്വാസത്തെ പിന്തുണയ്ക്കുന്നതിന് ഖുർആനിലോ സുന്നത്തിലോ യാതൊരു തെളിവുമില്ല, ഇത് ഒരു സാംസ്കാരികമോ പരമ്പരാഗതമോ ആയ ആചാരമായി കണക്കാക്കപ്പെടുന്നു. <br>മരണപ്പെട്ടയാൾക്ക് ഈ പ്രവർത്തനങ്ങളിൽ നിന്ന് പ്രയോജനം ലഭിക്കില്ല, അവർക്ക് വേണ്ടി ദുആ ചെയ്യുന്നതിലും സൽകർമ്മങ്ങൾ ചെയ്യുന്നതിലും ശ്രദ്ധ കേന്ദ്രീകരിക്കണം. 3, 40, അല്ലെങ്കിൽ 365 ദിവസത്തെ പ്രത്യേക മൗലൂദ് അനുഷ്ഠിക്കുന്നതിനുള്ള വിധിയെ സംബന്ധിച്ചിടത്തോളം, ഇത് ഒരു സ്ഥാപിത ഇസ്ലാമിക ആചാരമല്ല, അത് ഒഴിവാക്കേണ്ടതാണ്. <br>സൽകർമ്മങ്ങൾ അനുഷ്ഠിക്കുന്നതിലും മരണപ്പെട്ട വ്യക്തിക്ക് വേണ്ടി അല്ലാഹുവോട് പാപമോചനം തേടുന്നതിലും ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നതാണ് നല്ലത്.<br></p>', 0, 0, 5, NULL, NULL, '2019-11-21 02:51:45', '2023-04-23 06:15:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0136', 1, NULL, 1, NULL, NULL, 'testing1', 'testing1', 'English', 'published', '<p>tetsing1 answer</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-20 10:27:58', '2023-03-31 12:01:16') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0199', 1, NULL, 2, NULL, NULL, 'Trimming nails and Hair', 'If I am doing Qurbani in another country, should I stop trimming nails and hair when moon of Dul Hijjah is sighted in my place of residency or should I stop trimming when moon is sighted in the country where I have given for Qurbani?', 'English', 'published', '<p>He should stop trimming nails and hair when moon of dul-hijjah sighted on his place of residency because hadees says (if you saw the moon of dul-hijjah and one of you wanted to sacrifice an animal let him hold from his hair and nails</p>', 5, 0, 5, '1970-01-01 01:00:00', 1, '2020-07-19 15:02:00', '2023-10-28 04:03:59') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0273', 1, NULL, 2, NULL, NULL, 'പല്ല് അടയ്ക്കുന്നതിനായി സ്വർണ്ണമോ വെള്ളിയോ ഉപയോഗിച്ചിട്ടുണ്ടെങ്കിൽ വുളു ശരിയാകുമോ ?', 'പല്ല് അടയ്ക്കുന്നതിനായി സ്വർണ്ണമോ വെള്ളിയോ ഉപയോഗിച്ചിട്ടുണ്ടെങ്കിൽ  അതോടൊപ്പം വുളു എടുക്കുന്നതിൻ്റെ നിയമം എന്താണ്? അതിരിക്കുന്നതിനോപ്പം വുളൂ ശരിയാകുമോ ?', 'Malayalam', 'published', '<p>പല്ലിൽ ക്യാപ്പ് ഇട്ടിട്ടുണ്ടെങ്കിൽ അതിരിക്കുന്നതിനോടൊപ്പം വുളൂഉം കുളിയും ശരിയാകുന്നതാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-11-30 00:28:33', '2020-11-30 00:28:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0125', 1, NULL, 2, NULL, NULL, 'مِلے ہوئے سامان کے بارے میں', 'السلام علیکم ورحمۃ اللہ وبرکاتہ جناب عالی کیا راستے میں ملی ہوئی کوئی چیز اپنے پاس رکھنا درست ہے ـ مثلاً روپئے پیسے کمبل وغیرہ وغیرہ؟', 'Urdu', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2020-04-05 08:48:40', '2023-04-16 20:07:06') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0081', 1, NULL, 5, NULL, NULL, 'കെമിക്കൽ മൈലാഞ്ചിയും നിക്കാഹും', 'നിക്കാഹിന്റെ പരിപാടിയുടെ ഭാഗമായി chemical മൈലാഞ്ചി ഉപയോഗിച്ചിരുന്നു. പൂർണമായി മൈലാഞ്ചി ഇളകി പോകാൻ 1 മാസം അടുത്ത് എടുക്കും . അങ്ങനെയാണെങ്കിൽ <br /> 1) നമസ്‌കാരത്തിന്റെ വിധി എന്താണ്?<br /> 2) ഫർദ് കുളി ശരിയാകുമോ?<br /> 3) ഭർത്താവും ആയി വീടുകൂടുന്നതിനു തടസ്സമുണ്ടോ ? ', 'Malayalam', 'published', '<p>حامدا ومصليا<br /> കെമിക്കൽ മൈലാഞ്ചി കളിൽ വെള്ളം &nbsp;ചേരുന്നതിന് തടസമാകുന്ന രീതിയിൽ അതിൻറെ &nbsp;ഘടകങ്ങൾ ശേഷിക്കുന്നുവെങ്കിൽ &nbsp; അതിനെ ഉപേക്ഷിക്കേണ്ടതാണ്, കാരണം ഇത്തരത്തിലുള്ള മൈലാഞ്ചി &nbsp;വുദു ചെയ്യുമ്പോഴും കുളിക്കുമ്പോഴും &nbsp; തൊലിയിൽ വെള്ളം ചേരുന്നതിന് തടസ്സമാകുതാണ് . സാധാരണ മൈലാഞ്ചികളിൽ നിറം മാത്രമാണ് &nbsp; പതിയുന്നത്. പിന്നീട് ആ &nbsp;നിറം &nbsp;മങ്ങലേറ്റ ഘട്ടംഘട്ടമായി മാഞ്ഞുപോവുകയും ചെയ്യുന്നു. എന്നാൽ &nbsp;ചില കെമിക്കൽ &nbsp;മൈലാഞ്ചി കൾ &nbsp;നിറം മങ്ങാതെ &nbsp;അടർന്നു വരുന്നത് ആയിട്ടാണ് കാണപ്പെടുന്നത് . ഇത് ശരീരത്തിൽ ഉണ്ടായിരിക്കെ &nbsp;വുദുഉം കുളിയും ശരിയാക്കുന്നതല്ല<br /> &nbsp;</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-02 00:03:18', '2024-02-06 17:29:22') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0126', 1, NULL, 2, NULL, NULL, 'ഭാര്യക്ക് ഭർത്താവിന് സക്കാത്ത് നൽകാമോ?', 'സകാത്ത് നൽകാൻ പാകത്തിന് ഭാര്യക്ക് സ്വർണമുണ്ട്. പക്ഷെ ഭർത്താവ് കടത്തിൽ ആണ്. കൂടാതെ സ്വന്തം പേരിൽ സ്വത്തുമില്ല. (പക്ഷെ ഭർത്താവിന്റെ മാതാപിതാക്കൾ സമ്പന്നർ ആണ്, പക്ഷെ മകന് സ്വത്ത് കൈമാറിയിട്ടുമില്ല) 1) ഭാര്യയോ ഭർത്താവോ സ്വർണത്തിൻറെ സക്കാത്ത് നൽകണോ? 2) ഭാര്യക്ക് ഭർത്താവിന് സക്കാത്ത് നൽകാമോ?', 'Malayalam', 'published', '<p>1) ഭാര്യയുടെ ധരിക്കുന്നതിന് വേണ്ടിയല്ലാത്ത ആഭരണങ്ങൾക്ക് സകാത്ത് നൽകണം.&nbsp;<br /> 2) ഭർത്താവിന് സക്കാത്ത് നൽകൽ അനുവദനീയമാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-12 18:09:49', '2024-03-27 08:25:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0159', 1, NULL, 5, NULL, NULL, 'Adobe softwares', 'Adobe softwares crack ചെയ്ത് ഉപയോഗിക്കാമോ?(ആ company യുടെ വരുമാനം മുസ്‌ലിംകൾക്ക് എതിരായി ഉപയോഗിക്കുന്ന സാഹചര്യത്തിൽ.)', 'Malayalam', 'published', '<p>ഈ സോഫ്റ്റ്&zwnj;വെയറുകൾ ഉപയോഗിക്കാൻ ലൈസൻസ് വേണമെന്ന നിയമം ഉള്ള രാജ്യങ്ങളിൽ ലൈസൻസ് വാങ്ങാതെ ഉപയോഗിക്കൽ അനുവദനീയമല്ല.</p> <p>(يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ إِلَّا أَن تَكُونَ تِجَارَةً عَن تَرَاضٍ مِّنكُمْ ۚ وَلَا تَقْتُلُوا أَنفُسَكُمْ ۚ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا ( سورة النساء&nbsp;&nbsp;</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-16 09:04:08', '2024-08-28 16:42:51') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0244', 1, NULL, 1, NULL, NULL, 'طلاق کے بارے میں', 'مکرمی السلام علیکم ورحمتہ اللہ وبرکاتہ کیا فرماتے ہیں علمائے کرام اس بارے میں؟ یہ کہ زید شادی شدہ ہے اور اسکے دو بچے ہیں ۔ ایک دن زید کا اپنی بیوی سے کسی بات کو لے کر تنازعہ ہو جاتا ہے تنازعہ اس قدر بڑھتا ہے کہ زید اپنی بیوی کو طلاق دے دیتا ہے اور ایک نشست میں لاتعداد مرتبہ طلاق کے الفاظ استعمال کرتا ہے اور زید کی بیوی اسکے گھر سے چلی جاتی ہے ۔پھر دو دن کے بعد کچھ لوگوں کی ثالثی پر زید اور اسکی بیوی میں صلح ہو جاتی ہے اور عورت دوبارہ زید کے گھر لوٹ آتی ہے اور اسکے ہمراہ رہنے لگتی ہے ۔ تقریباً دو ماہ بھی نہیں گزرتے ہیں کہ دونوں میں دوبارہ تنازعہ شروع ہو جاتا ہے اور زید یہ کہتے ہوئے اس عورت کو گھر سے نکال دیتا ہے کہ وہ تو اسکو دو ماہ قبل ہی طلاق دے چکا ہے ۔ تو کیا پہلی نشست میں زید اور اسکی بیوی کے درمیان طلاق ہوگیا ؟ اگر طلاق ہوگیا تو دونوں کا ایک ساتھ دو ماہ گزارنا کیسا ہے؟ نوٹ۔۔۔۔۔۔ زید نے فقط طلاق کا لفظ استعمال کیا اسکی نوعیت بیان نہیں کی', 'Urdu', 'published', '<p>الجواب :زید نے ایک &rlm; &rlm;دفعہ &rlm;طلاق کا لفظ کہنے کے بعد &nbsp;باربار محض تاکید کی نیت ہے لفظ طلاق دہرایا ہے . اور جدید طلاق کی نیت نہیں کی تو دیانة ایک رجعی طلاق واقع ہوگی . تین حیض کی مدت کے اندر اندر صلح کرکے واپس آنا ہی رجعت ہے دونوں کا ایک ساتھ دو ماہ گزارنا جائز تہا&nbsp;<br /> &nbsp;</p>', 4, 0, 5, '1970-01-01 01:00:00', 1, '2020-10-03 10:01:30', '2024-02-02 16:36:13') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0188', 1, NULL, 2, NULL, NULL, 'അമിത വൈകാരികതയുള്ള എന്നാൽ നിക്കാഹ് കഴിക്കാൻ കഴിയാത്തവർക്ക് സ്വയംഭോഗം‌ അനുവദനീയമോ..?', 'ഞാൻ 22 വയസ്സ് പ്രായമുള്ള യുവാവാണ്. അല്ലാഹുവിന്റെ‌ ദീൻ സൂക്ഷിച്ച് പരിശുദ്ധിയോടെ ജീവിക്കാൻ അങ്ങേയറ്റം ആത്മാർഥമായി ആഗ്രഹിക്കുന്നു.‌ പക്ഷേ നഫ്സിന്റെ അമിതമായ വൈകാരികതയും, എന്നാൽ ഹലാലായ നിക്കാഹ് ചെയ്യാൻ വീട്ടുകാർ ഒരു‌തരത്തിലും അനുവദിക്കാത്ത അവസ്ഥയുമാണ് ഇപ്പോൾ ഉള്ളത്. വികാരം നിയന്ത്രിക്കാൻ കഴിയാത്ത സന്ദർഭത്തിൽ ഹറാമിലേക്ക് പോകാതിരിക്കാൻ സ്വയംഭോഗം‌ അനുവദനീയമാണോ..? എത്രയും‌ വേഗം നിക്കാഹ് നടക്കാനും, അതിനുള്ള മഈഷത്തിനുമുള്ള ഒരു‌ ദുആ നിർദ്ദേശിക്കാമോ..? കണ്ണിനെ നിയന്ത്രിക്കാനുള്ള ഏറ്റവും ഫലപ്രദമായ മാർഗ്ഗങ്ങൾ പറയാമോ..?', 'Malayalam', 'published', '<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ശറഇയ്യായ കാരണങ്ങളില്ലാതെയാണ്&nbsp; വീട്ടുകാർ വിവാഹത്തിന് തടസ്സം നിൽക്കുന്നതെങ്കിൽ അവരെ അനുസരിക്കൽ നിർബന്ധമല്ല. വീട്ടുകാരെ കാര്യങ്ങൾ പറഞ്ഞു ബോധ്യപ്പെടുത്താൻ ശ്രമിക്കുക. വികാരം നിയന്ത്രിക്കാൻ സാധിക്കാത്ത സന്ദർഭത്തിൽ ഹറാമിലേക്ക് പോകാതിരിക്കാൻ ആണെങ്കിൽ പോലും സ്വയംഭോഗം&nbsp; അനുവദിനീയമല്ല.</p> <p>&nbsp;</p> <p>&nbsp;<strong>കണ്ണിനെ നിയന്ത്രിക്കാനുള്ള ഫലപ്രദമായ മാർ</strong><strong>ഗങ്ങ</strong><strong>ൾ</strong></p> <p>&nbsp;</p> <ol> <li>സദാസമയവും അല്ലാഹു നമ്മെ നിരീക്ഷിച്ചുകൊണ്ടിരിക്കുന്നുണ്ടെന്നും കണ്ണുകളുടെ&nbsp; കട്ടു നോട്ടങ്ങൾ പോലും അല്ലാഹു അറിയുന്നുണ്ടെന്നും ബോധ്യം ഉണ്ടാവുക.</li> <li>ഹറാമായ&nbsp; നോട്ടങ്ങളിലേക്ക് എത്തിക്കുന്ന സാഹചര്യങ്ങൾ ഒഴിവാക്കുക&nbsp;</li> <li>കണ്ണുകളെ ഹറാമിൽ നിന്ന് സംരക്ഷിക്കാൻ ആത്മാർത്ഥമായി അല്ലാഹുവിനോട് ദുആ ചെയ്യുക.</li> <li>സജ്ജനങ്ങളുമായുള്ള സഹവാസം വർദ്ധിപ്പിക്കുക</li> </ol> <p>&nbsp;പ്രസ്തുത ആവശ്യ പൂർത്തീകരണത്തിനായി താഴെക്കാണുന്ന ദുആകൾ രാവിലെയും വൈകുന്നേരവും പതിവാക്കുക.</p> <p><br /> (يا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِي كُلَّهُ وَلَا تَكِلْنِي إِلَي نَفْسِي طَرْفَةَ عَيْنٍ (سنن النسائ)&nbsp;<br /> (اللهم أَنْتَ خَلَقْتنِي وَأَنْتَ تَهْدِينِي وَأَنْتَ تُطْعِمُنِي وَأَنْتَ تَسْقِينِي وَأَنْتَ تُمِيتُنِي وَأَنْتَ تُحْيِينِي (طبران)</p>', 10, 0, 5, '1970-01-01 01:00:00', 1, '2020-07-05 03:31:20', '2024-05-05 13:58:34') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0215', 1, NULL, 1, NULL, NULL, 'ഞണ്ട്, കൂന്തൾ, കക്ക, കല്ലുമ്മക്കായ എന്നിവ കഴിക്കാമോ?', 'ഞണ്ട്, കൂന്തൾ, കക്ക, കല്ലുമ്മക്കായ എന്നിവ കഴിക്കാമോ? ഗിനിപ്പന്നിയെ വളർത്താമോ? അതിനെ കഴിക്കാമോ?', 'Malayalam', 'published', '<p>സമുദ്രത്തിൽ നിന്നും ലഭിക്കുന്ന മത്സ്യം ഒഴികെയുള്ളവയെ കഴിക്കൽ അനുവദനീയമല്ല. ഞണ്ട്, കൂന്തൾ ,കക്ക, കല്ലുമ്മക്കായ, മുതലായവയെ മത്സ്യത്തെ സംബന്ധിച്ച് അവഗാഹമുള്ളവർ മത്സ്യ ഗണത്തിൽപ്പെടുത്താത്തതിനാൽ അവയെ കഴിക്കൽ അനുവദനീയമല്ല.<br /> &nbsp;ചെമ്മീനിന്റെ വിഷയത്തിൽ അഭിപ്രായ വ്യത്യാസം ഉണ്ട് .എങ്കിലും അഷ്റഫ് അലി ത്വാനവി (റ) യെ പോലെയുള്ള പ്രഗൽഭരായ പണ്ഡിതന്മാർ അതിനെ മത്സ്യത്തിന്റെ ഗണത്തിൽപ്പെടുത്തിയതിനാൽ അതിനെ കഴിക്കൽ അനുവദനീയമായി കണക്കാക്കപ്പെടുന്നു.<br /> &nbsp;ഗിനിപ്പന്നി പന്നിയുടെ വർഗ്ഗത്തിൽ പെട്ടതല്ലാത്തതിനാൽ ഇവകളെ വളർത്തൽ അനുവദനീയമാണെങ്കിലും എലിയുടെ&nbsp;<br /> ഗണത്തിൽ മനസ്സിലാക്കപ്പെടുന്ന ഇവകളെ കഴിക്കൽ അനുവദനീയമല്ല<br /> &nbsp; &nbsp; &nbsp; &nbsp;</p>', 15, 0, 5, '1970-01-01 01:00:00', 1, '2020-08-19 03:23:56', '2024-06-30 20:28:36') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0121', 1, NULL, 5, NULL, NULL, 'നമസ്‌കാരത്തിന് മാത്രം ഫാൻ ഓൺ ചെയ്യുന്ന പള്ളി കമ്മിറ്റിക്കാരുടെ പതിവ് അനുവദനീയം ആണോ?', '<ol> നമസ്‌കാരത്തിന് മാത്രം ഫാൻ ഓൺ ചെയ്യുന്ന പള്ളി കമ്മിറ്റിക്കാരുടെ പതിവ് അനുവദനീയം ആണോ? ഇബാദത് ചെയ്യാൻ വരുന്നവരെ ഫാൻ ഉപയോഗിക്കുന്നതിൽ നിന്ന് തടുക്കാമോ? </ol>', 'Malayalam', 'published', '<p>നിസ്കാരത്തിന് മാത്രം ഫാൻ ഓൺ ചെയ്യുന്ന പള്ളിക്കമ്മറ്റിക്കാരുടെ പതിവ് അനുവദനീയമാണോ? ഇബാദത്ത് ചെയ്യാൻ വരുന്നവരെ ഫാൻ ഉപയോഗിക്കുന്നതിൽ നിന്നും തടുക്കാമോ?</p> <p>&nbsp;</p> <p><span dir=\"RTL\">الجواب</span> <span dir=\"RTL\">حامدا</span> <span dir=\"RTL\">ومصليا</span>.......</p> <p>വാഖിഫിന്റെ ഉദ്ദേശം അനുസരിച്ചു മാത്രമെ വഖ്ഫ് ചെയ്യപ്പെട്ടവസ്തുക്കൾ ഉപയോഗിക്കാവൂ. നമ്മുടെ നാടുകളിൽ ജനങ്ങൾ സാധാരണ സ്പോൻസർ ചെയ്തും, എല്ലാവരും ചേർന്ന് പിരിവിട്ടുമാണ് ഫാൻ, ലൈറ്റ് മുതലായവ വാങ്ങിക്കുന്നത്. പള്ളിയുടെ ആവശ്യങ്ങൾക്ക് എന്ന് മാത്രമെ എല്ലാവരും ഈ സന്ദർഭത്തിൽ കരുതുകയും ചെയ്യുകയുള്ളൂ. ജമാഅത്തിന് മാത്രം എന്ന ഉദ്ദേശം വെക്കാറില്ല. അത്തരം പള്ളികളിൽ ഫാൻ ഉപയോഗം എല്ലാവർക്കും എപ്പോഴും അനുവദിക്കേണ്ടതാണ്. ഇബാദത്തിനായി വരുന്നവരെ അതിൽ നിന്നും തടയരുത്. അതിനോടൊപ്പം അനാവശ്യ ഉപയോഗം തടയാൻ പരിപാലകർ സംവിധാനം ഏർപ്പെടുത്തേണ്ടതുമാണ്.</p> <p>&nbsp;</p> <p><span dir=\"RTL\">الله أعلم بالصواب</span></p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2020-03-04 05:14:02', '2024-11-04 10:41:53') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0092', 1, NULL, 5, NULL, NULL, 'താടി വടിക്കൽ അനുവദനീയം ആണോ? ', 'താടി വടിക്കൽ അനുവദനീയം ആണോ? <br /> താടി വെട്ടി ചുരുക്കാമോ ?<br />  ', 'Malayalam', 'published', '<p>حامدا ومصليا أما بعد&nbsp;</p> <p>ഈ വിഷയത്തിൽ ഷാഫി മദ്ഹബിൽ വിഭിന്നമായ അഭിപ്രായങ്ങളാണുള്ളത്.ഭൂരിഭാഗം പിൻഗാമികളായ പണ്ഡിതന്മാരുടെയും അഭിപ്രായത്തിൽ താടി വടിക്കൽ ഹറാമാണ്.എന്നാൽ ശാഫി മദ്ഹബിലെ പ്രബലമായ അഭിപ്രായമനുസരിച്ച് താടി വടിച്ചക്കലും വെട്ടലും കറാഹത്താണ്. എന്നാൽ ഹനഫി മദ്ഹബിൽ താടി വടിക്കലും ഒരു പിടിയേക്കാൾ കുറച്ചു വെട്ടലും ഹറാമാണ്.ഈ വിഷയത്തിൽ പണ്ഡിതന്മാരുടെ കടുത്ത നിലപാടിലൂടെ നമുക്ക് മനസ്സിലാക്കാൻ കഴിയുന്നത് ഒരു പിടിയോളമെങ്കിലും താടി വളർത്തൽ എല്ലാ മുഅമിനീങ്ങൾക്കും അത്യാവശ്യമാണ് എന്നുള്ളതാണ്</p>', 114, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-08 23:09:02', '2024-10-25 20:58:40') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0264', 1, NULL, 5, NULL, NULL, 'വീട് പണിയിൽ വാസ്‌തു നിയമം തേടലും സ്ഥാനം നോക്കലും', 'വീട് വെക്കുമ്പോൾ വാസ്‌തു നിയമം നോക്കി സ്ഥലം തീരുമാനിക്കുന്നതിന്  ഇസ്ലാമിൽ വല്ല അടിസ്ഥാനവും ഉണ്ടോ? <br /> കേരളക്കരയിൽ  ഇത് വ്യാപകമാണ്. ഉണ്ടാക്കിയ ബാത്രൂം പൊളിക്കാനും സ്ഥാനം മാറ്റാനും ഗോവണി മാറ്റി പണിയാനും ചിലർ പറയുന്നു. ഇസ്‌ലാമിന്റെ ലേബലിൽ പറയപ്പെടുന്ന ഈ കാര്യങ്ങൾക്ക് ദീനുൽ ഇസ്‌ലാമുമായി വല്ല ബന്ധവും ഉണ്ടോ?', 'Malayalam', 'published', '<p>വീട് വെക്കുമ്പോൾ വാസ്തു നിയമം നോക്കി &nbsp;സ്ഥലം നിശ്ചയിക്കുക ഉണ്ടാക്കിയ ബാത്രൂം പൊളിക്കുക സ്ഥാനം മാറ്റുക &nbsp;ഗോവണി മാറ്റി പണിയുക തുടങ്ങിയ &nbsp;ഒന്നിനും &nbsp;ദീനുൽ ഇസ്ലാമിൽ യാതൊരു അടിസ്ഥാനവുമില്ല &nbsp; ഇതുപോലുള്ള എല്ലാവിധ അനിസ്ലാമിക ആചാരങ്ങളും മറ്റു സംസ്കാരങ്ങളിൽ നിന്നും ഇസ്ലാമിലേക്ക് കടന്നുവന്നത് ആണ് ഇസ്ലാമിൽ ഇതിന് യാതൊരു അടിസ്ഥാനവുമില്ല നബി തങ്ങളിൽ നിന്നോ &nbsp;സ്വഹാബത്തിൽ നിന്നോ സ്വാലിഹീങ്ങളിൽ നിന്നോ &nbsp;ഇതിന് യാതൊരു തെളിവുകളും ലഭിച്ചിട്ടില്ല ഇത്തരം അന്ധവിശ്വാസങ്ങൾ &nbsp; ഒരു മുസ്ലിമിന് &nbsp;ഉണ്ടായാൽ അത് അവൻറെ ഈമാനിനെ തന്നെ ബാധിക്കുന്നതാണ് &nbsp;അതിനാൽ ഒരു മുസ്ലിം തൻറെ വീട് നിർമ്മാണ സമയത്ത് ഈ രീതിയിൽ സ്ഥാനം നിർണയിക്കുന്ന വരെയോ ആശ്രയിക്കാൻ &nbsp; &nbsp;പാടില്ല</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2020-11-17 04:58:20', '2023-08-15 09:02:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0003', 1, NULL, 1, NULL, NULL, 'Investment Scheme & referral income', 'Is possible in Hanafi madhab investment Scheme. and earning profit. My doubt is i see a website about a company named DMG ( Dream makers global) The company offers a scheme if we invest 6000 rupees or its multiples to this company we will got 15000 after 5 months. The whole amount not got fully at a time but we will get daily 100 rupees. If we invest 12000 we will got 30000 after 5 months .The higher amount is 960000 and we will got 2400000 after 5 months. The company is mainly done gold silver crude oil Foreign currency exchange etc. Is it possible in Hanafi madhab? I have another doubt 2) if i joined a person to this company the company offers half of their investment will be got in my account. If the new member invest 18000 we will got 9000 after 5 months .it is called referral income. Is it possible in Hanafi madhab', 'English', 'published', 'The investment scheme and terms and conditions of this company is against the ruling of Sharia. So that, these kinds of dealings are not permissible & the earning through this profit is also haram.', 37, 0, 5, '1970-01-01 01:00:00', 1, '2019-09-29 06:47:36', '2024-08-19 18:23:15') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0098', 1, NULL, 2, NULL, NULL, 'ആൺ കുട്ടികൾക്ക് എത്ര വയസ്സ് വരെ സ്വർണം ഇടാൻ അനുവാദം ഉണ്ട്?', 'ആൺ കുട്ടികൾക്ക് എത്ര വയസ്സ് വരെ സ്വർണം ഇടാൻ അനുവാദം ഉണ്ട്?', 'Malayalam', 'published', '<p>الجواب وبالله التوفيق</p> <p>പ്രായപൂർത്തിയാകാത്ത ചെറിയ കുട്ടികൾക്ക് സ്വർണം ധരിക്കാൻ അനുവാദമുണ്ട് .എന്നാൽ ഈ വിഷയത്തിൽ തന്നെ ഇമാമുകൾക്കിടയിൽ അഭിപ്രായവ്യത്യാസമുള്ളതിനാലും പ്രായപൂർത്തിയായ ശേഷം ധരിക്കൽ ഹറാം ആയതിനാലും ആ പതിവ് മുതിർന്ന കുട്ടികൾക്ക് നേരത്തെ തന്നെ ഒഴിവാക്കേണ്ടതാണ് ആയതിനാൽ രണ്ടു വയസ്സിനു ശേഷം ധരിക്കരുതെന്നാണ് ആണ് ഇമാം بغوي യെ പോലുള്ള പ്രഗൽഭ പണ്ഡിതന്മാർ അഭിപ്രായപ്പെട്ടിട്ടുള്ളത്الله اعلم بالصواب</p>', 64, 0, 5, '1970-01-01 01:00:00', 1, '2020-02-09 09:11:22', '2024-06-08 04:17:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0207', 1, NULL, 5, NULL, NULL, 'ഓൺലൈൻ വിവാഹം അനുവതനീയ്യം ആണോ ?', 'Online ലൂടെയുള്ള വിവാഹം ശരിയാകുമോ ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-08-04 04:53:27', '2020-08-04 04:53:27') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0161', 1, NULL, 1, NULL, NULL, 'What is the ruling in believes of this party and accepting the principles', 'Assalamu Alaikum .I m living in a state of india called Tamilnadu.Here there is a political party named NTK in which a huge number of muslim youth are members.This social party speaks about communal rasicism, Tamil language linguistic.They say the lords ofhindussiva and murgan as forefathers of tamils.They say tamil is the greatest.They speak that everyone should unite as tamilians leaving their caste and community.And also they say that, they have introduced a religion called tamilam, its holy book is thirukural andeveryone willaccept their religion.Saying the gods of hindus as forefathers of tamils in which, they add all muslims also , They break the basic rules of islam.Many islamic youngsters are members of that social party.Islamic youngsters join this party on the basisof theirlove towardstamil language and also accept that the gods of hindus as their forefathers of them.But islam does not allow rasicism of tamils and saying a particular language as greater and saying people to unite on the basis of tamil language.They unite people on the basis of language which is against the basic principle of islam.Moreover they separate tamils muslims and urdu speaking muslims as different, and say that they are different muslims .They say that theyshould kill the islamic sentiment.These are theill principles of that political party that iscent percent against islamic law .They also say that all prayers should be performed only in tamil language.They say that tamil is the greatest language so all muslims who speak tamil shouldunite as tamilian not as islamic brotherhood .These muslim youngsters dont understand that this is against the base of islam.So, i hereby request you to give clear religious fatwa on being member and supporting this party which is against islamic laws.I also request youto save this islamic youngsters of tamilnadu,india from this evil social party by your clear guidelines and fatwa.', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2020-06-17 06:16:51', '2020-06-17 06:16:51') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0028', 1, NULL, 2, NULL, NULL, 'ഖുഫ്ഫക്കു പകരം സോക്സിൽ തടകൽ', 'ഖുഫ്ഫക്കു പകരം ഗൾഫ് നാടുകളിൽ സോക്സിൽ താടകാറുണ്ട്, അത് അനുവദനീയമാണോ?', 'Malayalam', 'published', '<p>ഖുഫ്ഫക്കു പറയപ്പെട്ടിരിക്കുന്ന നിബന്ധനകൾ സോക്സിൽ പൂർണമാകാത്തതിന്റെ പേരിൽ സോക്സിൽ തടകൽ മതിയാകുന്നതല്ല.&nbsp;</p>', 26, 0, 5, '2023-04-22 08:17:04', 1, '2019-11-18 01:24:59', '2024-07-11 19:30:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0237', 1, NULL, 2, NULL, NULL, 'Threading Eyebrows', 'Is it haram to thread eyebrows?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-09-21 06:36:33', '2023-11-02 04:58:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0145', 1, NULL, 5, NULL, NULL, 'what is the sunnah way of musafaha?', 'Asslamu Alikum, Kindly explain the how to do the musafaha?', 'English', 'published', '<p><br /> The completion of Sunnah in Musafahah is that it be done with two hands. But the sunnah will also be achieved with one hand.</p> <p>&nbsp;</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-25 07:26:03', '2023-10-14 04:37:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0062', 1, NULL, 1, NULL, NULL, 'Babri Masjid', 'Is it allowable for Muslims to accept 5 acres offered by the Supreme Court in lieu of Babri Masjid', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2019-12-13 06:16:56', '2019-12-13 06:16:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0160', 1, NULL, 5, NULL, NULL, 'നിഖാബ്', 'കല്യാണ സമയമായപ്പോൾ നിഖാബ് പറ്റില്ല എന്ന് പറഞ്ഞാണ് എന്ത് ചെയ്യണം? (ആ കുട്ടി ചെറുപ്പം മുതൽ നിഖാബ് ഇടുന്നു)', 'Malayalam', 'published', '<p>സ്ത്രീകൾക്ക് ചില അത്യാവശ്യ സന്ദർഭങ്ങളിൽ&nbsp; മുഖം വെളിവാക്കാനുള്ള അനുവാദം ഉണ്ടെങ്കിലും സാധാരണനിലയിൽ അന്യ പുരുഷന്മാരുടെ മുന്നിൽ മുഖം മറക്കൽ അനിവാര്യമാണ്.അത് പാടില്ല എന്ന് പറയുന്നവരോട് ആദ്യം അതിൻറെ ദീനീ വശങ്ങൾ പറഞ്ഞ് മനസ്സിലാക്കി കൊടുക്കുവാൻ ശ്രമിക്കുക , അതിനുശേഷവും&nbsp; വഴങ്ങുന്നില്ല എങ്കിൽ ഈ ബന്ധം വേണ്ടെന്നു വയ്ക്കുക , അല്ലാഹുവിൽ വിശ്വാസമർപ്പിക്കുക .</p> <p>വരനെ&nbsp; തെരഞ്ഞെടുക്കുമ്പോൾ അയാളുടെ സ്വഭാവത്തിനും ദീനിനിഷ്ഠക്കുമാണ്&nbsp; പ്രാധാന്യം നൽകേണ്ടത്,&nbsp; അല്ലാത്തപക്ഷം വൈവാഹിക ജീവിതം തന്നെ&nbsp; പ്രശ്നങ്ങളിലും പ്രയാസങ്ങളിലും പെട്ടുലയുമെന്ന് നബി സല്ലല്ലാഹു അലൈഹിവസല്ലം തങ്ങളുടെ ഹദീസുകൾ നമ്മെ പഠിപ്പിക്കുന്നു.</p>', 81, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-16 09:13:34', '2024-11-04 10:48:40') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0111', 1, NULL, 5, NULL, NULL, 'റമദാൻ മാസത്തിൽ ഭാര്യയുമായി ലൈംഗിക ബന്ധത്തിൽ ഏർപ്പെട്ടാൽ എന്തുചെയ്യണം?', '<ol> റമദാൻ മാസത്തിൽ മനഃപ്പൂർവമോ അല്ലാതെയോ ഭാര്യയുമായി ലൈംഗിക ബന്ധത്തിൽ ഏർപ്പെട്ടാൽ എന്തുനിലയിലുള്ള പ്രതിവിധി ആണ് നാം സ്വീകരിക്കേണ്ടത് ? ഭാര്യയും ഭർത്താവും ഒരുപോലെ കഫാറ അനുഷ്ഠിക്കണോ? </ol>', 'Malayalam', 'published', '<p>الجواب بحمد ربنا و الصلاة على نبينا<br /> റമദാൻ മാസത്തിൽ മനപ്പൂർവ്വം ഭാര്യയും ഭർത്താവും ലൈംഗിക ബന്ധത്തിലേർപ്പെട്ടാൽ നോമ്പ് ഖളാ വീട്ടുകയും കഫ്ഫാറ നൽകുകയും ചെയ്യേണ്ടതാണ്. മനഃപൂർവ്വമല്ലാതെ, നോമ്പാണെന്ന് അറിയാതെയാണ് രണ്ടുപേരും ലൈംഗികബന്ധത്തിലേർപ്പെട്ടതെങ്കിൽ &nbsp;ഖളാ വീട്ടിയാൽ മാത്രം മതിയാകും കഫ്ഫാറ കൊടുക്കേണ്ടതില്ല.</p>', 47, 0, 5, '1970-01-01 01:00:00', 1, '2020-03-04 04:42:31', '2024-08-18 10:07:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0011', 1, NULL, 1, NULL, NULL, 'ഭർത്താവ് മരിച്ച സ്ത്രീയുടെ ഇദ്ദ', 'ഭർത്താവ് മരിച്ചു കഴിഞ്ഞാൽ ഭാര്യക്ക് മറ ഇരിക്കൽ നിർബന്ധമാണോ ? അതിന്റെ കാരണം എന്താണ്?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2019-09-29 07:17:02', '2019-09-29 07:17:02') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0055', 1, NULL, 1, NULL, NULL, 'വുളു എടുക്കുമ്പോൾ ഔറത് മറയണം എന്ന് നിര്ബന്ധമുണ്ടോ?', 'വുളു എടുക്കുമ്പോൾ ഔറത് മറയണം എന്ന് നിര്ബന്ധമുണ്ടോ?', 'Malayalam', 'assigned', 'വുളു എടുക്കുമ്പോൾ വുളൂ ശരിയാക്കുന്നതിന് ഔറത്ത് മറക്കൽ നിർബന്ധമില്ല. ഔറത്ത് മറക്കാതെ വുളു എടുത്താലും വുളു ശരിയാകും.', 0, 0, 5, NULL, NULL, '2019-12-05 04:26:32', '2019-12-05 04:26:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0134', 1, NULL, 1, NULL, NULL, 'ഈദ് നിസ്കാരം ഹനഫി മദ്ഹബ്', 'അസ്സലാമു അലൈക്കും, ഹനഫി മദ്ഹബ് അനുസരിച്ച് ഈദ് നിസ്ക്കാരം റൂമിൽ വെച്ച് എന്ഗനെ നിർവഹിക്കാം എന്ന് വിശദീകരിക്കാമോ?', 'Malayalam', 'published', '<p>ജമാഅത്ത് ആയിട്ടാണ് പെരുന്നാൾ നമസ്കാരം നിർവഹിക്കേണ്ടത്. രണ്ടുപേർ ചേർന്ന് ജമാഅത്തായി നമസ്കരിച്ചാലും നമസ്കാരം ശരിയാകുമെങ്കിലും നാലു പേരിൽ കുറയാത്ത സംഘം ഉണ്ടാകലാണ് ഏറ്റവും സൂക്ഷ്മതയും നല്ലതും. കൂട്ടത്തിൽ ഏറ്റവും യോഗ്യനായ ആൾ ഇമാമത്ത് നിർവഹിക്കുക. നമസ്കാരശേഷം ശേഷം രണ്ട് ഖുതുബ ഓതൽ സുന്നത്താണ്.</p> <p><strong>പെരുന്നാൾ നമസ്കാരത്തിൻറെ&nbsp;രൂപം</strong></p> <p>വാജിബായ രണ്ട് റക്അത്ത് പെരുന്നാൾ നമസ്കാരം അല്ലാഹുവിനു വേണ്ടി നമസ്കരിക്കുന്നു എന്ന് നീയത്ത് ചെയ്ത്<br /> തക്ബീറതുൽ ഇഹ്റാം പറഞ്ഞ് കൈ കെട്ടി സനാഅ് ഓതിയതിന് ശേഷം രണ്ടു പ്രാവശ്യം തക്ബീർ പറഞ്ഞു കൈകൾ ഉയർത്തി താഴ്ത്തി ഇടുക. മൂന്നാമത്തെ തക്ബീർ പറഞ്ഞു കൈ കെട്ടി ഫാത്തിഹയും സൂറത്തും ഓതുക. റുകൂഉം സുജൂദും കഴിഞ്ഞ് രണ്ടാമത്തെ റക്അത്തിലെ ഫാതിഹയും സൂറത്തും ഓതിയതിനുശേഷം മൂന്നു പ്രാവശ്യം തക്ബീർ പറഞ്ഞ് കൈകളുയർത്തി താഴ്ത്തിയിടുക. നാലാമത്തെ തക്ബീർ പറഞ്ഞ് റുകൂഇലേക്ക്&zwnj; പോകുക. ശേഷം സാധാരണ പോലെ നമസ്കാരം പൂർത്തീകരിക്കുക.</p> <p><strong>പെരുന്നാൾ നമസ്കാരത്തിൻറെ ഖുതുബ</strong></p> <p><strong>ഒന്നാമത്തെ ഖുതുബ</strong></p> <p><br /> <strong>اللّه اَکْبَرُ،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر․اَلْحَمْدُلِلّه رَبِّ العَالَمِینَ وَ الصَّلاةُ وَ السَّلامُ عَلی سَیِّدِنَامُحَمَّدٍخَاتَمِ النَبِیینَ و عَلیَ آلِه وَاَصْحَابِه أجْمَعِینَ۔أمّا بَعْدُ!فَقَدْ قَالَ اللّه تَعَالَی: قَدْ أَفْلَحَ مَن تَزَکَّی ․ وَذَکَرَ اسْمَ رَبِّه فَصَلّی․ بَلْ تُؤْثِرُونَ الْحَیَاةَ الدُّنْیَا ․وَالْآخِرَةُ خَیْْرٌ وَأَبْقَی ․ إِنَّ هذَا لَفِیْ الصُّحُفِ الْأُولَی․ صُحُفِ إِبْرَاهیْمَ وَمُوسَی․وَقَالَ رَسُوْلُ اللّہُﷺ:اِنَّ لِکُلِّ قَوْمٍ عِیْداً وَهذَا عِیْدُنَا۔بَارَکَ اللّہُ لَنَا وَلَکُمْ فِی القُرْآنِ العَظِیْمِ وَ نَفَعَنَا وَ اِیّاکُمْ بِهدْیِ سِیِّدِ المُرْسَلِینَ</strong></p> <p><strong>രണ്ടാമത്തെ ഖുതുബ</strong></p> <p><strong>اللّه اَکْبَرُ،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اللّه اَکْبَر،اَلْحَمْدُ لِلّه نَحْمَدُہُ وَ نَسْتَعِینُه وَ نَسْتَغْفِرُہُ وَ نُوٴْمِنُ بِه وَ نَتَوَکَّلُ عَلَیْه وَنَعُوذُبِاللَه مِنْ شُرُورِأنْفُسِنَا وَ مِنْ سَیِّأتِ أعْمَاْلِنَا،وَ نَشْهدُأنْ لَا اِلآه اِلاّ اللّه وَ نَشْهدُأنَّ مُحَمّداًرَسُوْلَ اللَهﷺوَعَلَی آلِه وَصَحْبِه وَ بَارَکَ وَ سَلَّمَ۔أمَّا بَعْدُ!قَالَ رَسُوْلُ اللّهﷺزَکَاةُالفِطْرِطُهرَةٌلِلصَائِمِ مِنَ اللَغْوِوَالرَّفَثِ وَطُعْمَةٌ لِلمَسَاکِینِ أو کَمَا قَالَ عَلَیْه السَّلَا مُ وَقَالَ &nbsp;تَعَالی:َإِنَّ اللّه یَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ وَإِیْتَاء ذِیْ الْقُرْبَی وَیَنْہَی عَنِ الْفَحْشَاء وَالْمُنکَرِ وَالْبَغْیِ یَعِظُکُمْ لَعَلَّکُمْ تَذَکَّرُون۔وَلَذِکْرُاللّه اَکْبَرُ۔</strong></p>', 12, 0, 5, '1970-01-01 01:00:00', 1, '2020-05-19 05:27:27', '2023-10-14 04:45:16') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0157', 1, NULL, 5, NULL, NULL, 'Misl sawab', 'Assalamualikum  maranapettavarkku vendi quran oothi hadiyya cheyyal....thelivugal??', 'Malayalam', 'published', '<p>മരണപ്പെട്ടവർക്ക് വേണ്ടി ഖുർആൻ ഓതി ഹദിയ ചെയ്&zwnj;താൽ അത് സ്വീകരിക്കപ്പെടുകയും അതിൻറെ പ്രതിഫലം മരണപ്പെട്ടവർക്ക് ലഭിക്കുകയും ചെയ്യുന്നതാണ്</p> <p>ഇപ്രകാരം ഹനഫി മദ്ഹബ് പ്രകാരം എല്ലാ സൽകർമ്മങ്ങളും ചെയ്ത് ഹദിയ ചെയ്യാവുന്നതാണ്</p> <p>ഈ വിഷയവുമായി ബന്ധപ്പെട്ട് ഇമാം ഇബ്&zwnj;നു &nbsp;ജൗസി റഹ്മത്തുല്ലാഹി അലൈഹി കിതാബ് റൂഹിൽ പതിനാറാം പാഠമായി കൊണ്ട് വിശാലമായ ചർച്ചകൾ നടത്തുന്നുണ്ട് അദ്ദേഹം പറയുന്നു</p> <p>ജീവിച്ചിരിക്കുന്നവർ ചെയ്യുന്ന അമലുകൾ മരണപ്പെട്ടവർക്ക് പ്രയോജനം ലഭിക്കുന്ന വിഷയത്തിൽ<br /> അഹ്ലുസ്സുന്ന യുടെ കർമശാസ്ത്ര പണ്ഡിതൻമാരും തഫ്&zwnj;സീറിന്റെയും ഹദീസിന്റെയും ഉലമാക്കളും ഏക അഭിപ്രായക്കാർ ആണ്. ഹദീസുകളിൽ &nbsp;മരണപ്പെട്ടവർക്ക് വേണ്ടി ദുആ ചെയ്യാൻ പ്രേരിപ്പിച്ചു അവർക്ക് വേണ്ടി പാപമോചനം തേടാൻ വന്നതുമെല്ലാം ഇതിന് തെളിവാണ് &nbsp;<br /> മേൽപ്പറഞ്ഞ വിഷയത്തിൽ വന്നിരിക്കുന്ന കിതാബുകളുടെ കോട്ടിങ്ങുകൾ താഴെ നൽകുന്നു.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-12 04:47:22', '2023-08-16 11:08:54') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0221', 1, NULL, 2, NULL, NULL, 'I have a dog in the house and it is taken care by my friend so what will be the fatwa if I accidentally touch its hair', 'I have a dog in the house and it is taken care by my friend so what will be the fatwa if I accidentally touch its hair', 'English', 'published', '<p>We are allowed only to takecare &nbsp;of a dog for the security purposes of cattles,houses,farms and for hunting.If we touch the dog accidently there is nothing wrong in that.If the body of the dog or the touched part of our body is wet then,that part should be washed thoroughly with water seven times and one of that should be mixed with sand.)</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2020-08-19 03:39:49', '2024-08-19 07:23:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0169', 1, NULL, 5, NULL, NULL, 'പലിശയെ സംബന്ധിച്ച് ഉള്ള സംശയം', '1.ഗൂഗിൾ പേ പോലുള്ളവയിൽ നിന്ന് പണം അയക്കുമ്പോൾ ലഭിക്കുന്ന റിവാർഡുകൾ അനുവദനീയമാണോ? 2.ബങ്കിൽ നിന്ന് ലഭിക്കുന്ന പലിശ ആർക്കൊക്കെ കൊടുക്കാം? പുണ്യം പ്രതീക്ഷിക്കാതെ അത് പ്രായമായവർക്ക്ൽ നകാമോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2020-06-21 22:27:11', '2020-06-21 22:27:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0122', 1, NULL, 1, NULL, NULL, 'ഒരാളുടെ ഹൃദയം വേദനിപ്പിക്കുന്ന തു കഅബ', 'ഹൃദയം വേദനിപ്പിച്ചു. അത് കഅബ പൊളിക്കു ന്നത് പോലെ യാണോ', 'Malayalam', 'published', '<p><strong>ഹദീസിൽ വന്നിരിക്കുന്നു :<strong> </strong>من<strong> </strong>آذى</strong><strong> </strong><strong>مسلماً</strong><strong> </strong><strong>بغير</strong><strong> </strong><strong>حق</strong><strong> </strong><strong>فكأنما</strong><strong> </strong><strong>هدم</strong><strong> </strong><strong>بيت</strong><strong> </strong><strong>الله</strong><strong><span dir=\"LTR\">&nbsp; {&nbsp; </span>&nbsp;رواه الطبراني&nbsp;<span dir=\"LTR\">}</span> അന്യായമായി ആരെങ്കിലും ഒരു മുസ്ലിമിനെ വേദനിപ്പിച്ചാൽ അയാൾ അല്ലാഹുവിൻറെ ഭവനം പൊളിച്ചത് പോലെയാണ്<span dir=\"RTL\">.</span></strong></p>', 11, 0, 5, '1970-01-01 01:00:00', 1, '2020-03-26 22:29:36', '2024-01-23 11:49:50') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0155', 1, NULL, 1, NULL, NULL, 'Intraday trade', 'Intraday trade halaal aanohttps://youtu.be/Lqg6o6piBeU', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2020-06-10 04:27:00', '2020-06-10 04:27:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
