INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0401', 1, NULL, 1, NULL, NULL, 'Google pay nam upayogikkumbol ninnu kittunna benefits nammukku upayogikkal halal ano', 'Google pay nam upayogikkumbol athil ninnu kittunna benefits upayogikal halal ano', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-30 11:35:02', '2021-10-30 11:35:02') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0338', 1, NULL, 2, NULL, NULL, 'തഖ് ദീമിനും,തഅഖീറിനും, തർത്തീബ്, മുവാലാത്ത് നിർബന്ധമുണ്ടോ?', 'തഖ് ദീമിനും,തഅഖീറിനും, തർത്തീബ്, മുവാലാത്ത്  നിർബന്ധമുണ്ടോ?', 'Malayalam', 'published', '<p>ജംഅ തഖ്ദീമിൽ തർത്തീബും മുവാലാത്തും നിർബന്ധമാണ് ആണ്. എന്നാൽ ജംഅ തഅഖീറിൽ തർത്തീബ് മുവാലാത്ത് നിർബന്ധമില്ല.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:18:14', '2021-08-12 02:18:14') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0438', 1, NULL, 2, NULL, NULL, 'ഫർളായ കുളിയിൽ ഏതെങ്കിലും ഒരവയവം നനഞ്ഞിട്ടില്ലെങ്കിൽ കുളിക്ക് ശേഷം ആ അവയവത്തെ കുളിയുടെ നിയ്യത്തിൽ കഴുകിയാൽ കുളി ശരിയാകുമോ?', 'ഫർളായ കുളിയിൽ ഏതെങ്കിലും ഒരു അവയവം മനഃപൂർവ്വമല്ലാതെ നനഞ്ഞിട്ടില്ല എങ്കിൽ കുളിക്കു ശേഷം അറിയുമ്പോൾ ആ അവയവത്തെ കുളിയുടെ നിയ്യത്തിൽ കഴുകിയാൽ കുളി ശരിയാകുമോ? ഇതിൻ്റെ നിയമം ഹനഫി ശാഫി രണ്ടിലും പറയാമോ?', 'Malayalam', 'published', '<p>മേൽ പറഞ്ഞ രൂപത്തിൽ കുളിച്ചതിനു ശേഷം വെള്ളം തട്ടാത്ത അവയവത്തിൽ മാത്രം വെള്ളം ഒഴിച്ച് കഴുകിയാൽ ഷാഫി ഹനഫി മദ്ഹബ് അനുസരിച്ച് കുളി ശരിയാകുന്നതാണ്.</p>', 4, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-05 20:26:51', '2024-02-10 19:28:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0446', 1, NULL, 5, NULL, NULL, 'Eyebrows threade ചെയ്യുന്നവരുടെ ഇസ്ലാമിക വിധി എന്താണ്?', 'Eyebrows threade ചെയ്യുന്നവരുടെ ഇസ്ലാമിക വിധി എന്താണ്?', 'Malayalam', 'published', '<p>സ്ത്രീകൾക്ക് ഭംഗിക്ക് വേണ്ടി പുരികം threade ചെയ്യൽ അനുവദനീയമല്ല. എന്നാൽ പുരികം&nbsp;പരിധിവിട്ട് വികൃതമായ രൂപത്തിൽ വളർന്നാൽ വെട്ടി നേരെയാക്കുന്നതിൽ വിരോധമില്ല.&nbsp;</p>', 3, 0, 5, '2023-04-03 08:48:36', 1, '2021-11-07 11:55:44', '2023-04-03 08:49:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0515', 1, NULL, 2, NULL, NULL, 'Thasbeeh salah', 'Is thasbeeh salah authentic?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-08 04:33:05', '2023-11-11 15:55:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0305', 1, NULL, 5, NULL, NULL, 'ഹിജാമ', 'ഞാൻ ഒരു ഹിജാമ ചികിത്സകനാണ്. ക്ലിനിക്കൽ ഉപകരണങ്ങളും മറ്റ് ചിലവുകളും ചേർത്ത് ഞാൻ ചികിത്സ ചെയ്യുമ്പോൾ അതിൽ നിശ്ചിത ഫീസ് വാങ്ങുന്നതിന്റെ വിധി എന്താണ്...??<br /> ഹിജാമക്കാരന്റെ പ്രതിഫലം നിശിദ്ധമാണെന്ന് ചില ഹദീസുകൾ (ജാമിഉ തിർമുദി 1275, 1278, ബുഖാരി 2238, 5962, സുനൻ നസാഈ 4673, 4294, സുനൻ ഇബ്നു മാജ 2165, സഹീഹ് മുസ്ലിം 1568) വ്യക്തമായി സൂചിപ്പിക്കുന്നു.<br /> എന്നാൽ മറ്റ് ചില ഹദീസുകളാകട്ടെ ഹിജാമക്കാരന് പ്രവാചകൻ (സ) പ്രതിഫലം നൽകിയതായും, അത് വാങ്ങുന്നതിൽ കുഴപ്പവുമില്ല എന്നും വ്യക്തമായി സൂചിപ്പിക്കുന്നു. ( ബുഖാരി 2279, 2280, 2281,2277, ഇബ്നു മാജ 2163, 2164, സുനൻ അബൂ ദാവൂദ് 3423, 3224)  ഈ രണ്ട് വിഭാഗം ഹദീസുകളുടെയും അടിസ്ഥാനത്തിൽ ഹിജാമ ചികിത്സകൻ നിശ്ചിത പ്രതിഫലം ഫീസായി വാങ്ങുന്നതിന്റെ വിധിയെന്താണ്..? അനുവദനീയമെങ്കിൽ ഫീസിന്റെ മാനദണ്ഠങ്ങൾ എന്തൊക്കെയാണ്..?', 'Malayalam', 'published', '<p>ഹിജാമ ചികിൽസ നടത്തുന്ന വ്യക്തിക്ക് ഫീസായി നിശ്ചിത തുക വാങ്ങൽ &nbsp;അനുവദനീയമാണ്.<br /> ഇതാണ് ഭൂരിഭാഗം പണ്ഡിതന്മാരുടെയും അഭിപ്രായം. നബിﷺ ഹിജാമ ചെയ്ത ശേഷം أبو طيبة ക്ക് കൂലി നൽകി എന്ന ഹദീസിനെയാണ് അവർ അടിസ്ഥാനമാക്കുന്നതത്.<br /> عن عبدالله بن عباس احْتَجَمَ النبيُّ ﷺ، وأَعْطى الحَجّامَ أَجْرَهُ، ولو عَلِمَ كَراهيةً لَمْ يُعْطِهِ.<br /> ( صحيح البخاري ٢٢٧٩ &nbsp;)<br /> നബിﷺ ഹിജാമ ചെയ്യുകയും ഹിജാമ ചെയ്തയാൾക്ക് കൂലി നൽകുകയും ചെയ്തു. കൂലി നൽകൽ ഹറാമായിരുന്നെങ്കിൽ നബിﷺ നൽകുമായിരുന്നില്ല.</p> <p>എന്നാൽ<br /> &nbsp;عن رافع بن خديج عَنْ رَسُولِ اللّٰهِ ﷺ ثَمَنُ الكَلْبِ خَبِيثٌ، ومَهْرُ البَغِيِّ خَبِيثٌ، وكَسْبُ الحَجّامِ خَبِيثٌ.<br /> ( صحيح المسلم ٣٩٨٨)</p> <p>നായയുടെ വില മോശമാണ്, വേശ്യയുടെ സ്ത്രീധനം മോശമാണ്, &nbsp;ഹിജാമയുടെ വരുമാനം മോശമാണ്. &rdquo;</p> <p>ഈ രീതിയിൽ വന്നിട്ടുള്ള ഹദീസുകളിലെ خبيث<br /> &quot;മോശമാണ്&quot; എന്ന് പറഞ്ഞതിന്റെ ഉദ്ദേശം ആ ജോലി ഹറാമാണ് എന്ന അർത്ഥത്തിൽ അല്ല.മറിച്ച് നജസുമായി &nbsp;ബന്ധപ്പെട്ട് നിൽക്കുന്നത് കൊണ്ട് ആ പ്രവർത്തി അത്ര ഉജിതമല്ല എന്നാണ് ഉദ്ദേശം. മറ്റ് സമ്പാദ്യമാർഗം ഉണ്ടെങ്കിൽ അതിനെ കൈ കൊള്ളലാണ് നല്ലത്.<br /> ഇനി ഒരാൾ ഹിജാമയെ തൊഴിലായി സ്വീകരിച്ചാൽ ശറഇന്റെ വീക്ഷണത്തിൽ അതിന് പകരം ഫീസ് വാങ്ങൽ ഹലാലാണ്. ആ സമ്പത്ത് ഹറാം ആവുകയില്ല.</p> <p>ഫീസിനുള്ള മാനദണ്ഡമായി തന്റെ പ്രവർത്തനത്തെ നിശ്ചയിക്കാവുന്നതാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-04-16 05:34:44', '2023-08-02 06:12:15') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0336', 1, NULL, 2, NULL, NULL, 'ഇരുന്ന് നമസ്ക്കാരം യാത്രയിൽ അനുവാദം ഉണ്ടോ ?', 'ട്രെയിൻ ബസ്, പ്ലൈൻ എന്നിവയിൽ യാത്ര ചെയ്യുമ്പോൾ ഇരുന്ന് നമസ്കരിക്കാമോ ?', 'Malayalam', 'published', '<p>ട്രെയിൻ പോലെ നിന്ന് നമസ്കരിക്കാൻ സൗകര്യമുള്ള വാഹനങ്ങളിൽ ഫർള് നമസ്കാരങ്ങൾഇരുന്ന് നമസ്കരിക്കാൻ അനുവാദമില്ല ഇനി ഫർള് നമസ്കരിക്കുന്നതിനിടെ ട്രെയിനിലെ ശക്തമായ കുലുക്കത്തിന്റെ പേരിൽ ട്രെയിനിന്റെ നിലത്തിരുന്ന് നമസ്കരിക്കുന്നതിൽ വിരോധമില്ല.</p> <p>ബസ് പ്ലെയിൻ പോലെ നിന്ന് നമസ്കരിക്കാൻ അസൗകര്യമുള്ള വാഹനങ്ങളിൽ ഫർള് നമസ്കാരങ്ങൾ ഇരുന്ന് നമസ്കരിക്കുകയും പിന്നീട് മടക്കി നമസ്കരിക്കേണ്ടതുമാണ്.</p> <p>NB: സുന്നത്ത് നമസ്കാരങ്ങൾ നിരുപാധികം ഇരുന്നു നമസ്കരിക്കാവുന്നതാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 01:25:31', '2021-08-12 01:25:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0410', 1, NULL, 1, NULL, NULL, 'Phonepe qr code scaner കടകളിൽ ചെയ്തു കൊടുക്കുന്നത്', 'ഫോൺപേ scaner കടകളിൽ എത്തിച്ചു നൽകൽ അനുവതനിയമാണോ  Salari കിട്ടുന്നത് 1 മാസം 100എണ്ണം ചെയ്തു കൊടുത്താൽ 50രൂപ. 100 എണ്ണത്തിൽ thare ആയാൽ 30രൂപ ഇതിന്റെ വിധി?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-11-01 12:04:33', '2021-11-01 12:04:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0501', 1, NULL, 5, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', 'ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) എന്ന app വഴി stock വാങ്ങൽ അനുവദിനീയമാണോ (zomato) ടെ ഷെയർ ആണ് എടുത്തത് അത് അനുവദിനീയമാണോ', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 08:06:09', '2023-11-11 14:42:30') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0544', 1, NULL, 1, NULL, NULL, 'വിവാഹത്തിൽ ഭാര്യ ഭർത്താവിനേക്കാൾ പ്രായം കുറഞ്ഞവർ ആകണം എന്നതിൽ ഫിഖ്ഹിൻ്റെ കാഴ്ചപ്', 'വിവാഹത്തിൽ ഭാര്യ ഭർത്താവിനേക്കാൾ പ്രായം കുറഞ്ഞവർ ആകണം എന്നതിൽ ഫിഖ്ഹിൻ്റെ കാഴ്ചപ്പാട് എന്താണ് ?', 'Malayalam', 'published', 'നിരുപാധികം മൻദൂബ് (നല്ലത്) ആണെങ്കിലും ചില പ്രത്യേക സന്ദർഭങ്ങളിൽ പ്രായത്തിൽ ഭർത്താവിനേക്കാൾ മുതിർന്ന സ്ത്രീയെ വിവാഹം കഴിക്കൽ നല്ലതും ആകുന്നു.', 85, 0, 5, '2022-06-11 10:58:26', 1, '2022-06-11 10:58:26', '2024-11-02 19:13:27') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0420', 1, NULL, 1, NULL, NULL, 'അന്യന്റെ സാധനം അനുവാദമില്ലാതെ വിൽക്കൽ', '1-മറ്റൊരാളുടെ സാധനം അനുവാദം ഇല്ലാതെ വിൽക്കുന്നതിന്റെ വിധി എന്താണ് . 2- ഒരു സാധനം മറ്റാർക്കെങ്കിലും വിൽക്കാനായി ഉടമസ്ഥൻ ഒരാളെ ഏൽപിച്ചാൽ അതിനെ സ്വന്തം എടുത്തിട്ട് പൈസ ഉടമസ്ഥന് കൊടുക്കൽ അനുവദനീയമാണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-01 22:50:43', '2023-11-02 16:14:03') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0397', 1, NULL, 1, NULL, NULL, 'ശാരീരികബന്ധത്തിൽ ഏർപ്പെടുന്നതിന് കുളി അനിവാര്യമാണോ, തയമ്മുമ് മതിയാകുമോ', 'സ്ത്രീ ഏതെങ്കിലും നിർബന്ധിത സാഹചര്യത്തിൻ്റെ പേരിൽ കുളിക്കുന്നതിനു പകരമായി തയമ്മും ചെയ്താൽ അവളുമായി ശാരീരിക ബന്ധത്തിൽ ഏർപ്പെടുന്നത് അനുവദിക്കപ്പെട്ട കാര്യമാണോ ?', 'Malayalam', 'published', '<p>ശറഇയ്യായ കാരണങ്ങളുടെ പേരിൽ തയമ്മും ചെയ്&zwnj;താൽ ഒരു ഫർള് നിസ്കാരം നിർവഹിക്കാനെടുക്കുന്ന സമയം കഴിഞ്ഞതിനു ശേഷം ബന്ധപ്പെടുന്നതിന് കുഴപ്പമില്ല.</p> <p>NB:- 10 ദിവസം പൂർണ്ണമായി ഹൈള് വന്നാൽ ഹൈള് തീർന്ന ഉടനെ ശാരീരികബന്ധത്തിലേർപ്പെടാം.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-29 22:29:27', '2021-10-29 22:29:27') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0421', 1, NULL, 5, NULL, NULL, 'മരണ ശേഷം കിട്ടുന്ന നന്മകളിൽ മറ്റുള്ളവർ നമുക്ക് വേണ്ടി ചെയ്യുന്ന നന്മകൾ അതിൽ പെടുമോ?', 'മരണ ശേഷം കിട്ടുന്ന നന്മകളിൽ മറ്റുള്ളവർ നമുക്ക് വേണ്ടി ചെയ്യുന്ന നന്മകൾ അതിൽ പെടുമോ?(ഭാര്യ, മക്കൾ, മാതാപിതാക്കൾ എന്നിവരൊഴികെ )ബാക്കിയുള്ള ആളുകൾ ഓതുന്ന ഖുർആൻ ദിക്ർ മുതലായവ ഖബറിൽ പ്രയോജനം ചെയ്യുമോ.. അയാളുടെ നന്മ വർധിപ്പിക്കുമോ?', 'Malayalam', 'published', '<p>മരണശേഷം മറ്റുള്ളവർ നമുക്ക് വേണ്ടി ഓതുന്ന ഖുർആൻ ദിക്ർ മുതലായ അമലുകളുടെ പ്രതിഫലം ഖബറിൽ നമുക്ക് പ്രയോജനം ചെയ്യുന്നതാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-02 03:50:29', '2021-11-02 03:50:29') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0348', 1, NULL, 2, NULL, NULL, 'തയമ്മും കൊണ്ട് എത്ര നമസ്കാരം ജംഅ് ചെയ്യാം ?', 'തയമ്മും ചെയ്തു നമസ്കരിക്കുന്നവർക്ക് ഒരു ഫർള് മാത്രമേ പാടുള്ളൂ എങ്കിൽ ജംഅ് ചെയ്യുമ്പോൾ എന്ത് ചെയ്യണം?', 'Malayalam', 'published', '<p>തയമ്മും ചെയ്തുകൊണ്ട് ജംആക്കി നമസ്കരിക്കുന്ന വ്യക്തി ഓരോ നമസ്കാരത്തിനു വേണ്ടിയും തയമ്മും ചെയ്യണം.&nbsp;</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:42:08', '2024-08-18 10:02:29') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0469', 1, NULL, 5, NULL, NULL, 'Is Tata Ethical Fund (Mutual Fund) halal ??', 'Subject: Tata Ethical Fund اَلسَلامُ عَلَيْكُم وَرَحْمَةُ اَللهِ وَبَرَكاتُهُ&lrm; What&#39;s the ruling on investing in Tata Ethical Fund? They claim it as Sharia complied one For terms &amp; conditions please refer<br /> https://www.tatamutualfund.com/products/tata-ethical-fund <br /> جزاك اللهُ خيراً', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-12-02 15:08:53', '2023-11-11 14:45:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0482', 1, NULL, 2, NULL, NULL, 'നെറ്റ് വർക്ക് ബിസിനസ് കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആയി വർക്ക് ചെയ്യാൻ പറ്റുമോ', 'പ്രൊഡക്ട് ബേസ് ചെയ്തു (ആളെ ചേർക്കാൻ നിർബന്ധമില്ല) നെറ്റ്വർക്ക് ബിസിനസിലൂടെ കച്ചവടം ചെയ്യുന്ന കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആവാൻ പറ്റുമോ? താഴെതട്ടിൽ കച്ചവടം നടക്കുമ്പോൾ മേലേ തട്ടിലുള്ളവർക്ക് കമ്പനിയുടെ കമ്മീഷൻ സ്വീകരിക്കാൻ പറ്റുമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-01-02 01:11:51', '2023-11-11 14:45:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0584', 1, NULL, 5, NULL, NULL, 'ബിസിനസും നികുതിയും', 'ഇസ്ലാമിലെ ഏറ്റവും വലിയ പാപങ്ങളിലൊന്നാണ് നുണ.
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0276', 1, NULL, 5, NULL, NULL, 'വാഹനം CC ക്ക് എടുക്കാൻ അനുവാദം ഉണ്ടോ', 'വാഹനം CC ക്ക് എടുക്കാൻ അനുവാദം ഉണ്ടോ', 'Malayalam', 'published', '<p>ഇന്ന് പല വ്യക്തികളും&nbsp; വാഹനങ്ങൾ സിസിക്ക് എടുക്കാറുണ്ട് അതായത് വാഹനത്തിൻറെ വില മുഴുവനും ഒന്നിച്ചു&nbsp; നൽകാൻ കഴിയാത്ത കാരണത്താൽ തവണകളായി അടച്ചു തീർക്കുന്നു. </p><p>ഉദാ : ഒരു കമ്പനി വാഹനത്തിന് വില നിശ്ചയിക്കുന്നത് പത്ത് ലക്ഷം രൂപയാണ് എന്ന് സങ്കൽപ്പിക്കുക അത്രയും തുക&nbsp; ഒന്നിച്ചു നൽകാൻ ഉപഭോക്താവിന് കഴിയാത്തകാരണത്താൽ ഉപഭോക്താവ് finance option തിരഞ്ഞെടുക്കുന്നു അഥവാ വാഹന വിലയായ 10 ലക്ഷം രൂപ finance കമ്പനി showroom ന് കൊടുക്കുന്നു പിന്നീട് finance കമ്പനിക്ക് ഉപഭോക്താവ് ഒരു നിശ്ചിത amount വെച്ച് നിശ്ചിത വർഷംവരെ അടച്ചു തീർക്കുന്നു . </p><p>അങ്ങനെ വരുമ്പോൾ finance കമ്പനി വാഹന വിലയായി നൽകിയ പത്ത് ലക്ഷത്തേക്കാൾ കൂടുതൽ തുക ഉപഭോക്താവിൽ നിന്നും പലിശ എന്ന നിലയിൽ ഈടാക്കുന്നു. ഇന്ന് അധികം നടക്കുന്ന ഇടപാടുകൾ ഈ രീതിയിലാണ്. ഇത് ഇസ്‌ലാം നിരോധിച്ചിരിക്കുന്ന പലിശ ആയതിനാൽ ഹറാമാണ് .</p> <p>Nb: ഇന്ന് ചില പ്രമുഖ കമ്പനികൾ&nbsp; നേരിട്ട് മേൽപ്പറഞ്ഞ അതെ രൂപത്തിൽ വാഹനം finance ന് കൊടുക്കാറുണ്ട് ഇതും ശരീഅത്തിൽ അനുവദനീയമല്ല . എന്നാൽ ഇനി ഒരു വ്യക്തി തൻറെ നിത്യാവശ്യങ്ങൾക്കായി വാഹനം ഉപയോഗിക്കാൻ നിർബന്ധിതനാണ്, അല്ലെങ്കിൽ ready cash നൽകി വാഹനം വാങ്ങാൻ കഴിയും പക്ഷേ ഒറ്റയടിക്ക് ഇത്രയും വലിയ amount നൽകുന്ന കാരണത്താൽ നിയമപരമായി ബുദ്ധിമുട്ടുകൾ നേരിടേണ്ടി വരുമെന്ന് ഭയപ്പെട്ടാൽ കമ്പനികൾ നേരിട്ട് finance നൽകുന്ന രീതി സ്വീകരിച്ചുകൊണ്ട്&nbsp; ആദ്യം കമ്പനി മാനേജറുമായി സംസാരിച്ച് വാഹനം finance ന്&nbsp; നൽകുമ്പോൾ വരുന്ന additional amount ചേർത്ത് ആദ്യമേ വാഹന വിലയായി നിശ്ചയിച്ച് വാഹനം വാങ്ങാവുന്നതാണ് . </p><p>കമ്പനിയിൽ നിന്ന് നേരിട്ടല്ലാതെ വേറെ finance കമ്പനികളിൽ നിന്നാണ് E M I ലൂടെ വാഹനം വാങ്ങുന്നത് എങ്കിൽ&nbsp; ഉപഭോക്താവ് finance മാനേജറുമായി സംസാരിച്ച് വാഹനം ആദ്യം മാനേജർ വാങ്ങുക , എന്നിട്ട് വാഹനം മാനേജർക്ക് delivery ആയതിനു ശേഷം&nbsp;&nbsp; finance&nbsp; രീതിയിൽ വാങ്ങുമ്പോൾ വരുന്ന additional amount കൂടി വാഹന വിലയായി നിശ്ചയിച്ച് , എല്ലാ amount ഉും തെറ്റാതെ അടക്കാൻ കഴിയും എന്ന് ഉറപ്പുണ്ടെങ്കിൽ മാനേജറും&nbsp;അത്യാവശ്യ ക്കാരനായ ഉപഭോക്താവും വാക്കാൽ സമ്മതിച്ച് മാനേജറിൽ നിന്ന് വാഹനം വാങ്ങാവുന്നതാണ്.</p><p> എന്നാൽ രണ്ട് രൂപത്തിലും അതുമായി ബന്ധപ്പെട്ട രേഖകളെല്ലാം തന്നെ finance ഇടപാട് എന്ന നിലയിൽ ആണെങ്കിൽ തന്നെയും <span dir=\"RTL\">فقهاء</span>&nbsp;(കർമശാസ്ത്ര പണ്ഡിത മഹത്തുക്കൾ) കളുടെ അടുക്കൽ രേഖകളേക്കാൾ വാക്കുകൾക്കാണ് സ്ഥാനം എന്നതുകൊണ്ട് ഇത് തടസ്സമാകില്ല. </p>', 228, 0, 5, '2023-04-22 06:48:13', 1, '2020-12-03 09:15:54', '2024-11-04 02:56:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0499', 1, NULL, 2, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', '<div style=\"background:#eeeeee; border:1px solid #cccccc; padding:5px 10px\">ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) പോലുള്ള app വഴി ഷെയർ വാങ്ങാൻ പറ്റുമോ അത് ഹലാൽ ആണോ</div>', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 02:04:46', '2023-11-11 15:58:52') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
