INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0470', 1, NULL, 5, NULL, NULL, 'Is Tata Ethical Fund (Mutual Fund) halal ??', 'What #39;s the ruling on investing in Tata Ethical Fund? They claim it as Sharia complied one For terms, conditions please refer https://www.tatamutualfund.com/products/tata-ethical-fund', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2021-12-02 15:08:58', '2023-11-02 16:26:40') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0326', 1, NULL, 2, NULL, NULL, 'Is it permissible to invest in stock market in india.', 'Is it permissible to invest in stock market if the corporate company deals with bank?', 'English', 'published', '<p>Permission to invest in share business is based on the mode of company that you are investing. If the company follow Islamic Principles &amp; do not deal with interest, then it is Halal. If the company deals in haram businesses like investing in banks to receive interest, or the company didn&rsquo;t following Islamic Principles in their sales &amp; purchasing, then you cannot invest in such companies.</p>', 33, 0, 5, '1970-01-01 01:00:00', 1, '2021-06-25 15:57:01', '2024-10-08 13:03:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0472', 1, NULL, 5, NULL, NULL, 'Earning money', 'Game കളിച്ചു പണം ഉണ്ടാക്കുന്നതിൻ്റെ വിധിയെന്ത്?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-12-05 08:11:28', '2023-11-11 15:54:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0294', 1, NULL, 2, NULL, NULL, 'അഗതി മന്ദിരത്തിലെ ചിലവിന് സകാത്ത് പണം ഉപയോഗിക്കാൻഅനുവാദം ഉണ്ടോ ?', 'ഒരു വ്യക്തി തന്റെ സക്കാത്ത് അഗതിമന്ദിരത്തിൽ താമസിക്കുന്ന സകാത്തിന് അർഹനായ വ്യക്തിയുടെ ചിലവിലേക്ക് ഉപയോഗിക്കാനായി നടത്തിപ്പുകാരനെ ഏൽപ്പിക്കുന്നു. നടത്തിപ്പുകാർ സ്ഥാപനത്തിലെ അഗതികളുടെ ഭക്ഷണത്തിന്റെ ആവശ്യത്തിലേക്കായി ഈ തുക പൊതുവായി വിനിയോഗിച്ചാൽ ഭക്ഷണം കഴിക്കുന്നവരിൽ സക്കാത്തിന് അർഹതയില്ലാത്തവരായ അഗതികളും അഗതിമന്ദിരത്തിലെ ജീവനക്കാരും ഉണ്ടായിരിക്കെ സക്കാത്ത് ദാതാവിന്റെ സക്കാത്ത് പൂർത്തിയാകുമോ?.', 'Malayalam', 'published', '<p>-മേൽപ്പറഞ്ഞ രീതിയിൽ സക്കാത്ത് വീടുകയില്ല . എന്നാൽ ഒരു വ്യക്തിയെ അഗതിമന്ദിരത്തിൽ ചേർക്കുന്ന സന്ദർഭത്തിൽ തന്നെ നടത്തിപ്പുകാർ &#39;ഞങ്ങൾ താങ്കളുടെ സക്കാത്തിന്റെ തുക വാങ്ങി അത് താങ്കളുടെ ആവശ്യങ്ങൾക്കായി ചിലവാക്കുന്നതാണ് &#39; എന്ന് ആ വ്യക്തിയിൽ നിന്നും എഴുതി വാങ്ങുകയാണെങ്കിൽ അയാളുടെ സക്കാത്ത് വീടുന്നതാണ്.</p>', 4, 0, 5, '1970-01-01 01:00:00', 1, '2021-03-12 20:44:25', '2024-03-27 08:33:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0269', 1, NULL, 2, NULL, NULL, 'വുളു ചെയ്യുന്നയാളോട് സലാം പറയാമോ?', 'വുളു ചെയ്യുന്നയാളോട് സലാം പറയാമോ?', 'Malayalam', 'published', '<p>വുളുഅ് ചെയ്യുന്ന ആളോട് സലാം പറയലും അദ്ദേഹം സലാം മടക്കലും അനുവദനീയമാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-11-30 00:12:21', '2020-11-30 00:12:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0349', 1, NULL, 2, NULL, NULL, 'ജുമുഅ നമസ്കാരത്തോടൊപ്പം അസർ ജംആക്കാമോ ?', 'ജുമുഅ നമസ്കാരത്തോടൊപ്പം അസർ ജംആക്കാമോ ?', 'Malayalam', 'published', '<p>ജുമുഅയോടൊപ്പം അസർ നമസ്കാരത്തെ ജംആക്കൽ അനുവദനീയമാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:43:40', '2021-08-12 02:43:40') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0375', 1, NULL, 1, NULL, NULL, 'Dawah ചെയ്യാതിരിക്കല്‍ അന്ത്യനാളിന്റെ അടയാളമാണോ?', 'ചിലര്‍ പറയാറുണ്ട് :  ദീനിൻറെ പരിശ്രമം ചെയ്താൽ രണ്ട് മലകൾ തമ്മില്‍ വിളിച്ചുപറയും    അന്ത്യനാൾ ആയിട്ടില്ല കാരണം ഇന്നും ദഅവത്ത് നടക്കുന്നുണ്ട്. ഇത്‌ സ്ഥിരപ്പെട്ടാതാണോ?', 'Malayalam', 'published', '<p>ദീനിന്റെ പരിശ്രമവുമായി ബന്ധപ്പെട്ട് ഈ ആശയത്തിലുള്ള ഹദീസ് &nbsp;കിത്താബുകളിൽ കണ്ടിട്ടില്ല. എന്നാൽ ദിക്റ് ചെയ്യുന്നവരുടെ വിഷയത്തിൽ താഴെ പറയും പ്രകാരം ഒരു ഹദീസ് വന്നിരിക്കുന്നു. &quot;ഒരു മല മറ്റൊരു മലയോട് അല്ലാഹുവിന് ദിക്റ് ചെയ്തുകൊണ്ട് ആരെങ്കിലും നിന്റെ അടുക്കലൂടെ കടന്നു പോയിരുന്നോ എന്ന് ചോദിക്കും, അതെ എന്ന് മറുപടി പറഞ്ഞാൽ ആ മല സന്തോഷിക്കുന്നതുമാണ്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-21 12:24:09', '2023-06-17 05:50:24') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0416', 1, NULL, 2, NULL, NULL, 'വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധി ആകാൻ കുളിച്ച ശേഷം വുളു എടുക്കാനോ', 'വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധി ആകാൻ കുളിച്ച വെക്തിതിക്ക് വുളു എടുക്കാതെ നമസ്കരിക്കാൻ സദിക്കുമോ ( വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധി ആകുമ്പോൾ അവൻ്റെ ചെറിയ അശുദ്ധിയും നീങ്ങുമോ)?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-11-01 21:50:00', '2021-11-01 21:50:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0527', 1, NULL, 5, NULL, NULL, 'My question is regarding socil media platforms.', 'I&#39;m Certified Nutritionist Advisor, yoga trainner and business women also. In today&#39;s changing world everything is changing rapidly and all the businesses and works are transform from offline to online world. In this changing world my business and work is also transform offline to online world. And now today&#39;s time my totally business is going on social media platforms. And in this condition my question to you that can i record my own photos and videos for suggesting and promoting my own brand food supplements to people of social media. And can i share my own photos and videos of my workouts and yoga on social media for train the people which helps the audience to connect with workouts and healthy lifestyle. So, tells me the answer of my questions that the sharing of photos and video on social media like Facebook Instagram YouTube and others so, it is right or not according to Islam.', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-13 15:32:18', '2023-11-11 14:39:15') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0395', 1, NULL, 1, NULL, NULL, 'നജസ് ഉള്ള പാത്രം പോക്കറ്റിൽ ഉള്ളവൻ സമസ്കരിച്ചാൽ ശരിയാകുമോ ?', 'ലാബിലേക്ക് പരിശോധനക്കായി കൊണ്ടു പോകുന്ന കുപ്പിയിലെ മൂത്രവുമായി ഒരാൾ പള്ളിയിൽ കയറി അത് പോക്കറ്റിലാക്കി നമസ്കരിച്ചാൽ അവന്റെ നമസ്കാരം ശരിയാകുമോ ??', 'Malayalam', 'published', '<p>മൂത്രം നിറച്ച കുപ്പി പോക്കറ്റിലിട്ട് നമസ്കരിച്ചാൽ അവന്റെ നമസ്കാരം ശരിയാവുകയില്ല</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-28 23:05:58', '2021-10-28 23:05:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0402', 1, NULL, 1, NULL, NULL, 'Google pay nam upayogikkumbol ninnu kittunna benefits nammukku upayogikkal halal ano', 'Google pay nam upayogikkumbol athil ninnu kittunna benefits upayogikal halal ano', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-30 11:35:07', '2021-10-30 11:35:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0297', 1, NULL, 2, NULL, NULL, 'ഒരു തലാഖ് ചൊല്ലി പിരിയുന്നതിൻ്റെ വിധി എന്താണ് ?', 'ഞാൻ എൻറെ മുൻ ഭാര്യയായിരുന്ന (വീട്ട് പേര്) (പിതാവിന്റെ പേര്) മകൾ (സ്ത്രീയുടെ പേര്) (തിയതി) തീയതിയിൽ അനിവാര്യമായ കാര്യങ്ങളാൽ പല മധ്യസ്ഥകൾക്കും ശേഷം (സാക്ഷികളുടെ പേരുകൾ) എന്നിവരെ സാക്ഷികളാക്കി ഒരു ത്വലാഖ് ചൊല്ലി ബന്ധം വേർപ്പെടുത്തിയിട്ടുള്ളതും ഇതുവരെ തിരിച്ചെടുക്കാത്തതുമാണ്. നിലവിൽ ഞാനും (സ്ത്രീയുടെ പേര്) തമ്മിലുള്ള ബന്ധത്തിന്റെ അവസ്ഥ എന്താണെന്ന് അറിയാൻ താല്പര്യപ്പെടുന്നു. ?', 'Malayalam', 'published', '<p>താങ്കളുടെ മുൻ ഭാര്യയുടെ ഇദ്ദ കഴിയുന്ന പക്ഷം (ത്വലാഖ് ചൊല്ലുമ്പോൾ ഗർഭിണി ആയിരുന്നെങ്കിൽ പ്രസവത്തോട് കൂടി , ഗർഭിണി അല്ലായിരുന്നെങ്കിൽ മൂന്ന് ശുദ്ധികാലം കഴിയുന്നതോടുകൂടി ) താങ്കളും അവരും അന്യ സ്ത്രീ പുരുഷൻമാർ ആയിത്തീർന്നു. ഇനി അവർക്ക് താങ്കളെയോ താങ്കൾ അല്ലാത്ത മറ്റു പുരുഷൻമാരെയോ വിവാഹം കഴിക്കാവുന്നതാണ്.</p>', 5, 0, 5, '1970-01-01 01:00:00', 1, '2021-03-16 22:21:25', '2024-10-18 08:43:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0321', 1, NULL, 5, NULL, NULL, 'Salathul unsصلاة الأنس', 'ഷാഫി, ഹനഫീ മദ് ഹബുകളിൽ സലാത്തുൽ ഉൻസ് എന്ന നമസ്കാരം ഉണ്ടോ? ഇതുമായി ബന്ധപ്പെട്ട് പ്രചരിക്കുന്ന ഹദീസ് ഏത് വിഭാഗത്തിൽ പെട്ടതാണ്?', 'Malayalam', 'published', '<p>ഇസ്&zwnj;ലാമിൽ സ്വലാത്തുൽ ഉൻസ് എന്ന ഒരു നമസ്കാരം ഇല്ല. ഈ നമസ്കാരം ഉണ്ട് എന്ന നിലയിൽ പ്രചരിപ്പിക്കപ്പെടുന്ന ഹദീസ് വ്യാജമാണ്.</p> <p>&laquo;مَن أحْدَثَ فِي أمْرِنا هَذا ما لَيْسَ فِيهِ، فَهُوَ رَدٌّ&raquo; (صحيح البخاري)</p> <p>ആരെങ്കിലും നബി (സല്ലല്ലാഹു അലൈഹി വസല്ലം) പറയാത്ത കാര്യങ്ങൾ തങ്ങൾ പറഞ്ഞു എന്നു പറഞ്ഞാൽ അവൻ നരകത്തിൽ സീറ്റ് പിടിച്ച് കൊള്ളട്ടെ.</p> <p>&laquo;بَلِّغُوا عَنِّي ولَوْ آيَةً، وحَدِّثُوا عَنْ بَنِي إسْرائِيلَ ولاَ حَرَجَ، ومَن كَذَبَ عَلَيَّ مُتَعَمِّدًا، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النّارِ&raquo;</p> <p>صحيح البخاري ٤/&rlm;١٧٠&nbsp;<br /> &nbsp;</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-05-26 05:52:08', '2023-08-01 18:54:39') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0451', 1, NULL, 2, NULL, NULL, 'ആൺകുഞ്ഞിന് വെള്ളിയുടെ വള ഉപയോഗിക്കൽ അനുവാദം ഉണ്ടോ ?', 'ചെറിയ ആൺകുട്ടികൾക് വെള്ളിയുടെ ബ്രേസ്ലെറ്റ്(വെള്ളിയുടെ വള) ധരിക്കൽ അനുവദനീയമാണോ', 'Malayalam', 'published', '<p>അനുവദനീയമാണ്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-13 03:46:57', '2021-11-13 03:46:57') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0290', 1, NULL, 5, NULL, NULL, 'Is vocal karoke permissible....?', 'In modern times, an art called vocal karoke or vocal beatbox is trending. It is an art that makes the same sound of musical instruments with the human mouth. Is it permissible to listen directly....?Is it permissible to record and listen?', 'English', 'published', '<p>&nbsp;</p> <p>Music is a deadly disease that has a profound effect on human heart.</p> <p>أن رسول الله -صلى الله عليه وسلم- قال &laquo; فى هذه الأمة خسف ومسخ وقذف &raquo;. فقال رجل من المسلمين يا رسول الله ومتى ذاك قال &laquo; إذا ظهرت القينات والمعازف وشربت الخمور &raquo;.&nbsp;<br /> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (جامع الترمذي)<br /> ((In this Ummah there will be [people who will be] sunk into the earth, deformed, and upon whom stones will rain from heaven.))</p> <p>When the Sah&acirc;b&icirc; enquired as to when will that be, Ras&ucirc;lull&acirc;h sallall&acirc;hu &lsquo;alayhi wasallam replied:</p> <p>((When singing girls and instruments of music will appear (become prevalent), and wine will be drunk.))</p> <p><br /> As listening to music is prohibited; listening to music made by vocal karaoke is also not permissible.<br /> &nbsp;</p>', 15, 0, 5, '1970-01-01 01:00:00', 1, '2021-02-22 12:16:58', '2023-08-16 11:10:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0436', 1, NULL, 1, NULL, NULL, 'കോട്ടൻ & സിൽക് മിക്സ് ആയ വസ്ത്രം ധരിക്കാൻ പുരുഷന്മാർക്ക് പറ്റുമോ', 'കോട്ടൻ & സിൽക് മിക്സ് ആയ വസ്ത്രം ധരിക്കാൻ പുരുഷന്മാർക്ക് പറ്റുമോ', 'Malayalam', 'published', '<p>ഇന്ന് നമ്മുടെ നാടുകളിൽ അറിയപ്പെടുന്ന കോട്ടൺ സിൽക്ക് മിക്സ് വസ്ത്രത്തിൽ ഉപയോഗിക്കുന്ന സിൽക്ക് തനി സിൽക്ക് അല്ലാത്തതിനാലും കോട്ടൻ കലർത്തപ്പെട്ടതിനാലും അത്തരം വസ്ത്രങ്ങൾ പുരുഷന്മാർക്ക് ഉപയോഗിക്കൽ അനുവദനീയമാണ്</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-05 20:19:55', '2021-11-05 20:19:55') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0407', 1, NULL, 2, NULL, NULL, 'താടി ഷേവ് അല്ലെങ്കില് ട്രിം ചെയ്യുന്നത് ഹറാമോ ഹലാൽ ഓ?', 'എൻ്റെ കോളജിൽ താടി വളർത്താൻ അനുവദിക്കില്ല.അത്കൊണ്ട് എനിക്ക് എൻ്റെ താടി ട്രിം ചെയ്യാനോ ഷേവ് ചെയ്യാനോ അനുവാദം ഉണ്ടോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-31 04:26:22', '2021-10-31 04:26:22') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0524', 1, NULL, 5, NULL, NULL, 'My question is regarding socil media platforms.', 'I&#39;m Certified Nutritionist Advisor, yoga trainner and business women also. In today&#39;s changing world everything is changing rapidly and all the businesses and works are transform from offline to online world. In this changing world my business and work is also transform offline to online world. And now today&#39;s time my totally business is going on social media platforms. And in this condition my question to you that can i record my own photos and videos for suggesting and promoting my own brand food supplements to people of social media. And can i share my own photos and videos of my workouts and yoga on social media for train the people which helps the audience to connect with workouts and healthy lifestyle. So, tells me the answer of my questions that the sharing of photos and video on social media like Facebook Instagram YouTube and others so, it is right or not according to Islam.', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-02-13 15:31:45', '2023-11-11 14:46:43') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0371', 1, NULL, 1, NULL, NULL, 'Is salath ul ishraq and luha same?', 'Is salath ul ishraq and salatul ul luha same ? Please with evidence.', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-21 10:02:34', '2023-11-02 16:11:22') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0453', 1, NULL, 2, NULL, NULL, 'Silver bracelet for male child', 'ചെറിയ ആണ്കുട്ടികൾക് വെള്ളിയുടെ ബ്രേസ്ലെറ് ധരിക്കൽ അനുവദനീയമാണോ ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-13 03:48:18', '2023-11-02 16:19:51') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0413', 1, NULL, 2, NULL, NULL, 'ജീവനുള്ള വസ്തുക്കളുടെ ചിത്രം വരക്കുന്നതിൻ്റെ വിധി എന്താണ് ?', 'എനിക്ക് ചിത്ര രജന വളരെ ഇഷ്ടമുള്ള കാര്യമാണ്. മറ്റ് ചിലർ എന്നോട് ആവശ്യപ്പെടുമ്പോൾജ ജീവനുള്ള വസ്തുക്കളുടെ (ജീവികളുടെ) ചിത്രം വരക്കുന്നതിൻ്റെ വിധി എന്താണ് ?', 'Malayalam', 'published', '<p>ജീവികളുടെ ചിത്രം വരയ്ക്കൽ ഹറാം ആണ്.. ഇനി തല ഇല്ലാത്ത രൂപത്തിലാണ് വരക്കുന്നതെങ്കിൽ അതിനു കുഴപ്പമില്ല...</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-01 21:17:31', '2023-09-06 05:36:03') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0555', 1, NULL, 1, NULL, NULL, 'വസ്തുക്കളുടെ സക്കാത്ത് പണമായി നൽകൽ അനുവദനീയമാണോ ?', 'കച്ചവട സ്ഥാപനത്തിലെ സക്കാത്ത് കൂട്ടുന്ന സന്ദർഭത്തിൽ എൻറെ പാർട്ണറുമായി നിരന്തരം അഭിപ്രായ ഭിന്നത ഉണ്ടാകാറുണ്ട്. എൻറെ പാർട്ണർ ഷാഫി മദ്ഹബകാരനും ഞാൻ ഹനഫി മദ്ഹബ് കാരനും ആണ്. ഞങ്ങൾ കച്ചവട ചരക്കിന്റെ സക്കാത്ത് കൊടുക്കുന്ന സന്ദർഭത്തിൽ എങ്ങനെയാണ് കൊടുക്കേണ്ടത്, പണമാണോ അതെല്ലാ വസ്തുക്കളാണോ?', 'Malayalam', 'assigned', NULL, 8, 0, 5, NULL, NULL, '2022-10-16 02:08:26', '2022-10-16 02:08:26') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0423', 1, NULL, 5, NULL, NULL, 'മരണശേഷം കിട്ടുന്ന നന്മകളിൽ മറ്റുള്ളവർ നമുക്ക് വേണ്ടി ചെയ്യുന്ന ദിക്ർ മുതലായവ ഉൾപ്പെടുമോ?', 'മരണ ശേഷം മരിച്ചയാളുടെ കുടുംബക്കാരല്ലാതെ(ഭാര്യ, മക്കൾ, മാതാപിതാക്കൾ )ബാക്കിയുള്ള ആളുകൾ ഓതുന്ന ഖുർആൻ ദിക്ർ മുതലായവ ഖബറിൽ പ്രയോജനം ചെയ്യുമോ.. അയാളുടെ നന്മ വർധിപ്പിക്കുമോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-02 03:55:52', '2023-11-02 16:14:47') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0315', 1, NULL, 5, NULL, NULL, 'Hadith on fasting on Eid day', 'അസ്സലാമു അലൈകും വ റഹ്മതുല്ലാഹ് &quot;ശവ്വാൽ ഒന്നി&quot;ന് നോമ്പ് അനുഷ്ഠിക്കുക നിഷിദ്ധമാണ് ആണ് എന്ന് റസൂൽ (സ) പറഞ്ഞതായി ജനാബ് മണിക്ഫാനെ അനുകൂലിക്കുന്ന പണ്ഡിതരടക്കം പലരും ഉദ്ധരിക്കുന്നതായി കേട്ടിട്ടുണ്ട്. ഇങ്ങനെ ഒരു ഹദീസ് ഉണ്ടോ? ഉണ്ടെങ്കിൽ പദപ്രയോഗങ്ങൾ എങ്ങനെയാണ്. ജനാബ് മണിക്ഫാനും അദ്ദേഹത്തെ അനുകൂലിക്കുന്നവരും വാദിക്കുന്നത് അവർ പറയുന്ന ശവ്വാൽ ഒന്നിന് നോമ്പ് അനുഷ്ഠിക്കുക വഴി മുസ്ലിമീങ്ങൾ ഹറാം ചെയ്യുകയാണ് എന്നാണ്.<br /> മണിക്ഫാന്റെ ഒരു പ്രസംഗം തുടങ്ങുന്നത് തന്നെ ഈ ഒരു പ്രിമൈസിൽ നിന്ന് കൊണ്ടാണ്. അത് വഴി അദ്ദേഹത്തിന് സാധാരണക്കാരായ പലരെയും എളുപ്പത്തിൽ സ്വാധീനിക്കാൻ കഴിഞ്ഞിട്ടുണ്ട്.<br /> ചെറുപ്പത്തിൽ മദ്രസയിൽ ഒക്കെ പഠിച്ചത് പെരുന്നാൾ ദിവസം (അഥവാ ആളുകൾ പെരുന്നാൾ ആഘോഷിക്കുന്ന ദിവസം) നോമ്പ് ഹറാം ആണ് എന്നാണ്. ശരിയായ ഹദീസ് വ്യക്തമാക്കാമോ?', 'Malayalam', 'published', '<p>പെരുന്നാൾ ദിവസങ്ങളിൽ നോമ്പ് പിടിക്കൽ നിഷിദ്ധമാണ് എന്നറിയിക്കുന്ന &nbsp;നിരവധി ഹദീസുകൾ ബുഖാരി മുസ്ലിം അടക്കമുള്ള &nbsp;പ്രശസ്തമായ പല ഹദീസ് ഗ്രന്ഥങ്ങളിലും വന്നിട്ടുണ്ട് . (ഹദീസ് താഴെ ചേർക്കുന്നതാണ്). &nbsp;പക്ഷേ, പെരുന്നാൾ എന്നാണ് എന്ന് നിശ്ചയിക്കാൻ &nbsp;ശരീഅത്ത് ചില മാനദണ്ഡങ്ങൾ വച്ചിട്ടുണ്ട്. അഥവാ ഇരുപത്തിയൊമ്പതാം ദിവസം &nbsp;പൂർത്തിയായശേഷം നീതിമാന്മാരായ രണ്ടോ അതിൽ കൂടുതൽ ആളുകളോ മാസപ്പിറവി കണ്ടതായി അറിയിച്ചാൽ മാത്രമേ &nbsp;പിറ്റേദിവസം &nbsp;പെരുന്നാൾ ആയി പരിഗണിക്കുകയുള്ളൂ. അല്ലാത്തപക്ഷം ആ മാസം 30 ദിവസം ആയിരിക്കും. ഇങ്ങനെ മാസപ്പിറവി കണ്ടാൽ മാത്രമേ നോമ്പ് തുടങ്ങുവാനും അവസാനിപ്പിക്കുവാനും പറ്റുകയുള്ളൂ എന്ന് ഹദീസിൽ വന്നിട്ടുണ്ട്. (മുസ്ലിം : 1081) .<br /> &nbsp;ഈ രീതിയിൽ അല്ലാതെ &nbsp;കണക്കുകൾ ഉപയോഗിച്ചു പെരുന്നാൾ നിർണ്ണയിച്ചാൽ അത് പരിഗണനീയമല്ല എന്ന വിഷയത്തിൽ പണ്ഡിതർ ഏകാഭിപ്രായക്കാരാണ്. ചോദ്യത്തിൽ പ്രതിപാദിക്കപ്പെട്ട വ്യക്തി ചില കണക്കുകൾ ഉപയോഗിച്ച് &nbsp;പെരുന്നാൾ നിർണയിക്കുന്നതിനാൽ അത് പരിഗണിക്കപ്പെടുന്നതല്ല.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-05-13 07:35:16', '2023-03-31 10:28:48') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0379', 1, NULL, 1, NULL, NULL, 'മന്ത്രിച്ച് ഓതിയ ചരട് കെട്ടൽ കുഴപ്പമുണ്ടോ?', 'പല ലക്ഷ്യങ്ങൾക്ക് വേണ്ടി കയ്യിലോ കാലിലോ മന്ത്രിച്ച് ഊതിയ കറുത്ത ചരട് കെട്ടുന്നതു കൊണ്ട് കുഴപ്പമുണ്ടോ ?', 'Malayalam', 'published', '<p>അനുവദനീയമായ നല്ല ലക്ഷ്യങ്ങൾക്ക് വേണ്ടി മന്ത്രിച്ച് ഊതിയ ചരട് ശരീരത്തിൽ കെട്ടാവുന്നതാണ്. എന്നാൽ മന്ത്രത്തിൽ ശിർക് , കുഫ്റിന്റെ വാചകങ്ങൾ ഇല്ലാതിരിക്കുക, മന്ത്രത്തിന്റെ അർത്ഥം അറിഞ്ഞിരിക്കുക, മന്ത്രിച്ച ചരട് സ്വന്തമായി നന്മ ഉണ്ടാക്കുവാനോ വിപത്തുകൾ നീക്കുവാനോ കഴിവുള്ളതാണെന്ന് വിശ്വസിക്കാതിരിക്കുക. എന്നീ നിബന്ധനകൾ നിർബന്ധമായും പാലിച്ചിരിക്കണം</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-21 22:06:58', '2021-10-21 22:06:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0337', 1, NULL, 2, NULL, NULL, 'യാത്രയിൽ വെച്ച് നമസ്കരിച്ചത് മടക്കനോ', 'ളുഹറിൻ്റെ സമയത്തിൽ അസ്ർ ജംമ് ആക്കി നമസ്കരിച്ച വ്യക്തി അസർ ബാങ്ക് വിളിക്കുന്നതിന് മുമ്പ് നാട്ടിലെത്തിയാൽ അസർ നമസ്കരിക്കേണ്ടതുണ്ടോ?', 'Malayalam', 'published', '<p>ളുഹറിന്റെ സമയത്ത് അസ്ർ ജംമ് ആക്കി നമസ്കരിച്ച വ്യക്തി അസ്ർ ബാങ്ക് വിളിക്കുന്നതിന്&zwnj; മുമ്പ് നാട്ടിലെത്തിയാൽ അസ്ർ നമസ്കരിക്കേണ്ടതില്ല</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 01:28:12', '2021-08-12 01:28:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0360', 1, NULL, 1, NULL, NULL, 'Dawah to Non Muslims', 'Why we muslims are not doing dawa to Non Muslims, especially ulemas, as it is compulsory to us,and the Indian has the freedom to preach?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-19 13:47:28', '2023-11-02 16:08:52') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0389', 1, NULL, 1, NULL, NULL, 'ഓൺലൈൻ trading ന്റെ ഭാഗമായുള്ള coin നമ്മൾ cash മുടക്കി വാങ്ങിക്കുകയും...ഉദാഹരണം ഒരു 10000 രൂപയുടെ പല coins മേടിക്കുന്നു... അതിൽ ചില coins ന്റെ rate കൂടുകയും ചിലത് കുറയുകയും ചെയ്യാൻ സാധ്യത നിലനിൽക്കുന്നു... അതായത് ലാഭവും നഷ്ടവും സംഭവിക്കാൻ സാധ്യതയുണ്ട്....', 'ഓൺലൈൻ trading ന്റെ ഭാഗമായുള്ള coin നമ്മൾ cash മുടക്കി വാങ്ങിക്കുകയും...ഉദാഹരണം ഒരു 10000 രൂപയുടെ പല coins മേടിക്കുന്നു... അതിൽ ചില coins ന്റെ rate കൂടുകയും ചിലത് കുറയുകയും ചെയ്യാൻ സാധ്യത നിലനിൽക്കുന്നു... അതായത് ലാഭവും നഷ്ടവും സംഭവിക്കാൻ സാധ്യതയുണ്ട്.... ഇത് കച്ചവട സാധനങ്ങൾ സ്റ്റോക്ക് ചെയ്തു വില കൂടുകയും കുറയുകയും ചെയ്യുന്നതിന് സമമല്ലേ.. ഇവിടെ കച്ചവട വസ്തുവായി stock ചെയ്യുന്നത് cash മുടക്കി മേടിച്ച coins ആണെന്ന് മാത്രം.....എന്താണ് വിധി... ഈ ഓൺലൈൻ trading അനുവദനീയമാണോ', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-26 11:39:12', '2021-10-26 11:39:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0333', 1, NULL, 5, NULL, NULL, 'Beauty parlour business', 'Is Islam allowed to start beauty parlour business or shop , take shareholder?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-07-24 06:22:52', '2021-07-24 06:22:52') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0353', 1, NULL, 1, NULL, NULL, 'کسی سنی لڑکی کا اس قسم کے اثنا عشری مسلمان لڑکے سے نکاح کا کیا حکم ہے؟', 'مفتی صاحب بعد از سلام سوال عرض یہ ہے کہ ایک معتدل مزاجاثنا عشری مسلمانلڑکا جو صحآبہ کرام کا احترام کرتا ہو، اور صحابہ کرام اور امہات المومنین خصوصاحضرت عائشہ رضی اللہ عنہا پر تبرا نہیں کرتا ہو بلکہ تبرا کرنے کو ناجائز اور بر اکہتا اور سمجھتا ہے،اور حضرت علی رضہ اللہ عنہ کو انبیا کرام سے افضل نہیں مانتا ،بلکہ اہل بیت کا معتقد ہے پانچ وقت نمازیں پڑھتا ہے،زکاۃ ادا کرتا ہے، شیعہ گھرانے میں پرورش پانے کے باوجود معتدل مزاج رکھتے ہوئے کئی سال سنی طریقے کے مطابق بھی نمازیں پڑھتا رہا ہے وہ کہتا ہے کہ ہم اہل بیت کے بارہ اماموں کے معتقد ہیں لیکن یہ عقیدہ نہیں کہ نعوذباللہ امام حلال و حرام کا اختیار رکھتے ہیں ،یا نعوذبا اللہ حضرت جبرائیل سے وحی پہچانے میں غلطی ہوئی ہےبلکہ ہم صحابہ کرام میں حضرت علی رضی اللہ عنہ کے تفضل کے قائل ہیں لیکن ہم شیخین (حضرت ابو بکر و عمر رضی اللہ عنھما) کی شان میں گستاخیاں نہیں کرتے یہ ہمارا تاریخی اختلاف ہے جس میں طرفین کے پاس بھی الگ الگ دلائل ہیں۔ اب سوال یہ ہے کہ کیا ایسے شخص کا سنی گھرانے کی لڑکی سے مندرجہ ذیل شرائط پر کہ: 1-لڑکی تادم مرگ اپنے مسلک پر قائم رہے گی اور لڑکا اپنے عقاید و مذہبی معاملات میں لڑکی پر کسی قسم کی زورو زبردستی نہیں کرےگا ۔ 2-اولاد کے مسلک کے معاملے کو اولاد کےاپنے اختیار رپر چھوڑا جائے گا کہ وہ بڑے ہوکر سنی یا اثنا عشری مین سے اپنے علم اورتربیت کے مطابق جو راستہ اختیار کرنا چاہیں گے لڑکا یا اس کے گھر والےاپنے مسلک پر چلانے پر زبردستی نہیں گےاسی طرح لڑکی یا اس کے گھر والے اولاد کو اپنے مسلک کی طرف مائل کرنے پر کسی قسم کی زبردستی نہیں کریں گے بلکہ مسلک کا انتخاب اولاد کا اپنا ذاتی ومذہبی حق ہوگا ۔ مندرجہ بالا شرائط پر کسی سنی لڑکی کا اس اثنا عشری مسلمان لڑکے سے نکاح کا کیا حکم ہے؟ (واضح رہے لڑکی اور لڑکا دونوں اعلٰی تعلیم یافتہ اور پاکستان آرمی کے ادارے میں بر سرِ روزگار ہیں اور معاشی طور پر خود مختار بھی ہیں )', 'Urdu', 'published', '<p><span dir=\"RTL\">نکاح کے لیے لڑکی اور لڑکے کا ایک مذہب ہونا ضروری ہے یعنی دونوں کا مسلمان ہونا ضروری ہے چونکہ اثنا عشری اپنے عقائد باطلہ کی وجہ سے جو ان کی کتابوں میں موجود ہیں اسلام سے خارج اور کافر و مرتد ہیں، اس لیے سنی لڑکے کا نکاح شیعہ لڑکی سے یا شیعہ لڑکی کا نکاح سنی لڑکے کے ساتھ جائز نہیں, نکاح سرے سے ہوگا ہی نہیں, &nbsp;</span></p> <p><span dir=\"RTL\">سوال میں اگرچہ یہ کہا گیا ہے کہ مذکورہ شخص اثنا عشریہ کے بعض عقیدوں سے برائت ظاہر کرتا ہے تاہم شیعوں کے یہاں تقیہ اور کتمان ایسی چیزیں ہیں جن کے ذریعہ وہ اپنے اصل عقائد، خیالات، &nbsp;رحجانات کو چھپالے جاتے ہیں، بلا ثبوت کسی کے بارے میں بدگمانی نہیں کرنی چاہیے لیکن شیعوں کا عقیدہ صحابہٴ کرام، قرآن پاک، حضرت عائشہ صدیقہ کے بہتان کے سلسلہ میں معروف ہے جس کی بنا پر عام طور پر شیعوں کو کافر مرتد کہا جاتا ہے اور ان سے نکاح ناجائز بتلایا جاتا ہے, اگر کسی کے بارے میں یقین کے درجہ میں یہ معلوم ہوجائے کہ وہ نہ تو تمام صحابہ کے مرتد ہونے کا قائل ہے (چند کو چھوڑ کر)، &nbsp;نہ قرآن پاک کے بعض حصے کے غائب ہونے کا عقیدہ رکھتا ہے ، نہ ائمہ کے معصوم ہونے کا عقیدہ رکھتا ہے(کہ جیسے انبیاء سے گناہ صادر ہونا نا ممکن ہے اسی طرح سے ائمہ کو نہیں مانتا ہے)، &nbsp;نہ ہی حضرت عائشہ صدیقہ رضی اللہ تعالیٰ عنہا پر باندھے گئے بہتان کو صحیح سمجھتا ہے &nbsp;(صرف بدزبانی نہ کرنا ہی کافی نہیں بلکہ اس بہتان میں ذرہ بھر بھی سچائی ہونا نہیں مانتا ہے) ،نہ ہی نبوت کے پیغام رسانی کے سلسلہ میں حضرت جبریل علیہ السلام سے غلطی ہوجانے کا عقیدہ رکھتا ہے وغیرہ وغیرہ تو ایسی شخص پر کفر کا حکم لگانے میں اگرچہ احتیاط کی جائے گی اور اسے کافر نہیں کہیں گے؛ </span></p> <p><span dir=\"RTL\">لیکن نکاح جیسا نازک رشتہ قائم کرنے سے پہلے اچھی طرح تحقیق کرلینا اور مقامی علماء سے مشورہ لے کر اطمینان کرلینا ضروری ہوگا, کیونکہ نکاح کے لیے ایسی شخص کا انتخاب ہونا چاہئے جو دین واخلاق کے اعتبار سے صحیح قابل اطمینان اور پختہ ہو ورنہ اس کے غلط اثرات خود پر یا ہونے والی اولاد پر پڑنے کے امکانات رہتے ہیں, بالخصوص جبکہ سوال میں سنی لڑکی کا شیعہ لڑکے سے نکاح کرنے کے بارے پوچھا گیا ہے تو ظاہر ہے کہ مزید احتیاط لازم ہے</span></p>', 11, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-28 08:13:58', '2024-01-06 08:23:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0464', 1, NULL, 1, NULL, NULL, 'ഒരു വഖ്ഫ് ഭൂമിയിൽ നിന്നും ലഭിക്കുന്ന വരുമാനം അതിൻറെ ചെലവിനേക്കാൾ കുറവാകുന്ന സന്ദർഭത്തിൽ', 'ഒരു വഖ്ഫ് ഭൂമിയിൽ നിന്നും ലഭിക്കുന്ന വരുമാനം അതിൻറെ ചെലവിനേക്കാൾ കുറവാകുന്ന സന്ദർഭത്തിൽ / അല്ലെങ്കിൽ മുസ്ലിംകൾക്ക് പൊതുവായി വഖ്ഫ്ചെയ്യപ്പെട്ട ഭൂമി കൃഷി ചെയ്യാനോ ഖബറടക്കാനോ പറ്റാത്ത നിലയിലായിതീർന്നാൽ അതിനുപകരം മറ്റൊരു ഉപകാരപ്രദമായ അതിനെക്കാൾ ഗുണമുള്ള ഭൂമിയെ മാറ്റി വാങ്ങൽ ഹനഫിമദ്ഹബ് അനുസരിച്ച്അനുവദനീയമാ ണോ?', 'Malayalam', 'published', '<p>ചോദ്യത്തിൽ പരാമർശിക്കപ്പെട്ടതനുസരിച്ച് വഖ്ഫ് ചെയ്യപ്പെട്ട ഭൂമി പ്രയോജനരഹിതമായനാൽ അതിനെ വിൽക്കലും ഉപകാരപ്രദമായ, പ്രയോജനമുള്ള മറ്റൊരു ഭൂമി പകരമായി വാങ്ങലും അനുവദനീയമാണ്.</p> <p>വിൽപ്പനയും വാങ്ങലും നടത്തേണ്ടത് വഖ്ഫിന്റെ ഉത്തരവാദിത്വം ഏൽപ്പിക്കപ്പെട്ട വ്യക്തികൾ ആയിരിക്കണം. ആദ്യ ഭൂമി വിറ്റ് കിട്ടുന്ന പൈസ മുഴുവനായും രണ്ടാമത്തെ ഭൂമി വാങ്ങുന്നതിനായി ഉപയോഗിക്കേണ്ടതാണ്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-12-01 02:14:49', '2024-07-09 06:03:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0478', 1, NULL, 1, NULL, NULL, 'ഹജ്ജ് ഉംറ നിർവഹിക്കാൻ പണം തികഞ്ഞില്ലെങ്കിൽ എന്താണ് നിയമം ?', '2021/22 വർഷം ഹജ്ജും ഉംറയും നിർവഹിക്കുന്നതിന് സാധാരണയിൽ കൂടുതൽ പണം ആവശ്യമായി വന്നിരിക്കുന്നു. ഈ വർഷം കൂടി മാത്രം അവസരം ഉള്ള ആൾ നിർദ്ദേശിക്കപ്പെട്ട പണം കയ്യിൽ ഇല്ലെങ്കിൽ എന്താണ് ചെയ്യേണ്ടത്, അയാൾ പാപിയായി മാറുമോ ?', 'Malayalam', 'published', '<p>നിലവിൽ ഹജ്ജിന് മതിയായ പണം കൈവശമില്ലാത്ത വ്യക്തിക്ക് ഹജ്ജ് നിർബന്ധമാവുകയില്ല, അതിനാൽ അയാൾ പാപിയാകില്ല.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-12-30 06:01:47', '2024-09-30 12:49:20') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0313', 1, NULL, 5, NULL, NULL, 'Phigykart എന്ന MLM കമ്പനിയിൽ നിന്നും സമ്പാദിക്കുന്ന ആളുടെ income tax file ചെയ്ത് കിട്ടുന്ന വരുമാനം ഹലാലനോ?', 'Phigykart എന്ന MLM കമ്പനിയിൽ നിന്നും സമ്പാദിക്കുന്ന ആളുടെ income tax file ചെയ്ത് കിട്ടുന്ന വരുമാനം ഹലാലനോ? ഇങ്ങനെ ചെയ്യുന്നത് കൊണ്ട് അയാളുടെ commision il നിന്നും പിടിച്ച് വെച്ച TDS amount ayalk refund kittan chance und', 'Malayalam', 'pending', NULL, 2, 0, 5, NULL, NULL, '2021-05-10 06:14:10', '2023-11-02 05:02:46') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0314', 1, NULL, 1, NULL, NULL, 'ഹറാമായ സമ്പാദ്യം', 'السلام عليكم  ഒരാൾക്ക് ( മുസ്ലിം ) ഹറാമായ സമ്പാദ്യം മാത്രം ആണ് ഉള്ളത് .. വേറെ ഒന്നും ഇല്ല അയാളുടെ വീട് , വസ്ത്രം , വാഹനം , അയാളുടെ ഭാര്യയുടെ വസ്ത്രം മക്കളുടെ വസ്ത്രം എല്ലാം ഈ സമ്പാദ്യത്തിൽ നിന്നുമാണ് ..  അയാൾ ഹറാമിൻ്റെ പാപ ഭാരം മനസ്സിലാക്കി ആ ഹറാമായ സമ്പാദ്യ മാർഗത്തിൽ നിന്നും പിന്മാറി ഇപ്പോൾ അയാൾക്ക് ഒരു വരുമാന മാർഗവും ഇല്ല കാരണം എന്തെങ്കിലും ചെയ്യണം എങ്കിൽ ഈ ഹറാമായ പണം അലാതെ വേറെ ഒന്നും അയാളുടെ കയ്യിൽ ഇല്ല സമൂഹത്തിൽ നല്ല അന്തസ്സോടെ ജീവിക്കുന്ന വെക്തിയും ആണ്.. ഭാര്യക്കും മക്കൾക്കും കൊടുക്കാനും അയാളുടെ കയ്യിൽ വേറെ ഒന്നും ഇല്ല.. ചോദ്യം :1 അയാൾ എന്ത് ചെയ്യണം. ? 2 ഈ പണം ഉപയോഗിച്ച് ഹലാലായ ബിസിനസ് ചെയ്ത് ജീവിക്കാമോ ? 3 ഇയാളുടെ മകന് പിതാവിൻ്റെ ഈ ഹറാമായ സമ്പാദ്യം അനന്തരം എടുക്കാമോ. ? Nb : ഈ ഹറാമായ സമ്പാദ്യം മുഴുവനും ഉപേക്ഷിച്ചാൽ ഇയാൾ ഉടുതുണി പോലും ഉടമസ്ഥതയിൽ ഇല്ലാതെ വീട് വിട്ട് പുറത്ത് ഇറങ്ങേണ്ടി വരും...... السلام عليكم', 'Malayalam', 'published', '<p>ഈ വ്യക്തി തൻറെ കയ്യിലുള്ള ഹറാമായ സമ്പാദ്യം ഉപയോഗിച്ച് ഹലാലായ ഒരു ബിസിനസ് ആരംഭിക്കുക. &nbsp;അതിൽനിന്നും ലഭിക്കുന്ന ലാഭം ഹലാലാണ്. ഈ ഹലാലായ ലാഭം ഉപയോഗിച്ച് താൻ ഈ കച്ചവടം തുടങ്ങാൻ എത്ര രൂപയാണ് ഇൻവെസ്റ്റ് ചെയ്തത് (ഹറാമായ പണം) ആ തുകയും അതുപോലെ ഹറാമായ സമ്പത്തിലൂടെ സമ്പാദിച്ച മുഴുവൻ വസ്തുക്കളുടെയും വില കണക്കാക്കി ആ തുകയെ ഹലാലായ പുതിയ ബിസിനസിൽ നിന്നും ലഭിക്കുന്ന ലാഭം കൊണ്ട് ഫഖീർ/ മിസ്കീൻ തുടങ്ങിയ സാധുക്കൾക്കൊ, അല്ലെങ്കിൽ സാമൂഹിക സേവനങ്ങൾക്കോ പ്രതിഫലം &nbsp;ആഗ്രഹിക്കാതെ ദാനം ചെയ്യുക</p> <p>قَوْلُهُ اكْتَسَبَ حَرَامًا إلَخْ) تَوْضِيحُ الْمَسْأَلَةِ مَا فِي التَّتَارْخَانِيَّة حَيْثُ قَالَ: رَجُلٌ اكْتَسَبَ مَالًا مِنْ حَرَامٍ ثُمَّ اشْتَرَى فَهَذَا عَلَى خَمْسَةِ أَوْجُهٍ: أَمَّا إنْ دَفَعَ تِلْكَ الدَّرَاهِمَ إلَى الْبَائِعِ أَوَّلًا ثُمَّ اشْتَرَى مِنْهُ بِهَا أَوْ اشْتَرَى قَبْلَ الدَّفْعِ بِهَا وَدَفَعَهَا، أَوْ اشْتَرَى قَبْلَ الدَّفْعِ بِهَا وَدَفَعَ غَيْرَهَا، أَوْ اشْتَرَى مُطْلَقًا وَدَفَعَ تِلْكَ الدَّرَاهِمَ، أَوْ اشْتَرَى بِدَرَاهِمَ أُخَرَ وَدَفَعَ تِلْكَ الدَّرَاهِمَ. قَالَ أَبُو نَصْرٍ: يَطِيبُ لَهُ وَلَا يَجِبُ عَلَيْهِ أَنْ يَتَصَدَّقَ إلَّا فِي الْوَجْهِ الْأَوَّلِ،وَقَالَ الْكَرْخِيُّ: فِي الْوَجْهِ الْأَوَّلِ وَالثَّانِي لَا يَطِيبُ، وَفِي الثَّلَاثِ الْأَخِيرَةِ يَطِيبُ، وَقَالَ أَبُو بَكْرٍ: لَا يَطِيبُ فِي الْكُلِّ، لَكِنْ الْفَتْوَى الْآنَ عَلَى قَوْلِ الْكَرْخِيِّ دَفْعًا لِلْحَرَجِ عَنْ النَّاسِ<br /> (رد المحتار:٥/٢٣٥)</p> <p>صرح الفقهاء بأن من اكتسب مالا بغير حق فإما ان يكون كسبه بعقد فاسد كالبيوع الفاسدة والإستأجار على المعاصي والطاعات او بغير عقد كالسرقة، والغصب، والخيانة، والغلول، ففي جميع الاحوال المال حاصل له حرام عليه ولكن ان اخذه من غير عقد لم يملكه، ويجب عليه ان يرده على مالكه ان وجد المالك والا ففي جميع الأحوال يجب عليه أن يتصدق بمثل تلك الاموال على الفقراء..... ولكن لا يريد بذلك الأجر والثواب ولكن يريد دفع المعصية عن نفسه<br /> (بذل المجهود: ١:٣٧)</p> <p>മേൽപറയപ്പെട്ട രൂപത്തിൽ ഹറാമായ സമ്പത്ത് ഒഴിവാക്കി&nbsp; ഹലാല് മാത്രം അവശേഷിക്കുന്നുവെങ്കിൽ മകന് പിതാവിൻറെ സ്വത്ത് അനന്തരമായി എടുക്കാം അല്ലാത്തപക്ഷം അനന്തരമായി കിട്ടുന്ന സ്വത്ത് ദാനം ചെയ്യണം</p> <p>وَالْحَاصِلُ أَنَّهُ إنْ عَلِمَ أَرْبَابَ الْأَمْوَالِ وَجَبَ رَدُّهُ عَلَيْهِمْ، وَإِلَّا فَإِنْ عَلِمَ عَيْنَ الْحَرَامِ لَا يَحِلُّ لَهُ وَيَتَصَدَّقُ بِهِ بِنِيَّةِ صَاحِبِهِ<br /> (رد المحتار :٥/٩٩)<br /> &nbsp;</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-05-10 09:14:09', '2023-03-31 10:46:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0289', 1, NULL, 5, NULL, NULL, 'ഒരു സ്ത്രീക്ക് സംശയ രോഗിയായ ഭർത്താവിൽ നിന്നുമുള്ള മോചനം ഏത് രൂപത്തിൽ സാധിക്കും?', 'ഭർത്താവ് ഗൾഫിൽ ആയ എന്റെ ഒരു ബന്ധുവിന്റെ അവസ്ഥയാണ് പറയുന്നത്. 15 വർഷത്തോളം ആയി അങ്ങിനെ ആണ്. ഇടക്ക് വരും. ഭർത്താവിന്റെ വീട്ടുകാർ നല്ല ഉപദ്രവം ഉണ്ടാക്കുന്നുണ്ട്. അതിലും ബുദ്ധിമുട്ടുള്ളത് ഭർത്താവിന്റെ ഭാഗത്തു നിന്നുമാണ്. ഭർത്താവ് ഭയങ്കര സംശയ രോഗി ആണ്. വളരെ മോശമായ ആരോപണങ്ങൾ എപ്പോഴും. വാപ്പയെയും ആങ്ങളമാരെയും കൂട്ടി വെച്ചു പറയും. ഈ സ്ത്രീ ആരുടെയെങ്കിലും കൂടെ ഇറങ്ങി പോകുമോ എന്നാണ് ഭർത്താവിന്റെ ഭയം. എപ്പോഴും അതു പറയുകയും ചെയ്യും. എപ്പോഴും ഇതാണ് അവസ്ഥ. ചീത്ത വിളിയും, കൂട്ടി വെച്ചു പറച്ചിലും ആണ്. ആ സ്ത്രീയെ സമാധാനത്തോടെ ജീവിക്കാൻ സമ്മതിക്കുന്നില്ല. ഭർത്താവിന് വേറെ ബന്ധങ്ങളും ഉള്ളതായി ആ സ്ത്രീക്ക് തെളിവ് സഹിതം ബോധ്യപ്പെട്ടിട്ടുമുണ്ട്. ഭർത്താവിന്റെ കൂടെ ജീവിക്കാൻ വയ്യാത്ത അവസ്ഥയിൽ ആണ് ഇപ്പോൾ. ഇസ്ലാമികമായി ആ സ്ത്രീയുടെ വീട്ടുകാർക്ക് ചെയ്യാൻ പറ്റുന്ന കാര്യങ്ങൾ എന്തൊക്കെയാണ്? <ol> ആ സ്ത്രീയെ ഭർത്താവിന്റെ അനുവാദം ഇല്ലാതെ വീട്ടിൽ കൊണ്ട് നിർത്താൻ അനുവാദം ഉണ്ടോ? ഭർത്താവിൽ നിന്നും വിവാഹ മോചനം നേടാൻ ഭാര്യക്ക് അനുവാദം ഉണ്ടോ കുട്ടികളെ കൂടെ കൊണ്ടു വന്നിട്ട് ഭർത്താവിന്റെ വീട്ടിൽ അല്ലാതെ മാറി താമസിക്കാൻ അനുവാദം ഉണ്ടോ? </ol> അല്ലെങ്കിൽ ഇസ്ലാമികമായി എങ്ങിനെയാണ് ആ സ്ത്രീയെ ഭർത്താവിൽ നിന്നും രക്ഷിക്കുക?', 'Malayalam', 'published', '<p>മേൽ പറയപ്പെട്ട ഭാര്യ ഭർത്താക്കന്മാർക്കിടയിൽ ഒരുമിച്ച് മുന്നോട്ട് ജീവിക്കാൻ പറ്റാത്ത നിലയിലുള്ള പ്രശ്നം ഉള്ളതിന്റെ പേരിൽ ഭാര്യ തന്റെ ഭർത്താവിന് മോചനദ്രവ്യം നൽകാമെന്ന വ്യവസ്ഥയിൽ വിവാഹബന്ധം ഒഴിവാക്കിത്തരാൻ അദ്ദേഹത്തോട് ആവശ്യപെടാവുന്നതാണ്. ഇതിന് ശരീഅത്തിന്റെ ഭാഷയിൽ ഖുൽഅ് (خلع) എന്ന് പറയുന്നു.&nbsp;</p> <p>എന്നാൽ ഭർത്താവ് ഖുൽഅ് ചെയ്യാൻ തയ്യാറല്ലായെങ്കിൽ അവൾക്ക് ഏതെങ്കിലും ദാറുൽ ഖളായെയോ അല്ലെങ്കിൽ ശരീഅത്ത് നിയമങ്ങളെ കുറിച്ച് അറിവുള്ള പണ്ഡിതന്മാർ അടങ്ങിയ കമ്മിറ്റിയെയോ സമീപിക്കുകയും, ഭാര്യാ ഭർത്താക്കന്മാർക്ക് തീർത്തും യോജിച്ചു പോകാൻ പറ്റില്ലെന്ന് കമ്മിറ്റിക്ക് ബോധ്യപ്പെടുന്ന പക്ഷം മാലിക്കി മദ്ഹബനുസരിച്ച് ആ മദ്ഹബിലെ നിബന്ധനകളെ പാലിച്ചുകൊണ്ട് ഈ വിവാഹ ബന്ധം ആ കമ്മറ്റിക്ക് വേർപെടുത്താവുന്നതാണ്. ഇപ്രകാരം വിവാഹബന്ധം വേർപെടുത്തുന്നതിന് ഫസ്ഖ് (فسخ) എന്ന് പറയുന്നു.&nbsp;</p> <p>ഫസ്ഖ് നടന്ന ശേഷം സ്ത്രീ ഇദ്ദ (عدة) അനുഷ്ഠിക്കണം. ഭർത്താവിൻറെ വീട്ടിൽ തന്നെയാണ് ഇദ്ദ (عدة) അനുഷ്ഠിക്കേണ്ടത്, അത് സാധിക്കാതെ വന്നാൽ തന്റെ വീട്ടിലേക്ക് പോയി അവിടെ ഇദ്ദ (عدة) അനുഷ്ഠിക്കാവുന്നതാണ്.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-02-19 09:58:41', '2023-08-08 05:42:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0602', 1, NULL, 2, NULL, NULL, 'നമസ്കാരത്തിൽ ഫോൺ off ആക്കിയാൽ നമസ്കാരം മുറിയുമോ', 'നമസ്കാരത്തിൽ മൊബൈൽ റിംഗ് ചെയ്താൽ അത് off ആക്കുന്നതിലൂടെ നമസ്കാരം ബാത്വിൽ ആകുമോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-07-31 18:22:47', '2023-08-21 19:01:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0334', 1, NULL, 2, NULL, NULL, 'ജംമ്മിൻ്റെ കിലോമിറ്റർ എത്ര?', 'ജംമ്മിൻ്റെ കൃത്യമായാ കിലോമിറ്റർ എത്ര?', 'Malayalam', 'published', '<p>81 കിലോമീറ്റർ ദൂരമുള്ള യാത്ര ആണെങ്കിൽ നമസ്കാരം ജംഅ് ആക്കാവുന്നതാണ്</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 01:22:16', '2024-01-14 09:43:24') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0463', 1, NULL, 1, NULL, NULL, 'പണയത്തിലുള്ള സ്വർണ്ണം തിരിച്ചെടുക്കുന്നതിനായി സകാത്ത് ഫണ്ടിൽ നിന്നും ഒരു സകാത്ത് കമ്മിറ്റി അനുവദിച്ച് കൊടുക്കുകയാണെങ്കിൽ അനുവദനീയമാണോ?', 'ഞങ്ങളുടെ മഹല്ലിൽ പ്രവർത്തിക്കുന്ന ഒരു സകാത്ത് കമ്മിറ്റി പണയത്തിലുള്ള സ്വർണ്ണം തിരിച്ചെടുക്കുന്നതിനെന്ന് കാണിച്ച് ഒരാൾ നൽകിയ അപേക്ഷയുടെ അടിസ്ഥാനത്തിൽ പണയ മുതലിന്റെ വിലയോളം വരുന്ന തുക ഏതാണ്ട് ഒരു ലക്ഷത്തി പതിനയ്യായിരം രൂപാ സകാത്ത് ഫണ്ടിൽ നിന്നും അനുവദിച്ച് കൊടുക്കുകയുണ്ടായി. ഇത് അനുവദനീയമാണോ?', 'Malayalam', 'published', '<p>സക്കാത്തിന്റെ തുക ലഭിച്ച വ്യക്തിക്ക് സക്കാത്തിന്റെ അർഹതയുണ്ടെന്ന് ബോധ്യപ്പെട്ടത് പ്രകാരമാണ് കമ്മറ്റി പണം നൽകിയതെങ്കിൽ ആ സക്കാത്ത് വീടുന്നതാണ്.&nbsp;</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-29 11:39:32', '2024-03-06 10:46:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0491', 1, NULL, 2, NULL, NULL, 'ഒരു സാധാരണ കുടുംബത്തിന് സർക്കാർ അല്ലെങ്കിൽ സ്വകാര്യ ആരോഗ്യ ഇൻ്വറൻസ് സേവനം അപേക്ഷിക്കുകയും അതിൻ്റെ സേവനം ആശുപത്രിയിൽ അഡ്മിറ്റ് ആകുന്ന സമയത്ത് ഉപയോഗിക്കാമോ', 'ഒരു സാധാരണ കുടുംബത്തിന് സർക്കാർ അല്ലെങ്കിൽ സ്വകാര്യ ആരോഗ്യ ഇൻ്വറൻസ് സേവനം അപേക്ഷിക്കുകയും അതിൻ്റെ സേവനം ആശുപത്രിയിൽ അഡ്മിറ്റ് ആകുന്ന സമയത്ത് ഉപയോഗിക്കാമോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-01-12 12:08:26', '2023-08-25 05:50:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0368', 1, NULL, 1, NULL, NULL, 'തവസ്സുൽ', 'എന്തെല്ലാം കാര്യങ്ങൾ കൊണ്ടാണ് തവസ്സുൽ ചെയ്യാവുന്നതും ചെയ്യല്&zwj; അനുവദനീയമല്ലത്തതും?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-21 08:15:46', '2024-01-06 05:41:45') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0519', 1, NULL, 1, NULL, NULL, 'വീട്ടുവളപ്പിൽ കൃഷി ചെയ്യുന്ന വിളകൾക്ക് കച്ചവട ഉദ്ദേശമില്ലെങ്കിൽ സക്കാത്ത് കൊടുക്കണോ', 'വീട്ടുവളപ്പിൽ കൃഷി ചെയ്യുന്ന വിളകൾക്ക് കച്ചവട ഉദ്ദേശമില്ലെങ്കിൽ സക്കാത്ത് കൊടുക്കണോ? ഉദാ:- വീട്ടുവളപ്പിൽ നിൽക്കുന്ന രണ്ട് തെങ്ങിൽ നിന്ന് 5O തേങ്ങാ ലഭിച്ചാൽ സക്കാത്ത് നൽകണോ?', 'Malayalam', 'published', '<p>വീട്ടുവളപ്പിൽ കൃഷി ചെയ്യുന്ന വിളകൾക്ക് കച്ചവട ഉദ്ദേശമില്ലെങ്കിൽ സക്കാത്ത് പത്തിലൊന്ന് (عشر) കൊടുക്കൽ നിർബന്ധമല്ല.</p>', 5, 0, 5, '1970-01-01 01:00:00', 1, '2022-02-09 09:12:57', '2022-02-09 09:12:57') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0424', 1, NULL, 1, NULL, NULL, 'തലയിൽ തൊപ്പി വയ്ക്കുന്നത് സുന്നത്ത് ന്റെ പ്രതിഫലം ലഭിക്കുമോ', 'തല മറക്കുന്നത് സുന്നത്ത് ആണോ?.. തൊപ്പി മാത്രം വച്ചാൽ പൂർണ്ണ സുന്നതിന്റെ പ്രതിഫലം ലഭിക്കുമോ? തലമറക്കുന്നതിന്റെ പൂർണ്ണ രൂപം എങ്ങനെയാണ്?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-02 22:50:20', '2023-11-02 16:15:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0467', 1, NULL, 5, NULL, NULL, 'Is Tata Ethical Fund (Mutual Fund) halal ??', 'Subject: Tata Ethical Fund اَلسَلامُ عَلَيْكُم وَرَحْمَةُ اَللهِ وَبَرَكاتُهُ&lrm; What&#39;s the ruling on investing in Tata Ethical Fund? They claim it as Sharia complied one For terms &amp; conditions please refer<br /> https://www.tatamutualfund.com/products/tata-ethical-fund <br /> جزاك اللهُ خيراً', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-12-02 15:08:00', '2023-11-11 14:51:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0292', 1, NULL, 1, NULL, NULL, 'വീട്ടാവശ്യത്തിനായി കൃഷി ചെയ്യുന്ന വിളകൾക്ക് സക്കാത്ത് കൊടുക്കണോ? ', 'വീട്ടാവശ്യത്തിനായി കൃഷി ചെയ്യുന്ന വിളകൾക്ക് കച്ചവട ഉദ്ദേശമില്ലെങ്കിൽ സക്കാത്ത് കൊടുക്കണോ? <br /> ഉദാ :- വീട്ടുവളപ്പിൽ നിൽക്കുന്ന തെങ്ങിൽ നിന്ന് 5O തേങ്ങാ ലഭിച്ചാൽ സക്കാത്ത് നൽകണോ ?', 'Malayalam', 'published', '<p>&nbsp;വീട്ടുവളപ്പിൽ കൃഷി ചെയ്യുന്ന വിളകൾക്ക് സകാത്ത് നിർബന്ധമില്ല.&nbsp;</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-03-04 09:13:50', '2024-03-06 08:01:24') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0484', 1, NULL, 2, NULL, NULL, 'നെറ്റ് വർക്ക് ബിസിനസ് കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആയി വർക്ക് ചെയ്യാൻ പറ്റുമോ', 'പ്രൊഡക്ട് ബേസ് ചെയ്തു ( ആളെ ചേർക്കൽ നിർബന്ധമില്ല ) നെറ്റ്വർക്ക് ബിസിനസ്സിലൂടെ കച്ചവടം ചെയ്യുന്ന കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആവാൻ പറ്റുമോ? താഴെ തട്ടിൽ കച്ചവടം നടക്കുമ്പോൾ കമ്പനിയുടെ പ്രതിഫലം മേലെ തട്ടിലുള്ളവർക്ക് കൈ പറ്റൽ അനുവദനീയമാകുമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-01-02 01:16:31', '2023-11-11 14:44:34') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0512', 1, NULL, 1, NULL, NULL, 'ഒരു ഇമാമിന്റെ മൊബൈലിൻറെ അകത്ത് സിനിമയും മറ്റുമാണ്.അയാൾ സിനിമ കാണുന്നുവെന്ന് വ്യക്തമായി അറിയാമെങ്കിൽ അയാളുടെ പുറകിൽ നമ്മുക്ക് നമസ്കരിക്കാമോ?', 'ഒരു ഇമാമിന്റെ മൊബൈലിൻറെ അകത്ത് സിനിമയും മറ്റുമാണ്.അയാൾ സിനിമ കാണുന്നുവെന്ന് വ്യക്തമായി അറിയാമെങ്കിൽ അയാളുടെ പുറകിൽ നമ്മുക്ക് നമസ്കരിക്കാമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-06 12:15:48', '2023-11-02 16:23:38') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0322', 1, NULL, 1, NULL, NULL, 'منقولات حقیقت کے خلاف کیوں ہیں؟', 'السلام علیکم میرا سوال اعتقاد سے متعلق ہے، اسی لیے میں جواب قضایا یقینیہ سے چاہتا ہوں کیونکہ اعتقاد میں ظنیات کو میں نہیں مانتا۔  سوال: منقولات میں حقیقت کے خلاف باتیں کیوں آئی ہیں؟  منقولات میں یہ متکرر ہے کہ خصال باطنیہ قلب میں ہیں، و قلب ہی جسم کا حاکم ہے۔ جب کہ ہم برہان تجریب سے جانتے ہیں کہ یہ صادق نہیں ہے کیونکہ ۱۔ ہمارے عالم میں ہر سال ٣٥٠٠ قلب بدلے جاتے ہیں، لیکن کسی کا بھی یقین وغیرہ نہیں بدلتا۔ mri اور جب بھی کے تحت آدمی افعال باطینیہ یعنی فکر، تصور وغیرہ کرتا ہے تو سرگرمی خالص اس کے دماغ میں ہوتی ہے نہ کہ قلب میں۔ اور یہ دونوں برہان ہیں جو دلیل ہیں کہ خصال باطینیہ قلب میں نہیں ہیں اور برہان کی نقیض کاذب ہوتی ہے۔  اور اگر ہم یہ فرض کر لیں کہ نصوص کا معنی وہ نہیں جو سمجھا جاتا ہے بلکہ ایسا ایسا و ویسا ویسا ہے، تو اس کا مطلب ہوگا کہ سلف کے اعتقادات غلط تھے، و لاظم ہوگا کہ تمام منقولات کے جو معانی ہم اپنے زمانہ میں مانتے ہیں ممکن ہے کہ کل کو وہ بھی بدل جائیں، اور ہر وہ جو محتمل فیہ ہے تو وہ برہان کا مقدمہ نہیں بن سکتا، یعنی وہ یقینی نہیں ہے۔  اور اگر ہم تجریب کا انکار کریں تو تواتر کا بھی انکار لازم ہوگا کیونکہ دونوں ہی برہان کی نوع ہیں، تو قران کا ثابت ہونا بھی باقی نہ رہے گا۔  اور اگر آپ تجریب کا انکار کریں لیکن تواتر کو تسلیم کریں تو یہ اعتقاد محض آپ کا مسلم ہوگا نہ کہ برہان، جو اعتقاد فاسد ہے۔  اور میں پھر دوہرا دوں کہ جواب خالص برہان سے چاہتا ہوں نہ کہ جدلیات سے کیونکہ یہ مسئلہ مسلمانوں کی ترقی سے متعلق ہے کیونکہ سائینس صدق پر جاری ہوتی ہے و کذب اسے فاسد کر دیتا ہے۔ تو جو قلب کو تبدیل کرتا اس کے لیے لازم ہوتا ہے کہ پہلے وہ یہ اعتقاد رکھے کہ قلب میں کوئی بھی باطنی خصلت نہیں ہے۔  اور ایسے ہی جو یہ اعتقاد رکھتا ہو کہ سورج عرش کے نیچے جاتا ہے و نظام شمسی کا منکر ہو تو وہ کبھی بھی مارس پر نہیں جا سکتا۔ اور اگر کوئی کہے کہ &#39;الشمس ذہبت الآخ&#39; کا معنی ایسا ایسا و ویسا ویسا ہے تو اس کا مطلب ہوا کہ تمام منقولات کے جو معانی ہم آج مانتے ہیں مستقبل میں وہ بھی ایسے ایسے ویسے ویسے ہو سکتے ہیں، اور جو قضایا اپنے معانی بدلتے رہتے ہیں وہ برہان کا مقدمہ نہیں بن سکتے، یعنی وہ یقینی نہیں ہیں، اس سے لا محالہ لازم آئے گا کہ کوئی بھی منقول یقینی نہیں ہے۔  برائے کرم انشراح فرمائں۔ خالص قضایا برہان سے نہ کہ تمثیل و جدل و سفسطہ سے۔ جزاک اللہ۔', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-05-31 14:48:39', '2021-05-31 14:48:39') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0324', 1, NULL, 1, NULL, NULL, 'പുനർ വിവാഹം', 'നിക്കാഹ് കഴിഞ്ഞ് 2ദിവസം ഒരുമിച്ചു താമസിച്ചു. ശേഷം ബന്ധം വേർപെടുത്തി. 2വർഷം കഴിഞ്ഞു ഇദ്ധ ഇരുന്നിട്ടില്ല. അങ്ങനെ ഉള്ള പെൺകുട്ട്ടിയെ നിക്കാഹ് ചെയ്യാമോ. ഇദ്ധ പൂർത്തി ആക്കാത്ത ആളെ നിക്കാഹ് ചെയ്താൽ എന്താണ് വിധി?', 'Malayalam', 'published', '<p>വിവാഹ ബന്ധം വേർപെടുത്തിയ സ്ത്രീയുടെ ഇദ്ദ ആരംഭിക്കുന്നത് ബന്ധം വേർപ്പെടുത്തിയ സമയം മുതലാണ്. ബന്ധം വേർപ്പെടുത്തിയ സമയത്ത് സ്ത്രീ അതിനെ സംബന്ധിച്ച് അറിയുകയോ അറിയാതിരിക്കുകയും ചെയ്താലും ഇദ്ദയുടെ കാലഘട്ടം പൂർത്തിയാകുന്നതോടെ അവരുടെ ഇദ്ദ പൂർത്തിയാകുന്നതാണ്. ഇദ്ദയുടെ കാലയളവിനുശേഷം സ്ത്രീ ഇദ്ദ ഇരുന്നിട്ടില്ലെങ്കിലും അവളെ വിവാഹം കഴിക്കാവുന്നതാണ്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-06-13 09:16:11', '2024-01-04 06:10:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0259', 1, NULL, 5, NULL, NULL, 'നോമ്പ്കാരൻ ഹിജാമ ചെയ്താൽ ചെയ്തവന്റെയും ചെയ്യപ്പെട്ടവന്റെയും നോമ്പ് മുറിയുമോ..?', 'ഒരാൾ നോമ്പ്കാരനായിരിക്കെ ഹിജാമ ചികിത്സ ചെയ്യുന്നതിന്റെ വിധിയെന്താണ്.<br /> നോമ്പ്കാരൻ ഹിജാമ ചെയ്താൽ ചികിത്സകന്റെയും, ചെയ്യപ്പെട്ടവന്റെയും നോമ്പ് മുറിയും എന്ന് (മിഷ്കാത്തുൽ മസാബീഹ് 2012, 2017, സുനൻ അബീ ദാവൂദ് 2375, മുവത്വ മാലിക് 780, ബുഖാരി 1940, ഇബ്നു മാജ 1749,1750) എന്നീ ഹദീസുകൾ സൂചിപ്പിക്കുന്നു.<br /> എന്നാൽ നോമ്പ് മുറിയുകയില്ല എന്ന് (ബുലൂഗുൽ മറാം 665, സുനൻ അബീ ദാവൂദ് 2376, മുവത്വ മാലിക് 665, ഇബ്നു മാജ 752) ഹദീസുകളും സൂചിപ്പിക്കുന്നു. മേൽപ്രസ്താവിച്ച 2 വിഭാഗം ഹദീസുകളുടെയും അടിസ്ഥാനത്തിൽ നോമ്പ്കാരൻ ഹിജാമ ചെയ്താൽ ചികിത്സകന്റെയും രോഗിയുടെയും നോമ്പ് മുറിയുമോ..?<br /> നോമ്പ്കാരൻ ഹിജാമ ചെയ്യേണ്ട ഉത്തമ സമയവും രീതിയും ഏതാണ്..? വിശദമായ മറുപടി പ്രതീക്ഷിക്കുന്നു', 'Malayalam', 'published', '<p>നോമ്പുകാരനായിരിക്കെ ഹിജാമ ചെയ്യുന്നതിൽ കുഴപ്പമില്ല. എങ്കിലും ക്ഷീണം വരാൻ സാധ്യതയുള്ളതിന്റെ പേരിൽ ഹിജാമ ചെയ്യാതിരിക്കൽ മുസ്തഹബ്ബാണ്.</p> <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; മേൽപ്പറഞ്ഞ രണ്ട് ഹദീസുകളെ താരതമ്യപഠനം നടത്തി പണ്ഡിതർ രണ്ട് അഭിപ്രായമാണ് രേഖപ്പെടുത്തിയിരിക്കുന്നത്<span dir=\"RTL\">.</span></p> <p>ഒന്ന് : നോമ്പുകാരൻ ഹിജാമ ചെയ്താൽ ചികിത്സകന്റെയും ചെയ്യപ്പെട്ടവന്റെയും നോമ്പ് മുറിയും എന്ന നിയമം നിലവിലുണ്ടായിരുന്നു, എന്നാൽ &quot;നോമ്പ് മുറിയില്ല&quot; എന്ന് സൂചിപ്പിക്കുന്ന ഹദീസുകൾ മുഖേന ആ നിയമം അസ്ഥിരപ്പെടുകയുണ്ടായി<span dir=\"RTL\">.</span></p> <p>രണ്ട് : നോമ്പ് മുറിയും എന്ന് സൂചിപ്പിച്ചിട്ടുള്ള ഹദീസ് പരദൂഷണം പറഞ്ഞുകൊണ്ട് ഹിജാമ ചെയ്തുകൊണ്ടിരുന്ന രണ്ട് ആളുകളെ കുറിച്ചാണ്. അഥവാ പരദൂഷണം കാരണമായി അവരുടെ നോമ്പിന്റെ പ്രതിഫലം നഷ്ടപ്പെട്ടിരിക്കുന്നു എന്നാണ് ഹദീസിന്റെ ആശയം<span dir=\"RTL\"> .</span></p> <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; നോമ്പുകാരന് ഹിജാമ ചെയ്യാൻ പ്രത്യേക സമയമില്ല, ഹിജാമ കാരണമായി ക്ഷീണം നേരിടുമെന്നുണ്ടെങ്കിൽ ഹിജാമ ചെയ്യൽ കറാഹത്താണ്<span dir=\"RTL\"> .</span></p>', 5, 0, 5, '1970-01-01 01:00:00', 1, '2020-10-26 04:07:45', '2023-07-09 03:10:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0426', 1, NULL, 1, NULL, NULL, 'തൂങ്ങി മരിച്ചതിന് മറ ഇരിക്കൽ എന്താണ് വിധി?', '<h2 style=\"font-style:italic\">തൂങ്ങി മരിച്ചതിന് മറ ഇരിക്കൽ എന്താണ് വിധി?</h2>', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-11-02 23:38:56', '2021-11-02 23:38:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0428', 1, NULL, 5, NULL, NULL, 'കൊതുക് ബാറ്റ് ഉബായോഗികമോ?', 'കൊതുക് ബാറ്റ് ഉബായോഗികുന്നതിന് കുഴപ്പമുണ്ടോ?', 'Malayalam', 'published', '<p>കൊതുക് ബാറ്റ് &nbsp;ഉപയോഗിക്കൽ അനുവദനീയമാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-03 12:43:35', '2023-08-25 16:30:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0320', 1, NULL, 1, NULL, NULL, 'ലാഭവിഹിതത്തിന് വേണ്ടി ബിസിനസ്സിൽ ഷെയർ ചെയ്യുന്നതിന് വിധി എന്താണ് ആണ്', 'ലാഭവിഹിത ത്തിനുവേണ്ടി ബിസിനസ്സിൽ ഷെയർ ചെയ്യുന്നതിന് വിധി എന്ത്', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-05-23 11:24:02', '2021-05-23 11:24:02') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0183', 1, NULL, 2, NULL, NULL, 'CAN WE FOLLOW \"IBADI\" FOR FARD PRAYERS??', 'Assalamu Alaikm, Myself Abdulla safwan ,I am living in Oman and the muslims here are having \"IBADI\" aqaeda,the place where I live is 100% masjids with same people and I dont see any difference in their actions from ahlusunna. Searching and finding a masjid with imam not from ibadi background is very difficult here(or barely possible),we will understand the imam is ibadi at the end if it\'s a big jamath(they only make one salam to end the salah),or we can identify from their qiyam as they dont tie their hands. These are the only difference from ahlusunnah I found in them- in action kindly share the knowledge what should I do in this situation.and it will be better if a short detailing about Ibadi is possible. Jazakallah khair.', 'English', 'published', '<p>Ruling regarding them can only be issued after knowing their belief from any authentic sources.<br /> From Kitabs, &nbsp;we come to know that many of their beliefs are different from the beliefs of ahlu-sunnah wal jama&#39;ah.&nbsp;<br /> Some of them are explained below;</p> <p>1) A person will be in hell for ever, if a person commits major sin and die without making tauba.<br /> 2) Nobody will intercede for a person who committed major sins and died without making tauba.<br /> 3) None of the believers will see Allah in akhirah.<br /> 4) Meezan, Sirath bridge etc.. are not considered as real, but lame explanations are given.<br /> 5) Those who die without believing in Abaad will be in hell forever.</p> <p>One of the famous scholar from Abubakar bin Abdillah wrote : I guarantee that one who died without the belief of Abaad will be nasty, unworthy &amp; will be in hell for ever.<br /> (Al Jouharul Muqthasar-121)</p> <p>If Omani Abadis have these beliefs, then it is not permitted to follow them in salah.<br /> If they dont consider Muslims who don&#39;t have the same beliefs as them to be kafir, then it is karahat-u-tahreem to pray behind them; even though the prayers will be valid.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-30 03:22:58', '2020-06-30 03:22:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0352', 1, NULL, 1, NULL, NULL, 'വുളൂവിൻ്റെ അവവയവങ്ങളിൽ മുറിവുള്ള വെക്തി എന്ത് ചെയ്യണം ?', 'ഒരു രീതിയിലും വുളൂവോ അല്ലെങ്കിൽ തയമുമോ ചെയ്യാൻ കഴിയാത്ത നിലയിൽ വുളൂവിൻ്റെ അവവയവങ്ങളിൽ മുറിവുള്ള വെക്തി എന്ത് ആണ് നമസ്കരിക്കാൻ ചെയ്യേണ്ടത്. മുറിവുള്ള ഭാഗം എങ്ങിനെ ആണ് ശുദ്ധി ആക്കേണ്ടത്. ഉദാ : ട്രിപ്പ് ഇടാൻ വേണ്ടി കയ്യുടെ മുകളിൽ സൂചി വെക്കുമ്പോൾ അവിടെ വെള്ളം ഉപയോഗിക്കുന്നതിൽ ഇൻഫെക്ഷൻ സാധ്യത ഉള്ളത് പോലെ !', 'Malayalam', 'published', '<p>വുളൂഇന്റെ അവയവങ്ങളിൽ മുറിവുണ്ടായതിന്റെ പേരിൽ ആ ഭാഗം കഴുകുന്നതിനോ അല്ലെങ്കിൽ തടവുന്നതിനോ സാധ്യമാകുന്നില്ലെങ്കിൽ അതൊഴികെയുള്ള ബാക്കി ഭാഗങ്ങൾ കഴുകി വുളൂഅ് പൂർത്തിയാക്കണം.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-26 05:28:29', '2021-08-26 05:28:29') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0358', 1, NULL, 1, NULL, NULL, 'Name of Angel AZARAEEL is proved authoritatively?', 'Is there any proof in aayath or hadees or asar(word of sahaba or Imam) that the name of the malakul mauth is azaraeel? With evidence.', 'English', 'published', '<p>Qur&#39;an or Shaheeh Hadees didn&#39;t mention the name of malakul mauth (the angel of death) as &quot;Azraeel&quot;; but, it is referred in few narrations (خبر). With that many of Muffassirs say that:- The name of malakul mauth is &quot;Azraeel&quot;.Rather than it, this topic is not related to Islamic principles. So there is no problem in calling malakul mauth &quot;Azraeel&quot;.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-19 13:24:24', '2021-10-19 13:24:24') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0439', 1, NULL, 1, NULL, NULL, 'ത്വലാഖ്', 'ഒരാൾ തൻ്റെ ഭാര്യയോട് എനിക്കിനി നിന്നെ ഭാര്യയായി കാണാൻ സാധിക്കുകയില്ല അല്ലെങ്കിൽ ഒരു സദസ്സിൽ വെച്ചു ഇനി എനിക്ക് ഈ ബന്ധം മുമ്പോട്ടു കൊണ്ടുപോകാൻ സാധിക്കുകയില്ല എന്ന് പറഞ്ഞാൽ അത് ത്വലാഖ് ആകുമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-06 20:46:14', '2023-11-02 16:17:52') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0454', 1, NULL, 2, NULL, NULL, 'Cryptocurrency is a very popular medium of exchange and may become an alternative to real currency in the near future. So is investing in crypto halal or haram?', 'Crypto currency has gained popularity all over the world and it is now used as a medium of exchange in many countries and in the near future it can be a alternative for the original currency...so investing crypto is halal or haram?', 'English', 'published', '<p>The value of coins and currencies used in a country was based on the amount of gold and silver deposited behind them. But today the investment of the country&#39;s currencies is calculated on the basis of the total assets and services of the nation. The currency will only have value if there are investments behind it but the cryptocurrency that exist today and all its denominations such as Bitcoin, one coin and Morri&rsquo;s coin are de centralized or have no control or approval by any government or authority. Cryptocurrency came into effect in 2008 and 2009. Satoshi Niko Moto (No one knows who it is, whether it&#39;s a man or a woman or an individual or a group) invented the cryptocurrency when it first came into force. Similarly, the one-coin scheme, a branch of cryptocurrency, was merged with MLM to get a lot of people involved in it, which reached a very high level and one morning a massive scam took place. The fact is that there is no government or other authority that can recoup the losses incurred by consumers. Such big scams are behind this.</p> <p>Now, if we look at cryptocurrency transactions from an Islamic perspective, the Prophet (peace and blessings of Allah be upon him) said &nbsp;<span dir=\"RTL\">لا تبع ما ليس عندك</span>&nbsp; You have no right to sell someone else&#39;s property that you do not own Moreover, Islam does not allow one to sell an object that he owns (for how long) even if he does not have access to it. Islam has closed all loopholes in the form of fraud and deception. Therefore, no transactions with cryptocurrency and its denominations such as Bitcoin and Morris coin are permissible in the Islamic view.</p>', 26, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-19 22:58:24', '2024-03-10 17:25:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0504', 1, NULL, 1, NULL, NULL, 'ഭർത്താവ് എൻ്റെ ശാരീരിക ആവിശ്യങ്ങൾ നിറവേറ്റി തരുന്നില്ലാ എങ്കിൽ എനിക്ക് അത് ലഭിക്കാൻ എന്ത് ചെയ്യണം. ഇത് എനിക്ക് വിവാഹ മോചനം ആവിഷ്യപെടാനുള്ള കാരണം ആക്കാമോ ? പൊതു സമക്ഷത്തിൽ ഈ കാര്യം പറയാൻ കഴിയില്ലലോ !!!', 'ഭർത്താവ് എൻ്റെ ശാരീരിക ആവിശ്യങ്ങൾ നിറവേറ്റി തരുന്നില്ലാ എങ്കിൽ എനിക്ക് അത് ലഭിക്കാൻ എന്ത് ചെയ്യണം. ഇത് എനിക്ക് വിവാഹ മോചനം ആവിഷ്യപെടാനുള്ള കാരണം ആക്കാമോ ? പൊതു സമക്ഷത്തിൽ ഈ കാര്യം പറയാൻ കഴിയില്ലലോ !!!', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-01 19:37:16', '2023-11-11 14:46:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0517', 1, NULL, 5, NULL, NULL, 'ഖുർആൻ ഖത്തം തീർക്കുമ്പോൾ സൂറത്തുന്നാസിന് ശേഷം സൂറത്തുൽ ബഖറയുടെ ആദ്യ ഭാഗം പാരായണം ചെയ്യുന്നതിന്റെ അടിസ്ഥാനം എന്താണ്?', 'ഖുർആൻ ഖത്തം തീർക്കുമ്പോൾ സൂറത്തുന്നാസിന് ശേഷം സൂറത്തുൽ ബഖറയുടെ ആദ്യ ഭാഗം പാരായണം ചെയ്യുന്നതിന്റെ അടിസ്ഥാനം എന്താണ്? പ്രമാണബന്ധിതമായ മറുപടി പ്രതീക്ഷിക്കുന്നു.', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-09 06:29:12', '2023-11-11 15:55:36') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0542', 1, NULL, 1, NULL, NULL, 'ശവ്വാലിലെ ആറ് നോമ്പുകൾ തുടർച്ചയായി വേണോ അതോ പിരിച്ച് പിടിക്കാണോ ?', 'പെരുന്നാൾ കഴിഞ്ഞ് അനുഷ്ഠിക്കുന്ന ആറ് നോമ്പുകൾ എങ്ങനെ അനുഷ്ഠിക്കും?  
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0581', 1, NULL, 5, NULL, NULL, 'ബാങ്കിന് ഓഡിറ്റിംഗ്', 'ബാങ്കിന് ഓഡിറ്റിംഗ് സേവനങ്ങൾ നൽകുന്നത് ഹലാലാണോ?
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0506', 1, NULL, 2, NULL, NULL, 'Can I eat meat slaughtered by non muslim if we are travelling to a non muslim countries like europe?', 'If we are living in a non muslim country like europe it is very difficult for us to search for halal food but usually every where can find KFC, McDonald&#39;s etc but Meat available there might be either slaughtered by machine or non muslim is it permissible for me to eat that. Countries in Europe are mostly very cold so it is very difficult with out non veg also veg foods are bit costly or chance of availability is very low ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-03 00:32:43', '2024-01-06 05:39:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0419', 1, NULL, 1, NULL, NULL, 'അന്യന്റെ സാധനം അനുവാദമില്ലാതെ വിൽക്കൽ', '1-മറ്റൊരാളുടെ സാധനം അനുവാദം ഇല്ലാതെ വിൽക്കുന്നതിന്റെ വിധി എന്താണ് . 2- ഒരു സാധനം മറ്റാർക്കെങ്കിലും വിൽക്കാനായി ഉടമസ്ഥൻ ഒരാളെ ഏൽപിച്ചാൽ അതിനെ സ്വന്തം എടുത്തിട്ട് പൈസ ഉടമസ്ഥന് കൊടുക്കൽ അനുവദനീയമാണോ?', 'Malayalam', 'published', '1) മറ്റൊരാളുടെ സാധനം അയാളുടെ അനുവാദമില്ലാതെ വിൽക്കുകയും പിന്നീട് അയാൾ അനുവാദം നൽകുകയും ചെയ്താൽ ആ കച്ചവടം ശരിയാകുന്നതാണ്. അനുവാദം നൽകാത്ത പക്ഷം ആ കച്ചവടം &nbsp;ശരിയാകുന്നതല്ല.</p> <p>2) ഒരു സാധനം മറ്റാർക്കെങ്കിലും വിൽക്കാനായി ഉടമസ്ഥൻ ഒരാളെ ഏൽപ്പിച്ചാൽ ആ വസ്തു സ്വന്തമായി എടുക്കാൻ അനുവാദമില്ല. എന്നാൽ ഉടമസ്ഥന്റെ അനുവാദത്തോടുകൂടി വില നിശ്ചയിച്ച് എടുക്കാവുന്നതാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-01 22:48:56', '2021-11-01 22:48:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0430', 1, NULL, 2, NULL, NULL, 'കൊതുക് ബാറ്റ് ഉബായോഗികമോ?', 'കൊതുക് ബാറ്റ് ഉബായോഗികുന്നതിന് കുഴപ്പമുണ്ടോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-03 12:44:23', '2023-11-02 16:20:43') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0306', 1, NULL, 1, NULL, NULL, 'തറാവീഹ് 20 റകഅത്ത് ആണോ?', 'തറാവീഹ് നമസ്കാരം 20 റകഅത്ത് ആണോ, ആണെങ്കിൽ അതിൻ്റെ തെളിവുകൾ ഹദീസിൽ വന്നത് എന്താണ്, 20 നമസ്കരിക്കാൻ കഴിയാത്തവർ (എന്തെങ്കിലും ശാരീരിക പ്രയാസം ഉള്ളവർ) കുറഞ്ഞ എണ്ണം നിർവഹിക്കാൻ കഴിയുമോ ?', 'Malayalam', 'published', '<p>തറാവീഹ് നമസ്കാരം 20 റക്അത് ആകുന്നു.</p> <p>مقدار التراويح عند اصحابنا والشافعي رحمه الله تعالى ما روى الحسن عن ابي حنيفه رحمه الله قال القيام في شهر رمضان سنة لا ينبغي تركها يصلي اهل كل مسجد في مسجدهم كل ليلة سوى الوتر عشرين ركعة خمس ترويحات بعشر تسليمات يسلم في كل ركعتين<br /> الفتاوى الهندية (١/٢٣٤)</p> <p>&nbsp;◾20 റകഅത്ത് ആകുന്നു എന്നതിന് തെളിവുകൾ താഴെ കൊടുക്കുന്നു</p> <p>ഇബ്നു അബ്ബാസ് (റ)പറയുന്നു : നബി (സ) റമളാൻ മാസത്തിൽ 20 റകഅത്ത് തറാവീഹും വിത്റും നമസ്കരിക്കുമായിരുന്നു.<br /> (التعليق الحسن ٢/٥٦)</p> <p>സാഹിബ് ബിനു യസീദ് (റ) പറയുന്നു: ഞങ്ങൾ ഉമർ (റ) ൻ്റെ കാലത്ത് ഇരുപത് റക്അത്ത് തറാവീഹും വിത്റും നമസ്കരിക്കുമായിരുന്നു&nbsp;<br /> التعليق الحسن (٢/٢٥٤)</p> <p>അബ്ദുൽ അസീസ് ബ്നു റഫീഅ് (റ) പറയുന്നു:ഉബയ്യുബ്നു കഅ്ബ് (റ) റമദാൻ മാസത്തിൽ ഇരുപത് റക്അത്ത് തറാവീഹും മൂന്ന് റക്അത് വിത്റുംജനങ്ങൾക്ക് ഇമാമായി നിന്ന് നമസ്കരിക്കുമായിരുന്നു.&nbsp;<br /> (اثار السنن: ٢/٥٥)</p> <p>അബുൽഹസനാഅ (റ) പറയുന്നു അലി (റ) ഒരു വ്യക്തിയോട് 20 റക്അത്ത് തറാവീഹ് &nbsp; ജനങ്ങൾക്ക് ഇമാമായി നിന്ന് നമസ്കരിക്കാൻ കൽപ്പിച്ചു.<br /> (كنز العمال ٤/٢٨٤)&nbsp;</p> <p>അഅമശ് (റ) പറയുന്നു ഇബ്നുമസ്ഊദ്(റ) 20 റക്അത്ത് തറാവീഹും 3 റകഅത് വിത്റും നമസ്കരിക്കുമായിരുന്നു<br /> (قيام الليل: ص٩٠)<br /> മേൽപറയപ്പെട്ട ഹദീസുകളുടെ അടിസ്ഥാനത്തിൽ നബി(സ)യും സ്വഹാബത്തും 20 റക്അത്ത് തറാവീഹ് നമസ്കരിച്ചതായി നമുക്ക് മനസ്സിലാക്കാം</p> <p>◾ഇനി ശാരീരിക പ്രയാസങ്ങൾ ഉള്ളവർ തങ്ങളാൽ കഴിയുന്ന രൂപത്തിൽ തറയിൽ ഇരുന്നോ അതിന് കഴിയാത്തവർ കസേരയിലിരുന്നോ 20 പൂർത്തിയാക്കി നമസ്കരിക്കുക&nbsp;<br /> اذا عجز المريض عن القيام صلى قاعدا يركع ويسجد، هاكذا في الهداية واصح الأقاويل في تفصيل العجز ان يلحقه بالقيام ضرر وعليه الفتوى</p> <p>(الفتاوى الهندية:١/١٣٦)</p> <p>◾ഇനി അതിനും കഴിയാത്തവർ തങ്ങളെ കൊണ്ട് സാധിക്കുന്ന രൂപത്തിൽ 8/10/12 റക്അത്തുകൾ നമസ്കരിക്കുക</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-04-16 14:03:31', '2021-04-16 14:03:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0534', 1, NULL, 5, NULL, NULL, 'Is frozen chicken available in gulf countries halal', 'In gulf countries most of the chicken used in hotels are from countries like brazil wich are frozen chickenz which is mechanically slaughtered. Is it halal to eat? Are mechanically slaughtered mutton and beef halal? One alim told beef and mutton is ok to eat since it is only stunned but not chicken.', 'Malayalam', 'pending', NULL, 1, 0, 5, NULL, NULL, '2022-03-08 15:49:05', '2023-03-21 05:43:59') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0301', 1, NULL, 2, NULL, NULL, 'സവിങ്സ് അക്കൗണ്ടിലെ പലിശ ഒരു മുസ്ലിമിന് സഹായമായി നൽകാമോ?', 'അസ്സലാമു അലൈക്കും.<br /> സംശയം: ബാങ്ക് ലോൺ എടുത്ത് കട ബാദ്യത വന്ന ഒരു മുസ്ലിം സഹോദരൻ സഹായം ചോദിച്ചിരുന്നു.<br /> നമ്മുടെ സവിങ്സ് ബാങ്ക് അക്കൗണ്ടിലെ പലിശ ആയൾക് നൽകാമോ?<br /> ഏതായാലും ആ പലിശ എടുത്തു കളയേണ്ടതല്ലേ.', 'Malayalam', 'published', '<p>ബാങ്ക് ലോൺ എടുത്ത് കട ബാധ്യത വന്ന ഒരു മുസ്ലിം സഹോദരനെ നമ്മുടെ അക്കൗണ്ടിലെ പലിശ യാതൊരു പ്രതിഫലവും ആഗ്രഹിക്കാതെ കൊടുക്കാവുന്നതാണ്.<br /> &nbsp;</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-03-26 11:56:36', '2023-08-16 10:43:37') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0317', 1, NULL, 1, NULL, NULL, 'Wirasat', 'Bete ki inteqal k baad baap ki maujudgi m bete k bete yani (poto) ka wirasat m kya hukum hai ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-05-21 22:35:02', '2021-05-21 22:35:02') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0445', 1, NULL, 5, NULL, NULL, 'Inheritance of Flat Purchased by Parents, registration not done', 'Assalamu Alaikum W Rahmatullahi W Barakatuh Dear Mufti Our parents purchased flat, with advance booked under name of one of their children say &lsquo;A&rsquo;, but they returned to Allah before the flat was handed over to &lsquo;A&rsquo;. In such a condition that the flat key was not handed over, and the flat registration was not done, and the flat was not occupied by &lsquo;A&rsquo;. Kindly let us know In this situation will the flat come under the inheritance or not ? Jazakallah Khayr', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-07 06:18:05', '2023-11-02 16:18:41') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0579', 1, NULL, 2, NULL, NULL, 'റമദാൻ കിറ്റ് വിതരണത്തിനായി സക്കാത്തിന്റെ പണം ഉപയോഗിക്കാമോ ?', 'സകാത്തിന്റെ തുക റമളാൻ മാസത്തിലെ കിറ്റ് വിതരണത്തിന് വേണ്ടി വിനയോഗിക്കൽ അനുവദനീയമാണോ ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-04-01 13:44:56', '2023-04-06 08:39:26') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0603', 1, NULL, 1, NULL, NULL, 'Salah ruling for Mustahazah', 'I have been diagnosed with PSOC, and therefore I have been having my periods for 4 months strait now. I have been bleeding every day for 4 months straight now. I am in huge pain every day, but more because I cannot pray. What should I do? I haven’t prayed for 4 months now. Can I pray? I feel like I am being punished. Please help me. In Sha Allah', 'English', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-08-16 10:00:24', '2023-08-21 19:02:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0365', 1, NULL, 1, NULL, NULL, 'അമിത ചിലവ് (ഈസ്റാഫ്) എപ്പോഴാണ് ആകുന്നത്?', 'സമ്പന്നനായ ഒരു വ്യക്തി തൻറെ സമ്പത്തിന് അനുസരിച്ച് ജീവിച്ചാൽ അമിത ചിലവ് (ഈസ്റാഫ്) ആകുമോ? (ഉദാ: വിലകൂടിയ കാർ, വാച്ച്, ഡ്രസ്സ് ഉപയോഗിക്കുക) എപ്പോഴാണ് അമിത ചിലവ് (ഈസ്റാഫ്) എന്ന് പറയുന്നത്?', 'Malayalam', 'published', '<p>ശരീഅത്ത് വിലക്കാത്ത കാര്യങ്ങളിൽ സമ്പന്നനായ ഒരു വെക്തി തൻ്റെ സമ്പത്ത് അനുസരിച്ച് ജീവിച്ചാൽ അമിത ചിലവ്(ഇസ്റാഫ്) ആകുന്നതല്ല.<br /> ഉദ:വില കൂടിയ കാർ,വാച്ച്,അനുവദനീയമായ വസ്ത്രം എന്നിവ ഉപയോഗിക്കുക.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-21 07:28:47', '2024-02-14 12:26:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0465', 1, NULL, 2, NULL, NULL, 'Tata Ethical Fund', 'Subject: Tata Ethical Fund اَلسَلامُ عَلَيْكُم وَرَحْمَةُ اَللهِ وَبَرَكاتُهُ&lrm; What&#39;s the ruling on investing in Tata Ethical Fund? They claim it as Sharia complied one For terms &amp; conditions please refer<br /> https://www.tatamutualfund.com/products/tata-ethical-fund<br /> جزاك اللهُ خيراً', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-12-02 12:54:43', '2024-01-06 05:40:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0552', 1, NULL, 1, NULL, NULL, 'ഒന്നിലധികം ഭാര്യമാർ ഉള്ളവരുടെ രാത്രി ക്രമീകരിക്കുന്ന നിയമം', 'എനിക്ക് രണ്ട് ഭാര്യ മാർ ഉണ്ട്. ഒരാളുടെ അടുക്കൽ തുടർച്ചയായി 5 ദിവസം രാത്രി കഴിഞ്ഞ് കൂടുന്നു. എൻ്റെ സംശയം ഊഴം ലഭിച്ചവൾക്ക് പിരീഡ്സ് ടൈം ആണെങ്കിൽ ശാരീരിക ബന്ധം പുലർത്തുന്നതിന് വേണ്ടി ഇവളുടെ അനുവാദമില്ലാതെ മറ്റേ ഭാര്യയുടെ അടുക്കൽ പോകുന്നത് കുഴപ്പമുണ്ടോ ?
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0590', 1, NULL, 1, NULL, NULL, 'ജമാഅത്ത് നമസ്‌കാരത്തിന്റെ നഷ്‌ടമായ റകാത്തുകളിൽ ഫാതിഹ & സൂറ രണ്ടും ഓതാണോ?', 'ഇമാം ജമാഅതായി നമസ്കരിക്കുന്നതിനിടയിൽ ഒരാൾ റകാത് പിന്തിച്ച് നമസ്കാരം ആരംഭിച്ചാൽ ഇമാം സലാം വീട്ടിയതിന് ശേഷമുള്ള റകാത്തുകളിൽ ഫാത്തിഹ മാത്രം ഓതിയാൽ മതിയൊ, അതൊ ഫാത്തിഹയും സൂറത്തും ഓതണമൊ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-04-11 03:58:21', '2023-04-15 20:11:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0280', 1, NULL, 1, NULL, NULL, 'നമസ്കാരത്തിൻറെ ഫർളുകൾ എത്ര എണ്ണം', 'ഹനഫി മദ്ഹബ് അനുസരിച്ച് നമസ്കാരത്തിൻറെ ഫർളുകൾ എത്ര എണ്ണമാണ്', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-01-29 09:20:00', '2023-11-02 05:00:46') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0323', 1, NULL, 1, NULL, NULL, 'പഞ്ചഗവ്യം വില്യാദി ഗുളിക പോലുള്ള ആയുർവേദ മരുന്നുകൾ ഇസ്ലാമിൽ മരുന്നായി അനുവദനീയമാണോ', 'പഞ്ചഗവ്യം, വില്യാദി ഗുളിക പോലുള്ള ആയുർവേദ മരുന്നുകൾ ഇസ്ലാമിൽ അനുവദനീയമാണോ? ഇവയിൽ ഗോമൂത്രം ആട്ടിൻ മൂത്രം ഇവചേർക്കുന്നുണ്ട്. പഞ്ചഗവ്യം പോലുള്ളവ അപസ്മാരം പോലുള്ള രോഗത്തിനാണെങ്കിലും, വില്യാദി ഗുളിക പോലുള്ളവ തികച്ചും വളരെ അധികം ആയുർവേദ ഡോക്ടർ മാർ ചികിത്സക്കു സർവ സാധാരണയായി നൽകിവരുന്നതാണ് .വയർ സംബന്ധമായതും മറ്റു ഇതര രോഗങ്ങൾക്കും,പ്രിത്യേകിച്ചു കൊറോണ ചികിത്സയിലും പ്രധാനമായി ഉപയോഗിച്ച് വരുന്നു ഇത് ഇസ്ലാമിൽ കഴിക്കൽ അനുവദനീയം ആണോ? അതുപോലെ തന്നെ ആയുർവേദ ചികിത്സയിൽ അരിഷ്ടങ്ങൾ ഒഴിച്ച് കൂടാൻ പറ്റാത്തതാണല്ലോ അവ മരുന്ന് ആവശ്യത്തിനായി കുടിക്കാൻ അനുവദനീയം ആണോ?', 'Malayalam', 'published', '<p>പഞ്ചഗവ്യം ,വില്യാദി ഗുളിക പോലുളള ,ഗോമൂത്രവും കാഷ്ടവും അടങ്ങിയ &nbsp;ആയുർവേദ മരുന്ന്കഴിക്കൽ അനുവദിനീയമാണ്.പക്ഷേ വേറെ ഫലപ്രദമായ മരുന്ന് ഉള്ളപ്പോൾ അവ കഴിക്കാതിരിക്കലാണ് ഉത്തമം.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-06-12 13:16:23', '2021-06-12 13:16:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0351', 1, NULL, 1, NULL, NULL, 'കല്യാണത്തിന് ഫോട്ടോ, വീഡിയോസ് എടുക്കൽ എന്താണ് വിധി?', 'സാധാരണയായി കണ്ട് വരുന്ന ഒന്നാണ് കല്യാണത്തിന് ഫോട്ടോ, വീഡിയോസ് എടുക്കൽ. ഇസ്ലാമികമായി ഇത് ഒന്ന് വിശദീകരിക്കാമോ?', 'Malayalam', 'published', '<p>ആധുനിക സംവിധാനങ്ങളായ ഡിജിറ്റൽ ക്യാമറയിലും മൊബൈലിലും മറ്റും ഫോട്ടോ എടുക്കുന്നതുമായി ബന്ധപ്പെട്ട് പണ്ഡിതർക്കിടയിൽ അഭിപ്രായ വ്യത്യാസം നിലനിൽക്കുന്നുണ്ട്. ചിലർ അഭിപ്രായപ്പെടുന്നത് ഹറാമാണ് എന്നാണ്. മറ്റു ചിലർ പറയുന്നത് ഇവ ഉപയോഗിച്ച് എടുക്കുന്ന ചിത്രങ്ങൾക്ക് സ്ഥായിയായ രൂപമോ ഭാവമോ ഇല്ലാത്തതിനാൽ ഈ ചിത്രങ്ങളെ ഹദീസിൽ തടയപ്പെട്ട تصوير (രൂപം നിർമ്മിക്കൽ) ന്റെ ഗണത്തിൽ പെടുത്താൻ കഴിയില്ല എന്നാണ്. ആയതിനാൽ ക്യാമറയിലും മൊബൈലിലും മറ്റും എടുക്കുന്ന ഫോട്ടോ Film, Frame പോലുള്ളവയിലേക്ക് &nbsp;പകർത്താത്തിടത്തോളം അനുവദനീയമാണ്.</p> <p>എന്നാൽ Film, Frame പോലുള്ളവയിലേക്ക് പകർത്തുകയാണെങ്കിൽ തീർത്തും ഹറാം തന്നെയാണ്. ഹദീസിൽ തടയപ്പെട്ട تصوير ന്റെ ഗണത്തിൽ പെടുകയും ചെയ്യും. എന്നിരുന്നാലും സർക്കാരുമായി ബന്ധപ്പെട്ട Passport, Aadhar പോലുള്ള നിർബന്ധിത സാഹചര്യങ്ങളിൽ ഇതിന് അനുമതി നൽകപ്പെട്ടിട്ടുണ്ട്.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; لأن مواضع الضرورة مستثناة من الحرمة كما في تناول الميتة. &nbsp; &nbsp;(فتح الملهم)</p> <p>എന്നാൽ ഇന്ന് കണ്ടുവരുന്ന കല്ല്യാണങ്ങൾക്കും മറ്റ് ഫംഗ്ഷനുകൾക്കും മൊബൈലും മറ്റു ഡിജിറ്റൽ ക്യാമറകളും ഉപയോഗിച്ചുള്ള ഫോട്ടോ വീഡിയോസ് എടുക്കുന്നതും പ്രചരിപ്പിക്കുന്നതും നിഷിദ്ധമായ കാഴ്ചകളിലേക്കും മറ്റു പല അപകടങ്ങളിലേക്കും കൊണ്ടെത്തിക്കുന്നു. കാരണം അതിലൂടെ അന്യ സ്ത്രീകളുമായി കൂടിക്കലരുക, അവരെ കാണുക, അനാവശ്യമായി പൈസ പാഴാക്കുക തുടങ്ങിയ പല ഹറാമായ പ്രവർത്തികളും ചെയ്യേണ്ടിവരുന്നു. ആയതിനാൽ ഇത് അനുവദനീയമല്ല .<br /> &nbsp;</p> <p>&nbsp;</p> <p><a href=\"https://fatwa.kauzariyya.com/single.php?question=142\">For Reference : 142</a></p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-22 12:30:55', '2023-08-05 15:40:55') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0308', 1, NULL, 2, NULL, NULL, 'ആവി പിടിച്ചാൽ നോമ്പ് മുറിയുമോ ?', 'ആവി പിടിച്ചാൽ നോമ്പ് മുറിയുമോ ?', 'Malayalam', 'published', '<p>ആവി പിടിക്കുമ്പോൾ അതിൽ നിന്നും നീരാവി&nbsp; ഉള്ളിലേക്ക് പ്രവേശിക്കുന്നത് കാരണം നോമ്പ് മുറിയുന്നതാണ്.&nbsp;</p>', 18, 0, 5, '1970-01-01 01:00:00', 1, '2021-04-27 01:29:55', '2024-04-06 16:07:08') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0302', 1, NULL, 1, NULL, NULL, 'کیا شریعت کے مطابق کسی شیعہ شخص سے شادی جائز ہے؟', 'میرا نام.... ہے... میری ہمشیرہ کی شادی ہوئی ہے ابھی کچھ دن پہلے... جس لڑکے سے ہوئی ہے اسکے اور اسکی فیملی کے بارے میں لوگ کہتے ہیں کہ یہ اہل تشیع ہیں... انکے والد صاحب بھی شیعہ تھے.. وہ اب اس دینا میں نہیں ہیں... اب انکی اولاد کہتی ہے کہ ہم سنی ہیں. لیکن لڑکا اور فیملی امام بارگاہ میں بھی جاتے ہیں. ماتم کو بھی مانتے ہیں... کہتے ہیں کہ نعوذبااللہ حضرت محمد صل اللہ علیہ السلام نے بھی ماتم کیا تھا.. جب حضرت حمزہ رضی اللہ عنہ شہید ہوئے تھے...اور نعوذبااللہ حضرت عائشہ رضی اللہ عنہا نے بھی اپنے چہرے مبارک پر ماتم کیا تھا.... حضرت علی رضی اللہ عنہ کو سب سے افضل سمجھتے ہیں.. یعنی کافی عقائد شیعہ والے ہیں. نعوذبااللہ حضرت معاویہ رضی اللہ عنہ کو برا بھلا کہتے ہیں... منگنی میں بھی انہوں نے کچھ رسمیں انکی شیعہ والی تھیں... اور اب جیسے کہ میں بندہ علی ہوں....شیعہ زاکر کو سنتا ہے لڑکا خود...نماز ہماری طرح پڑھتے ہیں ( لیکن اب ہمیں پتا چلا ہے کہ یہ تقیہ کرتے ہیں) لڑکے سے تقیہ کے بارے میں پوچھا ہے کہ کیا جائز ہے؟؟ کوئی جواب نہیں... لڑکی کہتی ہے کہ شادی سے پہلے نعوذبااللہ یہ لڑکا صحابہ کرام رضی اللہ عنہ* کو بھی گالیاں دیتا تھا اب شادی کے بعد ہم نے لڑکی کو کہا ہے کہ لڑکے سے کچھ باتوں کی معلومات لو.. جیسے کہ لڑکا کہتا ہے کہ( میں بندہ علی ہوں) اسکا کیا مطلب ہے.. اور بھی بہت سی باتیں ہیں... لیکن اب لڑکی کچھ پوچھتی نہیں ہے... اب پتا نہیں ہوا ہے لڑکی کو.... تو کیا یہ عقائد شیعہ والے ہیں؟؟ لڑکا شیعہ ہے کیا؟؟ اگر شیعہ ہے تو نکاح ہوا ہے کیا یہ نہیں؟؟ برائے مہربانی زرہ تفصیل سے جواب دیا جائے... جزاک اللہ', 'Urdu', 'published', '<p>حضرت علی رضی اللہ عنہ کو الہ (اللہ) ہونے کا، &nbsp;جبریل علیہ السلام کو وحی میں غلطی ہونے کا،&zwnj; ابوبکر رضی اللہ عنہ&nbsp; کی صحبت حضور اکرم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نہ ہونے کا عقیدۃ رکھنے کا اور&nbsp;&nbsp; عائشہ رضی اللہ عنہا کو&nbsp; قذف دینا جیسا عمل ظاہر نہ ہونے کی بنا پر&nbsp;&nbsp; مذکورہ بالا آدمی کو کافر کہنا دشوار ہے،&nbsp; بلکہ وہ ضرور فاسق ہے، &nbsp;نیکی عورت کا نکاح ان جیسا فاسق سے&nbsp; کرایا گیا تو&nbsp; نکاح درست ہوگا،</p> <p>مذکورہ بالا باتوں (جن سے فاعل کافر ہوگا)&nbsp; سے کوئی بات ان سے ظاہر ہوا تو&nbsp; نکاح ان سے فسخ ہو جایے گا،</p>', 21, 0, 5, '1970-01-01 01:00:00', 1, '2021-04-04 03:39:43', '2024-02-01 21:40:59') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0511', 1, NULL, 1, NULL, NULL, 'Q:-ചില മഹല്ലുകളിൽ നാല് സൈഡും കോൺക്രീറ്റിൽ വാർത്ത ഖബർ നിർമ്മിച്ച് വച്ചിട്ടുണ്ട്. മരിച്ചയാളെ ഈ റെഡിമെയ്ഡ് ഖബറിൽ കൊണ്ടുവച്ച് അടക്കുന്ന പതിവ് ആണുള്ളത്.ഇങ്ങനെയുള്ള കബർ നിർമ്മാണം അനുവദനീയമാണോ?', 'ചില മഹല്ലുകളിൽ നാല് സൈഡും കോൺക്രീറ്റിൽ വാർത്ത ഖബർ നിർമ്മിച്ച് വച്ചിട്ടുണ്ട്. മരിച്ചയാളെ ഈ റെഡിമെയ്ഡ് ഖബറിൽ കൊണ്ടുവച്ച് അടക്കുന്ന പതിവ് ആണുള്ളത്.ഇങ്ങനെയുള്ള കബർ നിർമ്മാണം അനുവദനീയമാണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-06 12:14:30', '2023-11-11 15:56:18') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0592', 1, NULL, 1, NULL, NULL, 'ഉളുഹിയ്യ മൃഗത്തെ വിറ്റ് ഉളുഹിയ്യക്ക് വേണ്ടി ഒരു മൃഗത്തെ വാങ്ങാൻ കഴിയുമോ?', 'ഒരു മനുഷ്യൻ ഉളുഹിയ്യക്ക് വേണ്ടി അറുക്കാൻ ഒരു മൃഗത്തെ വാങ്ങുകയും എന്നാൽ ആ മൃഗത്തിന് അസുഖം വരാനും ഉളുഹിയ്യ ദിവസം വരെ ജീവിക്കാതിരിക്കാനും സാധ്യതയുണ്ട്, അവൻ എന്തുചെയ്യണം?  അയാൾക്ക് മൃഗത്തെ വിറ്റ് മറ്റൊന്ന് വാങ്ങാൻ കഴിയുമോ, അതോ മൃഗത്തെ ആരോഗ്യം കണക്കിലെടുക്കാതെ അറുത്താൽ മതിയോ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-06-19 05:04:00', '2023-06-19 07:35:59') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0340', 1, NULL, 2, NULL, NULL, 'ട്രൈൻ യാത്രയിൽ നിന്ന് നമസ്കരിക്കേണ്ടതുണ്ടൊ', 'ട്രൈൻ യാത്രയിൽ നിന്ന് നമസ്കരിക്കേണ്ടതുണ്ടൊ', 'Malayalam', 'published', '<p>ട്രെയിൻ പോലെ നിന്ന് നിസ്കരിക്കാൻ സൗകര്യമുള്ള വാഹനങ്ങളിൽ ഫർള് നമസ്കാരങ്ങൾ ഇരുന്നു നമസ്കരിക്കാൻ അനുവാദമില്ല ഇനി ഫർള് നമസ്കരിക്കുന്നതിനിടെ&nbsp;ട്രെയിനിലെ ശക്തമായ കുലുക്കത്തിൽ പേരിൽ മറിഞ്ഞു വീഴുമെന്ന് ഭയമുണ്ടാവുകയും നമസ്കാരത്തിന്റെ ഭയ ഭക്തിക്ക് കോട്ടം തട്ടുമെന്ന് ആശങ്കയുമുണ്ടായാൽ ട്രെയിനിന്റെ നിലത്തിരുന്ന് നമസ്കരിക്കുന്നതിൽ വിരോധമില്ല&nbsp;<br /> &nbsp;</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:19:53', '2024-05-21 13:46:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0382', 1, NULL, 2, NULL, NULL, 'Vehicle', 'Vehicle', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-21 23:20:07', '2021-10-21 23:20:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0386', 1, NULL, 1, NULL, NULL, 'പിതാവ് ജീവിച്ചിരിക്കുമ്പോൾ സഹോദരൻ വിവാഹ കരാർ പറഞ്ഞാൽ ശരിയാകുമോ ?', 'പ്രായാധിക്യത്തിൽ അവശതകൾ ഉള്ള പിതാവ് ജീവിച്ചിരിക്കുന്ന അവസ്ഥയിൽ പിതാവിൻറെ ഓർമശക്തിയിൽ ഉള്ള കുറവിനെ പരിഗണിച്ചുകൊണ്ട് അദ്ദേഹത്തിൻറെ അനുവാദമില്ലാതെ സഹോദരൻ സഹോദരിയെ വിവാഹം കഴിപ്പിച്ചയച്ചാൽ വിവാഹം ശരിയാകുമോ ?', 'Malayalam', 'published', '<p>വിവാഹം ശരിയാക്കുന്നതിന് പിതാവ് നിർബന്ധമാകുന്നത് വിവാഹിതയാകുന്നവൾ പ്രായപൂർത്തി ആവാത്ത സാഹചര്യത്തിലാണ് .<br /> ചോദ്യത്തിലെ രൂപത്തിൽ വധു പ്രായപൂർത്തിയായതിനാൽ സഹോദരന് വിവാഹം കഴിപ്പിക്കാവുന്നതാണ്. ആ വിവാഹം ശരിയാകുന്നതുമാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-23 13:02:09', '2023-09-22 15:24:49') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0452', 1, NULL, 2, NULL, NULL, 'Silver bracelet for male child', 'ചെറിയ ആണ്കുട്ടികൾക് വെള്ളിയുടെ ബ്രേസ്ലെറ് ധരിക്കൽ അനുവദനീയമാണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-13 03:47:35', '2023-11-02 16:19:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0518', 1, NULL, 1, NULL, NULL, 'മരണശേഷം നാട്ടിൽ കാണുന്ന ആചാരങ്ങൾ ചെയ്യൽ അനുവദനീയമാണോ ?', 'മരണശേഷം മരിച്ചയാളുടെ വീട്ടിൽ മൂന്നിനും നും 40 നും ഒക്കെ പ്രത്യേക ആഹാരം വച്ച് യാസീൻ ഓതി ഉസ്താദിനെയും കുടുംബക്കാരെയും വിളിച്ചു സൽക്കാരം നടത്താറുണ്ട് ഇങ്ങനെ ചെയ്യൽ അനുവദനീയമാണോ ?', 'Malayalam', 'published', '<p>മരിച്ച ആളുടെ വീട്ടിൽ മൂന്നിനും പത്തിനും നാൽപ്പതിനും ഒക്കെ പ്രത്യേക ആഹാരം വെച്ച് യാസീൻ ഓതി ഉസ്താദിനെയും കുടുംബക്കാരെയും വിളിച്ചു സൽക്കാരം നടത്തൽ ബിദ്അത്താണ്. ആയതിനാൽ അത് തീർത്തും ഉപേക്ഷിക്കപെടേണ്ടതാണ്.</p>', 14, 0, 5, '1970-01-01 01:00:00', 1, '2022-02-09 09:09:21', '2023-02-28 10:21:26') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0530', 1, NULL, 2, NULL, NULL, 'To by new car without intrest', 'By new car with out loan', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-02-25 06:34:10', '2023-04-15 20:14:49') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0540', 1, NULL, 2, NULL, NULL, 'Pampers ധരിച്ച മൂത്രം ഒഴിച്ചിട്ടുണ്ടായിരുന്ന കുട്ടി സുജൂദിൻ്റെ സമയത്ത് തോളിൽ കയറി ഇരുന്നാൽ വിധി എന്താണ്?', 'നമസ്കരിച്ചു കൊണ്ടിരുന്നപ്പോൾ Pampers ഇട്ട കുട്ടി സുജൂദിൻ്റെ സമയത്ത് തോളിൽ കയറി ഇരുന്നു. നമസ്കാരം കഴിഞ്ഞ് നോക്കിയപ്പോൾ കുട്ടി pampers ൽ മൂത്രം ഒഴിച്ചിട്ടുണ്ടായിരുന്നു, എങ്കിൽ ആ നമസ്കാരത്തിൻറെ വിധി എന്താണ്?', 'Malayalam', 'published', '<p>നമസ്കരിച്ചപ്പോൾ pampers ഇട്ട കുട്ടി സുജൂദിൻ്റെ സമയത്ത് തോളിൽ കയറി ഇരിക്കുകയും നമസ്കാരം കഴിഞ്ഞ് കുട്ടി അതിൽ മൂത്രമൊഴിച്ചതായി കാണുകയും ചെയ്താൽ ആ നമസ്കാരം മടക്കി നിർവഹിക്കേണ്ടതാണ്.</p>', 59, 0, 5, '2022-05-09 13:28:27', 1, '2022-03-23 13:04:25', '2023-08-16 11:05:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0557', 1, NULL, 1, NULL, NULL, 'മൃഗകൊഴുപ്പ് ഉപയോഗിക്കുന്ന പ്രോഡക്ടുകൾ വിൽക്കൽ അനുവദനീയം ഉണ്ടോ ?', 'മൃഗത്തിന്റെ കൊഴുപ്പ് ഉപയോഗിക്കപ്പെടാൻ സാധ്യതയുള്ള പ്രൊഡക്ടുകൾ ഇന്ന് മാർക്കറ്റിൽ സുലഭമാണ്, അവകൾ നമ്മുടെ കടകളിൽ വില്പന നടത്തൽ അനുവദനീയമാണോ ? ഈ നിയമത്തിൽ ആഹാരപദാർത്ഥങ്ങളും ഇതര വസ്തുക്കളും തമ്മിൽ എന്തെങ്കിലും വ്യത്യാസമുണ്ടോ ?', 'Malayalam', 'approved', 'ffhf', 16, 0, 5, NULL, NULL, '2022-10-16 02:14:22', '2022-10-16 02:14:22') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0288', 1, NULL, 1, NULL, NULL, 'സർജറിയിലൂടെ കൂടുതൽ ഉള്ള അവയവം നീക്കം ചെയ്യൽ അനുവദനീയമാണോ?', 'ഒരു വ്യക്തിയുടെ കയ്യിലോ കാലിലോ കൂടുതൽ വിരലുണ്ടെങ്കിൽ അത് സർജറിയിലൂടെ നീക്കം ചെയ്യൽ അനുവദനീയമാണോ?', 'Malayalam', 'published', '<p>ഒരു വ്യക്തിയുടെ കയ്യിലോ കാലിലോ &nbsp;കൂടുതൽ വിരലുകളുണ്ടെങ്കിൽ അത് സർജറിയിലൂടെ നീക്കം ചെയ്യുന്നത് കൊണ്ട് കുഴപ്പമില്ല.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-02-18 01:15:53', '2021-02-18 01:15:53') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0460', 1, NULL, 1, NULL, NULL, 'സകാത്ത് നൽകാൻ ഏൽപ്പിക്കപ്പെട്ട വ്യക്തി അർഹരല്ലാത്തവർക്ക് നൽകിയാൽ എന്ത് ചെയ്യണം?', 'വിനീതൻ എല്ലാ വർഷവും സകാത് കൃത്യമായി നിറവേറ്റാൻ ശ്രമിക്കുന്ന വ്യക്തിയാണ്. ഞാൻ എന്റെ കഴിഞ്ഞവർഷത്തെ സക്കാത്ത് വിഹിതം ഞങ്ങളുടെ മഹല്ലിൽ പ്രവർത്തിക്കുന്ന സകാത്ത് കമ്മിറ്റിയെ ഏൽപ്പിച്ചിരുന്നു. ഇപ്പോൾ കമ്മറ്റി വരവ് ചിലവുകൾ ഓഡിറ്റ് ചെയ്യുന്ന സന്ദർഭത്തിൽ സകാത് തുക വിനിയോഗിക്കപ്പെട്ട വിവരങ്ങൾ പുറത്തുവന്നു. അതിൽ ഒരു സ്കൂളിലേക്ക് വിദ്യാർഥികളുടെ ഓൺലൈൻ പഠനത്തിനായി സ്മാർട്ട് ഫോണുകൾ വാങ്ങാൻ ഇരുപത്തി അയ്യായിരം രൂപ അധികൃതർക്ക് നൽകിയതായി പറയുന്നു. സകാത് ഫണ്ടിൽ നിന്ന് ഇങ്ങനെ നൽകൽ അനുവദനീയമാണോ ? അനുവദനീയമല്ലെങ്കിൽ ഞാനടക്കമുള്ള ഈ സക്കാത്ത് കമ്മിറ്റിയെ വിഹിതം ഏൽപ്പിച്ച സക്കാത്ത് ദായകരുടെ സകാത്തിൻറെ വിധി എന്താണ് ? ഞങ്ങൾ വീണ്ടും സമ്പാദിച്ച് സകാത്ത് കൊടുക്കേണ്ടതുണ്ടോ? ഇസ്ലാമിക പ്രമാണങ്ങളുടെ വെളിച്ചത്തിൽ മതവിധി പറയണമെന്ന് അഭ്യർത്ഥിക്കുന്നു.', 'Malayalam', 'published', '<p>ചോദ്യത്തിൽ പരാമർശിക്കപ്പെട്ട &nbsp;രൂപത്തിൽ സകാത്തിന്റെ സമ്പത്തിൽ നിന്നും സ്മാർട്ട്ഫോൺ വാങ്ങി നൽകിയത് സകാത്തിന് അർഹരായ മുസ്ലിമീങ്ങൾക്കാണെന്ന് ഉറപ്പുണ്ടെങ്കിൽ ആ സകാത്ത് വീടുന്നതാണ്.</p> <p><br /> മറിച്ച് അനർഹർക്കാണ് നൽകിയതെങ്കിൽ ഇതും &nbsp;ഇതുപോലെ അനർഹരായ ആളുകൾക്ക് &nbsp;നൽകിയ മറ്റ് തുകകളും സകാത്താവുകയില്ല.ആയതിനാൽ ആ വർഷം &nbsp;സകാത്ത് ഇനത്തിൽ ലഭിച്ച മുഴുവൻ തുകയുടെ &nbsp;എത്ര ശതമാനം ആണ് &nbsp;അനർഹരിലേക്ക് &nbsp;എത്തിയതെന്ന് കണക്കാക്കുകയും &nbsp;ഓരോരുത്തരും അവർ നൽകിയ സകാത്ത് തുകയിൽ നിന്ന് &nbsp;ആ ശതമാന പ്രകാരമുള്ള തുക വീണ്ടും &nbsp;സക്കാത്തിന്റെ &nbsp;അർഹരിലേക്ക് &nbsp;കൊടുത്താൽ മാത്രമേ അവരുടെ സകാത്ത് &nbsp;വീടുകയുള്ളൂ. ഇവർക്ക് &nbsp;ആ തുക സകാത്ത് കമ്മിറ്റിയിൽ നിന്ന് തിരിച്ചു വാങ്ങാവുന്നതാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-29 04:22:48', '2023-08-30 11:15:22') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0487', 1, NULL, 1, NULL, NULL, 'ഖബറിന് മുകളിൽ മസ്ജിദ്', 'സൗകര്യം വർധിപ്പിക്കാൻ മുൻകാല ഖബറുകൾക്ക് മുകളിലേക്ക് മസ്ജിദ് നീട്ടാൻ സാധിക്കുമോ ❓️', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-01-03 08:56:10', '2023-11-11 14:49:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0526', 1, NULL, 5, NULL, NULL, 'My question is regarding socil media platforms.', 'I&#39;m Certified Nutritionist Advisor, yoga trainner and business women also. In today&#39;s changing world everything is changing rapidly and all the businesses and works are transform from offline to online world. In this changing world my business and work is also transform offline to online world. And now today&#39;s time my totally business is going on social media platforms. And in this condition my question to you that can i record my own photos and videos for suggesting and promoting my own brand food supplements to people of social media. And can i share my own photos and videos of my workouts and yoga on social media for train the people which helps the audience to connect with workouts and healthy lifestyle. So, tells me the answer of my questions that the sharing of photos and video on social media like Facebook Instagram YouTube and others so, it is right or not according to Islam.', 'Malayalam', 'pending', NULL, 1, 0, 5, NULL, NULL, '2022-02-13 15:32:16', '2023-11-11 14:43:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0531', 1, NULL, 2, NULL, NULL, 'I\'m a young business man (age17) I wanna know about doing ads in business', 'Asalamualaikum wa rahmathullah I run a business called better honey you can cheak it in Instagram or you tube .it is a dry fruit with honey business I do that currently it&#39;s basically a healthy product I have been getting so many opertunities in promoting my brand so my question is can we promote our brand or business through movie actors without spending any money like I don&#39;t have to pay them promoting without giving them money what is the fatwa for that I heard someone say it&#39;s not a problem My idea is to just give them the product and post a photo of them consuming it I will get a great reach through that I have already done it through social media influencers my question is whether I can do it with actors', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-03-02 07:45:49', '2024-01-06 05:38:49') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0403', 1, NULL, 1, NULL, NULL, 'വാടക ഒഴിവാക്കാൻ കൂടുതൽ പണം സെക്യൂരിറ്റി ആയി നൽകലും അത് ഉപയോഗിച്ച് കച്ചവടം ചെയ്യലും അനുവദനീയമാണോ ?', 'വീട് പണയത്തിന് കൊടുത്ത പണം ഉപയോഗിച്ച് കച്ചവടം ചെയ്യാമോ, വാടക ഒഴിവാക്കാൻ കൂടുതൽ പണം സെക്യൂരിറ്റി ആയി നൽകലും വാങ്ങലും അത് ഉപയോഗിച്ച് കച്ചവടം ചെയ്യലും അനുവദനീയമാണോ. ?', 'Malayalam', 'published', '<p>ഒറ്റി, നടപ്പു പണയം, &nbsp;എന്നിങ്ങനെയുള്ള പേരുകളിൽ ഇന്ന് നമ്മുടെ നാടുകളിൽ നിലനിൽക്കുന്ന വീട് പണയമായി നൽകുന്ന ഇടപാട് ഇസ്ലാം നിഷിദ്ധമാക്കിയ പലിശ ഉൾപ്പെട്ടതായതിനാൽ അനുവദനീയമല്ലാത്ത താണ്. വീടിന്റെ ഉടമയ്ക്ക് നിശ്ചിതകാലത്തേക്ക് വലിയൊരു തുക കടമായി നൽകുന്നതിന്റെ പ്രയോജനമായിട്ടാണ് വാടകയില്ലാതെ താമസത്തിനായി വീട് ലഭിക്കുന്നത്. ഇസ്ലാമിന്റെ കാഴ്ചപ്പാടിൽ കടത്തിന് പകരമായി ലഭിക്കുന്ന എല്ലാ പ്രയോജനങ്ങളും പലിശയാണ്.</p> <p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; എന്നാൽ ഈ ഇടപാടിലൂടെ വീടിന്റെ ഉടമയ്ക്ക് ലഭിക്കുന്ന പണം ഉപയോഗിച്ച് കൊണ്ട് എന്തെങ്കിലും കച്ചവടമോ മറ്റു ഇടപാടുകളോ നടത്തിയിട്ടുണ്ടെങ്കിൽ അതെല്ലാം ഹലാലായതും അനുവദനീയമായതുമാണ്. എന്നിരുന്നാലും ഉപരിസൂചിത പണയമിടപാടിൽ വിലക്കപ്പെട്ട പലിശയുടെ അംശം ഉൾപ്പെടുന്നതിനാൽ ഒരു മുസ്ലിം അതിൽ നിന്ന് എത്രയുംവേഗം ഒഴിവാകുകയും മേലിൽ ഇത്തരം ഇടപാടുകളിൽ ഏർപ്പെടാതിരിക്കുകയും ചെയ്യൽ നിർബന്ധമാണ്.</p>', 14, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-30 22:10:21', '2023-11-18 02:38:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0488', 1, NULL, 1, NULL, NULL, 'വകയിലെ ഭാര്യ സഹോദരിയെ വിവാഹം കഴിക്കാമോ ?', 'എൻ്റെ ഭാര്യയുടെ കൊച്ചപ്പായുടെ മകളെ എനിക്ക് വിവാഹം കഴിക്കാമോ ?', 'Malayalam', 'published', '<p>താങ്കൾക്ക് താങ്കളുടെ ഭാര്യയുടെ കൊച്ചാപ്പയുടെ മകളെ വിവാഹം കഴിക്കാവുന്നതാണ്.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2022-01-11 21:18:58', '2022-01-11 21:18:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0583', 1, NULL, 5, NULL, NULL, 'ഇസ്ലാമിലെ ഏറ്റവും വലിയ പാപങ്ങളിലൊന്നാണ് നുണ.', 'ഇസ്ലാമിലെ ഏറ്റവും വലിയ പാപങ്ങളിലൊന്നാണ് നുണ.
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0588', 1, NULL, 5, NULL, NULL, 'Starting a business with halal income earned from bank job permissible?', 'Is it permissible for me, as someone who works in a bank, to start a business using the income I have earned from my job? Despite not having inherited any money or property, I am hesitant about the halal status of my income and want to ensure that any business I start is in line with Islamic principles. I have only received a salary and have not engaged in any interest-based transactions.', 'English', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-04-06 18:12:58', '2023-04-06 18:20:37') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0311', 1, NULL, 1, NULL, NULL, 'Zakat related', 'Sir a friend nd of mine had taken money saying he will return me but when i ask him about the money he says that he doesn&#39;t have money and he won&#39;t return. Then he say that i take that money as zakat from you. So is it permissable to take that money into zakat account?', 'English', 'published', '<p>Your loan can only be considered as Zakat if you had intention of zakat before the borrowed person spend that money from his hand.<br /> currently the amount was spend by the borrowed person so it can&#39;t be considered as zakat.<br /> &nbsp;</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-05-05 14:17:10', '2024-09-13 06:10:14') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0277', 1, NULL, 1, NULL, NULL, 'using the Flipkart Pay Later system, Halal or Haram?', 'What is the Islamic ruling on purchasing goods using the Flipkart Pay Later system? If we repay the money according to their rules within exactly 35 days after the purchase we will not have to pay any more !!! You can use the link below to know more information https://www.flipkart.com/flipkart-pay-later-store <a href=\"https://flipkart.com/flipkart-pay-later-store\">link</a>', 'English', 'published', '<p>Pay later systems means purchasing of goods on installment basis by setting a fixed time period to pay the cost without having interest. But if the amount is not paid on its fixed time, you need to pay more money for that as fine or as interest. So using this system is not permissible.</p> <p><br /> البيع المؤجل وقد يسمي البيع بالنسيئة &nbsp;فما اشترط فيه تأجيل الثمن وهو جائز بالإجماع. ويجب &nbsp;لصحته أن يكون الأجل معلوما. فان كان الأجل فيه جهالة &nbsp;تفضي إلى النزاع فسد البيع. قال الله تعالى: ((يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه. (سورة البقرة ٢٨٢))<br /> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; فقه البيوع ١/٥٣٨</p> <p>الشرط الفاسد إن كان فيه منفعة لأحد العاقدين او للمعقود عليه فانها فاسدة ويفسد بها البيع.</p> <p>But in case of emergency you can use this system if you are sure regarding the payment of installment without due.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2020-12-03 10:04:11', '2020-12-03 10:04:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0283', 1, NULL, 1, NULL, NULL, 'About MLM Buisness', 'Is MLM Buisness is jaiz in hanafi madhab?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-01-30 02:20:29', '2023-11-02 16:08:16') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0372', 1, NULL, 2, NULL, NULL, 'Business insurance അനുവദനീയ൦ ആണോ?', 'നമ്മുടെ business assets നഷ്ടപ്പെടുന്ന സാഹചര്യത്തിൽ പപ്പരായിപ്പോകുന്നതിൽ നിന്നും സംരക്ഷിക്കുന്ന insurance അനുവദനീയ൦ ആണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-21 10:22:58', '2023-11-02 16:09:38') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0332', 1, NULL, 1, NULL, NULL, 'Beauty parlour business', 'Is Islam allowed to start beauty parlour business or shop , take shareholder?', 'English', 'published', '<p>It is not permissible to start a beauty parlour since it involves many activities that are prohibited in Islam.<br /> &nbsp;Even if, you are willing to start beauty parlour without doing those prohibited activities; it is not preferable to start a business like that.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-07-24 06:22:03', '2021-07-24 06:22:03') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0343', 1, NULL, 2, NULL, NULL, 'രോഗിയെ പരിജരിക്കുന്നവർക്ക് ജം.അ പറ്റുമോ ?', 'രോഗിയെ പരിജരിക്കുന്നവർക്ക് . ജം.അ പറ്റുമോ ?', 'Malayalam', 'published', '<p>രോഗിയെ പരിചരിക്കുന്നവർക്ക് ജംഅ് ചെയ്യൽ അനുവദിനിയമല്ല.&nbsp;</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:23:29', '2021-08-12 02:23:29') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0367', 1, NULL, 1, NULL, NULL, 'ഇസ്തിഗാസാ', 'എന്താണ് ഇസ്തിഗാസാ? ഇതിന്റെ വിധി എന്താണ്?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-21 07:46:34', '2023-11-02 16:09:16') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0396', 1, NULL, 1, NULL, NULL, 'മെൻസസ് താമസിക്കുമ്പോൾ വേഗം വരാൻ ഈത്തപ്പഴം, പൈനാപ്പിൾ പോലുള്ള വസ്തുക്കൾ കഴിക്കാമോ ?', 'എനിക്ക് രണ്ട് മക്കൾ ഉണ്ട്, രണ്ടാമത്തെ കുഞ്ഞിന് ഏഴ് മാസം, ഇപ്പൊൾ വീണ്ടും താൻ ഗർഭിണി ആയി എന്ന് പറഞ്ഞു കൊണ്ട് ഭാര്യ വലിയ മനോവിഷമത്തിൽ ആണ്. ഇതിന് കാരണം മെൻസസ് സമയം താമസിച്ചതാണ്. ഉറപ്പില്ലാത്ത ഈ അവസ്ഥയിൽ പൈനാപ്പിൾ, ഓമക്ക, ഈത്തപ്പഴം പോലുള്ള സാധനങ്ങൾ കഴിക്കാൻ പാടുണ്ടോ ?', 'Malayalam', 'published', '<p>താങ്കൾക്ക് താങ്കളുടെ&nbsp; ഭാര്യ ഗർഭിണി അല്ല എന്ന് ഉറപ്പാവുകയും ഭാര്യയെ സമാധാനിപ്പിക്കലും മാത്രമാണ് ഉദ്ദേശമെങ്കിൽ ഈ വസ്തുക്കൾ കഴിക്കുന്നതുകൊണ്ട് കുഴപ്പമില്ല.</p> <p>ഇനി താങ്കൾക്ക് സംശയമാണെങ്കിൽ Test ചെയ്ത് ഉറപ്പുവരുത്തണം. ഗർഭിണി ആണെന്ന് ഉറപ്പാവുകയാണെങ്കിൽ</p> <p>ഗർഭം നാല് മാസമായിക്കഴിഞ്ഞാൽ ഒരു കാരണവശാലും അലസിപ്പിക്കാൻ അനുവാദമില്ല. ഇനി നാല് മാസത്തേക്കാൾ കുറവാകുകയും ഈ ഗർഭം കാരണമായി കുഞ്ഞിനോ അല്ലെങ്കിൽ മാതാവിനോ ശാരീരികമായ ബുദ്ധിമുട്ടുകൾ ഉണ്ടാകും എന്ന് വിശ്വസ്തരായ ഡോക്ടർമാർ നിർദ്ദേശിക്കുകയും ചെയ്യുന്ന പക്ഷം ഗർഭം &nbsp;അലസിപ്പിക്കാവുന്നതാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-29 22:22:42', '2021-10-29 22:22:42') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0444', 1, NULL, 5, NULL, NULL, 'Inheritance of Flat Purchased by Parents, registration not done', 'Our parents bookedflat inadvance under name of one of their children say &lsquo;A&rsquo;, but they returned to Allah before the flat was handed over to &lsquo;A&rsquo;. In such a condition that, the construction is not complete ,the flat key was not handed over, and the flat registration was not done, and the flat was not occupied by &lsquo;A&rsquo;. Kindly let us know In this situation will the flat come under the inheritance or not ?', 'English', 'published', '<p>In the case mentioned in the question, Flat that father bought for Son A will be included in the inheritance since he hasn&#39;t hand overed it. Flat need to be distributed &nbsp;among the inheritors like all other inheritances.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-07 06:17:31', '2021-11-07 06:17:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0414', 1, NULL, 2, NULL, NULL, 'വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധിയാകാൻ കുളിച്ച ശേഷം വുളൂഅ് എടുക്കണോ?', 'വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധിയകാൻ കുളിച്ച് വെക്തിക്ക് വുളൂഅ് എടുക്കാതെ നമസ്കരിക്കാൻ സാധിക്കുമോ വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധിയാകുമ്പോൾ അവന്റെ ചെറിയ അശുദ്ധിയും നിങ്ങുമോ?', 'Malayalam', 'published', '<p>വലിയ അശുദ്ധിയിൽ നിന്ന് ശുദ്ധിയാകാൻ കുളിച്ച വെക്തിക്ക് വുളൂഅ് എടുക്കാതെ തന്നെ നമസ്കരിക്കാവുന്നതാണ് കുളിച്ച ശേഷം നമസ്കാരത്തിന് വേണ്ടി പ്രത്യേകം വുളൂഅ് എടുക്കേണ്ടതില്ല.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-01 21:49:00', '2021-11-01 21:49:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0404', 1, NULL, 1, NULL, NULL, 'വീട് പണയം', 'വീട് പണയത്തിന് കൊടുത്ത പണം ഉപയോഗിച്ച് കച്ചവടം ചെയ്യാമോ , വാടക ഒഴിവാക്കാൻ കൂടുതൽ പണം സെക്യൂരിറ്റി ആയി നൽകലും വാങ്ങളും അത് ഉപയോഗിച്ച് കച്ചവടം ചെയ്യലും അനുവദനീയമാണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-30 22:11:30', '2023-11-02 16:13:02') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0431', 1, NULL, 2, NULL, NULL, 'കൊതുക് ബാറ്റ് ഉബായോഗികമോ?', 'കൊതുക് ബാറ്റ് ഉബായോഗികമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-03 12:45:25', '2023-11-02 16:13:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0541', 1, NULL, 5, NULL, NULL, 'അടയ്ക്ക അനുവദനീയമാണോ?', 'അടയ്ക്ക കൃഷി ചെയ്യുകയും വിൽക്കുകയും ചെയ്യുന്നത് അനുവദനീയമാണോ?', 'Malayalam', 'published', 'അടയ്ക്ക കൃഷി ചെയ്യുകയും വിൽക്കുകയും ചെയ്യുന്നത് അനുവദനീയമാണ്
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0299', 1, NULL, 1, NULL, NULL, 'ایک جلدی طلاق والی لڑکی حلالہ کے بغیر رہنا چاہتی ہے', 'ایک جلدی طلاق والی لڑکی حلالہ کے بغیر رہنا چاہتی ہے', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-03-21 05:43:32', '2021-03-21 05:43:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0427', 1, NULL, 1, NULL, NULL, 'തൂങ്ങി മരിച്ചതിന് മറ ഇരിക്കൽ എന്താണ് വിധി?', '<h2 style=\"font-style:italic;\">തൂങ്ങി മരിച്ചതിന് മറ ഇരിക്കൽ എന്താണ് വിധി?</h2>', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-02 23:39:35', '2023-11-02 16:16:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0435', 1, NULL, 1, NULL, NULL, 'ചെറിയ ആൺകുട്ടികൾക്ക് സ്വർണ്ണം ധരിക്കൽ അനുവാദം ഉണ്ടോ ?', 'ചെറിയ ആൺകുട്ടികൾക്ക് സ്വർണ്ണം ധരിക്കൽ അനുവാദം ഉണ്ടോ ? <a href=\"https://fatwa.kauzariyya.com/single.php?question=98\">Fatwa Link (ആൺകുട്ടികൾക്ക് സ്വർണ്ണം രണ്ടുവയസ്സ് പൂർത്തിയാകുന്നതിനു മുമ്പ് ഉപയോഗിക്കാൻ അനുവാദം ഉണ്ടോ Shafi madhab)</a> https://fatwa.kauzariyya.com/single.php?question=98 ഇതിൽ കുഴപ്പം ഇല്ല എന്ന് ഷാഫി Madhab അനുസരിച്ച് കാണുന്നു. ഇത് തന്നെയാണോ ഹനഫീ മദ്ഹബിലെ നിയമവും. അത് പോലെ മുതിർന്നവർക്ക് വെള്ളിയുടെ മാല, വള പോലുള്ളവ ഉപയോഗിക്കാമോ ?', 'Malayalam', 'published', '<p>ചെറിയ ആൺകുട്ടികൾക്ക് സ്വർണം ധരിപ്പിക്കലും, പുരുഷന്മാർ വെള്ളിയുടെ മാലയും വളയും ധരിക്കലും അനുവദനീയമല്ല.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-05 09:05:36', '2021-11-05 09:05:36') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0553', 1, NULL, 1, NULL, NULL, 'ഓദി ദുആ ചെയ്യിപ്പിക്കുന്നതും മറ്റും മയ്യിത്തിന് പ്രതിഫലം കിട്ടാൻ കരണമായിത്തീരുമോ', 'എന്റെ ജേഷ്ഠൻ ഇന്നലെ വെള്ളിയാഴ്ച്ച ഉച്ചക്ക് ജുമുഅഃ സമയത്തു മരണപ്പെട്ടിരുന്നു. ജേഷ്ഠന് മക്കളില്ല. 
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0565', 1, NULL, 1, NULL, NULL, 'It is stipulated that the veil worn by women should be black ?', 'Is there a requirement that the veil worn by women should be black? Are other tiers allowed?', 'English', 'published', '<p>Most important factor in the dressing etiquette for women is to cover their body completely. Hence it is allowed to wear coloured burqa/pardha.<br><br></p>', 5, 0, 5, '2023-04-15 19:46:00', 1, '2022-11-13 21:12:48', '2023-04-15 19:49:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0456', 1, NULL, 2, NULL, NULL, 'Is crypto currency halal', '<strong>Crypto currency has gained popularity all over the world and it is now used as a medium of exchange in many countries and in the near future it can be a alternative for the original currency...so investing crypto is halal or haram?</strong>', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-19 23:00:04', '2023-11-11 15:57:16') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0561', 1, NULL, 1, NULL, NULL, 'ക്രെഡിറ്റ് കാർഡ് ഉപയോഗിക്കുന്നതിന് നിയമ വിധി എന്ത് ?', 'ഇന്ന് എല്ലാ ബിസിനസ് മേഖലകളിലും ക്രെഡിറ്റ് കാർഡിന്റെ ഉപയോഗം വ്യാപകമായിരിക്കുന്നു, ഫ്ലിപ്കാർട്ട് ആമസോൺ പോലുള്ള ഓൺലൈൻ ഷോപ്പിംഗ് വെബ്സൈറ്റുകളിൽ ക്രെഡിറ്റ് കാർഡ് ഉപയോഗിച്ചുള്ള പർച്ചേഴ്സിന് കൂടുതൽ ഓഫറുകൾ വാഗ്ദാനം ചെയ്യപ്പെടുന്ന ഈ സാഹചര്യത്തിൽ ക്രെഡിറ്റ് കാർഡ് ഉപയോഗിച്ച് കൊണ്ട് പണം ഇടപാട് നടത്തലും അതിലൂടെ ലഭ്യമാകുന്ന ഓഫറുകൾ സ്വീകരിക്കലും അനുവദനീയമാണോ ?', 'Malayalam', 'published', '<p> ഈ കാലത്ത് ക്രെഡിറ്റ് കാർഡിന്റെ ഉപയോഗം വളരെ വ്യാപകമായി കാണുന്നുണ്ട്, ആവശ്യക്കാർക്ക് ബാങ്ക് നിശ്ചയിക്കുന്ന കാലയളവിനുള്ളിൽ തന്നെ പലിശയില്ലാതെ തിരിച്ചടക്കാൻ കഴിയുമെന്ന്  ഉറപ്പുണ്ടെങ്കിൽ, ക്രെഡിറ്റ് കാർഡ് ഉപയോഗിക്കൽ അനുവദനീയമാണ്.കൂടാതെ അത് മുഖേന ലഭിക്കുന്ന ഓഫറുകളും സ്വീകരിക്കാവുന്നതാണ്...<br>എന്നാൽ ക്രെഡിറ്റ് കാർഡ് ഉപയോഗിച്ചു പലിശ വരുന്ന രൂപത്തിലുള്ള യാതൊരു ഇടപാടുകളും അനുവദനീയമല്ല.<br><br></p>', 24, 0, 5, '2023-04-04 06:28:15', 1, '2022-11-08 10:27:06', '2024-08-09 11:25:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0539', 1, NULL, 5, NULL, NULL, 'കൊച്ചുകുട്ടികൾ സോഫയിലും സെറ്റിയിലും മൂത്രമൊഴിച്ചാൽ അത് എങ്ങനെ ശുദ്ധിയാക്കണം?', 'കൊച്ചുകുട്ടികൾ സോഫയിലും സെറ്റിയിലും മൂത്രമൊഴിച്ചാൽ അത് എങ്ങനെ ശുദ്ധിയാക്കണം?', 'Malayalam', 'published', '<p style=\"margin-right: 0px; margin-left: 0px; font-size: 16px; font-family: &quot;Times New Roman&quot;, serif; margin-top: 0px;\"><span lang=\"ML\" style=\"font-size: 15px; font-family: &quot;Noto Serif Malayalam Medium&quot;; color: rgb(83, 82, 82);\">പാൽ മാത്രം
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0318', 1, NULL, 2, NULL, NULL, 'وراثہ', 'بیٹھے کی انتقال کا بعد باپ کی موجودگی میں بیٹھے کا بیٹھا یعنی پوتا کا وراثہ میں کیا حكم ہے ؟', 'Urdu', 'published', 'اگر باپ کی وفات کے وقت کوئی بیٹھے نہ ہوں تو ، پہلے انتقال ہوئی گئی بیٹا کا بیٹا یعنی پوتا کو پورا مال ملےگا ٬اگر موت کے وقت کوئی اور بیٹھے زندہ ہیں تو اس بیٹے کے بیٹے کو کچھ بھی نہیں ملے گا', 4, 0, 5, '1970-01-01 01:00:00', 1, '2021-05-21 22:39:36', '2024-02-05 08:44:50') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0492', 1, NULL, 1, NULL, NULL, 'ചാരിറ്റിക്ക് വേണ്ടി മാറ്റിവെച്ച പണത്തിൽ നിന്നും നമ്മുടെ ആവശ്യത്തിനായി തിരികെ എടുക്കാമോ', 'ചാരിറ്റിക്ക് വേണ്ടി മാറ്റിവെച്ച പണത്തിൽ നിന്നും നമ്മുടെ ആവശ്യത്തിനായി തിരികെ എടുക്കാമോ, നമ്മുടെ സ്ഥാപനത്തിൻ്റെ ലാഭം വിഹിതം ആകിയിരിക്കുന്നു.', 'Malayalam', 'published', '<p>നന്മയായ കാര്യങ്ങൾ ചെയ്യാൻ വേണ്ടി മാറ്റി വെച്ച സമ്പത്ത് നമ്മുടെ ഉടമസ്ഥതയിൽ നിന്നും നീങ്ങിപോകുന്നില്ല മറിച് ആ കാര്യങ്ങൾ ചെയ്യുമ്പോഴാണ് നമ്മുടെ ഉടമസ്ഥതയിൽ നിന്നും നീങ്ങുന്നത് ആയതിനാൽ ഇത് നമ്മുടെ സമ്പത്ത് തന്നെയാണ് നമ്മുടെ മറ്റു ആവശ്യങ്ങൾക്ക്&zwnj; ഉപയോഗിക്കുന്നതിന് തടസമില്ല.</p>', 6, 0, 5, '1970-01-01 01:00:00', 1, '2022-01-15 13:04:09', '2022-01-15 13:04:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0342', 1, NULL, 2, NULL, NULL, 'ട്രെയിനിൽ വെച്ച് ഇരുന്ന് നമസ്കരിച്ച നമസ്കാരങ്ങൾ മടക്കണോ ?', 'ട്രെയിനിൽ വെച്ച് ഇരുന്ന് നമസ്കരിച്ച നമസ്കാരങ്ങൾ പിന്നെ മാറ്റി നിസ്കരിക്കൽ നിർബന്ധം ഉണ്ടോ', 'Malayalam', 'published', '<p>ഫർള് നമസ്കരിക്കുന്ന വ്യക്തി മുഴുവൻ ശർത്തുകളും ഗൗനിച്ച് നിന്ന് നമസ്കരിക്കവെ &nbsp;ട്രെയിനിലെ ശക്തമായ കുലുക്കത്തിന്റെ പേരിൽ ട്രെയിനിൽ നിലത്തിരുന്ന് നമസ്കരിച്ചാൽ വ്യക്തമായ കാരണമുള്ളതിന്റെ പേരിൽ ആ നമസ്കാരം മടക്കി നമസ്കരിക്കേണ്ടതില്ല ഇനി ഒരു കാരണവുമില്ലാതെ ഫർള് നമസ്കാരം ട്രെയിനിൽ ഇരുന്നു നമസ്കരിക്കുകയോ സീറ്റിൽ ഇരുന്ന് നമസ്കരിക്കുകയോ ചെയ്താൽ ആ നമസ്കാരം മടക്കി നമസ്കരിക്കേണ്ടതാണ്</p> <p>&nbsp;സുന്നത്ത് നമസ്കാരങ്ങൾ ഇരുന്നു നമസ്കരിച്ചാൽ മടക്കി നമസ്കരിക്കേണ്ടതില്ല</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:22:42', '2021-08-12 02:22:42') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0394', 1, NULL, 1, NULL, NULL, 'ബോണസ്', 'ഒരു മുതലാളി (ഗവൺമെൻ്റോ/വ്യക്തിയോ) തൻ്റെ കീഴിൽ ജോലി ചെയ്യുന്ന ആളുകൾക്ക് വേറെ മതത്തിൻ്റെ ആഘോഷങ്ങളുടെ ഭാഗമായി (ഓണം/ ക്രിസ്തുമസ്/ദസറ) ബോണസ് ആയി കൂടുതൽ തുക നൽകിയാൽ അധികം നൽകുന്ന തുക ഹലാൽ ആന്നോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-28 22:42:48', '2021-10-28 22:42:48') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0495', 1, NULL, 2, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', 'ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) പോലുള്ള app വഴി ഷെയർ വാങ്ങാൻ പറ്റുമോ അത് ഹലാൽ ആണോ', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 02:03:28', '2023-11-11 14:55:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0601', 1, NULL, 2, NULL, NULL, 'ലിംഗമാറ്റ ശസ്ത്രക്രിയ ചെയ്ത വ്യക്തി പിന്നീട് മുസ്ലിമായാൽ', 'ലിംഗമാറ്റ ശസ്ത്രക്രിയ ചെയ്ത വ്യക്തി പിന്നീട് മുസ്ലിമായാൽ അയാൾക്ക് ശറഈയായ വിധിവിലക്കുകൾ മുമ്പ് ഉണ്ടായിരുന്ന ലിംഗം അനുസരിച്ചാണോ അതോ മാറ്റം വരുത്തിയ ലിംഗം അനുസരിച്ചാണോ ബാധകമാവുക?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-07-26 05:56:57', '2023-09-22 15:43:39') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0417', 1, NULL, 1, NULL, NULL, 'അന്യന്റെ സാധനം അനുവാദമില്ലാതെ വിൽക്കൽ', '1-മറ്റൊരാളുടെ സാധനം അനുവാദം ഇല്ലാതെ വിൽക്കുന്നതിന്റെ വിധി എന്താണ് . 2- ഒരു സാധനം മറ്റാർക്കെങ്കിലും വിൽക്കാനായി ഉടമസ്ഥൻ ഒരാളെ ഏൽപിച്ചാൽ അതിനെ സ്വന്തം എടുത്തിട്ട് പൈസ ഉടമസ്ഥന് കൊടുക്കൽ അനുവദനീയമാണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-01 22:47:49', '2023-11-02 16:13:43') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0350', 1, NULL, 2, NULL, NULL, 'നാല് ദിവസം വരെ ജംഉം കസ്റും ചെയ്യുന്ന മസ്അല എപ്പോഴാണ്?', 'നാല് ദിവസം വരെ തുടർച്ചയായി ജംഉം കസ്റും ചെയ്യുന്ന യാത്രയുടെ രൂപം എങ്ങിനെയാണ് ?', 'Malayalam', 'published', '<p>നാല് ദിവസത്തിനുള്ളിൽ തന്റെ ആവശ്യം പൂർത്തിയാക്കി മടങ്ങാം എന്ന് പ്രതീക്ഷിച്ച് ഒരു നാട്ടിൽ എത്തിയ വ്യക്തിക്ക് 4 ദിവസം വരെ ജംഉം ഖസ്റും ചെയ്യാവുന്നതാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:45:23', '2024-01-14 09:24:30') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0475', 1, NULL, 5, NULL, NULL, 'Is digital gold halal?', 'Is digital gold halal? Exp,Google pay goldlocker', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-12-29 12:08:33', '2024-01-06 05:39:34') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0378', 1, NULL, 1, NULL, NULL, 'സുബഹിക്ക് ശേഷം കൂട്ടമായി യാസീൻ പള്ളിയിൽ പാരായണം ചെയ്യാൻ അനുവതം ഉണ്ടോ ?', 'ഞങ്ങളുടെ പള്ളിയിൽ എല്ലാ ദിവസവും സുബഹിക്ക് ശേഷം കൂട്ടമായി യാസീൻ ഓതാറുണ്ട്. ഇത് കാരണമായി ധാരാളം ആൾക്കാർ യാസീൻ ഓതുന്നു. ഇത് ഒരു സുന്നത്തായി കണക്കാക്കാതെ അവരുടെ കൂടെ ഇരുന്ന് യാസീൻ ഓതുന്നതിൽ കുഴപ്പമുണ്ടോ? ഇത് ബിദ്അത്ത് ആകും എന്ന് കേട്ടിട്ടുണ്ട് ശരിയാണോ?', 'Malayalam', 'published', '<p>സുബഹിക്ക് ശേഷം കൂട്ടമായി യാസീൻ ഓതുന്നതുകൊണ്ട് കുഴപ്പമില്ല. പക്ഷേ അത് നിർബന്ധമാണെന്നോ ദീനിന്റെ ഭാഗമാണെന്നോ വിശ്വസിക്കാതെയും അതിനായി ജനങ്ങളെ നിർബന്ധിക്കാതെയും &nbsp;നിർവഹിക്കുന്നതിൽ കുറ്റമില്ലെങ്കിലും കാലക്രമത്തിൽ സാധാരണ ജനങ്ങൾ നിർബന്ധമായി കരുതാൻ സാധ്യതയുള്ളതിനാൽ ഈ സംഘടിത സ്വഭാവത്തിലുള്ള യാസീൻ പാരായണം ഉപേക്ഷിക്കലാണ് ഉത്തമം.</p>', 5, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-21 22:02:51', '2023-09-04 02:47:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0393', 1, NULL, 1, NULL, NULL, 'ബോണസ്', 'ഒരു മുതലാളി (ഗവൺമെൻ്റോ/വ്യക്തിയോ) തൻ്റെ കീഴിൽ ജോലി ചെയ്യുന്ന ആളുകൾക്ക് വേറെ മതത്തിൻ്റെ ആഘോഷങ്ങളുടെ ഭാഗമായി (ഓണം/ ക്രിസ്തുമസ്/ദസറ) ബോണസ് ആയി കൂടുതൽ തുക നൽകിയാൽ അധികം നൽകുന്ന തുക ഹലാൽ ആന്നോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-28 22:42:44', '2021-10-28 22:42:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0563', 1, NULL, 5, NULL, NULL, 'താടി വളർത്തൽ നിർബന്ധമാണോ ?', 'താടി വളർത്തൽ നിർബന്ധമല്ല എന്നും വെട്ടൽ അനുവദനീയമാണെന്നും ചില പ്രസംഗങ്ങളിൽ കേൾക്കുന്നു. എന്നാൽ നാടുകളിൽ ദീനി സ്വഭാവമുള്ളവർ താടി വളർത്തുന്നതായും അത് വെട്ടാത്ത അവസ്ഥയിലും കാണുന്നു.
