INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0214', 1, NULL, 2, NULL, NULL, 'Valuya ashudhi ayathinu shesham kulikkumbol nammude dehathu veena vellam thirichu kulikkan upayokikkunna vellathil thanne veenal athu kondu veendum kulikkan patto..', 'Valuya ashudhi ayathinu shesham kulikkumbol nammude dehathu veena vellam thirichu kulikkan upayokikkunna vellathil thanne veenal athu kondu veendum kulikkan patto..', 'Malayalam', 'published', '<p>കുളിക്കുമ്പോൾ വലിയ അശുദ്ധിക്കാരന്റെ ദേഹത്ത് നിന്നും വെള്ളം തെറിച്ച് കുളിക്കാനുപയോഗിക്കുന്ന വെള്ളത്തിൽ വീണാൽ അത് ഉപയോഗിക്കാൻ പാടില്ല. എന്നാൽ കുറഞ്ഞ അളവിലാണ് തെറിച്ചതെങ്കിൽ കുഴപ്പമില്ല.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2020-08-19 03:21:12', '2024-02-10 19:27:36') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0405', 1, NULL, 1, NULL, NULL, 'വീട് പണയം', 'വീട് പണയത്തിന് കൊടുത്ത പണം ഉപയോഗിച്ച് കച്ചവടം ചെയ്യാമോ , വാടക ഒഴിവാക്കാൻ കൂടുതൽ പണം സെക്യൂരിറ്റി ആയി നൽകലും വാങ്ങളും അത് ഉപയോഗിച്ച് കച്ചവടം ചെയ്യലും അനുവദനീയമാണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-30 22:11:48', '2023-11-02 16:12:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0497', 1, NULL, 2, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', 'ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) പോലുള്ള app വഴി ഷെയർ വാങ്ങാൻ പറ്റുമോ അത് ഹലാൽ ആണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 02:03:42', '2023-11-11 14:41:51') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0494', 1, NULL, 2, NULL, NULL, 'خواتین کا گاڑی چلانا', 'السلام علیکم و رحمۃ ﷲ حضرت مفتی صاحب ادام ﷲ فیوضکم درج ذیل مسئلہ میں حکم معلومکرنا ہے کہ کیاخواتین کا گاڑی چلانا شرعامباح ہے, کیا بغیر ضرورت کے محض شوق کیلئے گاڑی چلا سکتی ہیں؟ بینوا فلتؤجروا فقط والسلام', 'Urdu', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2022-01-22 00:22:14', '2023-11-11 14:52:11') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0572', 1, NULL, 5, NULL, NULL, 'Greeting for Christmas to the Christians', 'Assalamualaykum Respected Ulema-e-Ikram,
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0307', 1, NULL, 5, NULL, NULL, 'Can i try to become an IFS officer when there were some unislamic practices (like difficult in managing spouse, parents &amp; childrens, shave beard..etc) but will gain serve to ummah...?? Please give an advice on the view of Islam...?', 'I am intended to do Civil service examination to become an IFS (Indian foreign service officer) with the intention of serve ummah. The job structure is we must reside from foreign countries to country where according to government appointment until death. And the way of managing wife, children &amp; parents are very difficult. And also we must forced to remove beard and don&#39;t have chances to wear sunnah dress until retirement and the government also provide a luxury life. But the only positivity is i can serve the ummah with the provided governmental power &amp; can stand for justice.<br /> What is the Islamic view for doing such job by considering above all aspects', 'Malayalam', 'published', '<p>In the current situation of India the presence of Muslims is essential in all senior positions so shaving is permissible for getting the post like Indian foreign service and it is also important to pay &nbsp;maximum attention to your responsibilities to your family as you can.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-04-22 14:05:19', '2023-08-02 06:58:14') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0330', 1, NULL, 2, NULL, NULL, 'സ്റ്റോക്ക് മാർക്കറ്റിൽ ഇൻവെസ്റ്റ് ചെയ്യുന്നത് ഹറാമോ ഹലാലോ?', 'സ്റ്റോക്ക് മാർക്കറ്റിൽ ഇൻവെസ്റ്റ് ചെയ്യുന്നത് ഹറാമോ ഹലാലോ?', 'Malayalam', 'published', '<p>കമ്പനിയുടെ ബിസിനസും മറ്റ് ആക്ടിവിറ്റീസുകളും ഹലാലാകുകയും ഡെലിവറി എടുത്ത് ഇൻവസ്റ്റ് ചെയ്യുകയുമാണെങ്കിൽ ആ കമ്പനിയിൽ ഇൻവസ്റ്റ് ചെയ്യൽ ഹലാലാണ്.</p>', 22, 0, 5, '1970-01-01 01:00:00', 1, '2021-07-09 01:45:18', '2024-10-20 13:05:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0400', 1, NULL, 1, NULL, NULL, 'Google pay nam upayogikkumbol ninnu kittunna benefits nammukku upayogikkal halal ano', 'Google pay nam upayogikkumbol athil ninnu kittunna benefits upayogikal halal ano', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-30 11:34:57', '2023-11-02 16:11:42') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0493', 1, NULL, 5, NULL, NULL, 'നിക്കാഹ് കഴിഞ്ഞു അടുത്തമാസം ആണ് വലീമ മഹർ കൊടുത്തിട്ടില്ല ഈ സന്ദർഭത്തിൽ ഭാര്യയുമായി ബന്ധപ്പെടുന്നതിന്റെ വിധി?', 'നിക്കാഹ് കഴിഞ്ഞു, അടുത്ത മാസമാണ് വലീമ, ഇത് വരെ മഹ്റ് കൊടുത്തിട്ടില്ല. ഇങ്ങനെയുള്ള സന്ദർഭത്തിൽ ഭാര്യയുമായി (ശാരീരിക) ബന്ധപ്പെടുന്നതിന്റെ വിധി എന്താണ്?', 'Malayalam', 'published', '<p>മഹ്റ് അവധി നിശ്ചയിച്ച് നിക്കാഹ് ചെയ്താൽ ഭാര്യയുമായി ബന്ധപ്പെടുന്നതിലോ അവരുമായി യാത്ര ചെയ്യുന്നതിലോ കുഴപ്പമില്ല. ഇനി രൊക്കമായി മഹ്റ് നൽകാമെന്ന അടിസ്ഥാനത്തിൽ വിവാഹം ചെയ്യുകയും രൊക്കമായി മഹ്റ് കൊടുക്കാൻ സാധിക്കാതെ വരുകയും ചെയ്താൽ ഭാര്യയുടെ അനുവാദത്തോട് കൂടി ബന്ധപ്പെടാവുന്നതാണ് . ഭാര്യ വിസമ്മതിച്ചാൽ മഹ്റ് പൂർണമായും കൊടുക്കുന്നതുവരെ ബന്ധപ്പെടുന്നതിൽ നിന്നും മാറി നിൽക്കേണ്ടതാണ്.</p>', 6, 0, 5, '1970-01-01 01:00:00', 1, '2022-01-19 04:21:43', '2024-03-26 10:01:08') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0363', 1, NULL, 5, NULL, NULL, 'ഗെയിമിങ്ങ് അക്കൗണ്ട് വിൽക്കൽ അനുവദനീയമാണോ ....?', ' Online game കൾ വ്യാപകമായ ഈ കാലത്ത് ഒരുപാട് ആളുകൾ അവർ കളിക്കുന്ന account കൾ വിൽക്കുന്നു.. ഈ കച്ചവടം അനുവാദം ഉണ്ടോ....?', 'Malayalam', 'published', '<p>ഈ അക്കൗണ്ട് വിൽക്കുന്നതിലൂടെ വാങ്ങുന്ന വ്യക്തിക്ക് ശറഇയായ പ്രയോജനങ്ങൾ ഒന്നും ഇല്ലാത്തതിനാൽ ഗെയിമിംഗ് അക്കൗണ്ടുകൾ വിൽക്കലും വാങ്ങലും അനുവദനീയമല്ല.</p>', 12, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-19 22:01:14', '2023-12-14 05:06:25') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0550', 1, NULL, 1, NULL, NULL, 'സിഹ്റിന്റെ ജോലി ചെയ്ത ഇമാം നമസ്കരിപ്പിച്ചാൽ പുറകിൽ നമസ്കരിക്കുന്നവരുടെ നമസ്കാരം', 'മറ്റൊരാൾക്ക് പ്രശ്നങ്ങൾ ഉണ്ടാക്കുന്നതിനുവേണ്ടി സിഹ്റിന്റെ ജോലി അമ്പലത്തിലെ പൂജാരിയെ കൊണ്ട് സിഹ്റ് ചെയ്യിപ്പിച്ച ഇമാം നമസ്കരിപ്പിച്ചാൽ പുറകിൽ നമസ്കരിക്കുന്നവരുടെ നമസ്കാരം ശരിയാകുമോ ?', 'Malayalam', 'published', 'ഈ ഇമാം ചെയ്ത പ്രവർത്തി ഹറാമാണ്. അതിനെ കുറിച്ച് അറിവുള്ളതോടുകൂടി അദ്ദേഹത്തിന്റെ പുറകിൽ നിന്ന് നമസ്കരിക്കുന്ന വ്യക്തിയുടെ നമസ്കാരം ശരിയാകുമെങ്കിലും കറാഹത്ത് തഹ് രീമാണ് അതിനാൽ ഇമാമിനെ ഈ ഉത്തരവാദിത്വത്തിൽ നിന്നും മാറ്റുകയോ അതിന് കഴിയാതെ വന്നാൽ മറ്റൊരു പള്ളിയിൽ പോയി നമസ്കരിക്കുകയോ ചെയ്യേണ്ടതാണ്', 51, 0, 5, '2022-07-31 05:41:31', 1, '2022-07-31 05:41:31', '2024-04-14 14:03:47') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0335', 1, NULL, 2, NULL, NULL, 'നാട്ടിൽ നിന്ന് തന്നെ ജംആക്കി യാത്ര തുടങ്ങാൻ പറ്റുമോ?', 'ബസ് സ്റ്റാൻ്റ്, റെയിവേ സ്റ്റേഷൻ ഉള്ള സ്ഥലത്ത് താമസിക്കുന്ന വ്യക്തി നാട്ടിൽ നിന്ന് തന്നെ ജംആക്കി യാത്ര തുടങ്ങാൻ പറ്റുമോ?', 'Malayalam', 'published', '<p>സ്വന്തം നാടിന്റെ അതിർത്ഥി വിട്ട് കടക്കുകയോ ജനവാസകേന്ദ്രം കടന്ന് പോവുകയോ ചെയ്താലേ ജംഉം ഖസറും ചെയ്യാൻ പറ്റുകയുള്ളൂ.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 01:23:40', '2024-01-14 09:28:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0461', 1, NULL, 1, NULL, NULL, 'Zakath Fatwa', 'അസ്സലാമു അലൈക്കും വറഹ്മത്തുല്ലാഹ് ... വിനീതൻ എല്ലാ വർഷവും സകാത് കൃത്യമായി നിറവേറ്റാൻ ശ്രമിക്കുന്ന വ്യക്തിയാണ്. ഞാൻ എൻറെ കഴിഞ്ഞവർഷത്തെ സക്കാത്ത് വിഹിതം ഞങ്ങളുടെ മഹല്ലിൽ പ്രവർത്തിക്കുന്ന സകാത്ത് കമ്മിറ്റിയെ ഏൽപ്പിച്ചിരുന്നു.  ഇപ്പോൾ കമ്മറ്റി വരവ് ചിലവുകൾ ഓഡിറ്റ് ചെയ്യുന്ന സന്ദർഭത്തിൽ സകാത് തുക വി നിയോഗിക്കപ്പെട്ട വിവരങ്ങൾ പുറത്തുവന്നു. അതിൽ ഒരു സ്കൂളിലേക്ക് വിദ്യാർഥികളുടെ ഓൺലൈൻ പഠനത്തിനായി സ്മാർട്ട് ഫോണുകൾ വാങ്ങാൻ ഇരുപത്തി അയ്യായിരം രൂപ അധ്ർകൃതർക്ക് നൽകിയതായി പറയുന്നു. സകാത് ഫണ്ടിൽ നിന്ന് ഇങ്ങനെ നൽകൽ അനുവദനീയമാണോ ?  അനുവദനീയമല്ലെങ്കിൽ ഞാനടക്കമുള്ള ഈ സക്കാത്ത് കമ്മിറ്റിയെ വിഹിതം ഏൽപ്പിച്ച സക്കാത്ത് ദായകരുടെ സകാത്തിൻറെ വിധി എന്താണ് ? ഞങ്ങൾ വീണ്ടും സമ്പാദിച്ച് സകാത്ത് കൊടുക്കേണ്ടതുണ്ടോ?  ഇസ്ലാമിക പ്രമാണങ്ങളുടെ വെളിച്ചത്തിൽ മതവിധി പറയണമെന്ന് അഭ്യർത്ഥിക്കുന്നു.', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-29 04:23:25', '2024-01-06 05:37:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0577', 1, NULL, 2, NULL, NULL, 'കടയിൽ വിൽപനയ്ക്കായി ബഖൂർ കത്തിക്കാൻ കഴിയുമോ?', 'റമളാൻ മാസത്തിൽ കച്ചവട ആവശ്യാത്ഥം കടയിൽ ബഖൂർ പുകക്കൽ അനുവദനീയമാണോ ?', 'Malayalam', 'published', '<p>ശാഫീ മദ്ഹബ് അനുസരിച്ച് തുറക്കപ്പെട്ട ദ്വാരങ്ങളിലൂടെ തടിയുള്ള വസ്തുക്കൾ പ്രവേശിച്ചാലേ നോമ്പുമുറിയുകയുള്ളൂ.<br>സുഗന്ധവസ്തുക്കൾ പുകപ്പിക്കുമ്പോഴുണ്ടാകുന്ന പുകയെതടിയുള്ള വസ്തുക്കളിൽ ഫുഖഹാഅ് ഉൾപ്പെടുത്തിയിട്ടില്ല. അതിനാൽ അത്തരത്തിലുള്ളപുക ശ്വസിച്ചോമറ്റോ അകത്തേക്ക് പ്രവേശിച്ചാലും നോമ്പു മുറിയുകയില്ലെങ്കിലും കറാഹത്താകുന്ന കാരണത്താൽ അതിനെ ഒഴിവാക്കലാണ് ഉത്തമം.&nbsp;&nbsp;<br><br></p>', 117, 0, 5, '2023-04-01 11:22:18', 1, '2023-03-26 12:53:17', '2024-08-18 10:07:37') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0580', 1, NULL, 1, NULL, NULL, 'خواجہ سراؤں کے حقوق، شادی، وراثت اور آپریشن کیا ہیں؟', 'ٹرانسجینڈر افراد کے بارے میں مختلف اسلامی نقطہ نظر کیا ہیں، جن میں ان کے شادی کے حقوق، وراثت کے قوانین، اور صنفی تفویض کی سرجری سے گزرنا شامل ہے؟  برائے مہربانی ان مسائل پر اسلامی فقہ کے موقف کا جامع تجزیہ فراہم کریں۔', 'Urdu', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-04-01 18:53:52', '2023-04-03 08:51:20') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0310', 1, NULL, 1, NULL, NULL, 'Stock Trading in option index and option stock is Halal or Haram', 'Stock Trading in option index and option stock is Halal or Haram', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-05-03 09:18:44', '2023-11-02 16:07:53') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
