INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0409', 1, NULL, 1, NULL, NULL, 'Phonepe qr code scaner കടകളിൽ ചെയ്തു കൊടുക്കുന്നത്', 'ഫോൺപേ scaner കടകളിൽ എത്തിച്ചു നൽകൽ അനുവതനിയമാണോ  Salari കിട്ടുന്നത് 1 മാസം 100എണ്ണം ചെയ്തു കൊടുത്താൽ 50രൂപ. 100 എണ്ണത്തിൽ thare ആയാൽ 30രൂപ ഇതിന്റെ വിധി?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-11-01 12:04:15', '2021-11-01 12:04:15') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0425', 1, NULL, 1, NULL, NULL, 'തൂങ്ങി മരിച്ചതിന് മറ (ഇദ്ദ) ഇരിക്കൽ എന്താണ് വിധി?', 'തൂങ്ങി മരിച്ചതിന് മറ (ഇദ്ദ) ഇരിക്കൽ എന്താണ് വിധി?', 'Malayalam', 'published', '<p>ആത്മഹത്യ ചെയ്യുക എന്ന പ്രവർത്തി വൻപാവമാണ് എങ്കിലും ആത്മഹത്യ ചെയ്ത വ്യക്തിയുടെ ഭാര്യക്ക് മറ (ഇദ്ദ) ഇരിക്കൽ നിർബന്ധമാണ്.</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-02 23:38:31', '2024-08-27 08:48:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0547', 1, NULL, 1, NULL, NULL, 'ളുഹാ നമസ്കാരം ജമാഅത്തായി, ഉറക്കെ ഓതി നിർവഹിക്കാൻ പാടുണ്ടോ ?', 'ഹിഫ്‌സ് പഠിക്കുന്ന കുട്ടികൾക്ക് ഇമാമത്ത് പരിശീലനത്തിന് വേണ്ടി ളുഹാ നമസ്കാരം ജമാഅത്ത് ആയി ഖുർആൻ ഉച്ചത്തിൽ പാരായണം ചെയ്തുകൊണ്ട് നമസ്കരിക്കാൻ അനുവാദം ഉണ്ടോ ?', 'Malayalam', 'published', 'ളുഹാ നമസ്കാരത്തിൽ ഖുർആൻ ഉച്ചത്തിൽ പാരായണം ചെയ്ത് കൊണ്ട് ജമാഅത്തായി നമസ്കരിക്കാൻ അനുവാദമില്ല മറിച്ച് തഹജ്ജുദ് പോലെയുള്ള രാത്രിയിലെ നമസ്കാരങ്ങളിൽ രണ്ടു പേരെ വരെ പുറകിൽ നിർത്തി ഖുർആൻ ഉച്ചത്തിൽ പാരായണം ചെയ്ത് നമസ്കരിക്കാവുന്നതാണ്.', 44, 0, 5, '2022-07-24 11:09:40', 1, '2022-07-24 11:09:40', '2024-10-16 18:24:36') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0523', 1, NULL, 1, NULL, NULL, 'വഖ്ഫ് സ്വത്തിന്റെ സക്കാത്ത്', 'വഖ്ഫ് സ്വത്തിൽ നിന്നുള്ള വരുമാനത്തിന് സക്കാത്ത് നൽകണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-09 09:20:21', '2023-04-15 20:19:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0287', 1, NULL, 1, NULL, NULL, 'سورہ 24 آیت 3', 'قرآن سورۃ 24 آیت 3 السلام جلدی جواب دیجیے سوال 1۔ اس آیت کا صحیح مطلب کیا ہے ۔ اس آیت کا مطلب زناکار نکاح نہیں کرتا ہے یہ ہوگا یا فر زناکار نکاح نہیں کرے یہ ہوگا سوال 2۔ اگر اس آیت کا مطلب زناکار نکاح نہیں کرتا ہے یہ ہے تو اسکا مطلب صحیح کیسے ہے زناکار تو کسی سے نکاح کر لیتی ہے نیک مسلمان لوگوں سے بھی سوال 3۔اس آیت میں یہ کہا ہے کہ زناکار نکاح نہیں کرتا ہے يا فر زناکار نکاح نہ کرے صرف مشرق یا زناکار کے ساتھ یہاں پر صرف مشرق اور زناکار کے علاوہ ناستک، atheist، ( وہ شخص جو خدا یا خداؤں کے وجود سے کفر کرتا ہے یا اس کا اعتقاد نہیں رکھتا ہے۔) بھی ہیں جس سے زناکار نکاح کرتا ہے تو یہاں پر کافر کیوں نہیں لکھا ہے سوال 5 لَا يَنۡكِحُ کا مطلب کیا ہے سوال 4۔ سورہ 24 آیت 1 میں یہ کہا گیا ہے کی ہمنے اس کو نازل کیا اور فرض کر دیا تو فر اسکا مطلب تفسیر میں یہ ہے کی اس سورہ کی آیت فرض کی گئی ہے لیکن اس آیت میں سیدھا لکھا ہوا ہے کی اس کو ہمنے نازل کیا اور فرض کیا مطلب پورا سورہ فرض کیا گیا ہے فر آیت 3 فرض ہے یہ نہیں کتنے لوگ اسکو منسوخ بتا رہے ہیں اور فرض نہیں بتا رہے ہیں میرا خاص سوال یہ ہے کی یہاں زناکار لوگ صرف زناکار سے یا مشرق سے ہی نکاح نہیں کرتے ہیں اس کے علاوہ ایسے لوگ سے بھی نکاح کرتے ہیں جو نہ ہی مشرق ہے اور نہ ہی زناکار ہے وہ کسی خدا کو نہیں مانتا ہے اور وہ زنا بھی نہ کرتا ہے ( تو قرآن میں یہاں کافر کیوں نہیں لکھا گیا ہے ) قرآن میں تھوڑا سا بھی غلطی نہیں ہے لیکن یہاں مجھے شک لگتا ہے مجھے قرآن کی 50 آیت میں بہت ہی زیادہ سک ہے اور تفسیر پڑھنے کے بعد بھی سمجھ میں نہیں آتا ہے کیا آپ مجھے عالم کا نمبر دے سکتے جو 10 سال کا علم ہو میں whatsapp پر سب کا جواب سمجھ لوں 9032150744 حیدرآباد سے', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-02-15 15:44:54', '2021-02-15 15:44:54') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0481', 1, NULL, 2, NULL, NULL, 'നെറ്റ് വർക്ക് ബിസിനസ് കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആയി വർക്ക് ചെയ്യാൻ പറ്റുമോ', 'പ്രൊഡക്ട് ബേസ് ചെയ്തു ( ആളെ ചേർക്കൽ നിർബന്ധമില്ല ) നെറ്റ്വർക്ക് ബിസിനസ്സിലൂടെ കച്ചവടം ചെയ്യുന്ന കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആവാൻ പറ്റുമോ? താഴെ തട്ടിൽ കച്ചവടം നടക്കുമ്പോൾ കമ്പനിയുടെ പ്രതിഫലം മേലെ തട്ടിലുള്ളവർക്ക് കൈ പറ്റൽ അനുവദനീയമാകുമോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-02 01:08:10', '2023-11-11 14:49:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0562', 1, NULL, 2, NULL, NULL, 'സ്വർണ്ണം കടകളിൽ വിൽക്കുമ്പോൾ പണിക്കൂലി വാങ്ങാൻ പാടുണ്ടോ ?', 'സ്വർണ്ണം വില്പന നടത്തുന്ന  വ്യാപാരികൾക്ക് സ്വർണ്ണ വിലയോടൊപ്പം ചേർത്ത് പണിക്കൂലി ഇനത്തിൽ ക്യാഷ് ഈടാക്കൽ അനുവദനീയമാണോ', 'Malayalam', 'assigned', NULL, 2, 0, 5, NULL, NULL, '2022-11-08 10:27:49', '2022-11-08 10:27:49') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0339', 1, NULL, 2, NULL, NULL, 'യാത്രക്കിടയിലെ നിസ്ക്കാരത്തിൽ ഖിബ്ല തെറ്റുമ്പോൾ പ്രശ്നമുണ്ടോ?', 'യാത്രക്കിടയിലെ നിസ്ക്കാരത്തിൽ ഖിബ്ല തെറ്റുമ്പോൾ പ്രശ്നമുണ്ടോ?', 'Malayalam', 'published', '<p>യാത്രക്കിടയിലെ ഫർള് നമസ്കാരത്തിൽ ഖിബ് ല തെറ്റിയാൽ നമസ്കാരം ശരിയാക്കുന്നതല്ല ആ നമസ്കാരം മടക്കി നിർവ്വഹിക്കണം.&nbsp;</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:19:13', '2021-08-12 02:19:13') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
