INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0619', 1, NULL, 2, NULL, NULL, 'is pepsi halal?', 'is pepsi halal?', 'English', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-12-17 17:10:02', '2024-01-06 05:57:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0594', 1, NULL, 2, NULL, NULL, 'ഉള്ഹിയ കുടുംബതിലെ എല്ലാവരുടെ പേരിലും  അറുക്കേണ്ടതു ഉണ്ടോ ?', 'ഉള്ഹിയ കുടുംബതിലെ എല്ലാവരുടെ പേരിലും  അറുക്കേണ്ടതു ഉണ്ടോ ? എന്റെ ഭാര്യ ഹനഫി മദ്ഹബ് കാരിയാണ്.', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-06-20 06:07:17', '2023-06-21 04:18:31') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0598', 1, NULL, 1, NULL, NULL, 'പിരിച്ചെടുത്ത പണം കൊണ്ട് ഒരു മൃഗത്തെ വാങ്ങി ബലി കൊടുക്കുന്നത് അനുവദനീയമാണോ?', 'ഒരു നാട്ടിൽ ഉളുഹിയ്യക്കായി പള്ളി കമ്മിറ്റി അംഗങ്ങൾ നാട്ടുകാരിൽ നിന്നും പിരിവ് നടത്തി. അങ്ങനെ ഓരോരുത്തരും അഞ്ഞൂറും ആയിരവും വെച്ച് കൊടുത്തു നല്ലൊരു തുക സ്വരൂപിച്ചു. ആ തുകയ്ക്കുള്ള മൃഗം വാങ്ങി ബലിയറുത്താൽ അത് ശരിയാകുമോ ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-07-02 04:56:03', '2023-07-02 05:20:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0459', 1, NULL, 2, NULL, NULL, 'Is it permissible to go to Gym where music is playing?', 'Today, most of the gym and health centers have music playing. Is it permissible to go to the gym where music is being played?', 'English', 'published', '<p>It is not permissible to go to the gym where music is being played.</p>', 7, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-21 10:45:58', '2024-04-15 02:26:52') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0595', 1, NULL, 2, NULL, NULL, 'Can a lady slaughter her qurbani herself ?', 'Is it permissible for a woman to personally perform the act of slaughtering an animal for the purpose of qurbani (religious sacrifice)? What are the religious guidelines and cultural practices regarding this matter?', 'English', 'published', '<p>According to Islamic teachings, a woman is permitted to personally slaughter her own Qurbani (Uluhiyyah animal) during the designated time of Eid al-Adha. </p><p>Islamic jurisprudence allows women to slaughter&nbsp;the&nbsp;animal.&nbsp;</p><p>However, it is best to have a male slaughterer instead of a female.<br></p>', 89, 0, 5, '2023-06-20 09:00:06', 1, '2023-06-20 08:48:09', '2024-10-23 13:36:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0604', 1, NULL, 1, NULL, NULL, 'കിടപ്പുമുറിക്ക് സമീപം ബാത്ത്റൂം നിർമ്മിക്കുക ഇസ്ലാമിക നിയമം ?', 'കിടപ്പുമുറിയോട് ചേർന്ന് ഒരു കുളിമുറി പണിയുന്നതിന്റെ വിധി എന്താണ്? രണ്ടും മതിലും വാതിലും കൊണ്ട് വേർതിരിച്ചിരിക്കുന്നു. അറ്റാച്ച്ഡ് ബാത്ത്റൂം എന്നത് ഇസ്ലാമികമല്ല പാശ്ചാത്യ രീതിയാണെന്ന് കേട്ടിട്ടുണ്ട്.', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-08-22 03:56:57', '2023-08-25 14:34:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0610', 1, NULL, 2, NULL, NULL, 'കൈ മുട്ടുന്നത്തിന്റെ ഇസ്ലാമിക വിധി', 'ആഘോഷങ്ങളിൽ ഒക്കെ പ്രോത്സാഹനത്തിനു വേണ്ടി കൈ മുട്ടുന്നതിനുള്ള ഇസ്ലാമിക വിധി', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-10-04 06:35:53', '2023-10-11 07:36:49') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0615', 1, NULL, 1, NULL, NULL, 'പുരുഷന്മാർ മുണ്ട് ഉടുക്കുന്ന രീതി എങ്ങനെയായിരിക്കണം ?', 'പുരുഷന്മാർ മുണ്ടുടുക്കുമ്പോൾ ഇടതുവശത്തേക്ക് മുണ്ടിന്റെ മുൻ ഭാഗം വരുന്ന രൂപത്തിലൂടെ ആകണമെന്നതിന് എന്തെങ്കിലും തെളിവുണ്ടോ ?
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0576', 1, NULL, 1, NULL, NULL, 'ഹജ്ജ് ആരൊക്കെ ചെയ്യണം', 'ഹജ്ജ് ആരൊക്കെ ചെയ്യണം, ആരോഗ്യ പരമായ പ്രശ്ങ്ങൾ ഉള്ളവർ ഹജ്ജ് ചെയ്യണോ ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-03-20 17:18:27', '2023-04-06 09:01:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0415', 1, NULL, 2, NULL, NULL, 'വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധി ആകാൻ കുളിച്ച ശേഷം വുളു എടുക്കാനോ', 'വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധി ആകാൻ കുളിച്ച വെക്തിതിക്ക് വുളു എടുക്കാതെ നമസ്കരിക്കാൻ സദിക്കുമോ ( വലിയ അശുദ്ധിയിൽ നിന്നും ശുദ്ധി ആകുമ്പോൾ അവൻ്റെ ചെറിയ അശുദ്ധിയും നീങ്ങുമോ)?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-11-01 21:49:26', '2021-11-01 21:49:26') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0520', 1, NULL, 1, NULL, NULL, 'ഇമാം എങ്ങനെയുള്ള ആളാണെന്ന് പരിഗണിക്കേണ്ടതുണ്ടോ?', 'ഒരു ഇമാമിന്റെ മൊബൈലിൻറെ അകത്ത് സിനിമയും മറ്റുമാണ്.അയാൾ സിനിമ കാണുന്നുവെന്ന് വ്യക്തമായി അറിയാമെങ്കിൽ അയാളുടെ പുറകിൽ നമ്മുക്ക് നമസ്കരിക്കാമോ?', 'Malayalam', 'published', '<p>സിനിമ കാണുന്നു എന്ന് വ്യക്തമായി അറിയാവുന്ന ഇമാമിന്റെ പുറകിൽ നമസ്കരിക്കൽ കറാഹത്ത് തഹ്&zwnj;രീമം ആണ്.</p>', 17, 0, 5, '1970-01-01 01:00:00', 1, '2022-02-09 09:14:59', '2024-03-09 13:57:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0521', 1, NULL, 1, NULL, NULL, 'നാല് സൈഡും കോൺക്രീറ്റിൽ വാർത്ത ഖബർ നിർമ്മാണം അനുവദനീയമാണോ?', 'ചില മഹല്ലുകളിൽ നാല് സൈഡും കോൺക്രീറ്റിൽ വാർത്ത ഖബർ നിർമ്മിച്ച വച്ചിട്ടുണ്ട്. മരിച്ചയാളെ ഈ റെഡിമെയ്ഡ് ഖബറിൽ കൊണ്ടുവച്ച് അടക്കുന്ന പതിവ് ആണുള്ളത്.ഇങ്ങനെയുള്ള കബർ നിർമ്മാണം അനുവദനീയമാണോ?', 'Malayalam', 'published', '<p>നാല് സൈഡും കോൺക്രീറ്റിൽ വാർത്ത റെഡിമെഴ്ഡ് ഖബറിൽ മരിച്ചയാളെ അടക്കാൻ പാടില്ല. എന്നാൽ പൂഴി മണ്ണ് അല്ലെങ്കിൽ മണ്ണിന് ഉറപ്പില്ലാത്ത സ്ഥലമാണെങ്കിൽ മയ്യിത്തിനെ പെട്ടിയിലാക്കി അടക്കാവുന്നതാണ്. ഇനി പെട്ടിയിലാക്കി അടക്കാൻ സാധിക്കാത്ത പക്ഷം നാല് സൈഡും കോൺക്രീറ്റ് വാർത്ത് അടിയിൽ കോൺക്രീറ്റ് ചെയ്യാതെ ആ ഖബറിൽ മയ്യത്തിനെ അടക്കാവുന്നതാണ്.</p>', 8, 0, 5, '1970-01-01 01:00:00', 1, '2022-02-09 09:18:19', '2023-07-31 11:36:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0545', 1, NULL, 2, NULL, NULL, 'രാത്രിയിൽ വീട് വൃത്തിയാക്കുന്നത് ദാരിദ്ര്യത്തിന് കാരണമാകുമോ ?', 'രാത്രിയിൽ വീട് വൃത്തിയാക്കുന്നത് ദാരിദ്ര്യത്തിന് കാരണമാകും, ഇതിന് പ്രാമാണികമായ വല്ല തെളിവും ഉണ്ടോ?', 'Malayalam', 'assigned', NULL, 6, 0, 5, NULL, NULL, '2022-07-24 10:58:17', '2022-07-24 10:58:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0608', 1, NULL, 2, NULL, NULL, 'ഫോട്ടോ വീഡിയോ എടുക്കുന്നതിന്റെ വിധി ഇസ്ലാമിൽ', 'ഈ കാലഘട്ടത്തിൽ ഫോട്ടോയും വീഡിയോയും എടുക്കുന്നത് സർവ്വസാധാരണമായി നടന്നുകൊണ്ടിരിക്കുകയാണ്. നിക്കാഹിന്റെയോ ദഅവത്തിന്റെയോ ദീനി വിജ്ഞാന സദസ്സിലോ അതുമായി ബന്ധപ്പെട്ട സ്ഥാപനത്തിലോ ഹലാലായ സദസ്സുകളിലോ കുടുംബ സംഗമത്തിലോ ഈ സദസ്സുകളിൽ എല്ലാം ഒരുമിച്ചു കൂടുന്ന സ്ത്രീകൾ സ്ത്രീകളുമായും പുരുഷന്മാർ പുരുഷന്മാരുമായും നിൽക്കുന്ന ഫോട്ടോ പുരുഷന്മാർ പുരുഷന്മാരുടെ ഫോണിലും സ്ത്രീകൾ സ്ത്രീകളുടെ ഫോണിലും എടുക്കൽ അനുവദനീയമാണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-09-06 06:21:32', '2023-09-22 15:43:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0370', 1, NULL, 1, NULL, NULL, 'സ്വലാത്തുൽ തസ്ബീഹ് സ്ഥിരപ്പെട്ടതാണോ ?', 'സ്വലാത്തുൽ തസ്ബീഹ് സ്ഥിരപ്പെട്ടതാണോ ? തെളിവുകളോടുകൂടി പറയാമോ?', 'Malayalam', 'published', '<p>അതെ, തസ്ബീഹ് നമസ്കാരം ഹദീസുകളിലൂടെ സ്ഥിരപ്പെട്ടതാണ്, ഫിഖ്ഹിന്റെ കിതാബുകളിലുടനീളം തസ്ബീഹ് നമസ്കാരത്തെ സുന്നത്തായി ഗണിച്ചിട്ടുമുണ്ട്.</p> <p><br /> <strong>തെളിവുകൾ ചുവടെ കൊടുക്കുന്നു</strong></p> <p>عن عكرمة عن ابن عباس أن رسول الله صلى الله عليه وسلم قال للعباس بن عبد المطلب يا عباس يا عماه ألا أعطيك ألا أمنحك ألا أحبوك ألا أفعل بك عشر خصال إذا أنت فعلت ذلك غفر الله لك ذنبك أوله وآخره قديمه وحديثه خطأه وعمده صغيره وكبيره سره وعلانيته عشر خصال أن تصلي أربع ركعات تقرأ في كل ركعة فاتحة الكتاب وسورة فإذا فرغت من القراءة في أول ركعة وأنت قائم قلت سبحان الله والحمد لله ولا إله إلا الله والله أكبر خمس عشرة مرة ثم تركع فتقولها وأنت راكع عشرا ثم ترفع رأسك من الركوع فتقولها عشرا ثم تهوي ساجدا فتقولها وأنت ساجد عشرا ثم ترفع رأسك من السجود فتقولها عشرا ثم تسجد فتقولها عشرا ثم ترفع رأسك فتقولها عشرا فذلك خمس وسبعون في كل ركعة تفعل ذلك في أربع ركعات إن استطعت أن تصليها في كل يوم مرة فافعل فإن لم تفعل ففي كل جمعة مرة فإن لم تفعل ففي كل شهر مرة فإن لم تفعل ففي كل سنة مرة فإن لم تفعل ففي عمرك مرة.<br /> &nbsp;رواه ابو داود وابن ماجة وابن خزيمة في صحيحه وغيرهم ورواه الترمذي من رواية أبى رافع بمعناه</p> <p><br /> والحديث في صلاة التسبيح مختلف فيه قيل :ضعيف وقيل إنه حسن وهو المختار عند جمهور المحدثين</p> <p>فتاوي دار العلوم زكريا : ٤٧٣/٢</p> <p>وقال البيهقي كان عبدالله بن المبارك يصليها وتداوله الصالحون بعضهم عن بعض وفي ذلك تقوية للحديث المرفوع</p> <p><br /> തസ്ബീഹ് നമസ്കാരത്തെ സംബന്ധിച്ച് പത്തിലധികം സ്വഹാബാക്കൾ റിപ്പോർട്ട് ചെയ്തിട്ടുണ്ട്</p> <p>അബ്ബാസ് റ ഇബ്നു അബ്ബാസ് റ ഫള്ലുബ്നുഅബ്ബാസ് റ അബുറാഫിഗ് റ അനസ് റ ഇബ്നു ഉമർ റ അലിയ്യ് റ ജഅഫർ റ ഉബൈദുല്ല ബ്നു ജ അഫർ റ ഉബൈദുല്ല ബ്നു ജഅഫർ റ തുടങ്ങി പ്രമുഖ സ്വഹാബികളാണ് റിപ്പോർട്ട് ചെയ്തത്</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-21 09:54:03', '2021-10-21 09:54:03') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0485', 1, NULL, 1, NULL, NULL, 'പള്ളികളിലെ പഴയ ഖബറിന് മുകളിൽ മസ്ജിദ് പണിയാമോ?', 'സൗകര്യം വർധിപ്പിക്കാൻ മുൻകാല ഖബറുകൾക്ക് മുകളിലേക്ക് മസ്ജിദ് നീട്ടാൻ സാധിക്കുമോ?', 'Malayalam', 'published', '<p>മുൻകാല ഖബറുകളിലെ മയ്യിത്ത് പൂർണ്ണമായും മണ്ണായിട്ടുണ്ട് എന്ന് ഉറപ്പുണ്ടെങ്കിൽ ആ ഖബറുകളുടെ മുകളിലേക്ക് മസ്ജിദ്&nbsp;നീട്ടാവുന്നതാണ്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2022-01-03 08:54:54', '2023-08-08 07:39:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0489', 1, NULL, 1, NULL, NULL, 'വിദ്യാഭ്യാസ ലോൺ എടുക്കാൻ പാടുണ്ടോ ?', 'ഗവൺമെൻറിൻറെ ഭാഗത്തു നിന്നും ലഭിക്കുന്ന വിദ്യാഭ്യാസ ലോൺ (പലിശ രഹിത) നമുക്ക് എടുക്കൽ അനുവദനീയമാണോ ?', 'Malayalam', 'pending', NULL, 1, 0, 5, NULL, NULL, '2022-01-11 21:21:34', '2023-11-02 16:14:26') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0597', 1, NULL, 1, NULL, NULL, 'ഉളുഹിയയുടെ 7 ഓഹരികളിൽ ഒരു വ്യക്തി പലിശക്കാരൻ ആണെങ്കിൽ അറവ് ഹലാൽ ആകുമോ?', 'ഒരു ഉളുഹിയ മൃഗത്തിൻറെ 7 ഓഹരികളിൽ പങ്കുകാരായവരിൽ ഒരു വ്യക്തി പലിശക്കാരൻ ആണ്. 
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0312', 1, NULL, 1, NULL, NULL, 'Itikaf', 'Is it possible to cut the hair of the head in the state of Itikaf?', 'English', 'published', '<p>It is not allowed to go outside the masjid to get a haircut in the state of Itikaf. In case of an emergency, the hair can be cut from the veranda of the mosque without falling out of the mosque.<br /> &nbsp;</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-05-09 04:32:19', '2021-05-09 04:32:19') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0458', 1, NULL, 2, NULL, NULL, 'Are Black money Halaal?', 'Recently I started joining in a company in accounting field, but later i found that they are having seperate income without paying tax, which falls under black money. My main job duty is to handle the accounts seperately for both tax bill and without the bill. They told me to keep it hidden from gst audirors. Is working in that company permissible? Is my income halal?Are these types of income without paying tax halal? Do I need to look for another job?', 'Malayalam', 'assigned', NULL, 3, 0, 5, NULL, NULL, '2021-11-21 10:39:49', '2023-01-22 13:53:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0483', 1, NULL, 2, NULL, NULL, 'നെറ്റ് വർക്ക് ബിസിനസ് കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആയി വർക്ക് ചെയ്യാൻ പറ്റുമോ', 'പ്രൊഡക്ട് ബേസ് ചെയ്തു ( ആളെ ചേർക്കൽ നിർബന്ധമില്ല ) നെറ്റ്വർക്ക് ബിസിനസ്സിലൂടെ കച്ചവടം ചെയ്യുന്ന കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആവാൻ പറ്റുമോ? താഴെ തട്ടിൽ കച്ചവടം നടക്കുമ്പോൾ കമ്പനിയുടെ പ്രതിഫലം മേലെ തട്ടിലുള്ളവർക്ക് കൈ പറ്റൽ അനുവദനീയമാകുമോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-02 01:14:40', '2023-11-11 15:57:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0532', 1, NULL, 2, NULL, NULL, 'I\'m a young business man (age17) I wanna know about doing ads in business', 'Asalamualaikum wa rahmathullah I run a business called better honey you can cheak it in Instagram or you tube .it is a dry fruit with honey business I do that currently it&#39;s basically a healthy product I have been getting so many opertunities in promoting my brand so my question is can we promote our brand or business through movie actors without spending any money like I don&#39;t have to pay them promoting without giving them money what is the fatwa for that I heard someone say it&#39;s not a problem My idea is to just give them the product and post a photo of them consuming it I will get a great reach through that I have already done it through social media influencers my question is whether I can do it with actors', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-03-02 07:46:09', '2023-11-11 14:47:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0556', 1, NULL, 2, NULL, NULL, 'ചെറിയ കുട്ടികളെ ശിക്ഷണമെന്ന നിലയിൽ അടിക്കാമോ ?', 'പ്രായപൂർത്തിയാകാത്ത മക്കൾക്ക് ശിക്ഷണം എന്ന നിലയിൽ അടി കൊടുക്കുന്നതുകൊണ്ട് കുഴപ്പമുണ്ടോ ? അങ്ങനെ അടി കൊടുത്തു പോയിട്ടുണ്ടെങ്കിൽ അതിനെന്തെങ്കിലും പരിഹാരം ചെയ്യേണ്ടതുണ്ടോ ?', 'Malayalam', 'rejected', NULL, 11, 0, 5, NULL, NULL, '2022-10-16 02:12:51', '2022-10-16 02:12:51') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0345', 1, NULL, 2, NULL, NULL, 'ജംഉം, ഖസറുമാക്കിയ നമസ്കാരം വീണ്ടും നിർവഹിക്കണോ ?', 'യാത്രയിൽ ജംഉം, ഖസറുമാക്കി നാട്ടിലെത്തിയപ്പോൾ അവിടെ ജമാഅത്ത് നിസ്കാരം നടക്കുന്നു. അപ്പോൾ ആ ജമാഅത്തിൽ കൂടി വീണ്ടും നിസ്കരിക്കാമോ?', 'Malayalam', 'published', '<p>യാത്രയിൽ വെച്ച് ജംഉം ഖസറുമാക്കിയതിന് ശേഷം നാട്ടിലെത്തിയപ്പോൾ അവിടെ ജമാഅത്ത് നടക്കുന്നുണ്ടെങ്കിൽ ആ ജമാഅത്തിനോടൊപ്പം വീണ്ടും നമസ്കരിക്കൽ മുസ്തഹബ്ബാണ്</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:26:05', '2021-08-12 02:26:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0359', 1, NULL, 1, NULL, NULL, 'Today\'s innovation', 'Please notify the Common innovations practiced nowadays in our kerala state, in order to stay away from it.', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-10-19 13:39:39', '2021-10-19 13:39:39') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0325', 1, NULL, 1, NULL, NULL, '...', 'Questionassalam u alaikum.agar koi shaks roti ki sides chor kar roti ka darmayan ka hisa khata ho Q k us ko roti ki sides pasand nahi .to kia esa karna jaiz hai.', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-06-13 17:05:33', '2021-06-13 17:05:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0474', 1, NULL, 1, NULL, NULL, 'വഖ്ഫിന്റെ കൈമാറ്റ നിയമം', 'ഒരു മസ്ജിദ് വഖ്ഫ് ഭൂമിയിൽ [പള്ളി നിർമിക്കാനായി വഖ്ഫ് ചെയ്ത ഭൂമിയല്ല.മറിച്ച് പള്ളിക്ക് വരുമാനത്തിനായി അല്ലെങ്കിൽ ഖബറടക്കാനായി യിട്ടുള്ള ഭൂമി ]മുസ്ലീങ്ങൾക്കും അമുസ്ലീങ്ങൾക്കും ഉപയോഗിക്കാനായിഒരു വഴി നൽകി. ആ വഴിയിൽ നിന്നുംമറ്റൊരു ഭാഗത്തേക്ക് മുസ്ലിമീങ്ങൾക്ക് തന്നെയായി മറ്റൊരു വഴി പള്ളിയുടെ ഭൂമിയിലെ ഒരു മൂലയിൽ നിന്നും അൽപം സ്ഥലം ഉപയോഗപ്പെടുത്തി നൽകാമോ? ഹനഫിമദ്ഹബ് എന്ത് പറയുന്നു. ആ വഴിക്കായി ഉപയോഗിക്കുന്ന സ്ഥലത്തിന് പകരമായി മറ്റൊരു സ്ഥലമോ അതിൻറെ വിലയോ നൽകാൻ തയ്യാറാകുന്ന പക്ഷം എന്താണ് വിധി ? അങ്ങനെ പകരമായി കൊടുക്കുന്ന പക്ഷം വഴിയായിട്ടുള്ള ആ ഭൂമിക്ക്പകരം ഭൂമി നൽകിയ ആൾക്ക് പള്ളിയുടെ ഭൂമി ഉടമസ്ഥപെടുത്തി കൊടുക്കാമോ? ഇനി കൈമാറ്റം ചെയ്തു ഉടമസ്ഥ പെടുത്തി കൊടുക്കുന്നില്ല എങ്കിൽ പോലും വഴി ആയിട്ടുള്ള അവകാശം നൽകുക എന്നതിനുപകരം തത്തുല്യമായ ഭൂമി നൽകാനോ അതിന്റെ വില നൽകാനോ തയ്യാറാണെങ്കിൽ ആ ഭൂമിയെ വഴിയായി ഉപയോഗിക്കാനുള്ള അവകാശം പള്ളിക്കതിൽഅവകാശമുള്ളതിനോടൊപ്പം ആ വ്യക്തിക്ക്കൂടി നൽകാമോ? .  ഒരു വഖഫ് ഭൂമിയിൽ നിന്നും ഒരു വ്യക്തികുറച്ച് ആഗ്രഹിക്കുകയും അതിനു പകരമായി അതിനേക്കാൾ പ്രയോജനമുള്ള അതിനേക്കാൾ നല്ല മറ്റൊരു ഭൂമി പകരം നൽകാമെന്ന് പറയുകയുംഅങ്ങനെ പകരം വാങ്ങുന്ന പക്ഷം ഈ ഭൂമിയെ അയാൾക്ക് ഉടമസ്ഥപ്പെടുത്തി  കൊടുക്കാം എന്നഅഭിപ്രായം അബൂ യൂസുഫ് (റഹ ] പറഞ്ഞിട്ടുമുള്ളപ്പോൾ മേൽ പറഞ്ഞ പ്രകാരം കൈമാറുന്നത്വഖഫ് ഭൂമിക്ക് നഷ്ടമുണ്ടാക്കുന്ന തരത്തിലോ തെറ്റായ ഉദ്ദേശത്തിലോ ആകാതിരിക്കുകയും ചെയ്താൽ അങ്ങനെ കൈമാറ്റം നടത്തുന്നതിന്റെ വിധി എന്താണ് ?', 'Malayalam', 'published', '<p>ചോദ്യത്തിൽ പരാമർശിക്കപ്പെട്ട തരത്തിൽ പള്ളിക്ക് വരുമാനത്തിനായോ അല്ലെങ്കിൽ കബറടക്കുന്നതിനായോ വക്കഫ് ചെയ്യപ്പെട്ട ഭൂമിയിൽ നിന്നും വാഖിഫിൻ്റെ (വഖഫ് ചെയ്ത വ്യക്തി) അനുവാദമില്ലാതെ വഴിനടക്കാനുള്ള അവകാശം മറ്റുള്ളവർക്ക് നൽകാനോ അല്ലെങ്കിൽ വഴിക്ക് വേണ്ടി അതിൽ നിന്നും അല്പം ഭൂമി നൽകലോ അനുവദനീയമല്ല.</p> <p>വഖ്ഫ് ഭൂമിയിൽ നിന്നുള്ള പ്രയോജനങ്ങൾ എടുക്കുന്നതിനാവശ്യമായ തരത്തിലുള്ള വഴി ഉപയോഗം അനുവദനീയമാണ്. (ഖബറടക്കുന്നതിനായി മയ്യത്തിനെ കൊണ്ടുവരുന്നതിന് വേണ്ടിയുള്ള വഴിപോലെ)</p> <p>വഖ്ഫ് ഭൂമിയെ അതിനേക്കാൾ പ്രയോജനമുള്ള മറ്റ് ഭൂമികളുമായി കൈമാറ്റം ചെയ്യാമെന്ന് അബൂ യൂസുഫ് (റ) പറഞ്ഞത് &quot; വഖ്ഫ് ചെയ്ത വ്യക്തി വഖ്ഫിൽ അതിന്&nbsp; അനുവാദം നൽകിയിട്ടുണ്ടെങ്കിൽ എന്നതിനെ അടിസ്ഥാനപ്പെടുത്തിയാണ്. അതല്ലാത്ത രൂപങ്ങളിൽ അതിൽ നിന്നും പ്രയോജനങ്ങൾ ലഭിക്കുന്ന സാഹചര്യത്തിൽ മറ്റു ഭൂമികളുമായുള്ള കൈമാറ്റമോ വഖ്ഫ് ചെയ്ത വ്യക്തിയുടെ ഉദ്ദേശമല്ലാത്ത മറ്റ് ഉപയോഗങ്ങളോ വഖ്ഫ് ഭൂമിയിൽ അനുവദനീയമല്ല</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-12-07 04:42:48', '2024-07-09 06:01:32') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0508', 1, NULL, 2, NULL, NULL, 'Can I eat meat slaughtered by non muslim if we are travelling to a non muslim countries like europe?', 'If we areliving in a non muslim country like europe it is very difficult for us to search for halal food but usually every where can find KFC, McDonald&#39;s etc but Meat available there might be either slaughtered by machine or non muslim is it permissible for me to eat that. Countries in Europe are mostly very cold so it is very difficult with out non veg also veg foods are bit costly or chance of availability is very low ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-03 00:35:52', '2023-11-11 14:38:13') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0617', 1, NULL, 2, NULL, NULL, 'ഒരാളുടെ ഭാര്യയായി ഇരിക്കുന്ന സ്ത്രീയെക്കുവേണ്ടി കല്യാണ ആലോചന നടത്താമോ ?', 'ഒരു സ്ത്രീ ഒരാളുടെ ഭാര്യ ആയി ഇരിക്കുന്ന അവസ്ഥയിൽ വിവാഹം ആലോചിക്കുന്നതിന്റെ വിധി എന്ത്? തെളിവ് സഹിതം പറഞ്ഞ് തരുമോ ?
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0621', 1, NULL, 2, NULL, NULL, 'രക്തം മെൻസസ് പീരീഡ്‌ കഴിഞ്ഞു കാണുന്ന സ്ത്രീയുടെ നിയമം', 'സാധാരണ 7അല്ലെങ്കിൽ 8 ദിവസം മാത്രം മെൻസസ് പീരീഡ്‌ ഉള്ള  സ്ത്രീക്ക് പതിനൊന്നാം ദിവസം വീണ്ടും രക്തം വന്നാൽ എന്ത് ചെയ്യണം?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-12-26 05:22:17', '2024-01-05 14:52:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0587', 1, NULL, 5, NULL, NULL, 'Ruling on sexual activity with spouse while fasting. Mutual coercion?', 'What is the ruling on lying together with one\'s wife during fasting and touching each other\'s genitals with passion? If it is mutually coercive then what is the law?', 'English', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-04-06 10:01:41', '2023-04-06 10:03:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0390', 1, NULL, 1, NULL, NULL, 'Online trading', 'ഓൺലൈൻ trading ന്റെ ഭാഗമായുള്ള coin നമ്മൾ cash മുടക്കി വാങ്ങിക്കുകയും...ഉദാഹരണം ഒരു 10000 രൂപയുടെ പല coins മേടിക്കുന്നു... അതിൽ ചില coins ന്റെ rate കൂടുകയും ചിലത് കുറയുകയും ചെയ്യാൻ സാധ്യത നിലനിൽക്കുന്നു... അതായത് ലാഭവും നഷ്ടവും സംഭവിക്കാൻ സാധ്യതയുണ്ട്.... ഇത് കച്ചവട സാധനങ്ങൾ സ്റ്റോക്ക് ചെയ്തു വില കൂടുകയും കുറയുകയും ചെയ്യുന്നതിന് സമമല്ലേ.. ഇവിടെ കച്ചവട വസ്തുവായി stock ചെയ്യുന്നത് cash മുടക്കി മേടിച്ച coins ആണെന്ന് മാത്രം.....എന്താണ് വിധി... ഈ ഓൺലൈൻ trading അനുവദനീയമാണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-26 11:40:45', '2023-11-02 16:08:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0373', 1, NULL, 2, NULL, NULL, 'Business insurance അനുവദനീയ൦ ആണോ?', 'നമ്മുടെ business assets നഷ്ടപ്പെടുന്ന സാഹചര്യത്തിൽ പപ്പരായിപ്പോകുന്നതിൽ നിന്നും സംരക്ഷിക്കുന്ന insurance അനുവദനീയ൦ ആണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-21 10:26:27', '2023-11-02 16:10:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0441', 1, NULL, 5, NULL, NULL, 'ത്വലാഖ്', 'ഒരാൾ തൻ്റെ ഭാര്യയോട് എനിക്കിനി നിന്നെ ഭാര്യയായി കാണാൻ സാധിക്കുകയില്ല അല്ലെങ്കിൽ ഒരു സദസ്സിൽ വെച്ചു ഇനി എനിക്ക് ഈ ബന്ധം മുമ്പോട്ടു കൊണ്ടുപോകാൻ സാധിക്കുകയില്ല എന്ന് പറഞ്ഞാൽ അത് ത്വലാഖ് ആകുമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-06 20:47:26', '2023-11-02 16:12:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0448', 1, NULL, 1, NULL, NULL, 'താഴെ കാണുന്ന (لا اله الا انت سبحانك اني كنت من الظالمين) ദിക്റിനെ അധികമായി ചെല്ലുന്നത് കുഴപ്പമുണ്ടോ ?', 'താഴെ കാണുന്ന (لا اله الا انت سبحانك اني كنت من الظالمين) ദിക്റിനെ അധികമായി ചെല്ലുന്നത് കുഴപ്പമുണ്ടോ ? ഈ ദിക്ർ ചൊല്ലി ദുആ ചെയ്താൽ ആ ദുആ സ്വീകരിക്കപ്പെടാൻ ഉള്ള സാധ്യത !!!', 'Malayalam', 'published', '<p>ഈ ദിക്റിന്റെ ശ്രേഷ്ഠതയെപ്പറ്റി ഹദീസുകളിൽ പരാമർശം വന്നിട്ടുണ്ട്. നബി (സ) അരുളി: ആരെങ്കിലും ഈ ദിക്ർ ചൊല്ലി ദുആ ചെയ്താൽ ആ ദുആ സ്വീകരിക്കപ്പെടുന്നതാണ്. ആയതിനാൽ ഈ ദിക്ർ ധാരാളമായി ചൊല്ലുന്നത് നല്ലതാണ്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-07 22:12:21', '2021-11-07 22:12:21') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0554', 1, NULL, 5, NULL, NULL, 'ഫാമിലിക്കൊപ്പം ടൂർ പോകാൻ പാടുണ്ടോ ?', 'ഫാമിലിക്കൊപ്പം ടൂർ പോകുന്നത് അമ്പത്തിക ഇസ്രഫ് ആണെന്ന് ചില ദീനി പ്രവർത്തകരിൽ നിന്നും കേൾക്കാൻ കഴിയുന്നു, അപ്രകാരം ചെയ്യരുതെന്നും അവർ നമ്മളെ ഉപദേശിക്കുന്നു. ഈ വിഷയത്തിൽ ശരീഅത്തിൻെറ കാഴ്ചപ്പാട് ഒന്ന് വിശദീകരിക്കാമോ ?', 'Malayalam', 'assigned', NULL, 6, 0, 5, NULL, NULL, '2022-10-16 02:07:17', '2022-10-16 02:07:17') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0300', 1, NULL, 2, NULL, NULL, 'اس عورت کے 2 بچے ہیں ، وہ کسی بھی حالت میں ہلالہ کا راستہ اختیار نہیں کرنا چاہتی اور اسی شور کے ساتھ زندگی گزارنا چاہتی ہے۔', 'اس عورت کے 2 بچے ہیں ، وہ کسی بھی حالت میں ہلالہ کا راستہ اختیار نہیں کرنا چاہتی اور اسی شور کے ساتھ زندگی گزارنا چاہتی ہے۔', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-03-21 05:50:22', '2021-03-21 05:50:22') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0275', 1, NULL, 5, NULL, NULL, 'ചികിത്സ എന്ന നിലക്ക് ഹിജാമക്ക് പ്രതിഫലം വാങ്ങുന്നതിന്റെ വിധി', 'ഞാൻ ഒരു ഹിജാമ ചികിത്സകനാണ്. ക്ലിനിക്കൽ ഉപകരണങ്ങളും മറ്റ് ചിലവുകളും ചേർത്ത് ഞാൻ ചികിത്സ ചെയ്യുമ്പോൾ അതിൽ നിശ്ചിത ഫീസ് വാങ്ങുന്നതിന്റെ വിധി എന്താണ്...??<br /> ഹിജാമക്കാരന്റെ പ്രതിഫലം നിശിദ്ധമാണെന്ന് ചില ഹദീസുകൾ (ജാമിഉ തിർമുദി 1275, 1278, ബുഖാരി 2238, 5962, സുനൻ നസാഈ 4673, 4294, സുനൻ ഇബ്നു മാജ 2165, സഹീഹ് മുസ്ലിം 1568) വ്യക്തമായി സൂചിപ്പിക്കുന്നു.<br /> എന്നാൽ മറ്റ് ചില ഹദീസുകളാകട്ടെ ഹിജാമക്കാരന് പ്രവാചകൻ (സ) പ്രതിഫലം നൽകിയതായും, അത് വാങ്ങുന്നതിൽ കുഴപ്പവുമില്ല എന്നും വ്യക്തമായി സൂചിപ്പിക്കുന്നു. ( ബുഖാരി 2279, 2280, 2281,2277, ഇബ്നു മാജ 2163, 2164, സുനൻ അബൂ ദാവൂദ് 3423, 3224)  ഈ രണ്ട് വിഭാഗം ഹദീസുകളുടെയും അടിസ്ഥാനത്തിൽ ഹിജാമ ചികിത്സകൻ നിശ്ചിത പ്രതിഫലം ഫീസായി വാങ്ങുന്നതിന്റെ വിധിയെന്താണ്..? അനുവദനീയമെങ്കിൽ ഫീസിന്റെ മാനദണ്ഠങ്ങൾ എന്തൊക്കെയാണ്..?', 'Malayalam', 'published', '<p>ഹിജാമ ചികിൽസ നടത്തുന്ന വ്യക്തിക്ക് ഫീസായി നിശ്ചിത തുക വാങ്ങൽ &nbsp;അനുവദനീയമാണ്.<br /> ഇതാണ് ഭൂരിഭാഗം പണ്ഡിതന്മാരുടെയും അഭിപ്രായം. നബിﷺ ഹിജാമ ചെയ്ത ശേഷം أبو طيبة ക്ക് കൂലി നൽകി എന്ന ഹദീസിനെയാണ് അവർ അടിസ്ഥാനമാക്കുന്നതത്.<br /> عن عبدالله بن عباس احْتَجَمَ النبيُّ ﷺ، وأَعْطى الحَجّامَ أَجْرَهُ، ولو عَلِمَ كَراهيةً لَمْ يُعْطِهِ.<br /> ( صحيح البخاري ٢٢٧٩ &nbsp;)<br /> നബിﷺ ഹിജാമ ചെയ്യുകയും ഹിജാമ ചെയ്തയാൾക്ക് കൂലി നൽകുകയും ചെയ്തു. കൂലി നൽകൽ &nbsp;അനുവദനീയമല്ലായിരുന്നുവെങ്കിൽ നബിﷺ നൽകുമായിരുന്നില്ല.</p> <p>എന്നാൽ<br /> &nbsp;عن رافع بن خديج عَنْ رَسُولِ اللّٰهِ ﷺ ثَمَنُ الكَلْبِ خَبِيثٌ، ومَهْرُ البَغِيِّ خَبِيثٌ، وكَسْبُ الحَجّامِ خَبِيثٌ.<br /> ( صحيح المسلم ٣٩٨٨)</p> <p>നായയുടെ വില മോശമാണ്, വേശ്യയുടെ സ്ത്രീധനം മോശമാണ്, &nbsp;ഹിജാമയുടെ വരുമാനം മോശമാണ്. &rdquo;</p> <p>ഈ രീതിയിൽ വന്നിട്ടുള്ള ഹദീസുകളിലെ خبيث<br /> &quot;മോശമാണ്&quot; എന്ന് പറഞ്ഞതിന്റെ ഉദ്ദേശം ആ ജോലി ഹറാമാണ് എന്ന അർത്ഥത്തിൽ അല്ല.മറിച്ച് നജസുമായി &nbsp;ബന്ധപ്പെട്ട് നിൽക്കുന്നത് കൊണ്ട് ആ പ്രവർത്തി അത്ര ഉജിതമല്ല എന്നാണ് ഉദ്ദേശം. മറ്റ് സമ്പാദ്യമാർഗം ഉണ്ടെങ്കിൽ അതിനെ കൈ കൊള്ളലാണ് നല്ലത്.<br /> ഇനി ഒരാൾ ഹിജാമയെ തൊഴിലായി സ്വീകരിച്ചാൽ ശറഇന്റെ വീക്ഷണത്തിൽ അതിന് പകരം ഫീസ് വാങ്ങൽ ഹലാലാണ്. ആ സമ്പത്ത് ഹറാം ആവുകയില്ല.</p> <p>ഫീസിനുള്ള മാനദണ്ഡമായി തന്റെ പ്രവർത്തനത്തെ നിശ്ചയിക്കാവുന്നതാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2020-12-02 20:35:25', '2020-12-02 20:35:25') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0437', 1, NULL, 1, NULL, NULL, 'സ്ത്രീകൾ ആണുങ്ങൾക്ക് സലാം പറയുന്നതിന്റെ വിധി എന്ത്?', 'സ്ത്രീകൾ ആണുങ്ങൾക്ക് സലാം പറയുന്നതിന്റെ വിധി എന്ത് ? ഉദാ ഹോസ്പിറ്റലുകളിൽ രാവിലേയും വൈകുന്നേരവും രോഗിയുടെ റൂമിൽ കയറുമ്പോൾ അവർ സലാം പറയുന്നു. ഇതിൻറെ മസ്അല എന്താണ് ?', 'Malayalam', 'published', '<p>സ്ത്രീകൾ അന്യപുരുഷൻമാരോടും തിരിച്ചും സലാം പറയാൻ പാടില്ല.ഇനി അവർ സലാം പറയുകയാണെങ്കിൽ മനസ്സിലാണ് സലാമിന് മറുപടി നൽകേണ്ടത്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-05 20:23:25', '2021-11-05 20:23:25') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0502', 1, NULL, 5, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', 'ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) എന്ന app വഴി stock വാങ്ങൽ അനുവദിനീയമാണോ (zomato) ടെ ഷെയർ ആണ് എടുത്തത് അത് അനുവദിനീയമാണോ', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 08:06:26', '2023-11-11 14:56:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0609', 1, NULL, 1, NULL, NULL, 'വാങ്ങിയ വിലയിലോ അതോ വിൽപ്പന വിലയിലോ സകാത്ത് ?', 'ഇലക്‌ട്രോണിക് സാധനങ്ങൾ വിൽക്കുന്ന ഒരു കട ഉണ്ട്,  സാധനങ്ങളുടെ സകാത്ത് നൽകുമ്പോൾ ഞാൻ വാങ്ങിയ  നിരക്കിന്റെയോ വിൽപ്പന നിരക്കിന്റെയോ ? എനിക്ക് ഫിക്സ് നിരക്കുകളൊന്നുമില്ല; അത് ഇനത്തെയും ഉപഭോക്താവിന്റെ അവസ്ഥയെയും ആശ്രയിച്ചിരിക്കുന്നു.', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-09-22 15:41:26', '2023-09-22 15:42:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0612', 1, NULL, 2, NULL, NULL, 'സകാത് ഉണ്ടോ', 'ഒരു സ്വർണ്ണക്കടയിൽ സ്വർണ്ണം ഇൻവെസ്റ്റ്‌ ചെയ്ത് ഒരു വർഷം പൂർത്തിയായാൽ ആ ഇൻവെസ്റ്റ്‌ ചെയ്ത സ്വർണ്ണത്തിന് സകാത് ഉണ്ടോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-10-06 13:57:12', '2023-10-11 07:38:12') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0449', 1, NULL, 1, NULL, NULL, 'لا اله الا انت سبحانك اني كنت من الظالمين', 'لا اله الا انت سبحانك اني كنت من الظالمين Ee zikr athikam aayi cheyyunath kond kuzhappam ndo', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-07 22:12:53', '2023-11-02 16:21:54') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0507', 1, NULL, 2, NULL, NULL, 'Can I eat meat slaughtered by non muslim if we are travelling to a non muslim countries like europe?', 'If we areliving in a non muslim country like europe it is very difficult for us to search for halal food but usually every where can find KFC, McDonald&#39;s etc but Meat available there might be either slaughtered by machine or non muslim is it permissible for me to eat that. Countries in Europe are mostly very cold so it is very difficult with out non veg also veg foods are bit costly or chance of availability is very low ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-03 00:34:41', '2023-11-11 14:43:07') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0573', 1, NULL, 1, NULL, NULL, 'صلاة القضاء', 'هل تصلي الصلاة القضاء جماعة ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-01-28 13:16:11', '2023-01-28 10:20:20') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0117', 1, NULL, 5, NULL, NULL, 'മൃഗങ്ങളെ മെഷീൻ കട്ടിങ് ചെയ്‌താൽ ഹലാൽ ആകുമോ?', '<ol> മൃഗങ്ങളെ മെഷീൻ കട്ടിങ് ചെയ്താൽ ഹലാൽ ആകുമോ? ഹലാൽ ആകാനുള്ള നിബന്ധനകൾ എന്തെല്ലാം ആണ്? </ol>', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2020-03-04 05:03:21', '2023-11-02 05:02:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0434', 1, NULL, 1, NULL, NULL, 'പുരികം, മുടി, താടി, മീശ എന്നിവയിലുള്ള സുന്നത്തായ രൂപം ?', 'ഇപ്പോൾ നാട്ടിൽ ഒക്കെ സാധാരണ കണ്ടു വരുന്ന ഒരു കാര്യമാണ് പുരികം കട്ട് ചെയ്യുന്നത്. ഇങ്ങനെ ചെയ്യുന്നതിന് ഇസ്ലാമിൽ വിലക്കുണ്ടോ?,മുടി വെട്ടുന്നത് പല നിലയിലുള്ള രൂപവും ഉണ്ട്. പുരികം, മീശ, താടി, മുടി എന്നിവയിൽ വെട്ടുന്നതിൻ്റെയും വളർത്തുന്നതിൻ്റെയും സുന്നത്തായ രൂപം ഒന്ന് വിവരിക്കാമോ ?', 'Malayalam', 'published', '<p>ഇന്ന് സാധാരണഗതിയിൽ&nbsp; കണ്ടു വരുന്നതുപോലെ സ്ത്രീകൾ സൗന്ദര്യം വർദ്ധിപ്പിക്കാൻ വേണ്ടി പുരികം കട്ട് ചെയ്യൽ ഇസ്&zwnj;ലാമിൽ അനുവദനീയമല്ല. മീശ പറ്റ വെട്ടലാണ് സുന്നത്ത്. താടി ഒരു പിടി വളർത്തൽ വാജിബും അതിന് മുമ്പ് വെട്ടൽ ഹറാമുമാണ്. ഒരു പിടിക്ക് ശേഷം വെട്ടിയൊതുക്കൽ മുസ്തഹബ്ബുമാണ്. മുടി നീട്ടി വളർത്തൽ സുന്നത്താണ്. വെട്ടുകയാണെങ്കിൽ എല്ലാ ഭാഗവും ഒരേ അളവിലാക്കി വെട്ടേണ്ടതാണ്.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-04 03:10:37', '2023-08-28 18:23:23') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0476', 1, NULL, 5, NULL, NULL, 'Is digital gold halal?', 'Is digital gold halal? Exp,Google pay goldlocker', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-12-29 12:09:09', '2024-01-06 05:40:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0611', 1, NULL, 5, NULL, NULL, 'പണത്തിന് വീട് എടുക്കാമോ...?', 'വീട് നടപ്പ് പണയം (ഒറ്റി) ക്ക് എടുക്കുകയും ഒരു വലിയ തുക അവർക്ക് കടമായി നൽകുകയും ഒപ്പം ഒരു വാടക നിശ്ചയിക്കുകയും ചെയ്യുന്നു.വീട് എടുക്കുന്നത് നിച്ചിത്ത കാലാവധി വരെ യാണ്.ഈ രൂപം അനുവദനീയം ആണോ...??', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-10-04 15:21:52', '2023-10-11 07:37:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0613', 1, NULL, 2, NULL, NULL, 'കാലിൽ മോതിരം ധരിക്കാമോ ?', 'സ്ത്രീകൾക്ക് കാൽവിരലുകളിൽ മോതിരം ധരിക്കുന്നത് ഇസ്ലാം അനുവദിച്ച കാര്യമാണോ ?', 'Malayalam', 'published', '<p>സ്ത്രീകൾക്ക് കാലിൽ മോതിരം ധരിക്കൽ അനുവദനീയമാണ്.</p>', 34, 0, 5, '2023-12-19 10:55:27', 1, '2023-10-26 16:11:52', '2024-11-02 19:09:56') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0614', 1, NULL, 2, NULL, NULL, 'മുടി വെട്ടൽ', 'മുടി വെട്ടുന്നതിനു പ്രത്യേക ദിവസങ്ങൾ ദീനിൽ പരാമർശിച്ചിട്ടുണ്ടോ? പഴമക്കാർ പറയുന്നു ആഴ്ചകളിലെ ചില ദിവസങ്ങളിൽ മുടി വെട്ടാൻ കൊള്ളില്ലാന്ന്. എന്താണ് അതിന്റെ വസ്തുത', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-11-06 18:53:09', '2023-11-11 14:35:51') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0616', 1, NULL, 5, NULL, NULL, 'സ്ത്രീകളെ ഉപയോഗിച്ചുള്ള സോഷ്യൽ മീഡിയ പരസ്യപ്രചാരണം', 'കമ്പനി rewiew ക്ക് വേണ്ടി വിമൻസ്നെ  ഉപയോഗിച്ച് വീഡിയോ എടുത്ത് കമ്പനി സൈറ്റ്  പോലുള്ള സോഷ്യൽമീഡിയ പ്ലാറ്റഫോമുകളിൽ പോസ്റ്റ്‌ ചെയ്യുന്നതിന്റെ ഇസ്ലാമിക്‌ വശം എന്താണ്? ഇനി കമ്പനിയുമായി ബന്ധപ്പെട്ട സൈറ്റ് പോലുള്ളതിൽ ഷെയർ ചെയ്യാതെ, review ചെയ്യുന്ന വിമൻസ്ന്റെ  personal അക്കൗണ്ടിലാണ് ഷെയർ ചെയ്യുന്നത്, അങ്ങനെ ഉള്ള advertisements അനുവദനീയം ആണോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2023-11-24 05:09:47', '2023-11-24 05:37:27') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0564', 1, NULL, 5, NULL, NULL, 'Is the use of sex toys allowed?', 'I am 18 year old female. I want to get married, but my parents have decided to marry me only after I get a job. Is it okay to use any toys to satisfy my physical urges in this case?', 'English', 'assigned', NULL, 3, 0, 5, NULL, NULL, '2022-11-13 21:11:35', '2022-11-13 21:11:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0355', 1, NULL, 1, NULL, NULL, 'Fatwa about Inheritance law of the wife, indeath of Husbandwith three brothers and three sisters.', 'With Due Respect I xxxxxx W/o Late xxxx xxxx xxxx from xxxxx. i would like to introduce myself first that i got married with xxxx xxxx xxxx 3 years before and due to Covid he passed away 3.5 months before, I don&#39;t have any children. And Right now i do have some questions As I want to know the how things will get distributed between all stakeholders according to Sharia My Husband Passed away 3 months before and he do have 3 brothers and 3 sisters. i would like to tell all sister are married and settled. My husbands elder brother is doing job internationally and else are settled locally. My Husband do have Britannia Agency in Amroha from last 25 years and this is the only source of income. I do have some questions and wants answers accordingly. <ol> According to Islamic Law how the inputs used in business like transportation vehicle, crates etc.,property will get distributed according to Islamic Law? He do have Credit around 12 lakh After my husband passed away his elder brother looking after his business and I don&#39;t have any other source of income, his brother didn&#39;t gave me a single rupee after my husband passed away.As my husband was the sole owner of this company and according to company rules wife will get the distribution rights as it&#39;s not permitted to transfer distribution ship My husbands brother wants to run this business themselves. So please provide us the best possible answer under islamic law as I don&#39;t want to commit any sin of haq talfi as all of us has to face Almighty Allah on the day of judgement </ol>', 'English', 'published', '<p>1. The inherited property should be distributed to the all heirs on the basis of the value of all property included vehicles and companies goodwill. As mentioned in the question, hence he didn&#39;t have children, wife will get 25% of the total property that his husband had.&nbsp;</p> <p>2. The property will be distributed among the heirs after completing his debit of Rs. 12lakhs.&nbsp;</p> <p>3.&nbsp;As mentioned earlier, the brother have to give the value of one-fourth of the share to her soon as he can. Otherwise they run the company together with a wife&#39;s one-fourth share.&nbsp;</p> <p>4. Anyone of the heirs can run the company on his own with mutual understanding and after paying the share value of inherited property to other heirs. Or they all can run the company together. It is absolutely haraam to earn undeservedly without giving anything to others heirs.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-09-03 09:48:20', '2024-08-25 04:46:57') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0498', 1, NULL, 2, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', '<div style=\"background:#eeeeee;border:1px solid #cccccc;padding:5px 10px;\">ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) പോലുള്ള app വഴി ഷെയർ വാങ്ങാൻ പറ്റുമോ അത് ഹലാൽ ആണോ</div>', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 02:04:32', '2023-11-11 15:57:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0500', 1, NULL, 5, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', 'ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) എന്ന app വഴി stock വാങ്ങൽ അനുവദിനീയമാണോ (zomato) ടെ ഷെയർ ആണ് എടുത്തത് അത് അനുവദിനീയമാണോ', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 08:05:53', '2023-11-11 15:58:27') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0570', 1, NULL, 1, NULL, NULL, 'ശാരീരിക ബന്ധത്തിലേർപ്പെടുന്ന രൂപം ഭാര്യയുടെ ഇഷ്ടത്തിന് അനുസരിച്ചാകണമെന്നുണ്ടോ ?', 'ഭാര്യയുമായി ശാരീരിക ബന്ധത്തിൽ ഏർപ്പെടുന്ന സന്ദർഭത്തിൽ ഭർത്താവിന് താൽപര്യമുള്ളതും ഭാര്യക്ക് താൽപര്യമില്ലാത്തതുമായ ഒരു പൊസിഷൻ സ്വീകരിക്കുന്നത്  കുഴപ്പമുണ്ടോ ? പലരൂപങ്ങൾ സ്വീകരിക്കുന്നത് ശരീഅത്ത് അനുവദിച്ച കാര്യമാണെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു', 'Malayalam', 'published', '<p>ശാരീരിക ബന്ധത്തിൽ ശറഇൽ നിരോധന വന്നിട്ടില്ലാത്ത ഏതൊരു പൊസിഷനും ഭർത്താവിന് സ്വീകരിക്കാവുന്നതാണ്. ഇനി അത് ഭാര്യക്ക് ബുദ്ധിമുട്ടുണ്ടാക്കുന്നതാണെങ്കിൽ ഭർത്താവിന് അത് ബോധ്യമാവുകയും ചെയ്താൽ നിർബന്ധിക്കരുത്. യാതൊരു ബുദ്ധിമുട്ടും ഇല്ലാത്തതിനോട് കൂടിയാണ് വിസമ്മതിക്കുന്നതെങ്കിൽ ഭാര്യയെ കാര്യങ്ങൾ പറഞ്ഞു മനസ്സിലാക്കികൊടുക്കണം. യാതൊരു കാരണവുമില്ലാതെ ഭർത്താവിൻ്റെ താൽപര്യങ്ങൾക്ക് എതിര് നിൽക്കൽ ഭാര്യക്ക് അനുവദനീയമല്ല.</p>', 2, 0, 5, '2023-04-15 20:03:23', 1, '2022-12-18 08:49:23', '2023-04-15 20:04:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0344', 1, NULL, 2, NULL, NULL, 'മുസാഫിറിന്സുന്നത്ത് നമസ്കാരം ഉണ്ടോ ?', 'യാത്രക്കാരൻ (മുസാഫിർ) സുന്നത്ത് നമസ്കാരം നിർവഹിക്കേണ്ടത് ഉണ്ടോ ?', 'Malayalam', 'published', '<p>യാത്രക്കാരന് (മുസാഫിറിന്) സുന്നത്ത്. നമസ്&zwnj;കാരം ഉണ്ട്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:24:08', '2021-08-12 02:24:08') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0374', 1, NULL, 1, NULL, NULL, 'Is salath ul ishraq and luha same?', 'Is salath ul ishraq and salatul ul luha same or different ? Please with evidence.', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-10-21 10:30:20', '2024-01-06 05:41:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0170', 1, NULL, 5, NULL, NULL, 'പലിശയെ സംബന്ധിച്ച് ഉള്ള സംശയം?', '1.ഗൂഗിൾ പേ പോലുള്ളവയിൽ നിന്ന് പണം അയക്കുമ്പോൾ ലഭിക്കുന്ന റിവാർഡുകൾ അനുവദനീയമാണോ? 2.ബങ്കിൽ നിന്ന് ലഭിക്കുന്ന പലിശ ആർക്കൊക്കെ കൊടുക്കാം? പുണ്യം പ്രതീക്ഷിക്കാതെ അത് പ്രായമായവർക്ക്ൽ നകാമോ?', 'Malayalam', 'published', '<p><a href=\"https://fatwa.kauzariyya.com/single.php?question=163\">https://fatwa.kauzariyya.com/single.php?question=163</a></p>', 8, 0, 5, '1970-01-01 01:00:00', 1, '2020-06-21 22:27:20', '2024-08-01 16:30:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0505', 1, NULL, 2, NULL, NULL, 'Can I eat meat slaughtered by non muslim if we are travelling to a non muslim countries like europe?', 'If we are leaving in a non muslim country like europe it is very difficult for us to search for halal food but usually every where can find KFC, McDonald&#39;s etc but Meat available there might be either slaughtered by machine or non muslim is it permissible for me to eat that. Countries in Europe are mostly very cold so it is very difficult with out non veg also veg foods are bit costly or chance of availability is very low ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-02-03 00:31:40', '2023-11-11 14:49:55') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0296', 1, NULL, 1, NULL, NULL, 'جائیداد کی تقسیم شریعت کی روشنی میں', 'السلام علیکم جناب میرا سوال یہ ہے کی اگر کوئی انسان اپنی جیتے جی اپنی ملکیت کی اپنے پچوں میں تقسیم کرنا چاہئے تو وہ کس طرح کرے گا ۔اور اس میں ایک مسئلہ یہ بھی ہے کی کچھ وقت پہلے ایک بچے نے گھر میں اپنے حصے کو مانگنے کی خواہش رکھی اور گھر میں بدامنی پھیلائی جس کی وجہ سے والدین کی زندگی اثر اندوز ہوئی اور والدین کے پاس کوئی جمع پونجی نہیں تھی جو و انکو دیتے ۔لہذا اُنکے بڑے بچے نے اس مشکل کو دیکھتے ہوئے اس بات کو اپنے بھائی سے کہا کی آپ کا حصے میں خرید لیتا ہوں اسے آپ کی مشکل دور ہوگی اور کو اپنے حصے کو پڑے بھائی کو بیچ دیتے ہے اور آج صورتِ حال یہ ہے کی اب حصہ تقسیم کرنا ہے اور اب مسئلہ یہ ہے کہ بھہنوں نے اپنا حصے کا پیسہ بھائی کو دیدیا ہے اور اب وہ بہن کی حصے کے پیسے مانگ رہے ہیں ۔کیا انہیں پیسے دینے چاہئے ۔۔ برائے مہربانی کی مسئلہ کا حل شریت کی روشنی میں برائے اللہ آپ کو جزائے خیرعطا فرمائیں امین۔', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2021-03-15 02:44:40', '2021-03-15 02:44:40') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0328', 1, NULL, 1, NULL, NULL, 'Salah', 'When a woman starts menstruating at the time of one of the salahs, should she perform it after her period ends.will it count as qaza?', 'English', 'published', '<p>When a woman starts menstruating at the time of one of the salahs she does not have to perform it after her period ends.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-07-01 12:24:50', '2021-07-01 12:24:50') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0341', 1, NULL, 2, NULL, NULL, 'നാട്ടിലൂടെ കടന്നു പോകുന്നത് കൊണ്ട് ജമ്മും കസറും നഷ്ടമാകുമോ ?', 'യാത്രക്കിടയിൽ തൻ്റെ നാട്ടിലൂടെ കടന്നു പോകുന്നത് കൊണ്ട് ജമ്മും കസറും നഷ്ടമാകുമോ ?', 'Malayalam', 'published', '<p>യാത്രക്കിടയിൽ സ്വന്തം നാട്ടിലൂടെ കടന്നുപോയാൽ ആ യാത്ര മുറിഞ്ഞതായി കണക്കാക്കുന്നതാണ്.&nbsp;</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-08-12 02:21:33', '2021-08-12 02:21:33') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0391', 1, NULL, 1, NULL, NULL, 'ഇതര മതങ്ങളുടെ ആഘോഷങ്ങളുടെ ഭാഗമായി ശമ്പളത്തിന് പുറമെ നൽകപ്പെടുന്ന ബോണസ് തുക സ്വീകരിക്കൽ ഹലാൽ ആന്നോ?', 'ഒരു മുതലാളി (ഗവൺമെൻ്റോ / വ്യക്തിയോ) തൻ്റെ കീഴിൽ ജോലി ചെയ്യുന്ന ആളുകൾക്ക് വേറെ മതത്തിൻ്റെ ആഘോഷങ്ങളുടെ ഭാഗമായി (ഓണം / ക്രിസ്തുമസ് / ദസറ) ബോണസ് ആയി കൂടുതൽ തുക നൽകിയാൽ അധികം നൽകുന്ന തുക ഹലാൽ ആന്നോ?', 'Malayalam', 'published', '<p>ഈ രീതിയിൽ നൽകപ്പെടുന്ന ബോണസ് വാങ്ങൽ അനുവദനീയമാണ്.</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-28 22:41:54', '2021-10-28 22:41:54') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0447', 1, NULL, 5, NULL, NULL, 'Eyebrows threade ചെയ്യുന്നവരുടെ ഇസ്ലാമിക വിധി എന്താണ്?', 'Eyebrows threade ചെയ്യുന്നവരുടെ ഇസ്ലാമിക വിധി എന്താണ്?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2021-11-07 11:56:10', '2023-11-02 16:18:18') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0462', 1, NULL, 1, NULL, NULL, 'സ്വന്തം വീടും വാഹനവും ഉപജീവനമാർഗ്ഗവുമുള്ള വ്യക്തി സകാത്ത് ഫണ്ടിൽ നിന്നും പണം സ്വീകരിച്ചാൽ ആ സകാത്ത് നൽകിയവരുടെ ബാധ്യത വീടുമോ?', 'അസ്സലാമു അലൈക്കും വ റഹ്മത്തുള്ള ... ഞങ്ങളുടെ മഹല്ലിൽ പ്രവർത്തിക്കുന്ന സക്കാത്ത് കമ്മിറ്റിയെ സകാത്ത് വിഹിതം ഏൽപ്പിച്ച വ്യക്തിയാണ് ഞാൻ. താരതമ്യേന കടുത്ത ദുരിതമനുഭവിക്കുന്ന അർഹതപ്പെട്ട പലരും മഹല്ലിൽ ഉണ്ടായിരിക്കെ സകാത് കമ്മിറ്റിയിൽ അംഗമായ സ്വന്തം വീടും വാഹനവും ഉപജീവനമാർഗ്ഗവുമുള്ള വ്യക്തി പുതിയ സമ്പാദ്യ മാർഗം തുടങ്ങാൻ എന്ന പേരിൽ ഒരു ലക്ഷം രൂപ സകാത്ത് ഫണ്ടിൽനിന്നും സ്വീകരിച്ചതായി അറിയുന്നു. ഇത്തരം വ്യക്തികൾ സക്കാത്തിനായി അപേക്ഷിക്കുന്നതും അവർക്ക് സക്കാത്ത് അനുവദിക്കുന്നതും കമ്മറ്റിക്ക് അനുവദനീയമാണോ? കമ്മിറ്റി അംഗങ്ങളുടെ ഐക്യകണ്ഠത ഇത്തരം വീഴ്ചകളെ സാധൂകരിക്കുന്ന ഘടകമാണോ? 1, ഈ കമ്മറ്റിയെ സകാത് വിഹിതം ഏൽപിച്ച സകാത് ദായകരുടെ സകാത് നിറവേറിയോ?<br /> 2, ഇല്ലങ്കിൽ അവർ എന്ത് ചെയ്യണം?', 'Malayalam', 'published', '<p>അടിസ്ഥാന ആവശ്യങ്ങൾക്ക് പുറമേ ഉപജീവനമാർഗ്ഗം ഉള്ള വ്യക്തിക്ക് സകാത്ത് നൽകൽ അനുവദനീയമല്ല. ശറഅ് അനുവദിക്കാത്ത കാര്യം കമ്മിറ്റി അംഗങ്ങൾ ഏകോപിച്ചു എന്നതിന്റെ പേരിൽ അനുവദനീയം ആകുന്നതല്ല.</p> <p>അനർഹർക്കാണ് നൽകിയതെങ്കിൽ ഇതും &nbsp;ഇതുപോലെ അനർഹരായ ആളുകൾക്ക് &nbsp;നൽകിയ മറ്റ് തുകകളും സകാത്താവുകയില്ല.ആയതിനാൽ ആ വർഷം &nbsp;സകാത്ത് ഇനത്തിൽ ലഭിച്ച മുഴുവൻ തുകയുടെ &nbsp;എത്ര ശതമാനം ആണ് &nbsp;അനർഹരിലേക്ക് &nbsp;എത്തിയതെന്ന് കണക്കാക്കുകയും &nbsp;ഓരോരുത്തരും അവർ നൽകിയ &nbsp;സകാത്ത് തുകയിൽ നിന്ന് &nbsp;ആ ശതമാന പ്രകാരമുള്ള തുക വീണ്ടും &nbsp;സക്കാത്തിന്റെ അർഹരിലേക്ക് &nbsp;കൊടുത്താൽ മാത്രമേ അവരുടെ സകാത്ത് &nbsp;വീടുകയുള്ളൂ. ഇവർക്ക് &nbsp;ആ തുക സകാത്ത് കമ്മിറ്റിയിൽ നിന്ന് തിരിച്ചു വാങ്ങാവുന്നതാണ്.</p>', 2, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-29 04:24:50', '2024-04-01 02:34:01') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0558', 1, NULL, 1, NULL, NULL, 'ഹനഫി മദ്ഹബ്കാരന്റെ ളുഹർ ഏത് സമയം വരെ നമസ്കരിക്കാം ?', 'എൻറെ മാതാവ് ഷാഫി മദ്ഹബ് കാരി ആയ കാരണത്തിന്റെ പേരിൽ ഏതെങ്കിലും കാരണത്തിന്റെ പേരിൽ എന്റെ ളുഹർ താമസിച്ചു പോയാൽ ഷാഫി മദ്ഹബ് പ്രകാരം ഉള്ള അസർ സമയം എത്തിയാൽ എൻറെ ളുഹർ ഖളാ ആയി എന്നാണ് ഉമ്മ പറയുന്നത്. ഇത് ശരിയാണോ ? എപ്പോഴാണ് ഒരു ഹനഫി മദ്ഹബ് കാരൻറെ ളുഹർ നമസ്കാരം ഖളാ ആകുന്ന സമയം ?', 'Malayalam', 'approved', 'A', 7, 0, 5, NULL, NULL, '2022-10-17 02:26:58', '2022-10-17 02:26:58') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0593', 1, NULL, 1, NULL, NULL, 'വരിയുടച്ച മൃഗം, പ്രസവിക്കാത്ത മൃഗം ഇവയെ അറുക്കൽ അനുവദനീയമാണോ?', 'വരിയുടച്ച (ലൈംഗിക ശേഷി നശിപ്പിക്കപ്പെട്ട) മൃഗം, പ്രസവിക്കാത്ത മൃഗം ഇവയെ അറുക്കൽ അനുവദനീയമാണോ?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-06-19 07:39:37', '2023-06-19 07:41:57') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0385', 1, NULL, 1, NULL, NULL, 'ജുബ്ബ സുന്നത്ത് ആണോ?', 'ജുബ്ബയും തൊപ്പിയും ഖമീസ്സും ധരിക്കുന്നത് സുന്നത്ത് ആണോ?', 'Malayalam', 'published', '<p>നബി ( സ ) യുടെ വസ്ത്രം മുട്ടിനു താഴെ വരെയുള്ള ഒരു നീള കുപ്പായമാണ്. നമ്മുടെ നാട്ടിലുള്ള ജുബ്ബയും ഖമീസും നബി ( സ ) യുടെ വസ്ത്രത്തിനോട്&zwnj; സാദൃശ്യം ഉള്ളതിനാൽ സുന്നതിന്റെ നിയ്യത്തിൽ ധരിക്കാവുന്നതാണ്. തൊപ്പി ധരിക്കലും സുന്നത്ത് ആണ്.</p>', 11, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-23 10:36:29', '2024-09-21 06:07:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0605', 1, NULL, 5, NULL, NULL, 'കഴുത്തിൽ studs  ധരിക്കൽ', 'മൂക്ക്, കഴുത്ത് പൊക്കിൾ ഈ സ്ഥലങ്ങളിൽ സ്ത്രീകൾ മൂക്ക്കുത്തി പോലെ ദ്വാരം ഉണ്ടാക്കി ആഭരണം അണിയൽ
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0607', 1, NULL, 1, NULL, NULL, 'ഭർത്താവ് 4 വർഷം മിസിങ്, എനിക്ക് വാഹം പാടുണ്ടോ ?', 'എൻ്റെ ഭർത്താവ് നാലുവർഷമായി മിസിങ് ആണ്. അദ്ദേഹം എവിടെയാണെന്നോ ജീവിച്ചിരിപ്പുണ്ടോ എന്നോ അറിയാൻ കഴിയുന്നില്ല. 
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0586', 1, NULL, 1, NULL, NULL, 'Use of online payments from bank Apps or third party payments Apps', 'Now days, I am using online Apps for payments such as Phone Pay, Google Pay and bank associated Apps etc. They returned some token amount or coupons as a gift for using these Apps, like 20% cash back when we order food from Swiggy or Zomato Apps. Or 50% discount when we purchase clothes from Blackberry Stores. Is the use of these Apps like Google Pay, Phone Pay and bank associated payments Apps are halal? If halal, so can we use the rewards of these Apps in the light of Quran and Hadith?', 'English', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2023-04-06 09:57:44', '2023-04-06 10:04:35') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0291', 1, NULL, 1, NULL, NULL, 'വഖ്ഫ് സ്വത്തിൽ നിന്നുള്ള വരുമാനത്തിന് സക്കാത്ത് നൽകണോ?', 'വഖ്ഫ് സ്വത്തിൽ നിന്നുള്ള വരുമാനത്തിന് സക്കാത്ത് നൽകണോ?', 'Malayalam', 'published', '<p>വഖ്ഫ് ചെയ്ത ഭൂമിയിൽ നിന്നുള്ള കാർഷിക വരുമാനത്തിന് സക്കാത്ത് (عشر)കൊടുക്കൽ നിർബന്ധമാണ്.കാരണം കാർഷിക വിളകൾക്ക് സക്കാത്ത് കൊടുക്കണമെന്നറിയിക്കുന്ന ഖുർആൻ ആയത്തും ഹദീസും വഖഫ് സൊത്തിലെ വിളകളെയും ഉൾക്കൊള്ളിക്കുന്നു.&nbsp;<br /> NB:വഖ്ഫ് സ്വത്തിലെ കാർഷികേതര വരുമാനങ്ങളിൽ സക്കാത്ത് ഇല്ല.&nbsp;&nbsp; &nbsp;&nbsp;</p>', 1, 0, 5, '1970-01-01 01:00:00', 1, '2021-03-03 09:19:58', '2024-11-04 10:43:30') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0303', 1, NULL, 5, NULL, NULL, 'What is the law if you have to join an interest-bearing transaction for the survival of the company?', 'My father has a halal business but involves riba,that is he has a loan where he pays interest.He now ask me to help him in his business.If I help him ,I will have to pay interest ,also will have to witness many transactions of interest. How can I be dutiful to the parent in this situation?How should I help him in his business?Also ,the loan amount is so high that it\'s repayment is not possible inorder to make it halal and the only way to avoid the bank attachment is by paying the interest for lifetime. Secondly After his period ,in future, as a son I will be liable to pay the interest and loan to avoid bank attachment. Also I have warned him about riba and have not helped him in taking any kind of loan. ..Pls help.....', 'English', 'published', '<p>It is completely wrong that your father took loan from Bank. but the amount your father took as loan or the business which he had done with that money is not haram because that is not interest.</p> <p>On the other hand, if anyone take money as a loan and payback this money with interest his activity will be haram and his money will be halal and if anyone give to someone money as credit and take interest so his activity and interest amount also will be haram.</p> <p>even though in this situation where you have to complete the debt with interest you may help your father and be a part in his business...</p>', 3, 0, 5, '1970-01-01 01:00:00', 1, '2021-04-04 05:44:05', '2024-06-08 05:39:44') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0480', 1, NULL, 2, NULL, NULL, 'നെറ്റ് വർക്ക് ബിസിനസ് കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആയി വർക്ക് ചെയ്യാൻ പറ്റുമോ', 'പ്രൊഡക്ട് ബേസ് ചെയ്തു ( ആളെ ചേർക്കൽ നിർബന്ധമില്ല ) നെറ്റ്വർക്ക് ബിസിനസ്സിലൂടെ കച്ചവടം ചെയ്യുന്ന കമ്പനിയായ indusviva യിൽ ഡിസ്ട്രിബ്യൂട്ടർ ആവാൻ പറ്റുമോ? താഴെ തട്ടിൽ കച്ചവടം നടക്കുമ്പോൾ കമ്പനിയുടെ പ്രതിഫലം മേലെ തട്ടിലുള്ളവർക്ക് കൈ പറ്റൽ അനുവദനീയമാകുമോ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2022-01-02 01:07:35', '2023-11-11 14:48:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0387', 1, NULL, 1, NULL, NULL, 'ഇദ്ദയിൽ ഉള്ള സ്ത്രീ സ്വർണ്ണം ധരിക്കാൻ അനുവാദം ഉണ്ടോ ?', 'ഭർത്താവ് മരണപ്പെട്ട സ്ത്രീ ഇദ്ദയുടെ സമയത്ത് അലങ്കാരത്തിനുള്ള സ്വർണ്ണം ധരിക്കാൻ പാടുണ്ടോ, കമ്മൽ പോലെ ഊരിയാൽ പിന്നീട് ബുദ്ധിമുട്ട് ആകുന്നത് എന്താണ് ചെയ്യേണ്ടത്.', 'Malayalam', 'published', '<p>ഭർത്താവ് മരണപ്പെട്ട സ്ത്രീ ഇദ്ദ ഇരിക്കുന്ന സമയത്ത് അലങ്കാരത്തിനുള്ള സ്വർണ്ണം ധരിക്കാൻ പാടില്ല. കമ്മൽ പോലെ ഊരിയാൽ പിന്നീട് ബുദ്ധിമുട്ട് ഉണ്ടാകാൻ സാധ്യത ഉള്ള സ്ഥലങ്ങളിൽ അത് ഊരിയ ശേഷം അതിൻ്റെ ദ്വാരം അടയാതിരിക്കാൻ ആ ദ്വാരത്തിൽ മറ്റെന്തെങ്കിലും വെക്കാവുന്നതാണ്.</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-10-23 13:06:13', '2021-10-23 13:06:13') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0433', 1, NULL, 1, NULL, NULL, 'പള്ളിയുടെ മുകളിൽ (ടറസിന്റെ) മുകളിൽ അലക്കുന്ന സ്ഥലം, കാന്റീൻ, കളിസ്ഥലം (ടറഫ് പോലെ) ഉപയോഗിക്കുന്നതിന്റെ വിധി എന്ത്', 'പള്ളിയുടെ മുകളിൽ (ടറസിന്റെ) മുകളിൽ അലക്കുന്ന സ്ഥലം, കാന്റീൻ, കളിസ്ഥലം (ടറഫ് പോലെ) ഉപയോഗിക്കുന്നതിന്റെ വിധി എന്ത്? ചില സ്ഥലങ്ങളിൽ താഴെ നിലയിൽ വാടകക്ക് ശട്ടറും, മുകളിലെ നില പള്ളിയും ആക്കി ഉപയോഗിക്കുന്നു. ഇതിൻ്റെ നിയമം എന്താണ്?', 'Malayalam', 'published', '<p>പള്ളിയുടെ മുകളിലത്തെ നിലയിൽ പൊതുവായ അലക്കുന്ന സ്ഥലം ക്യാന്റീൻ turf പോലുള്ളവയ്ക്ക് വേണ്ടി ഉപയോഗിക്കാൻ അനുവാദമില്ല.<br /> ആദ്യമേ പള്ളി പണിയുമ്പോൾ തന്നെ താഴത്തെ നിലയിൽ വാടകയ്ക്ക് ഷട്ടറും മുകളിലെ നില പള്ളിയും ആക്കി പണിയാവുന്നതാണ്.എന്നാൽ ഒരു പള്ളി പൊളിച്ചു പുതുക്കിപ്പണിയുമ്പോൾ താഴെ കടമുറിയായി പണിയുവാൻ അനുവാദമില്ല</p>', 0, 0, 5, '1970-01-01 01:00:00', 1, '2021-11-04 03:03:05', '2021-11-04 03:03:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0503', 1, NULL, 5, NULL, NULL, 'ഷെയർ മാർകറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ', 'ഷെയർ മാർക്കറ്റിൽ പൈസ നിക്ഷേപിക്കാമോ (upstox) എന്ന app വഴി stock വാങ്ങൽ അനുവദിനീയമാണോ (zomato) ടെ ഷെയർ ആണ് എടുത്തത് അത് അനുവദിനീയമാണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2022-01-23 08:06:39', '2024-01-06 05:37:40') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
