INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0648', 1, NULL, 5, NULL, NULL, 'ബോച്ചേ ടീ', 'ബോച്ചേ ടീ സുലഭമായി കൊണ്ടിരിക്കുന്നു. അതിൽ നിന്നും തിരഞ്ഞെടുപ്പിലൂടെയുള്ള ആളുകൾക്ക് ഭീമമായ സംഖ്യ നൽകാറുമുണ്ടല്ലോ? എന്താണ് ഇതിൻ്റെ വിധി', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2024-07-21 02:53:35', '2024-07-31 08:02:46') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0657', 1, NULL, 5, NULL, NULL, 'Boche tea', 'Boche tea വാങ്ങുന്നത് ഹലാൽ ആണോ.അതിലൂടെ ലഭിക്കുന്ന കൂപ്പൺ മുകേന ലഭിക്കുന്ന സമ്മാന തുക ഉപയോഗിക്കൽ അനുവദനീയം ആണോ', 'Malayalam', 'pending', NULL, 2, 0, 5, NULL, NULL, '2024-10-07 15:06:26', '2025-02-17 10:36:00') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0636', 1, NULL, 5, NULL, NULL, 'ക്യാപ്സൂളുകളിൽ മൃഗ കൊഴുപ്പ് അടങ്ങിയിരിക്കുന്നതുമായി ബന്ധപ്പെട്ട', 'ക്യാപ്സൂൾ ഗുളികകളുടെ പുറംചട്ടകൾ നിർമ്മിച്ചിരിക്കുന്നത് ജലാറ്റിൻ പോലെയുള്ള ആനിമൽ ഫാറ്റുകളിൽ നിന്നാണ് എന്ന് വ്യക്തമാണ് അപ്പോൾ ക്യാപ്സൂളുകൾ കഴിക്കുന്നത് അനുവദനീയമാണോ', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2024-02-28 04:38:23', '2024-03-20 17:52:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0638', 1, NULL, 2, NULL, NULL, 'ഖളാആയതും/മുഅക്കദയും പരിഗണന', 'നമസ്ക്കാരം ഖളാ വീടാൻ ഉള്ള ആൾക്ക് ഖളാ നമസ്ക്കാരങ്ങൾ മാത്രമാണോ കടമ ആയിട്ടുള്ളത് അതോ സുന്നത്ത് ്് ്്മുഅക്കദയുംനമസ്ക്കരിക്കണമോ\'.... ഏതിനാണ് പരിഗണന       കൊടുക്കേ ണ്ടത്', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2024-04-14 13:55:34', '2024-04-14 14:59:25') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
