INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0653', 1, NULL, 5, NULL, NULL, 'കുട്ടികളുടെ ഹജ്ജും ഉംറയും', 'കൊച്ചു കുട്ടികളെ ഹജ്ജിനും ഉംറക്കും കൊണ്ട് പോകാമോ? ഹജ്ജ് സ്വീകരിക്കുമോ?', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2024-08-17 09:34:22', '2024-08-22 05:39:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
