INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0624', 1, NULL, 1, NULL, NULL, 'മുലപ്പാൽ കുടിക്കൽ', 'ഭാര്യയുടെ മുലപ്പാൽ കുടിക്കൽ അനുവദിനീയം ആണോ? അറിയാതെ ഉള്ളിൽ പോയാൽ വിധി എന്താണ്?', 'Malayalam', 'assigned', NULL, 0, 0, 5, NULL, NULL, '2024-01-04 06:13:33', '2024-05-07 08:51:46') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0627', 1, NULL, 2, NULL, NULL, 'ഉംറക്ക് പോകാൻ ഉദ്ദേശിക്കുന്ന വ്യക്തിക്ക് സക്കാത്തിന്റെ പണം നൽകാമോ?', 'ഉംറക്ക് പോകാൻ ഉദ്ദേശിക്കുന്ന വ്യക്തിക്ക് യാത്രക്കാരൻ എന്ന പരിഗണനയിൽ സക്കാത്തിന്റെ പണം നൽകാമോ?', 'Malayalam', 'published', '<p>(إعانة الطالبين</p><p>ഉംറക്ക് പോകുന്ന വ്യക്തി ആവശ്യക്കാരൻ ആണെങ്കിൽ യാത്രക്കാരൻ എന്ന് പരിഗണിച്ച്‌ സക്കാത്തിന്റെ പണം നൽകാവുന്നതാണ്.<br>والله أعلم بالصواب<br></p>', 15, 0, 5, '2024-01-30 06:50:51', 1, '2024-01-05 14:23:21', '2024-09-13 15:47:28') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0632', 1, NULL, 5, NULL, NULL, 'Indus viva എന്ന കമ്പനിയുടെ icoffee, ipulse എന്നീ പ്രോഡക്ടുകൾ', 'Indus viva( MLM company )എന്ന കമ്പനിയുടെ icoffee, ipulse എന്നീ പ്രോഡക്ടുകൾ വാങ്ങി ഉപയോഗിക്കാമോ
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0631', 1, NULL, 1, NULL, NULL, 'രണ്ടാം വിവാഹം എനിക്ക് നല്ലതാണോ?ല്ലതാണോ', 'എൻ്റെ വിവാഹം കഴിഞ്ഞിട്ട് 5 വർഷം കഴിഞ്ഞു. വിവാഹ സമയത്ത് ഞാൻ എൻ്റെ സൗന്ദര്യ സങ്കൽപങ്ങളിൽ വലിയ ഒരു വിട്ട് വീഴചക്ക് തയ്യാറായി. കാരണം എൻ്റെ ഭാര്യ ദീനി നിഷ്ടയിൽ ഒരു മാതൃകയാണ്, അന്നും ഇന്നും
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0641', 1, NULL, 1, NULL, NULL, 'കറാഹത്തിന്റെ സമയത്തുള്ള തിലാവത്തിൻ്റെ സുജൂദ്', 'സുബഹിക്ക് ശേഷവും അസറിന് ശേഷവും തിലാവത്തിന്റെ സുജൂദ് ചെയ്യൽ അനുവദനീയമാണോ?', 'Malayalam', 'published', '<p>സുബഹിക്ക് ശേഷവും അസറിനു ശേഷവും തിലാവത്തിന്റെ സുജൂദ് ചെയ്യൽ നിരുപാധികം അനുവദനീയമാണ്, എന്നാൽ സൂര്യൻ കൃത്യം ഉദിക്കുന്ന സമയത്തും, കൃത്യം മദ്ധ്യാനത്തിൽ നിൽക്കുന്ന സമയത്തും, കൃത്യം അസ്തമിക്കുന്ന സമയത്തും, മുമ്പ് നിർബന്ധമായ തിലാവത്തിന്റെ സുജൂദ് ചെയ്യൽ അനുവദനീയമല്ല, </p><p>എന്നാൽ ഓതിക്കൊണ്ടിരിക്കെ തിലാവത്തിന്റെ സുജൂദ് ഈ സമയവുമായി യോജിച്ചു വന്നാൽ അപ്പോൾ ചെയ്യൽ അനുവദനീയമാണ് എങ്കിലും ശ്രേഷ്ടമായത് ആ സമയം കഴിഞ്ഞ് നിർവഹിക്കലാണ്.</p>', 49, 0, 5, '2024-05-05 09:33:08', 1, '2024-05-05 09:23:02', '2024-10-24 12:17:05') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0623', 1, NULL, 5, NULL, NULL, 'കൈകാലുകളിലെ രോമം വെട്ടാൻ പറ്റുമോ', 'കൈകളിലേയും കാലുകളിലെയും രോമം പുരുഷന്മാർക്ക് വെട്ടി ഒതുക്കാൻ പറ്റുമോ (അമിതമായി വളർന്നു കിടക്കുന്ന സന്ദർഭത്തിൽ..)', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2024-01-03 10:31:26', '2024-01-06 05:52:06') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0640', 1, NULL, 2, NULL, NULL, 'നമസ്ക്കാരം ഖളാ വീടേണ്ട കാലയളവ് എങ്ങനെ നിശ്ചയിക്കും', 'പ്രായപൂർത്തി ആയതിൻ്റെ നിബന്ധന എന്താണ്. ഉദാഹരണത്തിന് ഒരാൾ 23 ാം വയസ്സിൽ ആണ് നമസ്ക്കരിക്കാൻ ആരംഭിച്ചത് . പ്രായപൂർത്തി ആയതിനെ പറ്റി വലിയ നിശ്ചയം(Idea) ഇല്ല. എനി എത്ര വർഷത്തെ നമസ്ക്കാരമാണ് ഖളാ വീടേണ്ടത് എന്ന് ക്ലിപത്തപ്പെടുത്തുക', 'Malayalam', 'pending', NULL, 0, 0, 5, NULL, NULL, '2024-04-15 02:36:59', '2024-05-07 08:39:30') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0642', 1, NULL, 1, NULL, NULL, 'തിലാവത്തിന്റെ സുജൂദ് ചെയ്യുന്നതിനെ സംബന്ധിച്ച് ഒരു സംശയം', 'സുബഹിക്ക് ശേഷവും അസറിന് ശേഷവും തിലാവത്തിന്റെ സുജൂദ് ചെയ്യൽ അനുവദനീയമാണോ ?', 'Malayalam', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2024-05-05 13:42:56', '2024-05-07 08:38:10') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0643', 1, NULL, 2, NULL, NULL, 'how can i marriage ?', 'how can i marriage ?', 'English', 'rejected', NULL, 0, 0, 5, NULL, NULL, '2024-05-15 11:11:33', '2024-08-20 03:13:49') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0628', 1, NULL, 5, NULL, NULL, 'ക്രെഡിറ്റ് കാർഡ് മുഖേന പൈസ അടയ്ക്കുമ്പോൾ ബാങ്ക് ഫീസ് കസ്റ്റമറിൽ നിന്ന് ഈടാക്കുന്നതിന്റെ വിധി എന്താണ്?', 'ഒരാൾ കടയിൽ നിന്നും ഒരു ലക്ഷം രൂപയുടെ സാധനം പർച്ചേസ് ചെയ്തു, ഒരു ലക്ഷം രൂപയുടെ ബില്ല് വന്നു, ക്രെഡിറ്റ് കാർഡ് മുഖേനയാണ് പൈസ അടയ്ക്കുന്നത് എങ്കിൽ ആയിരം രൂപ അധികം തരണം, കാരണം ഞങ്ങളിൽ നിന്നും ബാങ്ക് ഒന്നര ശതമാനം ഫീസ് ഈടാക്കാറുണ്ട് എന്ന് കടക്കാരൻ പറയുന്നു. ഈ രീതിയിൽ 1,01,000 രൂപ ക്രെഡിറ്റ് കാർഡിലൂടെ അടക്കുന്നതിന്റെ വിധി എന്താണ്?', 'Malayalam', 'published', '<p>.1,00,000 രൂപയുടെ സാധനം വാങ്ങിയിട്ട് ക്രെഡിറ്റ് കാർഡിലൂടെ പെയ്മെൻറ് ചെയ്യുമ്പോൾ കസ്റ്റമറിൽ നിന്നും ബാങ്ക് ഈടാക്കുന്ന പൈസയും കൂട്ടി 1,01,000 വാങ്ങൽ അനുവദനീയമല്ല. എന്നാൽ, ബാങ്കിൽ നിന്നും ഈടാക്കുന്ന ഒന്നര ശതമാനം കൂടെ കൂട്ടി സാധനത്തിന്റെ വിലയായി നിശ്ചയിച്ച് കച്ചവടക്കാരന് വിൽക്കൽ അനുവദനീയമാണ്.<br><br><br><br></p>', 49, 0, 5, '2024-01-30 07:06:08', 1, '2024-01-05 14:29:10', '2024-12-23 06:22:09') ON DUPLICATE KEY UPDATE `answer` = COALESCE(VALUES(`answer`), `answer`), `status` = VALUES(`status`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0635', 1, NULL, 1, NULL, NULL, 'ایک حدیث کی تحقیق ۔', 'السلام علیکم و رحمت اللہ و برکاتہ ۔
INSERT INTO `question_and_answer` (`question_id`, `user_id`, `category_id`, `madhab_id`, `assigned_mufti_id`, `checked_approved_by`, `title`, `body`, `language`, `status`, `answer`, `views`, `likes`, `stars`, `published_at`, `published_by`, `created_at`, `updated_at`) VALUES ('Q0646', 1, NULL, 5, NULL, NULL, 'Is it permissible to drink Non Alcoholic beer in islam.', 'Nowadays it is common drink in the market selling as Non Alcoholic beer in different flavours. Like Kumbaya Kombucha, Coolberg etc. So, is it permissible in islam to drink that if it has no any intoxicants in it?', 'English', 'published', '<p>Most of the non alcoholic beers contains a small percentage of alchohol. So that, It is not permissible to drink non alcoholic beer according to shafi madhab... According to hanafi madhab it is permissible to drink these kind of drinks only for treatment purposes, not for common use. whether, if it is made from dates or grapes then it should not be used for treatment also. Briefly, It is preffered to avoid these kind of non alcoholic drinks.&nbsp;</p>
