INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'عن إبن عباس رضي الله تعالى عنه قال لا بأس أن يقول للسلعة هي بنقد كذا او بنسيئة بكذا ولكن لا يتفرقان إلا عن رضي (مصنف ابن ابي شيبة. ٤٩٤) أم الائمة الاربعة وجمهور الفقهاء والمحدثين فقد أجازوا البيع المؤجل بأكثر من سعر النقد بشرط أن يبت العاقدان علي أنه بيع مؤجل بأجل معلوم (فقه البيوع ١ /٥٤٣) فان زيادة الثمن من أجل الأجل وإن كان جائزا عند بداية العقد ولكن لا تجوز الزيادة عند التخلف في الأداء فإنه ربا', 'فقه البيوع (Vol: ١, Pg: ٥٤٥)', 'Arabic', 0, 0, '2020-12-03 09:15:54', '2024-11-04 02:56:31' FROM `question_and_answer` WHERE `question_id` = 'Q0276' LIMIT 1;
