INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'ورد في حديث مسلم انه قال ان هذه من ثياب الكفار فلا تلبسها وهذا يقتضي الا يجوز المعصفر للنساء ايضا كما لا يجوز التختم بالحديد لهن نظرا للعلة وهي كونه لباس الكفار والجواب ان هذا قياس وهو يترك للنص وقد ورد النص بجواز المعصفر للنساء كما عرفت في المتن فتركنا القياس بخلاف خاتم الحديد فانه ليس هناك نص فعملنا بالقياس', 'اعلاء السنن ظفر احمد عثماني كتاب الحظر الاباحة  ادارة القرار العلوم الاسلاميه باكستان (Vol: ١٧, Pg: ٣٥١،٣٥٢)', 'Arabic', 0, 0, '2022-11-13 21:12:48', '2023-04-15 19:49:32' FROM `question_and_answer` WHERE `question_id` = 'Q0565' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'وكره لبس المعصفر والمزعفر الاحمر والاصفر للرجال مفاده انه لا يكره للنساء ولا باس بسائر الالوان', 'التنوير مع الرد شمس الدين التمر تاشي علاء الدين الحصكفي كتاب الحظر والاباحة -  المكتبة الاشرفية ديو بند (Vol: ٩, Pg: ٥٩١)', 'Arabic', 1, 0, '2022-11-13 21:12:48', '2023-04-15 19:49:32' FROM `question_and_answer` WHERE `question_id` = 'Q0565' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'انما اجيز ذلك لحاجة عامة فان لم يتيسر الحصول على بطاقة الحسم الفوري ولا التعاقد مع مصدر البطاقة بان يسحب مبلغ الفاتورة من حساب الحامل، واشتدت الحاجة الي  مثل هذه البطاقة, فالمرجوٌ انّ حاملها يعتبر معذورا في الدخول في هذا العقد ان شاء الله تعالي بعد اخذ جميع الاحتياطات اللازمة لان لا يلجأ الى دفع  الفائدة الربوية', 'فقه البيوع (Vol: ١, Pg: ٤٥٠)', 'Arabic', 0, 0, '2022-11-08 10:27:06', '2024-08-09 11:25:07' FROM `question_and_answer` WHERE `question_id` = 'Q0561' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'فالجائزة التي يقدمها مصدر البطاقة الى حاملها هي جائزة من قبل المقرض الى المستقرض فهو تبرّع محض لا قمار فيه ولا ربا', 'بحوث قضايا فقهيه معاصرة (Vol: ٢, Pg: ١٦٤)', 'Arabic', 1, 0, '2022-11-08 10:27:06', '2024-08-09 11:25:07' FROM `question_and_answer` WHERE `question_id` = 'Q0561' LIMIT 1;
