INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'وما نجس بغير نجاسة الكلب و بول الصبي ان لم تكن عين كفى جري الماء، هذه النجاسة ليست مغلة ولا مخففة بل هي متوسطة وهي حكمية وعينية فالحكمية التي لا تشاهد بالبصر ولا يدرك لها طعم ولا لون ولا رائحة كالبول اذا جف خفي اثره، والعينية نقيض ذلك وكلاهما يطهر بجري الماء سواء كان قلتين او اقل', 'النجم الوهاج (Vol: ١, Pg: ٤٢٧)', 'Arabic', 2, 0, '2022-03-23 12:49:58', '2023-04-01 18:40:13' FROM `question_and_answer` WHERE `question_id` = 'Q0539' LIMIT 1;
