INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'ويؤخذ منه أن وصول الدخان الذي فيه رائحة البخور أو غيره إلى الجوف لا يفطر به وإن تعمد فتح فيه لأجل ذلك وهو ظاهر، وبه أفتى الشمس البرماوي لما تقرر أنها ليست عينا: أي عرفا، إذ المدار هنا عليه وإن كانت ملحقة بالعين في باب الإحرام، ألا ترى أن ظهور الريح والطعم ملحق بالعين فيه لا هنا، وقد علم من ذلك أن فرض المسألة أنه لم يعلم انفصال عين هنا\"', 'نهاية للإمام الرملي', 'Arabic', 0, 0, '2023-03-26 12:53:17', '2024-08-18 10:07:37' FROM `question_and_answer` WHERE `question_id` = 'Q0577' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'لا يضر وصول الريح بالشم وكذا من الفم كرائحة البخور أو غيره إلى الجوف وإن تعمده لأنه ليس عينا وخرج به ما فيه عين كرائحة التتن يعني التنباك لعن الله من أحدثه لأنه من البدع القبيحة فإنه يفطر به', 'بغية المسترشدين', 'Arabic', 1, 0, '2023-03-26 12:53:17', '2024-08-18 10:07:37' FROM `question_and_answer` WHERE `question_id` = 'Q0577' LIMIT 1;
