INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'تَحِلُّ ذَبِيحَةُ الْمَرْأَةِ  بِلَا خِلَافٍ لِحَدِيثِ كَعْبِ بْنِ مَالِكٍ الْمَذْكُورِ فِي الْكِتَابِ وَذَكَاةُ الرَّجُلِ أَفْضَلُ مِنْ ذَكَاتِهَا لِمَا ذَكَرَهُ الْمُصَنِّفُ وَسَوَاءٌ كَانَتْ الْمَرْأَةُ حُرَّةً أَوْ أَمَةً طَاهِرًا أَوْ حَائِضًا أَوْ نُفَسَاءَ مُسْلِمَةً أَوْ كِتَابِيَّةً فَذَبِيحَتُهَا فِي كُلِّ هَذِهِ الْأَحْوَالِ حَلَالٌ نَصَّ عَلَيْهِ الشَّافِعِيُّ وَاتَّفَقُوا عَلَيْهِ', 'المجموع (Vol: ٩, Pg: ٧٦)', 'Arabic', 0, 0, '2023-06-20 08:48:09', '2024-10-23 13:36:05' FROM `question_and_answer` WHERE `question_id` = 'Q0595' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'قوله كما لو كان الكل خبيثا) في القنية لو كان الخبيث نصابا لا يلزمه الزكاة لان الكل واجب التصدق عليه فلا يفيد ايجاب التصدق ببعضه ومثله في البزازية', 'حاشية رد المحتار كتاب الزكاة / مكتبه دار الفكر (Vol: ٦, Pg: ٢٩١)', 'Arabic', 0, 0, '2023-07-02 04:52:00', '2023-07-10 07:49:10' FROM `question_and_answer` WHERE `question_id` = 'Q0597' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'وان كان كل واحد منه صبيا او كان شريك السبع من يريد اللحم او كان نصرانيا ونحو ذلك لا يجوز للاخرين ايضا كذا في السراجية ولو كان احد الشركاء ذميا كتابيا او غير كتابي وهو يريد اللحم او يريد القربة في دينه لم يجزئهم عندنا لان الكافرة لا يتحقق منه القربة فكانت نيته ملحقة بالعدم وكان يريد اللحم والمسلم لو اراد اللحم لا يجوز عندنا وكذلك اذا كان احدهم عبدا او مدبرا ويريد اضحية كذا في البدائع.', 'الفتاوى الهندية كتاب الاضحية / دار الكتاب ديو بند (Vol: ٥, Pg: ٣٠٤)', 'Arabic', 1, 0, '2023-07-02 04:52:00', '2023-07-10 07:49:10' FROM `question_and_answer` WHERE `question_id` = 'Q0597' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'ولو كان احد الشركاء ذميا كتابيا او غير كتابي فهو يريد اللحم او اراد القربة في دينه لم يجزهم عندنا لان الكافر لا تتحقق منه القربة فكانت نيته ملحقة بالعدم فكان مريد اللحم المسلم لو اراد اللحم لا يجوز عندنا فالكافر او لا وكذلك اذا كان احدهم عبدا او مدبرا ويريد الاضحية لان نيته باطلة لانه ليس من اهل هذه القربة فكان نصيبه لحما فيمتنع الجواز اصلا', 'بدائع الصنائع كتاب الاضحية / دار الكتاب ديوبند (Vol: ٤, Pg: ٢٠٩)', 'Arabic', 2, 0, '2023-07-02 04:52:00', '2023-07-10 07:49:10' FROM `question_and_answer` WHERE `question_id` = 'Q0597' LIMIT 1;
INSERT INTO `references` (`question_and_answer_id`, `arabic_text`, `book_name`, `language`, `sort_order`, `is_draft`, `created_at`, `updated_at`) SELECT `id`, 'ایک گائے میں بینک یا انشورنس کا ملازم یا کوئی بھی ایسا شخص شریک واہ کہ کل یہ اکثر آمدن حرام ہے اس کی شرکت سے دوسرے شرکاء کی قربانی پر کوئی اثر پڑے گا یا نہیں؟              اس صورت میں کسی کی قربانی بھی صحیح نہیں ہوئی', 'احسن الفتاوى كتاب الأضحيه / مكتبه زكريا ديوبند (Vol: ٧, Pg: ٥٠٣)', 'Arabic', 3, 0, '2023-07-02 04:52:00', '2023-07-10 07:49:10' FROM `question_and_answer` WHERE `question_id` = 'Q0597' LIMIT 1;
